INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6f07aa-32c4-4ef6-8804-38d843053c54', '沙路曲', '沙路曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["柳臉半眠丞相樹，珮馬釘鈴踏沙路。","斷燼遺香褭翠煙，燭騎啼烏上天去。","帝家玉龍開九關，帝前動笏移南山。","獨垂重印押千官，金窠篆字紅屈盤。","沙路歸來聞好語，旱火不光天下雨。"]', '["柳臉半眠丞相樹，珮马釘鈴踏沙路。","斷燼遺香褭翠煙，燭騎啼烏上天去。","帝家玉龙开九关，帝前动笏移南山。","独垂重印押千官，金窠篆字紅屈盤。","沙路归来闻好語，旱火不光天下雨。"]', '诗', 'shi', '', NULL, '沙路曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d08f89e8-887d-4dca-99b3-1ed4f2378876', '上之回', '上之回', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["上之回，大旗喜。","懸紅雲，撻鳳尾。","劒匣破，舞蛟龍。","蚩尤死，鼓逢逢。","天高慶雷齊墜地，地無驚煙海千里。"]', '["上之回，大旗喜。","懸紅云，撻鳳尾。","劒匣破，舞蛟龙。","蚩尤死，鼓逢逢。","天高慶雷齊墜地，地無驚煙海千里。"]', '诗', 'shi', '', NULL, '上之回 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4e6f5ab-ad75-4489-87f9-ffedbcc67926', '高軒過', '高軒過', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["華裾織翠青如葱，金環壓轡搖玲瓏。","馬蹄隱耳聲隆隆，入門下馬氣如虹。","云是東京才子，文章鉅公。","二十八宿羅心胸，九精照耀貫當中。","殿前作賦聲摩空，筆補造化天無功。","龐眉書客感秋蓬，誰知死草生華風。","我今垂翅附冥鴻，他日不羞蛇作龍。"]', '["华裾织翠青如葱，金环壓轡搖玲瓏。","马蹄隐耳声隆隆，入门下马氣如虹。","云是东京才子，文章鉅公。","二十八宿羅心胸，九精照耀貫當中。","殿前作賦声摩空，笔補造化天無功。","龐眉书客感秋蓬，誰知死草生华风。","我今垂翅附冥鴻，他日不羞蛇作龙。"]', '诗', 'shi', '', NULL, '高軒過 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd990bbb-82e3-458b-b958-f2783a07dd3a', '貝宮夫人', '貝宮夫人', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["丁丁海女弄金環，雀釵翹揭雙翅關。","六宮不語一生閑，高懸銀牓照青山。","長眉凝綠幾千年，清涼堪老鏡中鸞。","秋肌稍覺玉衣寒，空光帖妥水如天。"]', '["丁丁海女弄金环，雀釵翹揭雙翅关。","六宮不語一生闲，高懸銀牓照青山。","长眉凝綠幾千年，清涼堪老镜中鸾。","秋肌稍覺玉衣寒，空光帖妥水如天。"]', '诗', 'shi', '', NULL, '貝宮夫人 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c152a1b7-60aa-48c8-ac8c-7b2a9ddc6c24', '蘭香神女廟', '蘭香神女廟', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["古春年年在，閑綠搖暖雲。","松香飛晚華，柳渚含日昏。","沙砌落紅滿，石泉生水芹。","幽篁畫新粉，蛾綠橫曉門。","弱蕙不勝露，山秀愁空春。","舞珮剪鸞翼，帳帶塗輕銀。","蘭桂吹濃香，菱藕長莘莘。","看雨逢瑤姬，乘船值江君。","吹簫飲酒醉，結綬金絲裙。","走天呵白鹿，遊水鞭錦鱗。","密髮虛鬟飛，膩頰凝花勻。","團鬢分蛛巢，穠眉籠小脣。","弄蝶和輕妍，風光怯腰身。","深幃金鴨冷，奩鏡幽鳳塵。","踏霧乘風歸，撼玉山上聞。"]', '["古春年年在，闲綠搖暖云。","松香飞晚华，柳渚含日昏。","沙砌落紅满，石泉生水芹。","幽篁畫新粉，蛾綠橫晓门。","弱蕙不勝露，山秀愁空春。","舞珮剪鸾翼，帳带塗轻銀。","蘭桂吹濃香，菱藕长莘莘。","看雨逢瑤姬，乘船值江君。","吹簫饮酒醉，結綬金絲裙。","走天呵白鹿，游水鞭錦鱗。","密髮虛鬟飞，膩頰凝花勻。","團鬢分蛛巢，穠眉籠小脣。","弄蝶和轻妍，风光怯腰身。","深幃金鴨冷，奩镜幽鳳塵。","踏霧乘风归，撼玉山上闻。"]', '诗', 'shi', '', NULL, '蘭香神女廟 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd5fc9fd-285d-4464-8168-f245709cbe1a', '送韋仁實兄弟入關', '送韋仁實兄弟入关', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["送客飲別酒，千觴無赭顏。","何物最傷心，馬首鳴金鐶。","野色浩無主，秋明空曠間。","坐來壯膽破，斷目不能看。","行槐引西道，青梢長攢攢。","韋郎好兄弟，疊玉生文翰。","我在山上舍，一畝蒿磽田。","夜雨呌租吏，春聲暗交關。","誰解念勞勞，蒼突唯南山。"]', '["送客饮別酒，千觴無赭顏。","何物最傷心，马首鳴金鐶。","野色浩無主，秋明空曠间。","坐来壯膽破，斷目不能看。","行槐引西道，青梢长攢攢。","韋郎好兄弟，叠玉生文翰。","我在山上舍，一畝蒿磽田。","夜雨呌租吏，春声暗交关。","誰解念勞勞，蒼突唯南山。"]', '诗', 'shi', '', NULL, '送韋仁實兄弟入關 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8711b9e-4367-419b-8a7d-83e4f8ee8a98', '洛陽城外別皇甫湜', '洛陽城外別皇甫湜', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["洛陽吹別風，龍門起斷煙。","冬樹束生澀，晚紫凝華天。","單身野霜上，疲馬飛蓬間。","凭軒一雙淚，奉墜綠衣前。"]', '["洛陽吹別风，龙门起斷煙。","冬樹束生澀，晚紫凝华天。","單身野霜上，疲马飞蓬间。","凭軒一雙泪，奉墜綠衣前。"]', '诗', 'shi', '', NULL, '洛陽城外別皇甫湜 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab98ee1-0c01-45cb-966e-981b5b301c8b', '溪晚涼', '溪晚涼', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["白狐向月號山風，秋寒掃雲留碧空。","玉煙青溼白如幢，銀灣曉轉流天東。","溪汀眠鷺夢征鴻，輕漣不語細游溶。","層岫迴岑複疊龍，苦篁對客吟歌筒。"]', '["白狐向月號山风，秋寒掃云留碧空。","玉煙青溼白如幢，銀灣晓轉流天东。","溪汀眠鷺梦征鴻，轻漣不語細游溶。","層岫迴岑複叠龙，苦篁对客吟歌筒。"]', '诗', 'shi', '', NULL, '溪晚涼 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb653660-c834-4f30-a5c7-504e99f08354', '官不來題皇甫湜先輩廳', '官不来題皇甫湜先輩廳', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["官不來，官庭秋，老桐錯幹青龍愁。","書司曹佐走如牛，疊聲問佐官來不。","官不來，門幽幽。"]', '["官不来，官庭秋，老桐錯幹青龙愁。","书司曹佐走如牛，叠声问佐官来不。","官不来，门幽幽。"]', '诗', 'shi', '', NULL, '官不來題皇甫湜先輩廳 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd1c0560-c28a-4d9e-b303-5756dc060554', '長平箭頭歌', '长平箭头歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["漆灰骨末丹水沙，淒淒古血生銅花。","白翎金簳雨中盡，直餘三脊殘狼牙。","我尋平原乘兩馬，驛東石田蒿塢下。","風長日短星蕭蕭，黑旗雲溼懸空夜。","左魂右魄啼肌瘦，酪瓶倒盡將羊炙。","蟲棲雁病蘆筍紅，迴風送客吹陰火。","訪古汍瀾收斷鏃，折鋒赤璺曾刲肉。","南陌東城馬上兒，勸我將金換簝竹。"]', '["漆灰骨末丹水沙，淒淒古血生銅花。","白翎金簳雨中尽，直餘三脊殘狼牙。","我尋平原乘兩马，驛东石田蒿塢下。","风长日短星蕭蕭，黑旗云溼懸空夜。","左魂右魄啼肌瘦，酪瓶倒尽將羊炙。","蟲棲雁病蘆筍紅，迴风送客吹陰火。","訪古汍瀾收斷鏃，折鋒赤璺曾刲肉。","南陌东城马上兒，勸我將金換簝竹。"]', '诗', 'shi', '', NULL, '長平箭頭歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9168257a-0124-48ed-a906-9ba00f446ac8', '江樓曲', '江楼曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["樓前流水江陵道，鯉魚風起芙蓉老。","曉釵催鬢語南風，抽帆歸來一日功。","鼉吟浦口飛梅雨，竿頭酒旗換青苧。","蕭騷浪白雲差池，黃粉油衫寄郎主。","新槽酒聲苦無力，南湖一頃菱花白。","眼前便有千里愁，小玉開屏見山色。"]', '["楼前流水江陵道，鯉鱼风起芙蓉老。","晓釵催鬢語南风，抽帆归来一日功。","鼉吟浦口飞梅雨，竿头酒旗換青苧。","蕭騷浪白云差池，黄粉油衫寄郎主。","新槽酒声苦無力，南湖一頃菱花白。","眼前便有千里愁，小玉开屏见山色。"]', '诗', 'shi', '', NULL, '江樓曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49d31b27-344a-4ae2-b8cb-be347f790f3a', '塞下曲', '塞下曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["胡角引北風，薊門白於水。","天含青海道，城頭月千里。","露下旗濛濛，寒金鳴夜刻。","蕃甲鏁蛇鱗，馬嘶青塚白。","秋靜見旄頭，沙遠席羈愁。","帳北天應盡，河聲出塞流。"]', '["胡角引北风，薊门白於水。","天含青海道，城头月千里。","露下旗濛濛，寒金鳴夜刻。","蕃甲鏁蛇鱗，马嘶青塚白。","秋静见旄头，沙远席羈愁。","帳北天應尽，河声出塞流。"]', '诗', 'shi', '', NULL, '塞下曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a178fb4-16b1-4b9b-a552-c7ed198caa87', '染絲上春機', '染絲上春機', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["玉罌泣水桐花井，蒨絲沈水如雲影。","美人嬾態燕脂愁，春梭拋擲鳴高樓。","綵線結茸背複疊，白袷玉郎寄桃葉。","爲君挑鸞作腰綬，願君處處宜春酒。"]', '["玉罌泣水桐花井，蒨絲沈水如云影。","美人嬾態燕脂愁，春梭拋擲鳴高楼。","綵線結茸背複叠，白袷玉郎寄桃葉。","爲君挑鸾作腰綬，願君处处宜春酒。"]', '诗', 'shi', '', NULL, '染絲上春機 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe1d099d-0184-461a-9460-ee06e660584c', '五粒小松歌', '五粒小松歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["蛇子蛇孫鱗蜿蜿，新香幾粒洪厓飯。","綠波浸葉滿濃光，細束龍髯鉸刀剪。","主人壁上鋪州圖，主人堂前多俗儒。","月明白露秋淚滴，石筍溪雲肯寄書。"]', '["蛇子蛇孫鱗蜿蜿，新香幾粒洪厓飯。","綠波浸葉满濃光，細束龙髯鉸刀剪。","主人壁上鋪州圖，主人堂前多俗儒。","月明白露秋泪滴，石筍溪云肯寄书。"]', '诗', 'shi', '', NULL, '五粒小松歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5542580-eb5f-4d8a-beb9-7d1353e9bb73', '塘上行', '塘上行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["藕花涼露溼，花缺藕根澀。","飛下雌鴛鴦，塘水聲溘溘。"]', '["藕花涼露溼，花缺藕根澀。","飞下雌鴛鴦，塘水声溘溘。"]', '诗', 'shi', '', NULL, '塘上行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324b12b1-4e01-4037-bd08-4f6616e4ba53', '呂將軍歌', '呂將軍歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["呂將軍，騎赤兔。","獨攜大膽出秦門，金粟堆邊哭陵樹。","北方逆氣汙青天，劒龍夜呌將軍閑。","將軍振袖揮劒鍔，玉闕朱城有門閣。","榼榼銀龜搖白馬，傅粉女郎火旗下。","恆山鐵騎請金槍，遙聞箙中花箭香。","西郊寒蓬葉如刺，皇天新栽養神驥。","廐中高桁排蹇蹄，飽食青芻飲白水。","圓蒼低迷蓋張地，九州人事皆如此。","赤山秀鋌禦時英，綠眼將軍會天意。"]', '["呂將軍，騎赤兔。","独携大膽出秦门，金粟堆邊哭陵樹。","北方逆氣汙青天，劒龙夜呌將軍闲。","將軍振袖揮劒鍔，玉闕朱城有门閣。","榼榼銀龟搖白马，傅粉女郎火旗下。","恆山鐵騎請金槍，遙闻箙中花箭香。","西郊寒蓬葉如刺，皇天新栽養神驥。","廐中高桁排蹇蹄，飽食青芻饮白水。","圓蒼低迷蓋張地，九州人事皆如此。","赤山秀鋌禦时英，綠眼將軍會天意。"]', '诗', 'shi', '', NULL, '呂將軍歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a10a0601-e9b9-4e5e-9553-ab625ef13ddc', '休洗紅', '休洗紅', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["休洗紅，洗多紅色淺。","卿卿騁少年，昨日殷橋見。","封侯早歸來，莫作弦上箭。"]', '["休洗紅，洗多紅色淺。","卿卿騁少年，昨日殷橋见。","封侯早归来，莫作弦上箭。"]', '诗', 'shi', '', NULL, '休洗紅 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21b336af-06d1-4ec7-8492-ba001b89b96c', '神弦曲', '神弦曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["西山日沒東山昏，旋風吹馬馬踏雲。","畫弦素管聲淺繁，花裙綷䌨步秋塵。","桂葉刷風桂墜子，青狸哭血寒狐死。","古壁彩虬金帖尾，雨工騎入秋潭水。","百年老鴞成木魅，笑聲碧火巢中起。"]', '["西山日沒东山昏，旋风吹马马踏云。","畫弦素管声淺繁，花裙綷䌨步秋塵。","桂葉刷风桂墜子，青狸哭血寒狐死。","古壁彩虬金帖尾，雨工騎入秋潭水。","百年老鴞成木魅，笑声碧火巢中起。"]', '诗', 'shi', '', NULL, '神弦曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee31b315-58e8-4a6f-86eb-542e2405bae0', '野歌', '野歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["鵶翎羽箭山桑弓，仰天射落銜蘆鴻。","麻衣黑肥衝北風，帶酒日晚歌田中。","男兒屈窮心不窮，枯榮不等嗔天公。","寒風又變爲春柳，條條看即煙濛濛。"]', '["鵶翎羽箭山桑弓，仰天射落銜蘆鴻。","麻衣黑肥衝北风，带酒日晚歌田中。","男兒屈窮心不窮，枯榮不等嗔天公。","寒风又变爲春柳，條條看即煙濛濛。"]', '诗', 'shi', '', NULL, '野歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b0850d-cb82-47c3-91a5-6f3a93cb403f', '神弦', '神弦', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["女巫澆酒雲滿空，玉爐炭火香鼕鼕。","海神山鬼來座中，紙錢窸窣鳴𩘶風。","相思木帖金舞鸞，攢蛾一啑重一彈。","呼星召鬼歆杯盤，山魅食時人森寒。","終南日色低平灣，神兮長在有無間。","神嗔神喜師更顏，送神萬騎還青山。"]', '["女巫澆酒云满空，玉爐炭火香鼕鼕。","海神山鬼来座中，紙錢窸窣鳴𩘶风。","相思木帖金舞鸾，攢蛾一啑重一彈。","呼星召鬼歆杯盤，山魅食时人森寒。","終南日色低平灣，神兮长在有無间。","神嗔神喜師更顏，送神万騎還青山。"]', '诗', 'shi', '', NULL, '神弦 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff880442-2fe3-4e95-a762-ee8e9b1c026d', '將進酒', '將進酒', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["琉璃鍾，琥珀濃，小槽酒滴真珠紅。","烹龍炮鳳玉脂泣，羅屏繡幕圍香風。","吹龍笛，擊鼉鼓，皓齒歌，細腰舞。","況是青春日將暮，桃花亂落如紅雨。","勸君終日酩酊醉，酒不到劉伶墳上土。"]', '["琉璃鍾，琥珀濃，小槽酒滴真珠紅。","烹龙炮鳳玉脂泣，羅屏繡幕圍香风。","吹龙笛，擊鼉鼓，皓齒歌，細腰舞。","況是青春日將暮，桃花亂落如紅雨。","勸君終日酩酊醉，酒不到劉伶墳上土。"]', '诗', 'shi', '', NULL, '將進酒 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a75e413d-42ce-4ab5-8bad-8ec13b514a7a', '美人梳頭歌', '美人梳头歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["西施曉夢綃帳寒，香鬟墮髻半沈檀。","轆轤咿啞轉鳴玉，驚起芙蓉睡新足。","雙鸞開鏡秋水光，解鬟臨鏡立象牀。","一編香絲雲撒地，玉釵落處無聲膩。","纖手却盤老鵶色，翠滑寶釵簪不得。","春風爛熳惱嬌慵，十八鬟多無氣力。","妝成𩭏鬌敧不斜，雲裾數步踏雁沙。","背人不語向何處，下堦自折櫻桃花。"]', '["西施晓梦綃帳寒，香鬟墮髻半沈檀。","轆轤咿啞轉鳴玉，驚起芙蓉睡新足。","雙鸾开镜秋水光，解鬟臨镜立象牀。","一編香絲云撒地，玉釵落处無声膩。","纖手却盤老鵶色，翠滑寶釵簪不得。","春风爛熳惱嬌慵，十八鬟多無氣力。","妝成𩭏鬌敧不斜，云裾數步踏雁沙。","背人不語向何处，下堦自折櫻桃花。"]', '诗', 'shi', '', NULL, '美人梳頭歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('535efe6f-d7cc-4b2d-b6ca-3514fd6a3044', '月漉漉篇', '月漉漉篇', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["月漉漉，波煙玉。","莎青桂花繁，芙蓉別江木。","粉態裌羅寒，雁羽鋪煙溼。","誰能看石帆，乘船鏡中入。","秋白鮮紅死，水香蓮子齊。","挽菱隔歌袖，綠刺罥銀泥。"]', '["月漉漉，波煙玉。","莎青桂花繁，芙蓉別江木。","粉態裌羅寒，雁羽鋪煙溼。","誰能看石帆，乘船镜中入。","秋白鲜紅死，水香蓮子齊。","挽菱隔歌袖，綠刺罥銀泥。"]', '诗', 'shi', '', NULL, '月漉漉篇 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc44e8dd-356a-430e-96e6-945192f3fb85', '京城', '京城', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["驅馬出門意，牢落長安心。","兩事誰向道，自作秋風吟。"]', '["驱马出门意，牢落长安心。","兩事誰向道，自作秋风吟。"]', '诗', 'shi', '', NULL, '京城 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2b1699-d06e-4aaa-ae74-3e5caa7654cc', '官街鼓', '官街鼓', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["曉聲隆隆催轉日，暮聲隆隆呼月出。","漢城黃柳暎新簾，柏陵飛燕埋香骨。","磓發千年日長白，孝武秦王聽不得。","從君翠髮蘆花色，獨共南山守中國。","幾迴天上葬神仙，漏聲相將無斷緣。"]', '["晓声隆隆催轉日，暮声隆隆呼月出。","漢城黄柳暎新簾，柏陵飞燕埋香骨。","磓發千年日长白，孝武秦王听不得。","從君翠髮蘆花色，独共南山守中国。","幾迴天上葬神仙，漏声相將無斷緣。"]', '诗', 'shi', '', NULL, '官街鼓 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adc8f8c2-9cb5-4ee9-bf45-45d8f8011cc2', '許公子鄭姬歌', '許公子鄭姬歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["許史世家外親貴，宮錦千端買沈醉。","銅駝酒熟烘明膠，古堤大柳煙中翠。","桂開客花名鄭袖，入洛聞香鼎門口。","先將芍藥獻妝臺，後解黃金大如斗。","莫愁簾中許合歡，清弦五十爲君彈。","彈聲咽春弄君骨，骨興牽人馬上鞍。","兩馬八蹄踏蘭苑，情如合竹誰能見。","夜光玉枕栖鳳皇，袷羅當門刺純綫。","長翻蜀紙卷明君，轉角含商破碧雲。","自從小靨來東道，曲裏長眉少見人。","相如塚上生秋柏，三秦誰是言情客。","蛾鬟醉眼拜諸宗，爲謁皇孫請曹植。"]', '["許史世家外親貴，宮錦千端買沈醉。","銅駝酒熟烘明膠，古堤大柳煙中翠。","桂开客花名鄭袖，入洛闻香鼎门口。","先將芍藥獻妝台，後解黄金大如斗。","莫愁簾中許合歡，清弦五十爲君彈。","彈声咽春弄君骨，骨兴牽人马上鞍。","兩马八蹄踏蘭苑，情如合竹誰能见。","夜光玉枕栖鳳皇，袷羅當门刺純綫。","长翻蜀紙卷明君，轉角含商破碧云。","自從小靨来东道，曲裏长眉少见人。","相如塚上生秋柏，三秦誰是言情客。","蛾鬟醉眼拜諸宗，爲謁皇孫請曹植。"]', '诗', 'shi', '', NULL, '許公子鄭姬歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba9e4f53-6289-4f5c-a810-dbddc67fb100', '新夏歌', '新夏歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["曉木千籠真蠟綵，落蕊枯香數分在。","陰枝秀牙卷縹茸，長風迴氣扶葱蘢。","野家麥畦上新壠，長畛裴回桑柘重。","刺香滿地菖蒲草，雨梁燕語悲身老。","三月搖揚入河道，天濃地濃柳梳掃。"]', '["晓木千籠真蠟綵，落蕊枯香數分在。","陰枝秀牙卷縹茸，长风迴氣扶葱蘢。","野家麦畦上新壠，长畛裴回桑柘重。","刺香满地菖蒲草，雨梁燕語悲身老。","三月搖揚入河道，天濃地濃柳梳掃。"]', '诗', 'shi', '', NULL, '新夏歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2354f955-cf18-4f45-b55f-2ebe0a7329e3', '題歸夢', '題归梦', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長安風雨夜，書客夢昌谷。","怡怡中堂笑，小弟栽澗菉。","家門厚重意，望我飽飢腹。","勞勞一寸心，燈花照魚目。"]', '["长安风雨夜，书客梦昌谷。","怡怡中堂笑，小弟栽澗菉。","家门厚重意，望我飽飢腹。","勞勞一寸心，灯花照鱼目。"]', '诗', 'shi', '', NULL, '題歸夢 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('281fefbc-fb0a-4e20-80dc-726c2a682427', '經沙苑', '經沙苑', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["野水泛長瀾，宮牙開小蒨。","無人柳自春，草渚鴛鴦暖。","晴嘶臥沙馬，老去悲啼展。","今春還不歸，塞嚶折翅雁。"]', '["野水泛长瀾，宮牙开小蒨。","無人柳自春，草渚鴛鴦暖。","晴嘶臥沙马，老去悲啼展。","今春還不归，塞嚶折翅雁。"]', '诗', 'shi', '', NULL, '經沙苑 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7917ea14-d308-483a-af68-396ff5c08995', '出城別張又新酬李漢', '出城別張又新酬李漢', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["李子別上國，南山崆峒春。","不聞今夕鼓，差慰煎情人。","趙壹賦命薄，馬卿家業貧。","鄉書何所報，紫蕨生石雲。","長安玉桂國，戟帶披侯門。","慘陰地自光，寶馬踏曉昏。","臘春戲草苑，玉輓鳴𨏈轔。","綠網縋金鈴，霞卷清池漘。","開貫瀉蚨母，買冰防夏蠅。","時宜裂大袂，劒客車盤茵。","小人如死灰，心切生秋榛。","皇圖跨四海，百姓拖長紳。","光明靄不發，腰龜徒甃銀。","吾將譟禮樂，聲調摩清新。","欲使十千歲，帝道如飛神。","華實自蒼老，流采長傾湓。","沒沒暗齰舌，涕血不敢論。","今將下東道，祭酒而別秦。","六郡無勦兒，長刀誰拭塵。","地理陽無正，快馬逐服轅。","二子美年少，調道講清渾。","譏笑斷冬夜，家庭疎篠穿。","曙風起四方，秋月當東懸。","賦詩面投擲，悲哉不遇人。","此別定霑臆，越布先裁巾。"]', '["李子別上国，南山崆峒春。","不闻今夕鼓，差慰煎情人。","趙壹賦命薄，马卿家業貧。","乡书何所報，紫蕨生石云。","长安玉桂国，戟带披侯门。","慘陰地自光，寶马踏晓昏。","臘春戲草苑，玉輓鳴𨏈轔。","綠網縋金鈴，霞卷清池漘。","开貫瀉蚨母，買冰防夏蠅。","时宜裂大袂，劒客车盤茵。","小人如死灰，心切生秋榛。","皇圖跨四海，百姓拖长紳。","光明靄不發，腰龟徒甃銀。","吾將譟禮乐，声調摩清新。","欲使十千歲，帝道如飞神。","华實自蒼老，流采长傾湓。","沒沒暗齰舌，涕血不敢論。","今將下东道，祭酒而別秦。","六郡無勦兒，长刀誰拭塵。","地理陽無正，快马逐服轅。","二子美年少，調道講清渾。","譏笑斷冬夜，家庭疎篠穿。","曙风起四方，秋月當东懸。","賦诗面投擲，悲哉不遇人。","此別定霑臆，越布先裁巾。"]', '诗', 'shi', '', NULL, '出城別張又新酬李漢 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e3a49f-20cd-4347-a982-bee45e0b422c', '南園', '南园', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["方領蕙帶折角巾，杜若已老蘭苕春。","南山削秀藍玉合，小雨歸去飛涼雲。","熟杏暖香梨葉老，草梢竹柵鎖池痕。","鄭公鄉老開酒尊，坐汎楚奏吟招魂。"]', '["方領蕙带折角巾，杜若已老蘭苕春。","南山削秀藍玉合，小雨归去飞涼云。","熟杏暖香梨葉老，草梢竹柵鎖池痕。","鄭公乡老开酒尊，坐汎楚奏吟招魂。"]', '诗', 'shi', '', NULL, '南園 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('773e3420-7888-4c61-b026-fad74cf8a313', '假龍吟歌', '假龙吟歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["石軋銅杯，吟詠枯瘁。","蒼鷹擺血，白鳳下肺。","桂子自落，雲弄車蓋。","木死沙崩惡谿島，阿母得仙今不老。","窞中跳汰截清涎，隈壖臥水埋金爪。","崖蹬蒼苔弔石髮，江君掩帳篔簹折。","蓮花去國一千年，雨後聞腥猶帶鐵。"]', '["石軋銅杯，吟詠枯瘁。","蒼鷹擺血，白鳳下肺。","桂子自落，云弄车蓋。","木死沙崩惡谿島，阿母得仙今不老。","窞中跳汰截清涎，隈壖臥水埋金爪。","崖蹬蒼苔弔石髮，江君掩帳篔簹折。","蓮花去国一千年，雨後闻腥猶带鐵。"]', '诗', 'shi', '', NULL, '假龍吟歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b887a4-c160-4f64-add7-4fedcb3043ab', '感諷六首 一', '感諷六首 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["人間春蕩蕩，帳暖香揚揚。","飛光染幽紅，誇嬌來洞房。","舞席泥金蛇，桐竹羅花牀。","眼逐春瞑醉，粉隨淚色黃。","王子下馬來，曲沼鳴鴛鴦。","焉知腸車轉，一夕巡九方。"]', '["人间春蕩蕩，帳暖香揚揚。","飞光染幽紅，誇嬌来洞房。","舞席泥金蛇，桐竹羅花牀。","眼逐春瞑醉，粉隨泪色黄。","王子下马来，曲沼鳴鴛鴦。","焉知腸车轉，一夕巡九方。"]', '诗', 'shi', '', NULL, '感諷六首 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f83ee031-9f9f-493f-961e-7f16a7483b7a', '感諷六首 二', '感諷六首 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["苦風吹朔寒，沙驚秦木折。","舞影逐空天，畫鼓餘清節。","蜀書秋信斷，黑水朝波咽。","嬌魂從回風，死處懸鄉月。"]', '["苦风吹朔寒，沙驚秦木折。","舞影逐空天，畫鼓餘清節。","蜀书秋信斷，黑水朝波咽。","嬌魂從回风，死处懸乡月。"]', '诗', 'shi', '', NULL, '感諷六首 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d281fee1-0565-42c7-a16f-73cc97d6fd32', '感諷六首 三', '感諷六首 三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["雜雜胡馬塵，森森邊士戟。","天教胡馬戰，曉雲皆血色。","婦人攜漢卒，箭箙囊巾幗。","不慙金印重，踉蹡腰鞬力。","恂恂鄉門老，昨夜試鋒鏑。","走馬遣書勳，誰能分粉墨。"]', '["杂杂胡马塵，森森邊士戟。","天教胡马戰，晓云皆血色。","婦人携漢卒，箭箙囊巾幗。","不慙金印重，踉蹡腰鞬力。","恂恂乡门老，昨夜試鋒鏑。","走马遣书勳，誰能分粉墨。"]', '诗', 'shi', '', NULL, '感諷六首 三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('062be68d-ab40-4f92-a653-0b4444650205', '感諷六首 四', '感諷六首 四', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["青門放彈去，馬色連空郊。","何年帝家物，玉裝鞍上搖。","去去走犬歸，來來坐烹羔。","千金不了饌，狢肉稱盤臊。","試問誰家子，乃老能佩刀。","西山白蓋下，賢儁寒蕭蕭。"]', '["青门放彈去，马色連空郊。","何年帝家物，玉裝鞍上搖。","去去走犬归，来来坐烹羔。","千金不了饌，狢肉稱盤臊。","試问誰家子，乃老能佩刀。","西山白蓋下，賢儁寒蕭蕭。"]', '诗', 'shi', '', NULL, '感諷六首 四 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb82e8ad-edd0-482a-96b3-8e8b2ecb5ead', '感諷六首 五', '感諷六首 五', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["曉菊泫寒露，似悲團扇風。","秋涼經漢殿，班子泣衰紅。","本無辭輦意，豈見入空宮。","腰衱珮珠斷，灰蝶生陰松。"]', '["晓菊泫寒露，似悲團扇风。","秋涼經漢殿，班子泣衰紅。","本無辞輦意，豈见入空宮。","腰衱珮珠斷，灰蝶生陰松。"]', '诗', 'shi', '', NULL, '感諷六首 五 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d53c6d4b-cb61-49aa-a6ec-cbd8946a8bbc', '感諷六首 六', '感諷六首 六', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["蝶飛紅粉臺，柳掃吹笙道。","十日懸戶庭，九秋無衰草。","調歌送風轉，杯池白魚小。","水宴截香腴，菱科映青罩。","䒠蒙梨花滿，春昏弄長嘯。","唯愁苦花落，不悟世衰到。","撫舊唯銷魂，南山坐悲峭。"]', '["蝶飞紅粉台，柳掃吹笙道。","十日懸戶庭，九秋無衰草。","調歌送风轉，杯池白鱼小。","水宴截香腴，菱科映青罩。","䒠蒙梨花满，春昏弄长嘯。","唯愁苦花落，不悟世衰到。","撫旧唯銷魂，南山坐悲峭。"]', '诗', 'shi', '', NULL, '感諷六首 六 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e3272d3-dfbf-4e6b-86c2-22cb5ae6b4a7', '莫愁曲', '莫愁曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["草生龍坡下，鵶噪城堞頭。","何人此城裏，城角栽石榴。","青絲繫五馬，黃金絡雙牛。","白魚駕蓮船，夜作十里遊。","歸來無人識，暗上沈香樓。","羅牀倚瑤瑟，殘月傾簾鉤。","今日槿花落，明朝桐樹秋。","莫負平生意，何名何莫愁。"]', '["草生龙坡下，鵶噪城堞头。","何人此城裏，城角栽石榴。","青絲繫五马，黄金絡雙牛。","白鱼駕蓮船，夜作十里游。","归来無人識，暗上沈香楼。","羅牀倚瑤瑟，殘月傾簾鉤。","今日槿花落，明朝桐樹秋。","莫負平生意，何名何莫愁。"]', '诗', 'shi', '', NULL, '莫愁曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2159bbc3-f147-4442-82ee-16ee250587a9', '夜來樂', '夜来乐', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["紅羅複帳金流蘇，華燈九枝懸鯉魚。","麗人暎月開銅鋪，春水滴酒猩猩沽。","重一篋，香十株，赤金瓜子兼雜麩。","五絲封青鳧，阿侯此笑千萬餘。","南軒漢轉簾影疎，桐林啞啞挾子烏。","劒崖鞭節青石珠，白騧吹湍凝霜鬚。","漏長送珮承明廬，倡樓嵯峨明月孤。","新客下馬故客去，綠蟬秀黛重拂梳。"]', '["紅羅複帳金流蘇，华灯九枝懸鯉鱼。","丽人暎月开銅鋪，春水滴酒猩猩沽。","重一篋，香十株，赤金瓜子兼杂麩。","五絲封青鳧，阿侯此笑千万餘。","南軒漢轉簾影疎，桐林啞啞挾子烏。","劒崖鞭節青石珠，白騧吹湍凝霜鬚。","漏长送珮承明廬，倡楼嵯峨明月孤。","新客下马故客去，綠蟬秀黛重拂梳。"]', '诗', 'shi', '', NULL, '夜來樂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51b5b5b-fca3-41dc-955a-bca2eb6a3f06', '嘲雪', '嘲雪', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["昨日發葱嶺，今朝下蘭渚。","喜從千里來，亂笑含春語。","龍沙溼漢旗，鳳扇迎秦素。","久別遼城鶴，毛衣已應故。"]', '["昨日發葱嶺，今朝下蘭渚。","喜從千里来，亂笑含春語。","龙沙溼漢旗，鳳扇迎秦素。","久別遼城鹤，毛衣已應故。"]', '诗', 'shi', '', NULL, '嘲雪 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b07c75ea-7eec-4c11-890a-5dc4513ebdb9', '春懷引', '春懷引', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["芳蹊密影成花洞，柳結濃煙花帶重。","蟾蜍碾玉挂明弓，捍撥裝金打仙鳳。","寶枕垂雲選春夢，鈿合碧寒龍腦凍。","阿侯繫錦覓周郎，憑仗東風好相送。"]', '["芳蹊密影成花洞，柳結濃煙花带重。","蟾蜍碾玉挂明弓，捍撥裝金打仙鳳。","寶枕垂云選春梦，鈿合碧寒龙腦凍。","阿侯繫錦覓周郎，憑仗东风好相送。"]', '诗', 'shi', '', NULL, '春懷引 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e725e0c8-c1df-4ed4-ba45-0cf3cd64b40b', '白虎行', '白虎行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["火烏日暗崩騰雲，秦皇虎視蒼生羣。","燒書滅國無暇日，鑄劒佩玦惟將軍。","玉壇設醮思沖天，一世二世當萬年。","燒丹未得不死藥，拏舟海上尋神仙。","鯨魚張鬣海波沸，耕人半作征人鬼。","雄豪氣猛如燄煙，無人爲決天河水。","誰最苦兮誰最苦，報人義士深相許。","漸離擊筑荆卿歌，荆卿把酒燕丹語。","劒如霜兮膽如鐵，出燕城兮望秦月。","天授秦封祚未移，衮龍衣點荆卿血。","朱旗卓地白虎死，漢皇知是真天子。"]', '["火烏日暗崩腾云，秦皇虎視蒼生羣。","燒书滅国無暇日，鑄劒佩玦惟將軍。","玉壇設醮思沖天，一世二世當万年。","燒丹未得不死藥，拏舟海上尋神仙。","鯨鱼張鬣海波沸，耕人半作征人鬼。","雄豪氣猛如燄煙，無人爲決天河水。","誰最苦兮誰最苦，報人義士深相許。","漸離擊筑荆卿歌，荆卿把酒燕丹語。","劒如霜兮膽如鐵，出燕城兮望秦月。","天授秦封祚未移，衮龙衣点荆卿血。","朱旗卓地白虎死，漢皇知是真天子。"]', '诗', 'shi', '', NULL, '白虎行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec96e2f8-e52b-4a5e-813f-94c1c78d5270', '有所思', '有所思', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["去年陌上歌離曲，今日君書遠遊蜀。","簾外花開二月風，臺前淚滴千行竹。","琴心與妾腸，此夜斷還續。","想君白馬懸雕弓，世間何處無春風。","君心未肯鎮如石，妾顏不久如花紅。","夜殘高碧橫長河，河上無梁空白波。","西風未起悲龍梭，年年織素攢雙蛾。","江山迢遰無休絕，淚眼看燈乍明滅。","自從孤館深鎖窗，桂花幾度圓還缺。","鵶鵶向曉鳴森木，風過池塘響叢玉。","白日蕭條夢不成，橋南更問仙人卜。"]', '["去年陌上歌離曲，今日君书远游蜀。","簾外花开二月风，台前泪滴千行竹。","琴心與妾腸，此夜斷還續。","想君白马懸雕弓，世间何处無春风。","君心未肯鎮如石，妾顏不久如花紅。","夜殘高碧橫长河，河上無梁空白波。","西风未起悲龙梭，年年织素攢雙蛾。","江山迢遰無休絕，泪眼看灯乍明滅。","自從孤館深鎖窗，桂花幾度圓還缺。","鵶鵶向晓鳴森木，风過池塘响叢玉。","白日蕭條梦不成，橋南更问仙人卜。"]', '诗', 'shi', '', NULL, '有所思 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83cbc920-6d79-4458-ac38-df147d8e33f6', '啁少年', '啁少年', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["青騘馬肥金鞍光，龍腦入縷羅衫香。","美人狹坐飛瓊觴，貧人喚云天上郎。","別起高樓臨碧篠，絲曳紅鱗出深沼。","有時半醉百花前，背把金丸落飛鳥。","自說生來未爲客，一身美妾過三百。","豈知斸地種苗家，官稅頻催勿人織。","長得積玉誇豪毅，每揖閑人多意氣。","生來不讀半行書，只把黃金買身貴。","少年安得長少年，海波尚變爲桑田。","榮枯遞傳急如箭，天公不肯於公偏。","莫道韶華鎮長在，髮白面皺專相待。"]', '["青騘马肥金鞍光，龙腦入縷羅衫香。","美人狹坐飞瓊觴，貧人喚云天上郎。","別起高楼臨碧篠，絲曳紅鱗出深沼。","有时半醉百花前，背把金丸落飞鸟。","自说生来未爲客，一身美妾過三百。","豈知斸地種苗家，官稅頻催勿人织。","长得積玉誇豪毅，每揖闲人多意氣。","生来不读半行书，只把黄金買身貴。","少年安得长少年，海波尚变爲桑田。","榮枯遞傳急如箭，天公不肯於公偏。","莫道韶华鎮长在，髮白面皺專相待。"]', '诗', 'shi', '', NULL, '啁少年 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfd5cd4a-43aa-40c9-ad9b-a1865081dfcf', '高平縣東私路', '高平縣东私路', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["侵侵槲葉香，木花滯寒雨。","今夕山上秋，永謝無人處。","石磎遠荒澀，棠實懸辛苦。","古者定幽尋，呼君作私路。"]', '["侵侵槲葉香，木花滯寒雨。","今夕山上秋，永謝無人处。","石磎远荒澀，棠實懸辛苦。","古者定幽尋，呼君作私路。"]', '诗', 'shi', '', NULL, '高平縣東私路 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b18bfad-a576-4eda-b6cc-04e8c86a5ccb', '神仙曲', '神仙曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["碧峰海面藏靈書，上帝揀作神仙居。","清明笑語聞空虛，鬬乘巨浪騎鯨魚。","春羅書字邀王母，共讌紅樓最深處。","鶴羽衝風過海遲，不如却使青龍去。","猶疑王母不相許，垂露娃鬟更傳語。"]', '["碧峰海面藏靈书，上帝揀作神仙居。","清明笑語闻空虛，鬬乘巨浪騎鯨鱼。","春羅书字邀王母，共讌紅楼最深处。","鹤羽衝风過海遲，不如却使青龙去。","猶疑王母不相許，垂露娃鬟更傳語。"]', '诗', 'shi', '', NULL, '神仙曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38b8a259-112d-41a1-802d-b092799eea5f', '龍夜吟', '龙夜吟', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["鬈髮胡兒眼睛綠，高樓夜靜吹橫竹。","一聲似向天上來，月下美人望鄉哭。","直排七點星藏指，暗合清風調宮徵。","蜀道秋深雲滿林，湘江半夜龍驚起。","玉堂美人邊塞情，碧窗皓月愁中聽。","寒碪能擣百尺練，粉淚凝珠滴紅線。","胡兒莫作隴頭吟，隔窗暗結愁人心。"]', '["鬈髮胡兒眼睛綠，高楼夜静吹橫竹。","一声似向天上来，月下美人望乡哭。","直排七点星藏指，暗合清风調宮徵。","蜀道秋深云满林，湘江半夜龙驚起。","玉堂美人邊塞情，碧窗皓月愁中听。","寒碪能擣百尺練，粉泪凝珠滴紅線。","胡兒莫作隴头吟，隔窗暗結愁人心。"]', '诗', 'shi', '', NULL, '龍夜吟 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c8eaafa-5117-4c0a-beba-c08ea1739273', '崑崙使者', '崑崙使者', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["崑崙使者無消息，茂陵煙樹生愁色。","金盤玉露自淋漓，元氣茫茫收不得。","麒麟背上石文裂，虬龍鱗下紅枝折。","何處偏傷萬國心，中天夜久高明月。"]', '["崑崙使者無消息，茂陵煙樹生愁色。","金盤玉露自淋漓，元氣茫茫收不得。","麒麟背上石文裂，虬龙鱗下紅枝折。","何处偏傷万国心，中天夜久高明月。"]', '诗', 'shi', '', NULL, '崑崙使者 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18cb0076-2c50-47b6-a3c0-9cf51a30b701', '漢唐姬飲酒歌', '漢唐姬饮酒歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["御服沾霜露，天衢長蓁棘。","金隱秋塵姿，無人爲帶飾。","玉堂歌聲寢，芳林煙樹隔。","雲陽臺上歌，鬼哭復何益。","鐵劒常光光，至兇威屢逼。","彊梟噬母心，犇厲索人魄。","相看兩相泣，淚下如波激。","寧用清酒爲，欲作黃泉客。","不說玉山頹，且無飲中色。","勉從天帝訴，天上寡沈厄。","無處張穗帷，如何望松柏。","妾身晝團團，君魂夜寂寂。","蛾眉自覺長，頸粉誰憐白。","矜持昭陽意，不肯看南陌。"]', '["御服沾霜露，天衢长蓁棘。","金隐秋塵姿，無人爲带飾。","玉堂歌声寢，芳林煙樹隔。","云陽台上歌，鬼哭复何益。","鐵劒常光光，至兇威屢逼。","彊梟噬母心，犇厲索人魄。","相看兩相泣，泪下如波激。","寧用清酒爲，欲作黄泉客。","不说玉山頹，且無饮中色。","勉從天帝訴，天上寡沈厄。","無处張穗帷，如何望松柏。","妾身晝團團，君魂夜寂寂。","蛾眉自覺长，頸粉誰怜白。","矜持昭陽意，不肯看南陌。"]', '诗', 'shi', '', NULL, '漢唐姬飲酒歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03eec718-71e4-463f-a2f4-b1a65cda8271', '聽穎師琴歌', '听穎師琴歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["別浦雲歸桂花渚，蜀國弦中雙鳳語。","芙蓉葉落秋鸞離，越王夜起遊天姥。","暗珮清臣敲水玉，渡海蛾眉牽白鹿。","誰看挾劒赴長橋，誰看浸髮題春竹。","竺僧前立當吾門，梵宮真相眉稜尊。","古琴大軫長八尺，嶧陽老樹非桐孫。","涼館聞弦驚病客，藥囊暫別龍鬚席。","請歌直請卿相歌，奉禮官卑復何益。"]', '["別浦云归桂花渚，蜀国弦中雙鳳語。","芙蓉葉落秋鸾離，越王夜起游天姥。","暗珮清臣敲水玉，渡海蛾眉牽白鹿。","誰看挾劒赴长橋，誰看浸髮題春竹。","竺僧前立當吾门，梵宮真相眉稜尊。","古琴大軫长八尺，嶧陽老樹非桐孫。","涼館闻弦驚病客，藥囊暫別龙鬚席。","請歌直請卿相歌，奉禮官卑复何益。"]', '诗', 'shi', '', NULL, '聽穎師琴歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090c4ddd-409b-4518-b504-db28af790d03', '謠俗', '謠俗', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["上林胡蝶小，試伴漢家君。","飛向南城去，誤落石榴裙。","脈脈花滿樹，翾翾燕遶雲。","出門不識路，羞問陌頭人。"]', '["上林胡蝶小，試伴漢家君。","飞向南城去，誤落石榴裙。","脈脈花满樹，翾翾燕遶云。","出门不識路，羞问陌头人。"]', '诗', 'shi', '', NULL, '謠俗 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e1e940-c5c5-4a9d-bda5-56514b77f862', '靜女春曙曲', '静女春曙曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["嫩葉憐芳抱新蕊，泣露枝枝滴夭淚。","粉窗香咽頹曉雲，錦堆花密藏春睡。","戀屏孔雀搖金尾，鶯舌分明呼婢子。","冰洞寒龍半匣水，一隻商鸞逐煙起。"]', '["嫩葉怜芳抱新蕊，泣露枝枝滴夭泪。","粉窗香咽頹晓云，錦堆花密藏春睡。","戀屏孔雀搖金尾，鶯舌分明呼婢子。","冰洞寒龙半匣水，一隻商鸾逐煙起。"]', '诗', 'shi', '', NULL, '靜女春曙曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2b5ac48-6bb1-4334-a16c-df4735d0b339', '少年樂', '少年乐', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["芳草落花如錦地，二十長遊醉鄉裏。","紅纓不動白馬驕，垂柳金絲香拂水。","吳娥未笑花不開，綠鬢聳墮蘭雲起。","陸郎倚醉牽羅袂，奪得寶釵金翡翠。"]', '["芳草落花如錦地，二十长游醉乡裏。","紅纓不动白马驕，垂柳金絲香拂水。","吳娥未笑花不开，綠鬢聳墮蘭云起。","陸郎倚醉牽羅袂，奪得寶釵金翡翠。"]', '诗', 'shi', '', NULL, '少年樂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0694187-a3f6-45b6-891d-559eec2f8846', '句', '句', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["不見山巔樹，摧杌下爲薪。","日覩井中泥，上出作埃塵。","情知一丘趣，不謝千里印。","倚劍登高臺，悠悠送春目。"]', '["不见山巔樹，摧杌下爲薪。","日覩井中泥，上出作埃塵。","情知一丘趣，不謝千里印。","倚劍登高台，悠悠送春目。"]', '诗', 'shi', '', NULL, '句 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15b64bb3-bf4c-4fb0-a085-6e77003ee595', '冰柱', '冰柱', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["師干久不息，農爲兵兮民重嗟。","騷然縣宇，土崩水潰。","畹中無熟穀，壠上無桑麻。","王春判序，百卉茁甲含葩。","有客避兵奔遊僻，跋履險阨至三巴。","貂裘蒙茸已敝縷，鬢髮蓬舥。","雀驚鼠伏，寧遑安處。","獨臥旅舍無好夢，更堪走風沙。","天人一夜剪瑛琭，詰旦都成六出花。","南畝未盈尺，纖片亂舞空紛拏。","旋落旋逐朝暾化，簷間冰柱若削出交加。","或低或昂，小大瑩潔。","隨勢無等差，始疑玉龍下界來人世。","齊向茅簷布爪牙，又疑漢高帝。","西方未斬虵，人不識，誰爲當風杖莫邪。","鏗鏜冰有韻，的皪玉無瑕。","不爲四時雨，徒於道路成泥柤。","不爲九江浪，徒爲汩沒天之涯。","不爲雙井水，滿甌泛泛烹春茶。","不爲中山漿，清新馥鼻盈百車。","不爲池與沼，養魚種芰成霪䨟。","不爲醴泉與甘露，使名異瑞世俗誇。","特稟朝澈氣，潔然自許靡間其邇遐。","森然氣結一千里，滴瀝聲沈十萬家。","明也雖小，暗之大不可遮。","勿被曲瓦，直下不能抑羣邪。","奈何時逼，不得時在我目中。","倏然漂去無餘㱔，自是成毀任天理。","天於此物豈宜有忒賒，反令井蛙壁蟲變容易。","背人縮首競呀呀，我願天子回造化。","藏之韞櫝翫之生光華。"]', '["師干久不息，農爲兵兮民重嗟。","騷然縣宇，土崩水潰。","畹中無熟穀，壠上無桑麻。","王春判序，百卉茁甲含葩。","有客避兵奔游僻，跋履險阨至三巴。","貂裘蒙茸已敝縷，鬢髮蓬舥。","雀驚鼠伏，寧遑安处。","独臥旅舍無好梦，更堪走风沙。","天人一夜剪瑛琭，詰旦都成六出花。","南畝未盈尺，纖片亂舞空紛拏。","旋落旋逐朝暾化，簷间冰柱若削出交加。","或低或昂，小大瑩潔。","隨勢無等差，始疑玉龙下界来人世。","齊向茅簷布爪牙，又疑漢高帝。","西方未斬虵，人不識，誰爲當风杖莫邪。","鏗鏜冰有韻，的皪玉無瑕。","不爲四时雨，徒於道路成泥柤。","不爲九江浪，徒爲汩沒天之涯。","不爲雙井水，满甌泛泛烹春茶。","不爲中山漿，清新馥鼻盈百车。","不爲池與沼，養鱼種芰成霪䨟。","不爲醴泉與甘露，使名異瑞世俗誇。","特稟朝澈氣，潔然自許靡间其邇遐。","森然氣結一千里，滴瀝声沈十万家。","明也雖小，暗之大不可遮。","勿被曲瓦，直下不能抑羣邪。","奈何时逼，不得时在我目中。","倏然漂去無餘㱔，自是成毀任天理。","天於此物豈宜有忒賒，反令井蛙壁蟲变容易。","背人縮首競呀呀，我願天子回造化。","藏之韞櫝翫之生光华。"]', '诗', 'shi', '', NULL, '冰柱 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2476df2-cdf0-4858-ac5c-4701e1448249', '雪車', '雪车', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["臘令凝綈三十日，繽紛密雪一復一。","孰云潤澤在枯荄，闤闠餓民涷欲死。","死中猶被豺狼食，官車初還城壘未完備。","人家千里無煙火，雞犬何太怨。","天不卹吾甿，如何連夜瑤花亂。","皎潔既同君子節，沾濡多著小人面。","寒鏁侯門見客稀，色迷塞路行商斷。","小小細細如塵間，輕輕緩緩成樸簌。","官家不知民餒寒，盡驅牛車盈道載屑玉。","載載欲何之，祕藏深宮以禦炎酷。","徒能自衛九重間，豈信車轍血，點點盡是農夫哭。","刀兵殘喪後，滿野誰爲載白骨。","遠戍久乏糧，太倉誰爲運紅粟。","戎夫尚逆命，扁箱鹿角誰爲敵。","士夫困征討，買花載酒誰爲適。","天子端然少旁求，股肱耳目皆姦慝。","依違用事佞上方，猶驅餓民運造化防暑阨。","吾聞躬耕南畝舜之聖，爲民吞蝗唐之德。","未聞𭐁孽苦蒼生，相羣相黨上下爲蟊賊。","廟堂食祿不自慙，我爲斯民歎息還歎息。"]', '["臘令凝綈三十日，繽紛密雪一复一。","孰云潤澤在枯荄，闤闠餓民涷欲死。","死中猶被豺狼食，官车初還城壘未完備。","人家千里無煙火，雞犬何太怨。","天不卹吾甿，如何連夜瑤花亂。","皎潔既同君子節，沾濡多著小人面。","寒鏁侯门见客稀，色迷塞路行商斷。","小小細細如塵间，轻轻緩緩成樸簌。","官家不知民餒寒，尽驱牛车盈道載屑玉。","載載欲何之，祕藏深宮以禦炎酷。","徒能自衛九重间，豈信车轍血，点点尽是農夫哭。","刀兵殘喪後，满野誰爲載白骨。","远戍久乏糧，太倉誰爲運紅粟。","戎夫尚逆命，扁箱鹿角誰爲敵。","士夫困征討，買花載酒誰爲適。","天子端然少旁求，股肱耳目皆姦慝。","依違用事佞上方，猶驱餓民運造化防暑阨。","吾闻躬耕南畝舜之聖，爲民吞蝗唐之德。","未闻𭐁孽苦蒼生，相羣相黨上下爲蟊賊。","廟堂食祿不自慙，我爲斯民歎息還歎息。"]', '诗', 'shi', '', NULL, '雪車 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d3175cc-c64d-43f3-b4ad-71520347a41b', '修養', '修養', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["損神終日談虛空，不必歸命于胎中。","我神不西亦不東，煙收雲散何濛濛。","嘗令體如微微風，綿綿不斷道自沖。","世人逢一不逢一，一回存想一回出。","只知一切望一切，不覺一日損一日。","勸君修真復識真，世上道人多忤人。","披圖醮錄益亂神，此法那能堅此身。","心田自有靈地珍，惜哉自有不自親，明真汩沒隨埃塵。"]', '["損神終日談虛空，不必归命于胎中。","我神不西亦不东，煙收云散何濛濛。","嘗令體如微微风，綿綿不斷道自沖。","世人逢一不逢一，一回存想一回出。","只知一切望一切，不覺一日損一日。","勸君修真复識真，世上道人多忤人。","披圖醮錄益亂神，此法那能堅此身。","心田自有靈地珍，惜哉自有不自親，明真汩沒隨埃塵。"]', '诗', 'shi', '', NULL, '修養 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c2c7e1c-d794-41d1-9881-b5f10f3091b0', '勿執古寄韓潮州', '勿執古寄韓潮州', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["古人皆執古，不辭[凍]餓悲。","今人亦執古，自取行坐危。","老菊凌霜葩，獰松抱雪姿。","武王亦至明，寧哀首陽飢。","仲尼豈非聖，但爲互鄉嗤。","寸心生萬路，今古棼若絲。","逐逐行不盡，茫茫休者誰。","來恨不可遏，去悔何足追。","玉石共笑唾，駑驥相奔馳。","請君勿執古，執古徒自隳。"]', '["古人皆執古，不辞[凍]餓悲。","今人亦執古，自取行坐危。","老菊凌霜葩，獰松抱雪姿。","武王亦至明，寧哀首陽飢。","仲尼豈非聖，但爲互乡嗤。","寸心生万路，今古棼若絲。","逐逐行不尽，茫茫休者誰。","来恨不可遏，去悔何足追。","玉石共笑唾，駑驥相奔驰。","請君勿執古，執古徒自隳。"]', '诗', 'shi', '', NULL, '勿執古寄韓潮州 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079d8703-4f09-470f-befa-99a4ac7b8064', '荅孟東野', '荅孟东野', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["酸寒孟夫子，苦愛老叉詩。","生澀有百篇，謂是瓊瑤辭。","百篇非所長，憂來豁窮悲。","唯有剛腸鐵，百鍊不柔虧。","退之何可駡，東野何可欺。","文王已云沒，誰顧好爵縻。","生死守一丘，寧計飽與飢。","萬事付杯酒，從人笑狂癡。"]', '["酸寒孟夫子，苦愛老叉诗。","生澀有百篇，謂是瓊瑤辞。","百篇非所长，憂来豁窮悲。","唯有剛腸鐵，百鍊不柔虧。","退之何可駡，东野何可欺。","文王已云沒，誰顧好爵縻。","生死守一丘，寧計飽與飢。","万事付杯酒，從人笑狂癡。"]', '诗', 'shi', '', NULL, '荅孟東野 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c8b0e2e-4661-4642-a715-00d396d90cbd', '自古無長生勸姚合酒', '自古無长生勸姚合酒', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["奉子一杯酒，爲子照顏色。","但願腮上紅，莫管頦下白。","自古無長生，生者何戚戚。","登山勿厭高，四望都無極。","丘隴逐日多，天地爲我窄。","祗見李耳書，對之空脈脈。","何曾見天上，著得劉安宅。","若問長生人，昭昭孔丘籍。"]', '["奉子一杯酒，爲子照顏色。","但願腮上紅，莫管頦下白。","自古無长生，生者何戚戚。","登山勿厭高，四望都無極。","丘隴逐日多，天地爲我窄。","祗见李耳书，对之空脈脈。","何曾见天上，著得劉安宅。","若问长生人，昭昭孔丘籍。"]', '诗', 'shi', '', NULL, '自古無長生勸姚合酒 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f234b77-2534-4c6b-b520-f0777a31f3d1', '獨飲', '独饮', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["盡欲調太羹，自古無好手。","所以山中人，兀兀但飲酒。"]', '["尽欲調太羹，自古無好手。","所以山中人，兀兀但饮酒。"]', '诗', 'shi', '', NULL, '獨飲 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606b2f00-9ff0-4a2d-b063-af31f8ea1b5f', '作詩', '作诗', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["作詩無知音，作不如不作。","未逢賡載人，此道終寂寞。","有虞今已歿，來者誰爲託。","朗詠豁心胸，筆與淚俱落。"]', '["作诗無知音，作不如不作。","未逢賡載人，此道終寂寞。","有虞今已歿，来者誰爲託。","朗詠豁心胸，笔與泪俱落。"]', '诗', 'shi', '', NULL, '作詩 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b40d5d7a-e7ab-4119-b8ca-3c6ebbe9f557', '天津橋', '天津橋', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["洛陽宮闕照天地，四面山川無毒氣。","誰令漢祖都秦關，從此姦雄轉相熾。"]', '["洛陽宮闕照天地，四面山川無毒氣。","誰令漢祖都秦关，從此姦雄轉相熾。"]', '诗', 'shi', '', NULL, '天津橋 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce98907-9e83-4f28-8bb3-2362ae4e8e79', '嘲荆卿', '嘲荆卿', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["白虹千里氣，血頸一劒義。","報恩不到頭，徒作輕生士。"]', '["白虹千里氣，血頸一劒義。","報恩不到头，徒作轻生士。"]', '诗', 'shi', '', NULL, '嘲荆卿 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85af0312-9510-454d-afe8-b82853cba420', '代牛言', '代牛言', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["渴飲潁水流，餓喘吳門月。","黃金如可種，我力終不竭。"]', '["渴饮潁水流，餓喘吳门月。","黄金如可種，我力終不竭。"]', '诗', 'shi', '', NULL, '代牛言 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d996038d-4df8-41f4-8af6-162acb4f27b2', '莫問卜', '莫问卜', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["莫問卜，人生吉凶皆自速。","伏羲文王若無死，今人不爲古人哭。"]', '["莫问卜，人生吉凶皆自速。","伏羲文王若無死，今人不爲古人哭。"]', '诗', 'shi', '', NULL, '莫問卜 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5eecaf-79f1-484c-93e2-8e28fb3c0816', '觀八駿圖', '观八駿圖', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["穆王八駿走不歇，海外去尋長日月。","五雲望斷阿母宮，歸來落得新白髮。"]', '["穆王八駿走不歇，海外去尋长日月。","五云望斷阿母宮，归来落得新白髮。"]', '诗', 'shi', '', NULL, '觀八駿圖 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('050e1015-1d53-45c5-b538-623ee654739e', '經戰地', '經戰地', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["殺氣不上天，陰風吹雨血。","冤魂不入地，髑髏哭沙月。","人命固有常，此地何夭折。"]', '["殺氣不上天，陰风吹雨血。","冤魂不入地，髑髏哭沙月。","人命固有常，此地何夭折。"]', '诗', 'shi', '', NULL, '經戰地 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be87407-badb-43ad-818f-ae1cc5912e5d', '野哭', '野哭', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["棘針生獰義路閑，野泉相弔聲潺潺。","哀哉異教溺頹俗，淳源一去何時還。"]', '["棘針生獰義路闲，野泉相弔声潺潺。","哀哉異教溺頹俗，淳源一去何时還。"]', '诗', 'shi', '', NULL, '野哭 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49b1dcf3-10cf-418c-b0ea-0ad13c57c113', '古怨', '古怨', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["君莫嫌醜婦，醜婦死守貞。","山頭一怪石，長作望夫名。","鳥有並翼飛，獸有比肩行。","丈夫不立義，豈如鳥獸情。"]', '["君莫嫌醜婦，醜婦死守貞。","山头一怪石，长作望夫名。","鸟有並翼飞，獸有比肩行。","丈夫不立義，豈如鸟獸情。"]', '诗', 'shi', '', NULL, '古怨 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96236616-17cf-4ad6-ae80-f61082920c1c', '烈士詠', '烈士詠', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["烈士或愛金，愛金不爲貧。","義死天亦許，利生鬼亦嗔。","胡爲輕薄兒，使酒殺平人。"]', '["烈士或愛金，愛金不爲貧。","義死天亦許，利生鬼亦嗔。","胡爲轻薄兒，使酒殺平人。"]', '诗', 'shi', '', NULL, '烈士詠 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('677e4fd6-dc66-4cb1-836a-ec7acc9efbfd', '狂夫', '狂夫', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["大妻唱舜歌，小妻鼓湘瑟。","狂夫遊冶歸，端坐仍作色。","不讀關雎篇，安知后妃德。"]', '["大妻唱舜歌，小妻鼓湘瑟。","狂夫游冶归，端坐仍作色。","不读关雎篇，安知后妃德。"]', '诗', 'shi', '', NULL, '狂夫 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366a64be-3fe0-40ae-a68f-7d4b7cc07d8c', '餓詠', '餓詠', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["文王久不出，賢士如土賤。","妻孥從餓死，敢愛黃金篆。"]', '["文王久不出，賢士如土賤。","妻孥從餓死，敢愛黄金篆。"]', '诗', 'shi', '', NULL, '餓詠 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e053f9c5-6d2d-49e8-ae48-0a088e092a90', '自問', '自问', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["自問彭城子，何人授汝顛。","酒腸寬似海，詩膽大於天。","斷劒徒勞匣，枯琴無復弦。","相逢不多合，賴是向林泉。"]', '["自问彭城子，何人授汝顛。","酒腸寬似海，诗膽大於天。","斷劒徒勞匣，枯琴無复弦。","相逢不多合，賴是向林泉。"]', '诗', 'shi', '', NULL, '自問 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3f3d740-0b8d-40ba-ac34-e31f181a780a', '入蜀', '入蜀', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["望空問真宰，此路爲誰開。","峽色侵天去，江聲滾地來。","孔明深有意，鍾會亦何才。","信此非人事，悲歌付一杯。"]', '["望空问真宰，此路爲誰开。","峽色侵天去，江声滾地来。","孔明深有意，鍾會亦何才。","信此非人事，悲歌付一杯。"]', '诗', 'shi', '', NULL, '入蜀 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4330b62-6af0-4f81-81b7-6987aae2d27c', '塞上逢盧仝', '塞上逢盧仝', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["直到桑乾北，逢君夜不眠。","上樓腰脚健，懷土眼睛穿。","斗柄寒垂地，河流[凍]徹天。","羈魂泣相向，何事有詩篇。"]', '["直到桑乾北，逢君夜不眠。","上楼腰脚健，懷土眼睛穿。","斗柄寒垂地，河流[凍]徹天。","羈魂泣相向，何事有诗篇。"]', '诗', 'shi', '', NULL, '塞上逢盧仝 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4cf7b5-bbe2-4d5a-b477-84e8f83f766f', '偶書', '偶书', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["日出扶桑一丈高，人間萬事細如毛。","野夫怒見不平處，磨損胸中萬古刀。"]', '["日出扶桑一丈高，人间万事細如毛。","野夫怒见不平处，磨損胸中万古刀。"]', '诗', 'shi', '', NULL, '偶書 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('257f4489-b3b3-4d7f-b58d-4cae8b7b7b48', '愛碣山石', '愛碣山石', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["碣石何青青，挽我雙眼睛。","愛爾多古峭，不到人間行。"]', '["碣石何青青，挽我雙眼睛。","愛爾多古峭，不到人间行。"]', '诗', 'shi', '', NULL, '愛碣山石 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c335d0-4a26-4d20-9e5d-2e9af410fc26', '與孟東野', '與孟东野', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["寒衣草木皮，飢飯葵藿根。","不爲孟夫子，豈識市井門。"]', '["寒衣草木皮，飢飯葵藿根。","不爲孟夫子，豈識市井门。"]', '诗', 'shi', '', NULL, '與孟東野 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039c28a3-da91-4375-8060-e61bbc52ad40', '姚秀才愛予小劒因贈', '姚秀才愛予小劒因贈', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["一條古時水，向我手心流。","臨行瀉贈君，勿薄細碎讐。"]', '["一條古时水，向我手心流。","臨行瀉贈君，勿薄細碎讐。"]', '诗', 'shi', '', NULL, '姚秀才愛予小劒因贈 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a14f435a-c28e-46f8-8ccc-4b5e1760a3d0', '老恨', '老恨', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["雪打杉松殘，補書書不完。","嬾學渭上翁，辛苦把釣竿。"]', '["雪打杉松殘，補书书不完。","嬾学渭上翁，辛苦把釣竿。"]', '诗', 'shi', '', NULL, '老恨 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a29dfca-8f3f-421d-a0da-2cc6fc67ef12', '思歸樂', '思归乐', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["山中思歸樂，盡作思歸鳴。","爾是此山鳥，安得失鄉名。","應緣此山路，自古離人征。","陰愁感和氣，俾爾從此生。","我雖失鄉去，我無失鄉情。","慘舒在方寸，寵辱將何驚。","浮生居大塊，尋丈可寄形。","身安即形樂，豈獨樂咸京。","命者道之本，死者天之平。","安問遠與近，何言殤與彭。","君看趙工部，八十支體輕。","交州二十載，一到長安城。","長安不須臾，復作交州行。","交州又累歲，移鎮廣與荆。","歸朝新天子，濟濟爲上卿。","肌膚無瘴色，飲食康且寧。","長安一晝夜，死者如霣星。","喪車四門出，何關炎瘴縈。","況我三十二，百年未半程。","江陵道塗近，楚俗雲水清。","遐想玉泉寺，久聞峴山亭。","此去盡綿歷，豈無心賞幷。","紅餐日充腹，碧澗朝析酲。","開門待賓客，寄書安弟兄。","閑窮四聲韻，悶閱九部經。","身外皆委順，眼前隨所營。","此意久已定，誰能求苟榮。","所以官甚小，不畏權勢傾。","傾心豈不易，巧詐神之刑。","萬物有本性，況復人性靈。","金埋無土色，玉墜無瓦聲。","劒折有寸利，鏡破有片明。","我可俘爲囚，我可刃爲兵。","我心終不死，金石貫以誠。","此誠患不至，誠至道亦亨。","微哉滿山鳥，呌噪何足聽。"]', '["山中思归乐，尽作思归鳴。","爾是此山鸟，安得失乡名。","應緣此山路，自古離人征。","陰愁感和氣，俾爾從此生。","我雖失乡去，我無失乡情。","慘舒在方寸，寵辱將何驚。","浮生居大塊，尋丈可寄形。","身安即形乐，豈独乐咸京。","命者道之本，死者天之平。","安问远與近，何言殤與彭。","君看趙工部，八十支體轻。","交州二十載，一到长安城。","长安不須臾，复作交州行。","交州又累歲，移鎮廣與荆。","归朝新天子，濟濟爲上卿。","肌膚無瘴色，饮食康且寧。","长安一晝夜，死者如霣星。","喪车四门出，何关炎瘴縈。","況我三十二，百年未半程。","江陵道塗近，楚俗云水清。","遐想玉泉寺，久闻峴山亭。","此去尽綿歷，豈無心賞幷。","紅餐日充腹，碧澗朝析酲。","开门待賓客，寄书安弟兄。","闲窮四声韻，悶閱九部經。","身外皆委順，眼前隨所營。","此意久已定，誰能求苟榮。","所以官甚小，不畏權勢傾。","傾心豈不易，巧詐神之刑。","万物有本性，況复人性靈。","金埋無土色，玉墜無瓦声。","劒折有寸利，镜破有片明。","我可俘爲囚，我可刃爲兵。","我心終不死，金石貫以誠。","此誠患不至，誠至道亦亨。","微哉满山鸟，呌噪何足听。"]', '诗', 'shi', '', NULL, '思歸樂 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ebe174-7a53-4aee-aa19-4eddbee497eb', '春鳩', '春鳩', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春鳩與百舌，音響詎同年。","如何一時語，俱得春風憐。","猶知化工意，當春不生蟬。","免教爭呌噪，沸渭桃花前。"]', '["春鳩與百舌，音响詎同年。","如何一时語，俱得春风怜。","猶知化工意，當春不生蟬。","免教爭呌噪，沸渭桃花前。"]', '诗', 'shi', '', NULL, '春鳩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9607c64e-762e-4d27-a30f-353287826d55', '春蟬', '春蟬', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我自東歸日，厭苦春鳩聲。","作詩憐化工，不遣春蟬生。","及來商山道，山深氣不平。","春秋兩相似，蟲豸百種鳴。","風松不成韻，蜩螗沸如羹。","豈無朝陽鳳，羞與微物爭。","安得天上雨，奔渾河海傾。","蕩滌反時氣，然後好晴明。"]', '["我自东归日，厭苦春鳩声。","作诗怜化工，不遣春蟬生。","及来商山道，山深氣不平。","春秋兩相似，蟲豸百種鳴。","风松不成韻，蜩螗沸如羹。","豈無朝陽鳳，羞與微物爭。","安得天上雨，奔渾河海傾。","蕩滌反时氣，然後好晴明。"]', '诗', 'shi', '', NULL, '春蟬 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('393238aa-5671-4a79-ba77-4ee2f61b4ecd', '兔絲', '兔絲', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["人生莫依倚，依倚事不成。","君看兔絲蔓，依倚榛與荆。","荆榛易蒙密，百鳥撩亂鳴。","下有狐兔穴，奔走亦縱橫。","樵童斫將去，柔蔓與之幷。","翳薈生可恥，束縛死無名。","桂樹月中出，珊瑚石上生。","俊鶻度海食，應龍升天行。","靈物本特達，不復相纏縈。","纏縈竟何者，荆棘與飛莖。"]', '["人生莫依倚，依倚事不成。","君看兔絲蔓，依倚榛與荆。","荆榛易蒙密，百鸟撩亂鳴。","下有狐兔穴，奔走亦縱橫。","樵童斫將去，柔蔓與之幷。","翳薈生可恥，束縛死無名。","桂樹月中出，珊瑚石上生。","俊鶻度海食，應龙升天行。","靈物本特達，不复相纏縈。","纏縈竟何者，荆棘與飞莖。"]', '诗', 'shi', '', NULL, '兔絲 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b38d0371-cb80-445a-b403-dd45f14735c0', '古社', '古社', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["古社基阯在，人散社不神。","惟有空心樹，妖狐藏魅人。","狐惑意顛倒，臊腥不復聞。","丘墳變城郭，花草仍荆榛。","良田千萬頃，占作天荒田。","主人議芟斫，怪見不敢前。","那言空山燒，夜隨風馬奔。","飛聲鼓鼙震，高燄旗幟飜。","逡巡荆棘盡，狐兔無子孫。","狐死魅人滅，煙消壇墠存。","繞壇舊田地，給授有等倫。","農收邨落盛，社樹新團圓。","社公千萬歲，永保邨中民。"]', '["古社基阯在，人散社不神。","惟有空心樹，妖狐藏魅人。","狐惑意顛倒，臊腥不复闻。","丘墳变城郭，花草仍荆榛。","良田千万頃，占作天荒田。","主人議芟斫，怪见不敢前。","那言空山燒，夜隨风马奔。","飞声鼓鼙震，高燄旗幟飜。","逡巡荆棘尽，狐兔無子孫。","狐死魅人滅，煙消壇墠存。","繞壇旧田地，給授有等倫。","農收邨落盛，社樹新團圓。","社公千万歲，永保邨中民。"]', '诗', 'shi', '', NULL, '古社 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06235d6c-7a5b-4c35-beb0-d39a618f3ac9', '松樹', '松樹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["華山高幢幢，上有高高松。","株株遙各各，葉葉相重重。","槐樹夾道植，枝葉俱冥蒙。","既無貞直榦，復有罥挂蟲。","何不種松樹，使之搖清風。","秦時已曾種，顦顇種不供。","可憐孤松意，不與槐樹同。","閑在高山頂，樛盤虯與龍。","屈爲大廈棟，庇蔭侯與公。","不肯作行伍，俱在塵土中。"]', '["华山高幢幢，上有高高松。","株株遙各各，葉葉相重重。","槐樹夾道植，枝葉俱冥蒙。","既無貞直榦，复有罥挂蟲。","何不種松樹，使之搖清风。","秦时已曾種，顦顇種不供。","可怜孤松意，不與槐樹同。","闲在高山頂，樛盤虯與龙。","屈爲大廈棟，庇蔭侯與公。","不肯作行伍，俱在塵土中。"]', '诗', 'shi', '', NULL, '松樹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c950fba-cec7-4ba4-88c5-1dc0c53d6fc3', '芳樹', '芳樹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["芳樹已寥落，孤英尤可嘉。","可憐團團葉，蓋覆深深花。","遊蜂競鑽刺，鬬雀亦紛拏。","天生細碎物，不愛好華光。","非無殲殄法，念爾有生涯。","春雷一聲發，驚燕亦驚蛇。","清池養神蔡，已復長蝦蟇。","雨露貴平施，吾其春草芽。"]', '["芳樹已寥落，孤英尤可嘉。","可怜團團葉，蓋覆深深花。","游蜂競鑽刺，鬬雀亦紛拏。","天生細碎物，不愛好华光。","非無殲殄法，念爾有生涯。","春雷一声發，驚燕亦驚蛇。","清池養神蔡，已复长蝦蟇。","雨露貴平施，吾其春草芽。"]', '诗', 'shi', '', NULL, '芳樹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8a399d1-a4cb-465e-8fb9-94b6c70f95f0', '桐花', '桐花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["朧月上山館，紫桐垂好陰。","可惜暗澹色，無人知此心。","舜沒蒼梧野，鳳歸丹穴岑。","遺落在人世，光華那復深。","年年怨春意，不競桃杏林。","唯占清明後，牡丹還復侵。","況此空館閉，云誰恣幽尋。","徒煩鳥噪集，不語山嶔岑。","滿院青苔地，一樹蓮花簪。","自開還自落，暗芳終暗沈。","爾生不得所，我願裁爲琴。","安置君王側，調和元首音。","安問宮徵角，先辨雅鄭淫。","宮弦春以君，君若春日臨。","商弦廉以臣，臣作旱天霖。","人安角聲暢，人困鬬不任。","羽以類萬物，祆物神不歆。","徵以節百事，奉事罔不欽。","五者苟不亂，天命乃可忱。","君若問孝理，彈作梁山吟。","君若事宗廟，拊以和球琳。","君若不好諫，願獻觸疏箴。","君若不罷獵，請聽荒于禽。","君若侈臺殿，雍門可霑襟。","君若傲賢雋，鹿鳴有食芩。","君聞祈招什，車馬勿駸駸。","君若欲敗度，中有式如金。","君聞薰風操，志氣在愔愔。","中有阜財語，勿受來獻賝。","北里當絕聽，禍莫大於婬。","南風苟不競，無往遺之擒。","姦聲不入耳，巧言寧孔壬。","梟音亦云革，安得沴與祲。","天子既穆穆，羣材亦森森。","劒士還農野，絲人歸織紝。","丹鳳巢阿閣，文魚游碧潯。","和氣浹寰海，易若溉蹄[涔]。","改張乃可鼓，此語無古今。","非琴獨能爾，事有諭因鍼。","感爾桐花意，閑怨杳難禁。","待我持斤斧，置君爲大琛。"]', '["朧月上山館，紫桐垂好陰。","可惜暗澹色，無人知此心。","舜沒蒼梧野，鳳归丹穴岑。","遺落在人世，光华那复深。","年年怨春意，不競桃杏林。","唯占清明後，牡丹還复侵。","況此空館閉，云誰恣幽尋。","徒煩鸟噪集，不語山嶔岑。","满院青苔地，一樹蓮花簪。","自开還自落，暗芳終暗沈。","爾生不得所，我願裁爲琴。","安置君王側，調和元首音。","安问宮徵角，先辨雅鄭淫。","宮弦春以君，君若春日臨。","商弦廉以臣，臣作旱天霖。","人安角声暢，人困鬬不任。","羽以類万物，祆物神不歆。","徵以節百事，奉事罔不欽。","五者苟不亂，天命乃可忱。","君若问孝理，彈作梁山吟。","君若事宗廟，拊以和球琳。","君若不好諫，願獻觸疏箴。","君若不罷獵，請听荒于禽。","君若侈台殿，雍门可霑襟。","君若傲賢雋，鹿鳴有食芩。","君闻祈招什，车马勿駸駸。","君若欲敗度，中有式如金。","君闻薰风操，志氣在愔愔。","中有阜財語，勿受来獻賝。","北里當絕听，禍莫大於婬。","南风苟不競，無往遺之擒。","姦声不入耳，巧言寧孔壬。","梟音亦云革，安得沴與祲。","天子既穆穆，羣材亦森森。","劒士還農野，絲人归织紝。","丹鳳巢阿閣，文鱼游碧潯。","和氣浹寰海，易若溉蹄[涔]。","改張乃可鼓，此語無古今。","非琴独能爾，事有諭因鍼。","感爾桐花意，闲怨杳难禁。","待我持斤斧，置君爲大琛。"]', '诗', 'shi', '', NULL, '桐花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a9478ae-d31f-4585-b661-148d0ed6a26e', '雉媒', '雉媒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雙雉在野時，可憐同嗜欲。","毛衣前後成，一種文章足。","一雉獨先飛，衝開芳草綠。","網羅幽草中，暗被潛羈束。","剪刀摧六翮，絲線縫雙目。","啖養能幾時，依然已馴熟。","都無舊性靈，返與他心腹。","置在芳草中，翻令誘同族。","前時相失者，思君意彌篤。","朝朝舊處飛，往往巢邊哭。","今朝樹上啼，哀音斷還續。","遠見爾文章，知君草中伏。","和鳴忽相召，鼓翅遙相矚。","畏我未肯來，又啄翳前粟。","歛翮遠投君，飛馳勢奔蹙。","罥挂在君前，向君聲促促。","信君決無疑，不道君相覆。","自恨飛太高，疎羅偶然觸。","看看架上鷹，擬食無罪肉。","君意定何如，依舊雕籠宿。"]', '["雙雉在野时，可怜同嗜欲。","毛衣前後成，一種文章足。","一雉独先飞，衝开芳草綠。","網羅幽草中，暗被潛羈束。","剪刀摧六翮，絲線縫雙目。","啖養能幾时，依然已馴熟。","都無旧性靈，返與他心腹。","置在芳草中，翻令誘同族。","前时相失者，思君意彌篤。","朝朝旧处飞，往往巢邊哭。","今朝樹上啼，哀音斷還續。","远见爾文章，知君草中伏。","和鳴忽相召，鼓翅遙相矚。","畏我未肯来，又啄翳前粟。","歛翮远投君，飞驰勢奔蹙。","罥挂在君前，向君声促促。","信君決無疑，不道君相覆。","自恨飞太高，疎羅偶然觸。","看看架上鷹，擬食無罪肉。","君意定何如，依旧雕籠宿。"]', '诗', 'shi', '', NULL, '雉媒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b435b155-568b-402a-bf90-fcff2881aabd', '箭鏃', '箭鏃', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["箭鏃本求利，淬礪良甚難。","礪將何所用，礪以射凶殘。","不礪射不入，不射人不安。","爲盜即當射，寧問私與官。","夜射官中盜，中之血闌干。","帶箭君前訴，君王悄不歡。","頃曾爲盜者，百箭中心攢。","競將兒女淚，滴瀝助辛酸。","君王責良帥，此禍誰爲端。","帥言發硎罪，不使刃稍刓。","君王不忍殺，逐之如迸丸。","仍令後來箭，盡可頭團團。","發硎去雖遠，礪鏃心不闌。","會射蛟螭盡，舟行無惡瀾。"]', '["箭鏃本求利，淬礪良甚难。","礪將何所用，礪以射凶殘。","不礪射不入，不射人不安。","爲盜即當射，寧问私與官。","夜射官中盜，中之血闌干。","带箭君前訴，君王悄不歡。","頃曾爲盜者，百箭中心攢。","競將兒女泪，滴瀝助辛酸。","君王責良帥，此禍誰爲端。","帥言發硎罪，不使刃稍刓。","君王不忍殺，逐之如迸丸。","仍令後来箭，尽可头團團。","發硎去雖远，礪鏃心不闌。","會射蛟螭尽，舟行無惡瀾。"]', '诗', 'shi', '', NULL, '箭鏃 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3b191f6-3b5b-42bc-bb0e-dc0421c9df0e', '賽神', '賽神', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["邨落事妖神，林木大如邨。","事來三十載，巫覡傳子孫。","邨中四時祭，殺盡雞與豚。","主人不堪命，積燎曾欲燔。","旋風天地轉，急雨江河翻。","採薪持斧者，棄斧縱橫奔。","山深多掩暎，僅免鯨鯢吞。","主人集鄰里，各各持酒罇。","廟中再三拜，願得禾稼存。","去年大巫死，小覡又妖言。","邑中神明宰，有意效西門。","焚除計未決，伺者迭乘軒。","廟深荆棘厚，但見狐兔蹲。","巫言小神變，可驗牛馬蕃。","邑吏齊進說，幸勿禍鄉原。","踰年計不定，縣聽良亦煩。","涉夏祭時至，因令修四垣。","憂虞神憤恨，玉帛意彌敦。","我來神廟下，簫鼓正喧喧。","因言遣妖術，滅絕由本根。","主人中罷舞，許我重疊論。","蜉蝣生溼處，鴟鴞集黃昏。","主人邪心起，氣燄日夜繁。","狐貍得蹊徑，潛穴主人園。","腥臊襲左右，然後託丘樊。","歲深樹成就，曲直可輪轅。","幽妖盡依倚，萬怪之所屯。","主人一心好，四面無籬藩。","命樵執斤斧，怪木寧遽髠。","主人且傾聽，再爲諭清渾。","阿膠在末派，罔象游上源。","靈藥逡巡盡，黑波朝夕噴。","神龍厭流濁，先伐鼉與黿。","黿鼉在龍穴，妖氣常鬱溫。","主人惡淫祀，先去邪與惛。","惛邪中人意，蠱禍蝕精魂。","德勝妖不作，勢強威亦尊。","計窮然後賽，後賽復何恩。"]', '["邨落事妖神，林木大如邨。","事来三十載，巫覡傳子孫。","邨中四时祭，殺尽雞與豚。","主人不堪命，積燎曾欲燔。","旋风天地轉，急雨江河翻。","採薪持斧者，棄斧縱橫奔。","山深多掩暎，僅免鯨鯢吞。","主人集鄰里，各各持酒罇。","廟中再三拜，願得禾稼存。","去年大巫死，小覡又妖言。","邑中神明宰，有意效西门。","焚除計未決，伺者迭乘軒。","廟深荆棘厚，但见狐兔蹲。","巫言小神变，可驗牛马蕃。","邑吏齊進说，幸勿禍乡原。","踰年計不定，縣听良亦煩。","涉夏祭时至，因令修四垣。","憂虞神憤恨，玉帛意彌敦。","我来神廟下，簫鼓正喧喧。","因言遣妖術，滅絕由本根。","主人中罷舞，許我重叠論。","蜉蝣生溼处，鴟鴞集黄昏。","主人邪心起，氣燄日夜繁。","狐貍得蹊徑，潛穴主人园。","腥臊襲左右，然後託丘樊。","歲深樹成就，曲直可輪轅。","幽妖尽依倚，万怪之所屯。","主人一心好，四面無籬藩。","命樵執斤斧，怪木寧遽髠。","主人且傾听，再爲諭清渾。","阿膠在末派，罔象游上源。","靈藥逡巡尽，黑波朝夕噴。","神龙厭流濁，先伐鼉與黿。","黿鼉在龙穴，妖氣常鬱溫。","主人惡淫祀，先去邪與惛。","惛邪中人意，蠱禍蝕精魂。","德勝妖不作，勢強威亦尊。","計窮然後賽，後賽复何恩。"]', '诗', 'shi', '', NULL, '賽神 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08155b8d-f4f2-486d-8d3d-b7260482feb1', '大觜烏', '大觜烏', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["陽烏有二類，觜白者名慈。","求食哺慈母，因以此名之。","飲啄頗廉儉，音響亦柔雌。","百巢同一樹，棲宿不復疑。","得食先反哺，一身常苦羸。","緣知五常性，飜被衆禽欺。","其一觜大者，攫搏性貪癡。","有力強如鶻，有爪利如錐。","音響甚㕭嗗，潛通妖怪詞。","受日餘光庇，終天無死期。","翺翔富人屋，棲息屋前枝。","巫言此烏至，財產日豐宜。","主人一心惑，誘引不知疲。","轉見烏來集，自言家轉孳。","白鶴門外養，花鷹架上維。","專聽烏喜怒，信受若神龜。","舉家同此意，彈射不復施。","往往清池側，却令鵷鷺隨。","羣烏飽粱肉，毛羽色澤滋。","遠近恣所往，貪殘無不爲。","巢禽攫雛卵，廐馬啄瘡痍。","滲瀝脂膏盡，鳳皇那得知。","主人一朝病，爭向屋檐窺。","呦鷕呼羣鵩，翩翻集怪鴟。","主人偏養者，嘯聚最奔馳。","夜半仍驚噪，鵂鶹逐老狸。","主人病心怯，燈火夜深移。","左右雖無語，奄然皆淚垂。","平明天出日，陰魅走參差。","烏來屋檐上，又惑主人兒。","兒即當家業，玩好方愛奇。","占募能言鳥，置者許高貲。","隴樹巢鸚鵡，言語好光儀。","美人傾心獻，雕籠身自持。","求者臨軒坐，置在白玉墀。","先問鳥中苦，便言烏若斯。","衆烏齊搏鑠，翠羽幾離披。","遠擲千餘里，美人情亦衰。","舉家懲此患，事烏踰昔時。","向言池上鷺，啄肉寢其皮。","夜漏天終曉，陰雲風定吹。","況爾烏何者，數極不知危。","會結彌天網，盡取一無遺。","常令阿閣上，宛宛宿長離。"]', '["陽烏有二類，觜白者名慈。","求食哺慈母，因以此名之。","饮啄頗廉儉，音响亦柔雌。","百巢同一樹，棲宿不复疑。","得食先反哺，一身常苦羸。","緣知五常性，飜被衆禽欺。","其一觜大者，攫搏性貪癡。","有力強如鶻，有爪利如錐。","音响甚㕭嗗，潛通妖怪词。","受日餘光庇，終天無死期。","翺翔富人屋，棲息屋前枝。","巫言此烏至，財產日豐宜。","主人一心惑，誘引不知疲。","轉见烏来集，自言家轉孳。","白鹤门外養，花鷹架上維。","專听烏喜怒，信受若神龟。","舉家同此意，彈射不复施。","往往清池側，却令鵷鷺隨。","羣烏飽粱肉，毛羽色澤滋。","远近恣所往，貪殘無不爲。","巢禽攫雛卵，廐马啄瘡痍。","滲瀝脂膏尽，鳳皇那得知。","主人一朝病，爭向屋檐窺。","呦鷕呼羣鵩，翩翻集怪鴟。","主人偏養者，嘯聚最奔驰。","夜半仍驚噪，鵂鶹逐老狸。","主人病心怯，灯火夜深移。","左右雖無語，奄然皆泪垂。","平明天出日，陰魅走參差。","烏来屋檐上，又惑主人兒。","兒即當家業，玩好方愛奇。","占募能言鸟，置者許高貲。","隴樹巢鸚鵡，言語好光儀。","美人傾心獻，雕籠身自持。","求者臨軒坐，置在白玉墀。","先问鸟中苦，便言烏若斯。","衆烏齊搏鑠，翠羽幾離披。","远擲千餘里，美人情亦衰。","舉家懲此患，事烏踰昔时。","向言池上鷺，啄肉寢其皮。","夜漏天終晓，陰云风定吹。","況爾烏何者，數極不知危。","會結彌天網，尽取一無遺。","常令阿閣上，宛宛宿长離。"]', '诗', 'shi', '', NULL, '大觜烏 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048200b9-d1cb-4c99-bd0d-69066c944e24', '分水嶺', '分水嶺', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["崔嵬分水嶺，高下與雲平。","上有分流水，東西隨勢傾。","朝同一源出，暮隔千里情。","風雨各自異，波瀾相背驚。","勢高競奔注，勢曲已回縈。","偶值當途石，蹙縮又縱橫。","有時遭孔穴，變作嗚咽聲。","褊淺無所用，奔波奚所營。","團團井中水，不復東西征。","上應美人意，中涵孤月明。","旋風西面起，井深波不生。","堅冰一時合，井深凍不成。","終年汲引絕，不耗復不盈。","五月金石鑠，既寒亦既清。","易時不易性，改邑不改名。","定如拱北極，瑩若燒玉英。","君門客如水，日夜隨勢行。","君看守心者，井水爲君盟。"]', '["崔嵬分水嶺，高下與云平。","上有分流水，东西隨勢傾。","朝同一源出，暮隔千里情。","风雨各自異，波瀾相背驚。","勢高競奔注，勢曲已回縈。","偶值當途石，蹙縮又縱橫。","有时遭孔穴，变作嗚咽声。","褊淺無所用，奔波奚所營。","團團井中水，不复东西征。","上應美人意，中涵孤月明。","旋风西面起，井深波不生。","堅冰一时合，井深凍不成。","終年汲引絕，不耗复不盈。","五月金石鑠，既寒亦既清。","易时不易性，改邑不改名。","定如拱北極，瑩若燒玉英。","君门客如水，日夜隨勢行。","君看守心者，井水爲君盟。"]', '诗', 'shi', '', NULL, '分水嶺 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34cc279f-d8a2-42b0-9549-522d116b8897', '四皓廟', '四皓廟', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["巢由昔避世，堯舜不得臣。","伊呂雖急病，湯武乃可君。","四賢胡爲者，千載名氛氳。","顯晦有遺迹，前後疑不倫。","秦政虐天下，黷武窮生民。","諸侯戰必死，壯士眉亦嚬。","張良韓孺子，椎碎屬車輪。","遂令英雄意，日夜思報秦。","先生相將去，不復嬰世塵。","雲卷在孤岫，龍潛爲小鱗。","秦王轉無道，諫者鼎鑊親。","茅焦脫衣諫，先生無一言。","趙高殺二世，先生如不聞。","劉項取天下，先生游白雲。","海內八年戰，先生全一身。","漢業日已定，先生名亦振。","不得爲濟世，宜哉爲隱淪。","如何一朝起，屈作儲貳賓。","安存孝惠帝，摧顇戚夫人。","舍大以謀細，虯盤而蠖伸。","惠帝竟不嗣，呂氏禍有因。","雖懷安劉志，未若周與陳。","皆落子房術，先生道何屯。","出處貴明白，故吾今有云。"]', '["巢由昔避世，堯舜不得臣。","伊呂雖急病，湯武乃可君。","四賢胡爲者，千載名氛氳。","显晦有遺迹，前後疑不倫。","秦政虐天下，黷武窮生民。","諸侯戰必死，壯士眉亦嚬。","張良韓孺子，椎碎屬车輪。","遂令英雄意，日夜思報秦。","先生相將去，不复嬰世塵。","云卷在孤岫，龙潛爲小鱗。","秦王轉無道，諫者鼎鑊親。","茅焦脫衣諫，先生無一言。","趙高殺二世，先生如不闻。","劉項取天下，先生游白云。","海內八年戰，先生全一身。","漢業日已定，先生名亦振。","不得爲濟世，宜哉爲隐淪。","如何一朝起，屈作儲貳賓。","安存孝惠帝，摧顇戚夫人。","舍大以謀細，虯盤而蠖伸。","惠帝竟不嗣，呂氏禍有因。","雖懷安劉志，未若周與陳。","皆落子房術，先生道何屯。","出处貴明白，故吾今有云。"]', '诗', 'shi', '', NULL, '四皓廟 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cab97ee-60f4-4700-a7c6-8df13d928a21', '青雲驛', '青云驛', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["岧嶢青雲嶺，下有千仞谿。","裴回不可上，人倦馬亦嘶。","願登青雲路，若望丹霞梯。","謂言青雲驛，繡戶芙蓉閨。","謂言青雲騎，玉勒黃金蹄。","謂言青雲具，瑚璉雜象犀。","謂言青雲吏，的的顏如珪。","懷此青雲望，安能復久稽。","攀援信不易，風雨正淒淒。","已怪杜鵑鳥，先來山下啼。","纔及青雲驛，忽遇蓬蒿妻。","延我開蓽戶，鑿竇宛如圭。","逡巡吏來謁，頭白顏色黧。","饋食頻叫噪，假器仍乞醯。","嚮時延我者，共捨藿與藜。","乘我牂牁馬，蒙茸大如羝。","悔爲青雲意，此意良噬臍。","昔游蜀門下，有驛名青泥。","聞名意慘愴，若墜牢與狴。","雲泥異所稱，人物一以齊。","復聞閶闔上，下視日月低。","銀城蘂珠殿，玉版金字題。","大帝直南北，羣仙侍東西。","龍虎儼隊仗，雷霆轟鼓鼙。","元君理庭內，左右桃花蹊。","丹霞爛成綺，景雲輕若綈。","天池光灩灩，瑤草綠萋萋。","衆真千萬輩，柔顏盡如荑。","手持鳳尾扇，頭戴翠羽笄。","雲韶互鏗戛，霞服相提攜。","雙雙發皓齒，各各揚輕袿。","天祚樂未極，溟波浩無隄。","穢賤靈所惡，安肯問黔黎。","桑田變成海，宇懸烹爲韲。","虛皇不願見，雲霧重重翳。","大帝安可夢，閶闔何由躋。","靈物可見者，願以諭端倪。","蟲蛇吐雲氣，妖氛變虹蜺。","獲麟書諸冊，豢龍醢爲臡。","鳳皇占梧桐，叢雜百鳥棲。","野鶴啄腥蟲，貪饕不如雞。","山鹿藏窟穴，虎豹吞其麛。","靈物比靈境，冠履寧甚睽。","道勝即爲樂，何慙居稗稊。","金張好車馬，於陵親灌畦。","在梁或在火，不變玉與鵜。","上天勿行行，潛穴勿悽悽。","吟此青雲諭，達觀終不迷。"]', '["岧嶢青云嶺，下有千仞谿。","裴回不可上，人倦马亦嘶。","願登青云路，若望丹霞梯。","謂言青云驛，繡戶芙蓉閨。","謂言青云騎，玉勒黄金蹄。","謂言青云具，瑚璉杂象犀。","謂言青云吏，的的顏如珪。","懷此青云望，安能复久稽。","攀援信不易，风雨正淒淒。","已怪杜鵑鸟，先来山下啼。","纔及青云驛，忽遇蓬蒿妻。","延我开蓽戶，鑿竇宛如圭。","逡巡吏来謁，头白顏色黧。","饋食頻叫噪，假器仍乞醯。","嚮时延我者，共捨藿與藜。","乘我牂牁马，蒙茸大如羝。","悔爲青云意，此意良噬臍。","昔游蜀门下，有驛名青泥。","闻名意慘愴，若墜牢與狴。","云泥異所稱，人物一以齊。","复闻閶闔上，下視日月低。","銀城蘂珠殿，玉版金字題。","大帝直南北，羣仙侍东西。","龙虎儼隊仗，雷霆轟鼓鼙。","元君理庭內，左右桃花蹊。","丹霞爛成綺，景云轻若綈。","天池光灩灩，瑤草綠萋萋。","衆真千万輩，柔顏尽如荑。","手持鳳尾扇，头戴翠羽笄。","云韶互鏗戛，霞服相提携。","雙雙發皓齒，各各揚轻袿。","天祚乐未極，溟波浩無隄。","穢賤靈所惡，安肯问黔黎。","桑田变成海，宇懸烹爲韲。","虛皇不願见，云霧重重翳。","大帝安可梦，閶闔何由躋。","靈物可见者，願以諭端倪。","蟲蛇吐云氣，妖氛变虹蜺。","獲麟书諸冊，豢龙醢爲臡。","鳳皇占梧桐，叢杂百鸟棲。","野鹤啄腥蟲，貪饕不如雞。","山鹿藏窟穴，虎豹吞其麛。","靈物比靈境，冠履寧甚睽。","道勝即爲乐，何慙居稗稊。","金張好车马，於陵親灌畦。","在梁或在火，不变玉與鵜。","上天勿行行，潛穴勿悽悽。","吟此青云諭，達观終不迷。"]', '诗', 'shi', '', NULL, '青雲驛 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fabc073e-fb05-46e9-92c1-398d7c47c759', '陽城驛', '陽城驛', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["商有陽城驛，名同陽道州。","陽公沒已久，感我淚交流。","昔公孝父母，行與曾閔儔。","既孤善兄弟，兄弟和且柔。","一夕不相見，若懷三歲憂。","遂誓不婚娶，沒齒同衾裯。","妹夫死他縣，遺骨無人收。","公令季弟往，公與仲弟留。","相別竟不得，三人同遠遊。","共負他鄉骨，歸來藏故丘。","棲遲居夏邑，邑人無苟媮。","里中競長短，來問劣與優。","官刑一朝恥，公短終身羞。","公亦不遺布，人自不盜牛。","問公何能爾，忠信先自修。","發言當道理，不顧黨與讐。","聲香漸翕習，冠蓋若雲浮。","少者從公學，老者從公遊。","往來相告報，縣尹與公侯。","名落公卿口，湧如波薦舟。","天子得聞之，書下再三求。","書中願一見，不異旱地虯。","何以持爲聘，束帛藉琳球。","何以持爲御，駟馬駕安輈。","公方伯夷操，事殷不事周。","我實唐士庶，食唐之田疇。","我聞天子憶，安敢專自由。","來爲諫大夫，朝夕侍冕旒。","希夷惇薄俗，密勿獻良籌。","神醫不言術，人瘼曾暗瘳。","月請諫官俸，諸弟相對謀。","皆曰親戚外，酒散目前愁。","公云不有爾，安得此嘉猷。","施餘盡酤酒，客來相獻酬。","日旰不謀食，春深仍弊裘。","人心良戚戚，我樂獨由由。","貞元歲云暮，朝有曲如鉤。","風波勢奔蹙，日月光綢繆。","齒牙屬爲猾，禾黍暗生蟊。","豈無司言者，肉食吞其喉。","豈無司搏者，利柄扼其鞲。","鼻復勢氣塞，不得辯薰蕕。","公雖未顯諫，惴惴如患瘤。","飛章八九上，皆若珠暗投。","炎炎日將熾，積燎無人抽。","公乃帥其屬，決諫同報仇。","延英殿門外，叩閤仍叩頭。","且曰事不止，臣諫誓不休。","上知不可遏，命以美語酬。","降官司成署，俾之爲贅疣。","姦心不快活，擊刺礪戈矛。","終爲道州去，天道竟悠悠。","遂令不言者，反以言爲訧。","喉舌坐成木，鷹鸇化爲鳩。","避權如避虎，冠豸如冠猴。","平生附我者，詩人稱好逑。","私來一執手，恐若墜諸溝。","送我不出戶，決我不迴眸。","唯有太學生，各具糧與糇。","咸言公去矣，我亦去荒陬。","公與諸生別，步步駐行騶。","有生不可訣，行行過閩甌。","爲師得如此，得爲賢者不。","道州聞公來，鼓舞歌且謳。","昔公居夏邑，狎人如狎鷗。","況自爲刺史，豈復援鼓桴。","滋章一時罷，教化天下遒。","炎瘴不得老，英華忽已秋。","有鳥哭楊震，無兒悲鄧攸。","唯餘門弟子，列樹松與楸。","今來過此驛，若弔汨羅洲。","祠曹諱羊祜，此驛何不侔。","我願避公諱，名爲避賢郵。","此名有深意，蔽賢天所尤。","吾聞玄元教，日月冥九幽。","幽陰蔽翳者，永爲幽翳囚。"]', '["商有陽城驛，名同陽道州。","陽公沒已久，感我泪交流。","昔公孝父母，行與曾閔儔。","既孤善兄弟，兄弟和且柔。","一夕不相见，若懷三歲憂。","遂誓不婚娶，沒齒同衾裯。","妹夫死他縣，遺骨無人收。","公令季弟往，公與仲弟留。","相別竟不得，三人同远游。","共負他乡骨，归来藏故丘。","棲遲居夏邑，邑人無苟媮。","里中競长短，来问劣與優。","官刑一朝恥，公短終身羞。","公亦不遺布，人自不盜牛。","问公何能爾，忠信先自修。","發言當道理，不顧黨與讐。","声香漸翕習，冠蓋若云浮。","少者從公学，老者從公游。","往来相告報，縣尹與公侯。","名落公卿口，湧如波薦舟。","天子得闻之，书下再三求。","书中願一见，不異旱地虯。","何以持爲聘，束帛藉琳球。","何以持爲御，駟马駕安輈。","公方伯夷操，事殷不事周。","我實唐士庶，食唐之田疇。","我闻天子憶，安敢專自由。","来爲諫大夫，朝夕侍冕旒。","希夷惇薄俗，密勿獻良籌。","神醫不言術，人瘼曾暗瘳。","月請諫官俸，諸弟相对謀。","皆曰親戚外，酒散目前愁。","公云不有爾，安得此嘉猷。","施餘尽酤酒，客来相獻酬。","日旰不謀食，春深仍弊裘。","人心良戚戚，我乐独由由。","貞元歲云暮，朝有曲如鉤。","风波勢奔蹙，日月光綢繆。","齒牙屬爲猾，禾黍暗生蟊。","豈無司言者，肉食吞其喉。","豈無司搏者，利柄扼其鞲。","鼻复勢氣塞，不得辯薰蕕。","公雖未显諫，惴惴如患瘤。","飞章八九上，皆若珠暗投。","炎炎日將熾，積燎無人抽。","公乃帥其屬，決諫同報仇。","延英殿门外，叩閤仍叩头。","且曰事不止，臣諫誓不休。","上知不可遏，命以美語酬。","降官司成署，俾之爲贅疣。","姦心不快活，擊刺礪戈矛。","終爲道州去，天道竟悠悠。","遂令不言者，反以言爲訧。","喉舌坐成木，鷹鸇化爲鳩。","避權如避虎，冠豸如冠猴。","平生附我者，诗人稱好逑。","私来一執手，恐若墜諸溝。","送我不出戶，決我不迴眸。","唯有太学生，各具糧與糇。","咸言公去矣，我亦去荒陬。","公與諸生別，步步駐行騶。","有生不可訣，行行過閩甌。","爲師得如此，得爲賢者不。","道州闻公来，鼓舞歌且謳。","昔公居夏邑，狎人如狎鷗。","況自爲刺史，豈复援鼓桴。","滋章一时罷，教化天下遒。","炎瘴不得老，英华忽已秋。","有鸟哭楊震，無兒悲鄧攸。","唯餘门弟子，列樹松與楸。","今来過此驛，若弔汨羅洲。","祠曹諱羊祜，此驛何不侔。","我願避公諱，名爲避賢郵。","此名有深意，蔽賢天所尤。","吾闻玄元教，日月冥九幽。","幽陰蔽翳者，永爲幽翳囚。"]', '诗', 'shi', '', NULL, '陽城驛 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59c6ba2-5861-4180-a422-9adbd40dc892', '苦雨', '苦雨', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["江瘴氣候惡，庭空田地蕪。","煩昏一日內，陰暗三四殊。","巢燕汚牀席，蒼蠅點肌膚。","不足生詬怒，但苦寡歡娛。","夜來稍清晏，放體階前呼。","未飽風月思，已爲蚊蚋圖。","我受簪組身，我生天地爐。","炎蒸安敢勌，蟲豸何時無。","凌晨坐堂廡，努力泥中趨。","官家事不了，尤悔亦可虞。","門外竹橋折，馬驚不敢踰。","回頭命僮御，向我色踟躕。","自顧方濩落，安能相詰誅。","隱忍心憤恨，翻爲聲喣愉。","逡巡崔嵬日，杲曜東南隅。","已復雲蔽翳，不使及泥塗。","良農盡蒲葦，厚地積潢汚。","三光不得照，萬物何由蘇。","安得飛廉車，磔裂雲將軀。","又提精陽劒，蛟螭支節屠。","陰沴皆電埽，幽妖亦雷驅。","煌煌啓閶闔，軋軋掉乾樞。","東西生日月，晝夜如轉珠。","百川朝巨海，六龍蹋亨衢。","此意倍寥廓，時來本須臾。","今也泥鴻洞，黿鼉真得途。"]', '["江瘴氣候惡，庭空田地蕪。","煩昏一日內，陰暗三四殊。","巢燕汚牀席，蒼蠅点肌膚。","不足生詬怒，但苦寡歡娛。","夜来稍清晏，放體階前呼。","未飽风月思，已爲蚊蚋圖。","我受簪組身，我生天地爐。","炎蒸安敢勌，蟲豸何时無。","凌晨坐堂廡，努力泥中趨。","官家事不了，尤悔亦可虞。","门外竹橋折，马驚不敢踰。","回头命僮御，向我色踟躕。","自顧方濩落，安能相詰誅。","隐忍心憤恨，翻爲声喣愉。","逡巡崔嵬日，杲曜东南隅。","已复云蔽翳，不使及泥塗。","良農尽蒲葦，厚地積潢汚。","三光不得照，万物何由蘇。","安得飞廉车，磔裂云將軀。","又提精陽劒，蛟螭支節屠。","陰沴皆電埽，幽妖亦雷驱。","煌煌啓閶闔，軋軋掉乾樞。","东西生日月，晝夜如轉珠。","百川朝巨海，六龙蹋亨衢。","此意倍寥廓，时来本須臾。","今也泥鴻洞，黿鼉真得途。"]', '诗', 'shi', '', NULL, '苦雨 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b7e07cd-3289-4873-ab4f-3e582641ddd7', '種竹', '種竹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔公憐我直，比之秋竹竿。","秋來苦相憶，種竹廳前看。","失地顏色改，傷根枝葉殘。","清風猶淅淅，高節空團團。","鳴蟬聒暮景，跳蛙集幽闌。","塵土復晝夜，梢雲良獨難。","丹丘信云遠，安得臨仙壇。","瘴江冬草綠，何人驚歲寒。","可憐亭亭榦，一一青琅玕。","孤鳳竟不至，坐傷時節闌。"]', '["昔公怜我直，比之秋竹竿。","秋来苦相憶，種竹廳前看。","失地顏色改，傷根枝葉殘。","清风猶淅淅，高節空團團。","鳴蟬聒暮景，跳蛙集幽闌。","塵土复晝夜，梢云良独难。","丹丘信云远，安得臨仙壇。","瘴江冬草綠，何人驚歲寒。","可怜亭亭榦，一一青琅玕。","孤鳳竟不至，坐傷时節闌。"]', '诗', 'shi', '', NULL, '種竹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fbada56-daea-4a1d-86de-04d8687d70d9', '和樂天贈樊著作', '和乐天贈樊著作', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["君爲著作詩，志激詞且溫。","璨然光揚者，皆以義烈聞。","千慮竟一失，冰玉不斷痕。","謬予頑不肖，列在數子間。","因君譏史氏，我亦能具陳。","羲黃眇云遠，載籍無遺文。","煌煌二帝道，鋪設在典墳。","堯心惟舜會，因著爲話言。","臯夔益稷禹，粗得無間然。","緬然千載後，後聖曰孔宣。","迥知皇王意，綴書爲百篇。","是時游夏輩，不敢措舌端。","信哉作遺訓，職在聖與賢。","如何至近古，史氏爲閑官。","但令識字者，竊弄刀筆權。","由心書曲直，不使當世觀。","貽之千萬代，疑言相竝傳。","人人異所見，各各私所偏。","以是曰褒貶，不如都無焉。","況乃丈夫志，用捨貴當年。","顧予有微尚，願以出處論。","出非利吾已，其出貴道全。","全道豈虛設，道全當及人。","全則富與壽，虧則饑與寒。","遂我一身逸，不如萬物安。","解懸不澤手，拯溺無折旋。","神哉伊尹心，可以冠古先。","其次有獨善，善己不善民。","天地爲一物，死生爲一源。","合雜分萬變，忽若風中塵。","抗哉巢由志，堯舜不可遷。","捨此二者外，安用名爲賓。","持謝著書郎，愚不願有云。"]', '["君爲著作诗，志激词且溫。","璨然光揚者，皆以義烈闻。","千慮竟一失，冰玉不斷痕。","謬予頑不肖，列在數子间。","因君譏史氏，我亦能具陳。","羲黄眇云远，載籍無遺文。","煌煌二帝道，鋪設在典墳。","堯心惟舜會，因著爲話言。","臯夔益稷禹，粗得無间然。","緬然千載後，後聖曰孔宣。","迥知皇王意，綴书爲百篇。","是时游夏輩，不敢措舌端。","信哉作遺訓，職在聖與賢。","如何至近古，史氏爲闲官。","但令識字者，竊弄刀笔權。","由心书曲直，不使當世观。","貽之千万代，疑言相竝傳。","人人異所见，各各私所偏。","以是曰褒貶，不如都無焉。","況乃丈夫志，用捨貴當年。","顧予有微尚，願以出处論。","出非利吾已，其出貴道全。","全道豈虛設，道全當及人。","全則富與壽，虧則饑與寒。","遂我一身逸，不如万物安。","解懸不澤手，拯溺無折旋。","神哉伊尹心，可以冠古先。","其次有独善，善己不善民。","天地爲一物，死生爲一源。","合杂分万变，忽若风中塵。","抗哉巢由志，堯舜不可遷。","捨此二者外，安用名爲賓。","持謝著书郎，愚不願有云。"]', '诗', 'shi', '', NULL, '和樂天贈樊著作 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc28e2e-578e-47bd-8ca9-c648ab400c82', '和樂天感鶴', '和乐天感鹤', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我有所愛鶴，毛羽霜雪妍。","秋霄一滴露，聲聞林外天。","自隨衛侯去，遂入大夫軒。","雲貌久已隔，玉音無復傳。","吟君感鶴操，不覺心惕然。","無乃予所愛，誤爲微物遷。","因茲諭直質，未免柔細牽。","君看孤松樹，左右蘿蔦纏。","既可習爲飽，亦可薰爲荃。","期君常善救，勿令終棄捐。"]', '["我有所愛鹤，毛羽霜雪妍。","秋霄一滴露，声闻林外天。","自隨衛侯去，遂入大夫軒。","云貌久已隔，玉音無复傳。","吟君感鹤操，不覺心惕然。","無乃予所愛，誤爲微物遷。","因茲諭直質，未免柔細牽。","君看孤松樹，左右蘿蔦纏。","既可習爲飽，亦可薰爲荃。","期君常善救，勿令終棄捐。"]', '诗', 'shi', '', NULL, '和樂天感鶴 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29f6c161-100e-4023-90c0-26a5739b7e53', '諭寶二首 一', '諭寶二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["沈玉在弱泥，泥弱玉易沈。","扶桑寒日薄，不照萬丈心。","安得潛淵虯，拔壑超鄧林。","泥封泰山阯，水散旱天霖。","洗此泥下玉，照耀臺殿深。","刻爲傳國寶，神器人不侵。"]', '["沈玉在弱泥，泥弱玉易沈。","扶桑寒日薄，不照万丈心。","安得潛淵虯，拔壑超鄧林。","泥封泰山阯，水散旱天霖。","洗此泥下玉，照耀台殿深。","刻爲傳国寶，神器人不侵。"]', '诗', 'shi', '', NULL, '諭寶二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f8b47ed-b2ac-4b77-8af3-2b131e20a8cf', '諭寶二首 二', '諭寶二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["冰置白玉壺，始見清皎潔。","珠穿殷紅縷，始見明洞徹。","鏌鋣無人淬，兩刃幽壤鐵。","秦鏡無人拭，一片埋霧月。","驥跼環堵中，骨附筋入節。","虯蟠尺澤內，魚貫蛙同穴。","艅艎無巨海，浮浮矜瀎潏。","棟梁無廣廈，顛倒臥霜雪。","大鵬無長空，舉翮受羈絏。","豫樟無厚地，危柢真卼臲。","圭璧無卞和，甘與頑石列。","舜禹無陶堯，名隨腐草滅。","神功伏神物，神物神乃別。","神人不世出，所以神功絕。","神物豈徒然，用之乃施設。","禹功九州理，舜德天下悅。","璧充傳國璽，圭用祈太折。","千尋豫樟榦，九萬大鵬歇。","棟梁庇生民，艅艎濟來哲。","虯騰旱天雨，驥騁流電掣。","鏡懸姦膽露，劒拂妖蛇裂。","珠玉照乘光，冰瑩環坐熱。","此物比在泥，斯言爲誰發。","於今盡凡耳，不爲君不說。"]', '["冰置白玉壺，始见清皎潔。","珠穿殷紅縷，始见明洞徹。","鏌鋣無人淬，兩刃幽壤鐵。","秦镜無人拭，一片埋霧月。","驥跼环堵中，骨附筋入節。","虯蟠尺澤內，鱼貫蛙同穴。","艅艎無巨海，浮浮矜瀎潏。","棟梁無廣廈，顛倒臥霜雪。","大鵬無长空，舉翮受羈絏。","豫樟無厚地，危柢真卼臲。","圭璧無卞和，甘與頑石列。","舜禹無陶堯，名隨腐草滅。","神功伏神物，神物神乃別。","神人不世出，所以神功絕。","神物豈徒然，用之乃施設。","禹功九州理，舜德天下悅。","璧充傳国璽，圭用祈太折。","千尋豫樟榦，九万大鵬歇。","棟梁庇生民，艅艎濟来哲。","虯腾旱天雨，驥騁流電掣。","镜懸姦膽露，劒拂妖蛇裂。","珠玉照乘光，冰瑩环坐熱。","此物比在泥，斯言爲誰發。","於今尽凡耳，不爲君不说。"]', '诗', 'shi', '', NULL, '諭寶二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52ba3893-9000-4079-9996-b50f4c7bf415', '說劒', '说劒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["吾友有寶劒，密之如密友。","我實膠漆交，中堂共杯酒。","酒酣肝膽露，恨不眼前剖。","高唱荆卿歌，亂擊相如缶。","更擊復更唱，更酌亦更壽。","白虹坐上飛，青蛇匣中吼。","我聞音響異，疑是干將偶。","爲君再拜言，神物可見不。","君言我所重，我自爲君取。","迎篋已焚香，近鞘先澤手。","徐抽寸寸刃，漸屈彎彎肘。","殺殺霜在鋒，團團月臨紐。","逡巡潛虯躍，鬱律驚左右。","霆電滿室光，蛟龍繞身走。","我爲捧之泣，此劒別來久。","鑄時近山破，藏在松桂朽。","幽匣獄底埋，神人水心守。","本是稽泥淬，果非雷煥有。","我欲評劒功，願君良聽受。","劒可剸犀兕，劒可切瓊玖。","劒決天外雲，劒衝日中斗。","劒隳妖蛇腹，劒拂佞臣首。","太古初斷鼇，武王親擊紂。","燕丹卷地圖，陳平綰花綬。","曾被桂樹枝，寒光射林藪。","曾經鑄農器，利用翦稂莠。","神物終變化，復爲龍牝牡。","晉末武庫燒，脫然排戶牖。","爲欲埽羣胡，散作彌天帚。","自茲失所往，豪英共爲詬。","今復誰人鑄，挺然千載後。","既非古風胡，無乃近鵶九。","自我與君遊，平生益自負。","況擎寶劒出，重以雄心扣。","此劒何太奇，此心何太厚。","勸君慎所用，所用無或苟。","潛將辟魑魅，勿但防妾婦。","留斬泓下蛟，莫試街中狗。","君今困泥滓，我亦坌塵垢。","俗耳驚大言，逢人少開口。"]', '["吾友有寶劒，密之如密友。","我實膠漆交，中堂共杯酒。","酒酣肝膽露，恨不眼前剖。","高唱荆卿歌，亂擊相如缶。","更擊复更唱，更酌亦更壽。","白虹坐上飞，青蛇匣中吼。","我闻音响異，疑是干將偶。","爲君再拜言，神物可见不。","君言我所重，我自爲君取。","迎篋已焚香，近鞘先澤手。","徐抽寸寸刃，漸屈彎彎肘。","殺殺霜在鋒，團團月臨紐。","逡巡潛虯躍，鬱律驚左右。","霆電满室光，蛟龙繞身走。","我爲捧之泣，此劒別来久。","鑄时近山破，藏在松桂朽。","幽匣獄底埋，神人水心守。","本是稽泥淬，果非雷煥有。","我欲評劒功，願君良听受。","劒可剸犀兕，劒可切瓊玖。","劒決天外云，劒衝日中斗。","劒隳妖蛇腹，劒拂佞臣首。","太古初斷鼇，武王親擊紂。","燕丹卷地圖，陳平綰花綬。","曾被桂樹枝，寒光射林藪。","曾經鑄農器，利用翦稂莠。","神物終变化，复爲龙牝牡。","晉末武庫燒，脫然排戶牖。","爲欲埽羣胡，散作彌天帚。","自茲失所往，豪英共爲詬。","今复誰人鑄，挺然千載後。","既非古风胡，無乃近鵶九。","自我與君游，平生益自負。","況擎寶劒出，重以雄心扣。","此劒何太奇，此心何太厚。","勸君慎所用，所用無或苟。","潛將辟魑魅，勿但防妾婦。","留斬泓下蛟，莫試街中狗。","君今困泥滓，我亦坌塵垢。","俗耳驚大言，逢人少开口。"]', '诗', 'shi', '', NULL, '說劒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d383b134-10df-471c-9c0b-09230cb4d342', '書異', '书異', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["孟冬初寒月，渚澤蒲尚青。","飄蕭北風起，皓雪紛滿庭。","行過冬至後，凍閉萬物零。","奔渾馳暴雨，驟鼓轟雷霆。","傳云不終日，通宵曾莫停。","瘴雲愁拂地，急霤疑注缾。","洶湧潢潦濁，噴薄鯨鯢腥。","跳趫井蛙喜，突兀水怪形。","飛蚋奔不死，修蛇蟄再醒。","應龍非時出，無乃歲不寧。","吾聞陰陽戶，啓閉各有扃。","後時無肅殺，廢職乃玄冥。","座配五天帝，薦用百品珍。","權爲祝融奪，神其焉得靈。","春秋雷電異，則必書諸經。","仲冬雷雨苦，願省蒙蔽刑。"]', '["孟冬初寒月，渚澤蒲尚青。","飄蕭北风起，皓雪紛满庭。","行過冬至後，凍閉万物零。","奔渾驰暴雨，驟鼓轟雷霆。","傳云不終日，通宵曾莫停。","瘴云愁拂地，急霤疑注缾。","洶湧潢潦濁，噴薄鯨鯢腥。","跳趫井蛙喜，突兀水怪形。","飞蚋奔不死，修蛇蟄再醒。","應龙非时出，無乃歲不寧。","吾闻陰陽戶，啓閉各有扃。","後时無肅殺，廢職乃玄冥。","座配五天帝，薦用百品珍。","權爲祝融奪，神其焉得靈。","春秋雷電異，則必书諸經。","仲冬雷雨苦，願省蒙蔽刑。"]', '诗', 'shi', '', NULL, '書異 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1404cdcc-cc01-430c-8aed-f0897c9f4d66', '和樂天折劒頭', '和乐天折劒头', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["聞君得折劒，一片雄心起。","詎意鐵蛟龍，潛在延津水。","風雲會一合，呼吸期萬里。","雷震山嶽碎，電斬鯨鯢死。","莫但寶劒頭，劒頭非此比。"]', '["闻君得折劒，一片雄心起。","詎意鐵蛟龙，潛在延津水。","风云會一合，呼吸期万里。","雷震山嶽碎，電斬鯨鯢死。","莫但寶劒头，劒头非此比。"]', '诗', 'shi', '', NULL, '和樂天折劒頭 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1958fe-3b06-4860-9050-66a413ebf53f', '松鶴', '松鹤', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["渚宮本坳下，佛廟有臺閣。","臺下三四松，低昂勢前却。","是時晴景麗，松梢殘雪薄。","日色相玲瓏，纖雲暎羅幕。","逡巡九霄外，似振風中鐸。","漸見尺帛光，孤飛唳空鶴。","裴回耀霜雪，顧慕下寥廓。","蹋動樛盤枝，龍蛇互跳躍。","俯瞰九江水，旁瞻萬里壑。","無心眄烏鳶，有字悲城郭。","清角已沈絕，虞韶亦冥寞。","鶱翻勿重留，幸及鈞天作。"]', '["渚宮本坳下，佛廟有台閣。","台下三四松，低昂勢前却。","是时晴景丽，松梢殘雪薄。","日色相玲瓏，纖云暎羅幕。","逡巡九霄外，似振风中鐸。","漸见尺帛光，孤飞唳空鹤。","裴回耀霜雪，顧慕下寥廓。","蹋动樛盤枝，龙蛇互跳躍。","俯瞰九江水，旁瞻万里壑。","無心眄烏鳶，有字悲城郭。","清角已沈絕，虞韶亦冥寞。","鶱翻勿重留，幸及鈞天作。"]', '诗', 'shi', '', NULL, '松鶴 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aceae76b-ffff-4b6f-8c08-6572a7b2bdf8', '競渡', '競渡', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["吾觀競舟子，因測大競源。","天地昔將競，蓬勃晝夜昏。","龍蛇相嗔薄，海岱俱崩奔。","羣動皆攪撓，化作流渾渾。","數極鬬心息，太和蒸混元。","一氣忽爲二，矗然畫乾坤。","日月復照耀，春秋遞寒溫。","八荒坦以曠，萬物羅以繁。","聖人中間立，理世了不煩。","延綿復幾歲，逮及羲與軒。","炎皇熾如炭，蚩尤扇其燔。","有熊競心起，驅獸出林樊。","一戰波委燄，再戰火燎原。","戰訖天下定，號之爲軒轅。","自是豈無競，瑣細不復言。","其次有龍競，競渡龍之門。","龍門浚如瀉，淙射不可援。","赤鱗化時至，唐突鰭鬣掀。","乘風瞥然去，萬里黃河飜。","接瞬電烻出，微吟霹靂喧。","傍瞻曠宇宙，俯瞰卑崑崙。","庶類咸在下，九霄行易捫。","倏辭蛙黽穴，遽排天帝閽。","迴悲曝鰓者，未免鯨鯢吞。","帝命澤諸夏，不棄蟲與昆。","隨時布膏露，稱物施厚恩。","草木霑我潤，豚魚望我蕃。","嚮來同競輩，豈料由我存。","壯哉龍競渡，一競身獨尊。","捨此皆蟻鬬，競舟何足論。"]', '["吾观競舟子，因測大競源。","天地昔將競，蓬勃晝夜昏。","龙蛇相嗔薄，海岱俱崩奔。","羣动皆攪撓，化作流渾渾。","數極鬬心息，太和蒸混元。","一氣忽爲二，矗然畫乾坤。","日月复照耀，春秋遞寒溫。","八荒坦以曠，万物羅以繁。","聖人中间立，理世了不煩。","延綿复幾歲，逮及羲與軒。","炎皇熾如炭，蚩尤扇其燔。","有熊競心起，驱獸出林樊。","一戰波委燄，再戰火燎原。","戰訖天下定，號之爲軒轅。","自是豈無競，瑣細不复言。","其次有龙競，競渡龙之门。","龙门浚如瀉，淙射不可援。","赤鱗化时至，唐突鰭鬣掀。","乘风瞥然去，万里黄河飜。","接瞬電烻出，微吟霹靂喧。","傍瞻曠宇宙，俯瞰卑崑崙。","庶類咸在下，九霄行易捫。","倏辞蛙黽穴，遽排天帝閽。","迴悲曝鰓者，未免鯨鯢吞。","帝命澤諸夏，不棄蟲與昆。","隨时布膏露，稱物施厚恩。","草木霑我潤，豚鱼望我蕃。","嚮来同競輩，豈料由我存。","壯哉龙競渡，一競身独尊。","捨此皆蟻鬬，競舟何足論。"]', '诗', 'shi', '', NULL, '競渡 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67027072-45f2-443a-b8b2-b82cbfd0558d', '寺院新竹', '寺院新竹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寶地琉璃坼，紫苞琅玕踴。","亭亭巧於削，一一大如拱。","冰碧林外寒，峯巒眼前聳。","槎枒矛戟合，屹仡龍蛇動。","煙泛翠光流，歲餘霜彩重。","風朝竽籟過，雨夜鬼神恐。","佳色有鮮妍，修莖無擁腫。","節高迷玉鏃，籜綴疑花捧。","詎必太山根，本自仙壇種。","誰令植幽壤，復此依閑冗。","居然霄漢姿，坐受藩籬壅。","噪集勌鴟烏，炎昏繁蠛蠓。","未遭伶倫聽，非安子猶寵。","威鳳來有時，虛心豈無奉。"]', '["寶地琉璃坼，紫苞琅玕踴。","亭亭巧於削，一一大如拱。","冰碧林外寒，峯巒眼前聳。","槎枒矛戟合，屹仡龙蛇动。","煙泛翠光流，歲餘霜彩重。","风朝竽籟過，雨夜鬼神恐。","佳色有鲜妍，修莖無擁腫。","節高迷玉鏃，籜綴疑花捧。","詎必太山根，本自仙壇種。","誰令植幽壤，复此依闲冗。","居然霄漢姿，坐受藩籬壅。","噪集勌鴟烏，炎昏繁蠛蠓。","未遭伶倫听，非安子猶寵。","威鳳来有时，虛心豈無奉。"]', '诗', 'shi', '', NULL, '寺院新竹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0604487-cc43-4761-9d62-013e84c9f087', '詶別致用', '詶別致用', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風行自委順，雲合非有期。","神哉心相見，無眹安得離。","我有懇憤志，三十無人知。","修身不言命，謀道不擇時。","達則濟億兆，窮亦濟毫氂。","濟人無大小，誓不空濟私。","研幾未淳熟，與世忽參差。","意氣一爲累，猜仍良已隨。","昨來竄荆蠻，分與平生隳。","那言返爲遇，獲見心所奇。","一見肺肝盡，坦然無滯疑。","感念交契定，淚流如斷縻。","此交定生死，非爲論盛衰。","此契宗會極，非爲同路岐。","君今虎在柙，我亦鷹就羈。","馴養保性命，安能奮殊姿。","玉色深不變，井水撓不移。","相看各年少，未敢深自悲。"]', '["风行自委順，云合非有期。","神哉心相见，無眹安得離。","我有懇憤志，三十無人知。","修身不言命，謀道不擇时。","達則濟億兆，窮亦濟毫氂。","濟人無大小，誓不空濟私。","研幾未淳熟，與世忽參差。","意氣一爲累，猜仍良已隨。","昨来竄荆蠻，分與平生隳。","那言返爲遇，獲见心所奇。","一见肺肝尽，坦然無滯疑。","感念交契定，泪流如斷縻。","此交定生死，非爲論盛衰。","此契宗會極，非爲同路岐。","君今虎在柙，我亦鷹就羈。","馴養保性命，安能奮殊姿。","玉色深不变，井水撓不移。","相看各年少，未敢深自悲。"]', '诗', 'shi', '', NULL, '詶別致用 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('193fbd8d-cb2c-41d3-b3f2-7756d0fdcef9', '竹部', '竹部', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["竹部竹山近，歲伐竹山竹。","伐竹歲亦深，深林隔深谷。","朝朝冰雪行，夜夜豺狼宿。","科首霜斷蓬，枯形燒餘木。","一束十餘莖，千錢百餘束。","得錢盈千百，得粟盈斗斛。","歸來不買食，父子分半菽。","持此欲何爲，官家歲輸促。","我來荆門掾，寓食公堂肉。","豈惟遍妻孥，亦以及僮僕。","分爾有限資，飽我無端腹。","愧爾不復言，爾生何太蹙。"]', '["竹部竹山近，歲伐竹山竹。","伐竹歲亦深，深林隔深谷。","朝朝冰雪行，夜夜豺狼宿。","科首霜斷蓬，枯形燒餘木。","一束十餘莖，千錢百餘束。","得錢盈千百，得粟盈斗斛。","归来不買食，父子分半菽。","持此欲何爲，官家歲輸促。","我来荆门掾，寓食公堂肉。","豈惟遍妻孥，亦以及僮僕。","分爾有限資，飽我無端腹。","愧爾不复言，爾生何太蹙。"]', '诗', 'shi', '', NULL, '竹部 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d97c36a4-f388-4f8a-bd90-85c9131f8766', '賽神', '賽神', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["楚俗不事事，巫風事妖神。","事妖結妖社，不問疎與親。","年年十月暮，珠稻欲垂新。","家家不歛穫，賽妖無富貧。","殺牛貰官酒，椎鼓集頑民。","喧闐里閭隘，兇酗日夜頻。","歲暮雪霜至，稻珠隨隴湮。","吏來官稅迫，求質倍稱緡。","貧者日消鑠，富亦無倉囷。","不謂事神苦，自言誠不真。","岳陽賢刺史，念此爲俗屯。","未可一朝去，俾之爲等倫。","粗許存習俗，不得呼黨人。","但許一日澤，不得月與旬。","吾聞國僑理，三年名乃振。","巫風燎原久，未必憐徙薪。","我來歌此事，非獨歌政仁。","此事四鄰有，亦欲聞四鄰。"]', '["楚俗不事事，巫风事妖神。","事妖結妖社，不问疎與親。","年年十月暮，珠稻欲垂新。","家家不歛穫，賽妖無富貧。","殺牛貰官酒，椎鼓集頑民。","喧闐里閭隘，兇酗日夜頻。","歲暮雪霜至，稻珠隨隴湮。","吏来官稅迫，求質倍稱緡。","貧者日消鑠，富亦無倉囷。","不謂事神苦，自言誠不真。","岳陽賢刺史，念此爲俗屯。","未可一朝去，俾之爲等倫。","粗許存習俗，不得呼黨人。","但許一日澤，不得月與旬。","吾闻国僑理，三年名乃振。","巫风燎原久，未必怜徙薪。","我来歌此事，非独歌政仁。","此事四鄰有，亦欲闻四鄰。"]', '诗', 'shi', '', NULL, '賽神 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855b9365-2123-4728-8eed-13888fc717ab', '競舟', '競舟', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["楚俗不愛力，費力爲競舟。","買舟俟一競，競歛貧者賕。","年年四五月，蠒實麥小秋。","積水堰堤壞，拔秧蒲稗稠。","此時集丁壯，習競南畝頭。","朝飲邨社酒，暮椎鄰舍牛。","祭船如祭祖，習競如習讐。","連延數十日，作業不復憂。","君侯饌良吉，會客陳膳羞。","畫鷁四來合，大競長江流。","建標明取舍，勝負死生求。","一時讙呼罷，三月農事休。","岳陽賢刺史，念此爲俗疣。","習俗難盡去，聊用去其尤。","百船不留一，一競不滯留。","自爲里中戲，我亦不寓遊。","吾聞管仲教，沐樹懲墮遊。","節此淫競俗，得爲良政不。","我來歌此事，非獨歌此州。","此事數州有，亦欲聞數州。"]', '["楚俗不愛力，費力爲競舟。","買舟俟一競，競歛貧者賕。","年年四五月，蠒實麦小秋。","積水堰堤壞，拔秧蒲稗稠。","此时集丁壯，習競南畝头。","朝饮邨社酒，暮椎鄰舍牛。","祭船如祭祖，習競如習讐。","連延數十日，作業不复憂。","君侯饌良吉，會客陳膳羞。","畫鷁四来合，大競长江流。","建標明取舍，勝負死生求。","一时讙呼罷，三月農事休。","岳陽賢刺史，念此爲俗疣。","習俗难尽去，聊用去其尤。","百船不留一，一競不滯留。","自爲里中戲，我亦不寓游。","吾闻管仲教，沐樹懲墮游。","節此淫競俗，得爲良政不。","我来歌此事，非独歌此州。","此事數州有，亦欲闻數州。"]', '诗', 'shi', '', NULL, '競舟 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('909d8dde-fbcd-4dff-a1c5-db20860f1635', '茅舍', '茅舍', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["楚俗不理居，居人盡茅舍。","茅苫竹梁棟，茅疎竹仍罅。","邊緣隄岸斜，詰屈檐楹亞。","籬落不蔽肩，街衢不容駕。","南風五月盛，時雨不來下。","竹蠹茅亦乾，迎風自焚灺。","防虞集鄰里，巡警勞晝夜。","遺燼一星然，連延禍相嫁。","號呼鄰穀帛，奔走伐桑柘。","舊架已新焚，新茅又初架。","前日洪州牧，念此常嗟訝。","牧民未及久，郡邑紛如化。","峻邸儼相望，飛甍遠相跨。","旗亭紅粉泥，佛廟青鴛瓦。","斯事纔未終，斯人久云謝。","有客自洪來，洪民至今藉。","惜其心太亟，作役無容暇。","臺觀亦已多，工徒稍冤咤。","我欲他郡長，三時務耕稼。","農收次邑居，先室後臺榭。","啓閉既及期，公私亦相借。","度材無強略，庀役有定價。","不使及僭差，粗得禦寒夏。","火至殊陳鄭，人安極嵩華。","誰能繼此名，名流襲蘭麝。","五袴有前聞，斯言我非詐。"]', '["楚俗不理居，居人尽茅舍。","茅苫竹梁棟，茅疎竹仍罅。","邊緣隄岸斜，詰屈檐楹亞。","籬落不蔽肩，街衢不容駕。","南风五月盛，时雨不来下。","竹蠹茅亦乾，迎风自焚灺。","防虞集鄰里，巡警勞晝夜。","遺燼一星然，連延禍相嫁。","號呼鄰穀帛，奔走伐桑柘。","旧架已新焚，新茅又初架。","前日洪州牧，念此常嗟訝。","牧民未及久，郡邑紛如化。","峻邸儼相望，飞甍远相跨。","旗亭紅粉泥，佛廟青鴛瓦。","斯事纔未終，斯人久云謝。","有客自洪来，洪民至今藉。","惜其心太亟，作役無容暇。","台观亦已多，工徒稍冤咤。","我欲他郡长，三时務耕稼。","農收次邑居，先室後台榭。","啓閉既及期，公私亦相借。","度材無強略，庀役有定價。","不使及僭差，粗得禦寒夏。","火至殊陳鄭，人安極嵩华。","誰能繼此名，名流襲蘭麝。","五袴有前闻，斯言我非詐。"]', '诗', 'shi', '', NULL, '茅舍 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755c64d7-d314-457d-a628-c906470a71ae', '後湖', '後湖', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["荆有泥濘水，在荆之邑郛。","郛前水在後，謂之爲後湖。","環湖十餘里，歲積潢與汚。","臭腐魚鼇死，不植菰與蒲。","鄭公理三載，其理用喣愉。","歲稔民四至，隘廛亦隘衢。","公乃署其地，爲民先矢謨。","人人儻自爲，我亦不庀徒。","下里得聞之，各各相俞俞。","提攜翁及孫，捧戴婦與姑。","壯者負礫石，老亦捽茅蒭。","斤磨片片雪，椎隱連連珠。","朝餐布庭落，夜宿完戶樞。","鄰里近相告，親戚遠相呼。","鬻者自爲鬻，酤者自爲酤。","雞犬豐中市，人民岐下都。","百年廢滯所，一旦奧浩區。","我實司水土，得爲官事無。","人言賤事貴，貴直不貴諛。","此實公所小，安用歌袴襦。","答云潭及廣，以至鄂與吳。","萬里盡澤國，居人皆墊濡。","富者不容蓋，貧者不庇軀。","得不歌此事，以我爲楷模。"]', '["荆有泥濘水，在荆之邑郛。","郛前水在後，謂之爲後湖。","环湖十餘里，歲積潢與汚。","臭腐鱼鼇死，不植菰與蒲。","鄭公理三載，其理用喣愉。","歲稔民四至，隘廛亦隘衢。","公乃署其地，爲民先矢謨。","人人儻自爲，我亦不庀徒。","下里得闻之，各各相俞俞。","提携翁及孫，捧戴婦與姑。","壯者負礫石，老亦捽茅蒭。","斤磨片片雪，椎隐連連珠。","朝餐布庭落，夜宿完戶樞。","鄰里近相告，親戚远相呼。","鬻者自爲鬻，酤者自爲酤。","雞犬豐中市，人民岐下都。","百年廢滯所，一旦奧浩區。","我實司水土，得爲官事無。","人言賤事貴，貴直不貴諛。","此實公所小，安用歌袴襦。","答云潭及廣，以至鄂與吳。","万里尽澤国，居人皆墊濡。","富者不容蓋，貧者不庇軀。","得不歌此事，以我爲楷模。"]', '诗', 'shi', '', NULL, '後湖 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd9a064c-3229-4e8d-870c-9ddbccad9c50', '八駿圖詩', '八駿圖诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["穆滿志空闊，將行九州野。","神馭四來歸，天與八駿馬。","龍種無凡性，龍行無暫捨。","朝辭扶桑底，暮宿崑崙下。","鼻息吼春雷，蹄聲裂寒瓦。","尾掉滄波黑，汗染白雲赭。","華輈本修密，翠蓋尚妍冶。","御者腕不移，乘者寐不假。","車無輪扁斵，轡無王良把。","雖有萬駿來，誰是敢騎者。"]', '["穆满志空闊，將行九州野。","神馭四来归，天與八駿马。","龙種無凡性，龙行無暫捨。","朝辞扶桑底，暮宿崑崙下。","鼻息吼春雷，蹄声裂寒瓦。","尾掉滄波黑，汗染白云赭。","华輈本修密，翠蓋尚妍冶。","御者腕不移，乘者寐不假。","车無輪扁斵，轡無王良把。","雖有万駿来，誰是敢騎者。"]', '诗', 'shi', '', NULL, '八駿圖詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fd0c84b-5f2e-4973-afb7-5deef60546be', '畫松', '畫松', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["張璪畫古松，往往得神骨。","翠帚掃春風，枯龍戛寒月。","流傳畫師輩，奇態盡埋沒。","纖枝無蕭灑，頑榦空突兀。","乃悟埃塵心，難狀煙霄質。","我去淅陽山，深山看真物。"]', '["張璪畫古松，往往得神骨。","翠帚掃春风，枯龙戛寒月。","流傳畫師輩，奇態尽埋沒。","纖枝無蕭灑，頑榦空突兀。","乃悟埃塵心，难狀煙霄質。","我去淅陽山，深山看真物。"]', '诗', 'shi', '', NULL, '畫松 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaf435b6-7c18-4c02-b8ca-1a2c7b738c15', '遣興十首 一', '遣兴十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["始見棃花房，坐對棃花白。","行看棃葉青，已復棃葉赤。","嚴霜九月半，危蔕幾時客。","況有高高原，秋風四來迫。"]', '["始见棃花房，坐对棃花白。","行看棃葉青，已复棃葉赤。","嚴霜九月半，危蔕幾时客。","況有高高原，秋风四来迫。"]', '诗', 'shi', '', NULL, '遣興十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e6e7b3-dda9-4f2a-91a7-9a2976ec97ce', '遣興十首 二', '遣兴十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫厭夏日長，莫愁冬日短。","欲識短復長，君看寒又暖。","城中百萬家，冤哀雜絲管。","草沒奉誠園，軒車昔曾滿。"]', '["莫厭夏日长，莫愁冬日短。","欲識短复长，君看寒又暖。","城中百万家，冤哀杂絲管。","草沒奉誠园，軒车昔曾满。"]', '诗', 'shi', '', NULL, '遣興十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ee554fc-28dd-423b-a821-57d98415b601', '遣興十首 三', '遣兴十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["孤竹迸荒園，誤與蓬麻列。","久擁蕭蕭風，空長高高節。","嚴霜蕩羣穢，蓬斷麻亦折。","獨立轉亭亭，心期鳳皇別。"]', '["孤竹迸荒园，誤與蓬麻列。","久擁蕭蕭风，空长高高節。","嚴霜蕩羣穢，蓬斷麻亦折。","独立轉亭亭，心期鳳皇別。"]', '诗', 'shi', '', NULL, '遣興十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd266d86-07dc-40f5-9434-b62b1d96d70a', '遣興十首 四', '遣兴十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["豔豔翦紅英，團團削翠莖。","託根在褊淺，因依泥滓生。","中有合歡蘂，池枯難遽呈。","涼宵露華重，低徊當月明。"]', '["豔豔翦紅英，團團削翠莖。","託根在褊淺，因依泥滓生。","中有合歡蘂，池枯难遽呈。","涼宵露华重，低徊當月明。"]', '诗', 'shi', '', NULL, '遣興十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e16a0af-bbba-400c-b2f9-0242307b8afe', '遣興十首 五', '遣兴十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["晚荷猶展卷，早蟬遽蕭嘹。","露葉行已重，況乃江風搖。","炎夏火再伏，清商暗回飆。","寄言抱志士，日月東西跳。"]', '["晚荷猶展卷，早蟬遽蕭嘹。","露葉行已重，況乃江风搖。","炎夏火再伏，清商暗回飆。","寄言抱志士，日月东西跳。"]', '诗', 'shi', '', NULL, '遣興十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a81d7f9e-49be-4cbf-83ba-a4b64617e5a9', '遣興十首 六', '遣兴十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["買馬買鋸牙，買犢買破車。","養禽當養鶻，種樹先種花。","人生負俊健，天意與光華。","莫學蚯蚓輩，食泥近土涯。"]', '["買马買鋸牙，買犢買破车。","養禽當養鶻，種樹先種花。","人生負俊健，天意與光华。","莫学蚯蚓輩，食泥近土涯。"]', '诗', 'shi', '', NULL, '遣興十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cab9190-6971-47af-8208-c109b241231f', '遣興十首 七', '遣兴十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["愛直莫愛夸，愛疾莫愛斜。","愛謨莫愛詐，愛施莫愛奢。","擇才不求備，任物不過涯。","用人如用己，理國如理家。"]', '["愛直莫愛夸，愛疾莫愛斜。","愛謨莫愛詐，愛施莫愛奢。","擇才不求備，任物不過涯。","用人如用己，理国如理家。"]', '诗', 'shi', '', NULL, '遣興十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39c0ce48-29cc-4ea4-ba3e-d31aa9a75e60', '遣興十首 八', '遣兴十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["㸌㸌刀刃光，彎彎弓面張。","入水斬犀兕，上山椎虎狼。","里中無老少，喚作癲兒郎。","一日風雲會，橫行歸故鄉。"]', '["㸌㸌刀刃光，彎彎弓面張。","入水斬犀兕，上山椎虎狼。","里中無老少，喚作癲兒郎。","一日风云會，橫行归故乡。"]', '诗', 'shi', '', NULL, '遣興十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e82ab5b9-7ad5-40ad-ab93-c4a7f2347b0b', '遣興十首 九', '遣兴十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["團團規內星，未必明如月。","託迹近北辰，周天無淪沒。","老人在南極，地遠光不發。","見則壽聖明，願照高高闕。"]', '["團團規內星，未必明如月。","託迹近北辰，周天無淪沒。","老人在南極，地远光不發。","见則壽聖明，願照高高闕。"]', '诗', 'shi', '', NULL, '遣興十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2edd5889-0cf6-40f9-8f25-4495d45076fa', '遣興十首 十', '遣兴十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["河清諒嘉瑞，吾帝真聖人。","時哉不我夢，此時爲廢民。","光陰本跳躑，功業勞苦辛。","一到江陵郡，三年成去塵。"]', '["河清諒嘉瑞，吾帝真聖人。","时哉不我梦，此时爲廢民。","光陰本跳躑，功業勞苦辛。","一到江陵郡，三年成去塵。"]', '诗', 'shi', '', NULL, '遣興十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a2a2ea7-19ad-4913-b71c-9636923b14d9', '野節鞭', '野節鞭', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["神鞭鞭宇宙，玉鞭鞭騏驥。","緊綛野節鞭，本用鞭贔屭。","使君鞭甚長，使君馬亦利。","司馬竝馬行，司馬馬顦顇。","短鞭不可施，疾步無由致。","使君駐馬言，願以長鞭遺。","此遺不尋常，此鞭不容易。","金堅無繳繞，玉滑無塵膩。","青蛇坼生石，不刺山阿地。","烏龜旋眼斑，不染江頭淚。","長看雷雨痕，未忍駑駘試。","持用換所持，無令等閑棄。","答云君何奇，贈我君所貴。","我用亦不凡，終身保明義。","誓以鞭姦頑，不以鞭蹇躓。","指撝狡兔蹤，決撻怪龍睡。","惜令寸寸折，節節不虛墜。","因作換鞭詩，詩成謂同志。","而我得聞之，笑君年少意。","安用換長鞭，鞭長亦奚爲。","我有鞭尺餘，泥拋風雨漬。","不擬閑贈行，唯將爛誇醉。","春來信馬頭，款緩花前轡。","願我遲似攣，饒君疾如翅。"]', '["神鞭鞭宇宙，玉鞭鞭騏驥。","緊綛野節鞭，本用鞭贔屭。","使君鞭甚长，使君马亦利。","司马竝马行，司马马顦顇。","短鞭不可施，疾步無由致。","使君駐马言，願以长鞭遺。","此遺不尋常，此鞭不容易。","金堅無繳繞，玉滑無塵膩。","青蛇坼生石，不刺山阿地。","烏龟旋眼斑，不染江头泪。","长看雷雨痕，未忍駑駘試。","持用換所持，無令等闲棄。","答云君何奇，贈我君所貴。","我用亦不凡，終身保明義。","誓以鞭姦頑，不以鞭蹇躓。","指撝狡兔蹤，決撻怪龙睡。","惜令寸寸折，節節不虛墜。","因作換鞭诗，诗成謂同志。","而我得闻之，笑君年少意。","安用換长鞭，鞭长亦奚爲。","我有鞭尺餘，泥拋风雨漬。","不擬闲贈行，唯將爛誇醉。","春来信马头，款緩花前轡。","願我遲似攣，饒君疾如翅。"]', '诗', 'shi', '', NULL, '野節鞭 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc2dc6a8-32e6-482a-ad51-309c52882337', '旱災自咎貽七縣宰', '旱災自咎貽七縣宰', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["吾聞上帝心，降命明且仁。","臣稹苟有罪，胡不災我身。","胡爲旱一州，禍此千萬人。","一旱猶可忍，其旱亦已頻。","臘雪不滿地，膏雨不降春。","惻惻詔書下，半減麥與緡。","半租豈不薄，尚竭力與筋。","竭力不敢憚，慚戴天子恩。","纍纍婦拜姑，吶吶翁語孫。","禾黍日夜長，足得盈我囷。","還填折粟稅，酬償貰麥鄰。","苟無公私責，飲水不爲貧。","歡言未盈口，旱氣已再振。","六月天不雨，秋孟亦既旬。","區區昧陋積，禱祝非不勤。","日馳衰白顏，再拜泥甲鱗。","歸來重思忖，願告諸邑君。","以彼天道遠，豈如人事親。","團團囹圄中，無乃冤不申。","擾擾食廩內，無乃姦有因。","軋軋輸送車，無乃使不倫。","遙遙負擔卒，無乃役不均。","今年無大麥，計與珠玉濱。","邨胥與里吏，無乃求取繁。","符不歛錢急，值官因酒嗔。","誅求與撻罰，無乃不逡巡。","生小下里住，不曾州縣門。","訴詞千萬恨，無乃不得聞。","強豪富酒肉，窮獨無蒭薪。","俱由案牘吏，無乃移禍屯。","官分市井戶，迭配水陸珍。","未蒙所償直，無乃不敢言。","有一於此事，安可尤蒼旻。","借使漏刑憲，得不虞鬼神。","自顧頑滯牧，坐貽災沴臻。","上羞朝廷寄，不愧閭里民。","豈無神明宰，爲我同苦辛。","共布慈惠語，慰此衢客塵。"]', '["吾闻上帝心，降命明且仁。","臣稹苟有罪，胡不災我身。","胡爲旱一州，禍此千万人。","一旱猶可忍，其旱亦已頻。","臘雪不满地，膏雨不降春。","惻惻詔书下，半減麦與緡。","半租豈不薄，尚竭力與筋。","竭力不敢憚，慚戴天子恩。","纍纍婦拜姑，吶吶翁語孫。","禾黍日夜长，足得盈我囷。","還填折粟稅，酬償貰麦鄰。","苟無公私責，饮水不爲貧。","歡言未盈口，旱氣已再振。","六月天不雨，秋孟亦既旬。","區區昧陋積，禱祝非不勤。","日驰衰白顏，再拜泥甲鱗。","归来重思忖，願告諸邑君。","以彼天道远，豈如人事親。","團團囹圄中，無乃冤不申。","擾擾食廩內，無乃姦有因。","軋軋輸送车，無乃使不倫。","遙遙負擔卒，無乃役不均。","今年無大麦，計與珠玉濱。","邨胥與里吏，無乃求取繁。","符不歛錢急，值官因酒嗔。","誅求與撻罰，無乃不逡巡。","生小下里住，不曾州縣门。","訴词千万恨，無乃不得闻。","強豪富酒肉，窮独無蒭薪。","俱由案牘吏，無乃移禍屯。","官分市井戶，迭配水陸珍。","未蒙所償直，無乃不敢言。","有一於此事，安可尤蒼旻。","借使漏刑憲，得不虞鬼神。","自顧頑滯牧，坐貽災沴臻。","上羞朝廷寄，不愧閭里民。","豈無神明宰，爲我同苦辛。","共布慈惠語，慰此衢客塵。"]', '诗', 'shi', '', NULL, '旱災自咎貽七縣宰 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4403a9ef-46d6-4167-a6f8-5110a82548de', '蟲豸詩  一', '蟲豸诗  一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["巴蛇千種毒，其最鼻褰蛇。","掉舌翻紅燄，盤身蹙白花。","噴人豎毛髮，飲浪沸泥沙。","欲學叔敖瘞，其如多似麻。"]', '["巴蛇千種毒，其最鼻褰蛇。","掉舌翻紅燄，盤身蹙白花。","噴人豎毛髮，饮浪沸泥沙。","欲学叔敖瘞，其如多似麻。"]', '诗', 'shi', '', NULL, '蟲豸詩  一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bb4e894-312f-4685-8215-9a91b4857fba', '蟲豸詩  二', '蟲豸诗  二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["越嶺南濱海，武都西隱戎。","雄黃假名石，鷣鳥遠難籠。","詎有隳腸計，應無破腦功。","巴山晝昏黑，妖霧毒濛濛。"]', '["越嶺南濱海，武都西隐戎。","雄黄假名石，鷣鸟远难籠。","詎有隳腸計，應無破腦功。","巴山晝昏黑，妖霧毒濛濛。"]', '诗', 'shi', '', NULL, '蟲豸詩  二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f76a9c6-8aa6-4ba6-8e93-28f7e7feaa24', '蟲豸詩  三', '蟲豸诗  三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["漢帝斬蛇劒，晉時燒上天。","自茲繁巨蟒，往往壽千年。","白晝遮長道，青溪蒸毒煙。","戰龍蒼海外，平地血浮船。"]', '["漢帝斬蛇劒，晉时燒上天。","自茲繁巨蟒，往往壽千年。","白晝遮长道，青溪蒸毒煙。","戰龙蒼海外，平地血浮船。"]', '诗', 'shi', '', NULL, '蟲豸詩  三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3eb6890-789c-467d-b5e7-9892520ca718', '蟲豸詩  一', '蟲豸诗  一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["巴蛇蟠窟穴，穴下有巢蜂。","近樹禽垂翅，依原獸絕蹤。","微遭斷手足，厚毒破心胸。","昔甚招魂句，那知眼自逢。"]', '["巴蛇蟠窟穴，穴下有巢蜂。","近樹禽垂翅，依原獸絕蹤。","微遭斷手足，厚毒破心胸。","昔甚招魂句，那知眼自逢。"]', '诗', 'shi', '', NULL, '蟲豸詩  一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0a27bf8-573b-4d89-b177-98de3a00b452', '蟲豸詩  二', '蟲豸诗  二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["梨笑清都月，蜂游紫殿春。","構脾分部伍，嚼蕊奉君親。","翅羽頗同類，心神固異倫。","安知人世裏，下有噬人人。"]', '["梨笑清都月，蜂游紫殿春。","構脾分部伍，嚼蕊奉君親。","翅羽頗同類，心神固異倫。","安知人世裏，下有噬人人。"]', '诗', 'shi', '', NULL, '蟲豸詩  二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9692918c-8a0b-4091-8c2b-4c997717b993', '蟲豸詩  三', '蟲豸诗  三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蘭蕙本同畹，蜂蛇亦雜居。","害心俱毒螫，妖燄兩吹噓。","雷蟄吞噬止，枯焚巢穴除。","可憐相濟惡，勿謂禍無餘。"]', '["蘭蕙本同畹，蜂蛇亦杂居。","害心俱毒螫，妖燄兩吹噓。","雷蟄吞噬止，枯焚巢穴除。","可怜相濟惡，勿謂禍無餘。"]', '诗', 'shi', '', NULL, '蟲豸詩  三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f5f4c9c-9cba-45ab-a378-b9eaaea6e9a4', '蟲豸詩  一', '蟲豸诗  一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蜘蛛天下足，巴蜀就中多。","縫隙容長踦，虛空織橫羅。","縈纏傷竹柏，吞噬及蟲蛾。","爲送佳人喜，珠櫳無奈何。"]', '["蜘蛛天下足，巴蜀就中多。","縫隙容长踦，虛空织橫羅。","縈纏傷竹柏，吞噬及蟲蛾。","爲送佳人喜，珠櫳無奈何。"]', '诗', 'shi', '', NULL, '蟲豸詩  一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128bab67-8594-48a5-ba06-60aa72426fd4', '蟲豸詩  二', '蟲豸诗  二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["網密將求食，絲斜誤著人。","因依方紀緒，挂罥遂容身。","截道蟬冠礙，漫天玉露頻。","兒童憐小巧，漸欲及車輪。"]', '["網密將求食，絲斜誤著人。","因依方紀緒，挂罥遂容身。","截道蟬冠礙，漫天玉露頻。","兒童怜小巧，漸欲及车輪。"]', '诗', 'shi', '', NULL, '蟲豸詩  二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb23364-cf92-4fad-9b8e-d0c74f5f8726', '蟲豸詩  三', '蟲豸诗  三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["稚子憐圓網，佳人祝喜絲。","那知緣暗隙，忽被囓柔肌。","毒腠攻猶易，焚心療恐遲。","看看長祅緒，和扁欲漣洏。"]', '["稚子怜圓網，佳人祝喜絲。","那知緣暗隙，忽被囓柔肌。","毒腠攻猶易，焚心療恐遲。","看看长祅緒，和扁欲漣洏。"]', '诗', 'shi', '', NULL, '蟲豸詩  三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411395f3-d3f0-4b64-b7ec-e2341f7701c8', '蟲豸詩  一', '蟲豸诗  一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蟻子生無處，偏因溼處生。","陰霪煩擾攘，拾粒苦譻𧭈。","牀上主人病，耳中虛藏鳴。","雷霆翻不省，聞汝作牛聲。"]', '["蟻子生無处，偏因溼处生。","陰霪煩擾攘，拾粒苦譻𧭈。","牀上主人病，耳中虛藏鳴。","雷霆翻不省，闻汝作牛声。"]', '诗', 'shi', '', NULL, '蟲豸詩  一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('872884eb-a61d-4884-94dd-69dc32620d22', '蟲豸詩  二', '蟲豸诗  二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["時術功雖細，年深禍亦成。","攻穿漏江海，噆食困蛟鯨。","敢憚榱𣡵蠹，深藏柱石傾。","寄言持重者，微物莫全輕。"]', '["时術功雖細，年深禍亦成。","攻穿漏江海，噆食困蛟鯨。","敢憚榱𣡵蠹，深藏柱石傾。","寄言持重者，微物莫全轻。"]', '诗', 'shi', '', NULL, '蟲豸詩  二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3fe932c-027b-4689-9289-d4445b39c9be', '蟲豸詩  三', '蟲豸诗  三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["攘攘終朝見，悠悠卒歲疑。","詎能分牝牡，焉得有蝝蚳。","徙市竟何意，生涯都幾時。","巢由或逢我，應似我相期。"]', '["攘攘終朝见，悠悠卒歲疑。","詎能分牝牡，焉得有蝝蚳。","徙市竟何意，生涯都幾时。","巢由或逢我，應似我相期。"]', '诗', 'shi', '', NULL, '蟲豸詩  三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c76ab9d-896e-4d57-937f-91695a9aa894', '蟲豸詩  一', '蟲豸诗  一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蟆子微於蚋，朝繁夜則無。","毫端生羽翼，針喙噆肌膚。","暗毒應難免，羸形日漸枯。","將身遠相就，不敢恨非辜。"]', '["蟆子微於蚋，朝繁夜則無。","毫端生羽翼，針喙噆肌膚。","暗毒應难免，羸形日漸枯。","將身远相就，不敢恨非辜。"]', '诗', 'shi', '', NULL, '蟲豸詩  一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eceec461-19df-41bb-9979-fc6f2d6ab4e3', '蟲豸詩  二', '蟲豸诗  二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["晦景權藏毒，明時敢噬人。","不勞生詬怒，祗足助酸辛。","隼眥看無物，蛇軀庇有鱗。","天方芻狗我，甘與爾相親。"]', '["晦景權藏毒，明时敢噬人。","不勞生詬怒，祗足助酸辛。","隼眥看無物，蛇軀庇有鱗。","天方芻狗我，甘與爾相親。"]', '诗', 'shi', '', NULL, '蟲豸詩  二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a566d6-89d1-4036-a849-abe633e5bf14', '蟲豸詩  三', '蟲豸诗  三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有口深堪異，趨時詎可量。","誰令通鼻息，何故辨馨香。","沈水來滄海，崇蘭泛露光。","那能枉焚爇，爾衆我微茫。"]', '["有口深堪異，趨时詎可量。","誰令通鼻息，何故辨馨香。","沈水来滄海，崇蘭泛露光。","那能枉焚爇，爾衆我微茫。"]', '诗', 'shi', '', NULL, '蟲豸詩  三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0102e91-8d1f-43c3-8116-88098ac902ce', '蟲豸詩  一', '蟲豸诗  一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["可歎浮塵子，纖埃喻此微。","寧諭隔紗幌，幷解透綿衣。","有毒能成痏，無聲不見飛。","病來雙眼暗，何計辨雰霏。"]', '["可歎浮塵子，纖埃喻此微。","寧諭隔紗幌，幷解透綿衣。","有毒能成痏，無声不见飞。","病来雙眼暗，何計辨雰霏。"]', '诗', 'shi', '', NULL, '蟲豸詩  一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e7e7f3-7d24-4968-9bf6-e9fd2d02bbeb', '蟲豸詩  二', '蟲豸诗  二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["乍可巢蚊睫，胡爲附蟒鱗。","已微於蠢蠢，仍害及仁人。","動植皆分命，毫芒亦是身。","哀哉此幽物，生死敵浮塵。"]', '["乍可巢蚊睫，胡爲附蟒鱗。","已微於蠢蠢，仍害及仁人。","动植皆分命，毫芒亦是身。","哀哉此幽物，生死敵浮塵。"]', '诗', 'shi', '', NULL, '蟲豸詩  二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2c4140a-ed9f-4d7f-a3b2-2da6d6bc3fe1', '蟲豸詩  三', '蟲豸诗  三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["但覺皮膚憯，安知瑣細來。","因風吹薄霧，向日誤輕埃。","暗囓堪銷骨，潛飛有禍胎。","然無防備處，留待雪霜摧。"]', '["但覺皮膚憯，安知瑣細来。","因风吹薄霧，向日誤轻埃。","暗囓堪銷骨，潛飞有禍胎。","然無防備处，留待雪霜摧。"]', '诗', 'shi', '', NULL, '蟲豸詩  三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40637f56-967f-417a-89ad-4f372182b82c', '蟲豸詩  一', '蟲豸诗  一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["陰深山有瘴，溼墊草多蝱。","衆噬錐刀毒，羣飛風雨聲。","汗粘瘡痏痛，日曝苦辛行。","飽爾蛆殘腹，安知天地情。"]', '["陰深山有瘴，溼墊草多蝱。","衆噬錐刀毒，羣飞风雨声。","汗粘瘡痏痛，日曝苦辛行。","飽爾蛆殘腹，安知天地情。"]', '诗', 'shi', '', NULL, '蟲豸詩  一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f99da0-5d2c-4175-a138-4ad16e360342', '蟲豸詩  二', '蟲豸诗  二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["千山溪沸石，六月火燒雲。","自顧生無類，那堪毒有羣。","搏牛皮若截，噬馬血成文。","蹄角尚如此，肌膚安可云。"]', '["千山溪沸石，六月火燒云。","自顧生無類，那堪毒有羣。","搏牛皮若截，噬马血成文。","蹄角尚如此，肌膚安可云。"]', '诗', 'shi', '', NULL, '蟲豸詩  二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de1c8d47-55b7-4072-b878-93cd07a02b5f', '蟲豸詩  三', '蟲豸诗  三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["辛螫終非久，炎涼本遞興。","秋風自天落，夏蘖與霜澄。","一鏡開潭面，千鋒露石稜。","氣平蟲豸死，雲路好攀登。"]', '["辛螫終非久，炎涼本遞兴。","秋风自天落，夏蘖與霜澄。","一镜开潭面，千鋒露石稜。","氣平蟲豸死，云路好攀登。"]', '诗', 'shi', '', NULL, '蟲豸詩  三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba754cfa-4feb-43f8-9bcb-24deaabd5487', '楚歌十首 一', '楚歌十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["楚人千萬戶，生死繫時君。","當璧便爲嗣，賢愚安可分。","干戈長浩浩，篡亂亦紛紛。","縱有明在下，區區何足云。"]', '["楚人千万戶，生死繫时君。","當璧便爲嗣，賢愚安可分。","干戈长浩浩，篡亂亦紛紛。","縱有明在下，區區何足云。"]', '诗', 'shi', '', NULL, '楚歌十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('966f4f4f-388a-41fd-9ae0-bb13f11b8bfd', '楚歌十首 二', '楚歌十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["陶虞事已遠，尼父獨將明。","潛穴龍無位，幽林蘭自生。","楚王謀授邑，此意復中傾。","未別子西語，縱來何所成。"]', '["陶虞事已远，尼父独將明。","潛穴龙無位，幽林蘭自生。","楚王謀授邑，此意复中傾。","未別子西語，縱来何所成。"]', '诗', 'shi', '', NULL, '楚歌十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c148921-adcf-446f-b195-73b2a6fb7f7d', '楚歌十首 三', '楚歌十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["平王漸昏惑，無極轉承恩。","子建猶相貳，伍奢安得存。","生居宮雉閟，死葬寢園尊。","豈料奔吳士，鞭屍郢市門。"]', '["平王漸昏惑，無極轉承恩。","子建猶相貳，伍奢安得存。","生居宮雉閟，死葬寢园尊。","豈料奔吳士，鞭屍郢市门。"]', '诗', 'shi', '', NULL, '楚歌十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffd2582f-032b-469c-8197-86a6b3fcab91', '楚歌十首 四', '楚歌十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["懼盈因鄧曼，罷獵爲樊姬。","盛德留金石，清風鑒薄帷。","襄王忽妖夢，宋玉復淫辭。","萬事捐宮館，空山雲雨期。"]', '["懼盈因鄧曼，罷獵爲樊姬。","盛德留金石，清风鑒薄帷。","襄王忽妖梦，宋玉复淫辞。","万事捐宮館，空山云雨期。"]', '诗', 'shi', '', NULL, '楚歌十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc3a802-7480-4a0e-88fe-b013e9cff7da', '楚歌十首 五', '楚歌十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["宜僚南市住，未省食人恩。","臨難忽相感，解紛寧用言。","何如晉夷甫，坐占紫微垣。","看著五胡亂，清談空自尊。"]', '["宜僚南市住，未省食人恩。","臨难忽相感，解紛寧用言。","何如晉夷甫，坐占紫微垣。","看著五胡亂，清談空自尊。"]', '诗', 'shi', '', NULL, '楚歌十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8ed0cae-28f1-4bbc-b9a8-0e48ac31c24f', '楚歌十首 六', '楚歌十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["誰恃王深寵，誰爲楚上卿。","包胥心獨許，連夜哭秦兵。","千乘徒虛爾，一夫安可輕。","殷勤聘名士，莫但倚方城。"]', '["誰恃王深寵，誰爲楚上卿。","包胥心独許，連夜哭秦兵。","千乘徒虛爾，一夫安可轻。","殷勤聘名士，莫但倚方城。"]', '诗', 'shi', '', NULL, '楚歌十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('701da57e-3257-4289-998b-a3042ad5fb14', '楚歌十首 七', '楚歌十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["梁業雄圖盡，遺孫世運消。","宣明徒有號，江漢不相朝。","碑碣高臨路，松枝半作樵。","唯餘開聖寺，猶學武皇妖。"]', '["梁業雄圖尽，遺孫世運消。","宣明徒有號，江漢不相朝。","碑碣高臨路，松枝半作樵。","唯餘开聖寺，猶学武皇妖。"]', '诗', 'shi', '', NULL, '楚歌十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a70a992c-6ca6-4a79-9997-2197a204c5bb', '楚歌十首 八', '楚歌十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["江陵南北道，長有遠人來。","死別登舟去，生心上馬迴。","榮枯誠異日，今古盡同灰。"]', '["江陵南北道，长有远人来。","死別登舟去，生心上马迴。","榮枯誠異日，今古尽同灰。"]', '诗', 'shi', '', NULL, '楚歌十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfe907e2-c892-4893-b463-3cb229cddb89', '楚歌十首 九', '楚歌十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["三峽連天水，奔波萬里來。","風濤各自急，前後苦相推。","倒入黃牛漩，驚衝灩澦堆。","古今流不盡，流去不曾迴。"]', '["三峽連天水，奔波万里来。","风濤各自急，前後苦相推。","倒入黄牛漩，驚衝灩澦堆。","古今流不尽，流去不曾迴。"]', '诗', 'shi', '', NULL, '楚歌十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2f9fd22-4d4e-4614-97e8-b5f0186584a9', '楚歌十首 十', '楚歌十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["八荒同日月，萬古共山川。","生死既由命，興衰還付天。","棲棲王粲賦，憤憤屈平篇。","各自埋幽恨，江流終宛然。"]', '["八荒同日月，万古共山川。","生死既由命，兴衰還付天。","棲棲王粲賦，憤憤屈平篇。","各自埋幽恨，江流終宛然。"]', '诗', 'shi', '', NULL, '楚歌十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef397857-d135-46ca-8580-dd9ab65d2db3', '襄陽道', '襄陽道', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["羊公名漸遠，唯有峴山碑。","近日稱難繼，曹王任馬彝。","椒蘭俱下世，城郭到今時。","漢水清如玉，流來本爲誰。"]', '["羊公名漸远，唯有峴山碑。","近日稱难繼，曹王任马彝。","椒蘭俱下世，城郭到今时。","漢水清如玉，流来本爲誰。"]', '诗', 'shi', '', NULL, '襄陽道 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b4aa2bb-9d0c-41c6-9a2f-bd7dac0df7ac', '賦得魚登龍門', '賦得鱼登龙门', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["魚貫終何益，龍門在苦登。","有成當作雨，無用恥爲鵬。","激浪誠難泝，雄心亦自憑。","風雲潛會合，鬐鬣忽騰凌。","泥滓辭河濁，煙霄見海澄。","迴瞻順流輩，誰敢望同升。"]', '["鱼貫終何益，龙门在苦登。","有成當作雨，無用恥爲鵬。","激浪誠难泝，雄心亦自憑。","风云潛會合，鬐鬣忽腾凌。","泥滓辞河濁，煙霄见海澄。","迴瞻順流輩，誰敢望同升。"]', '诗', 'shi', '', NULL, '賦得魚登龍門 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fffe87cc-4990-4051-9cae-9cc53afef0bd', '貞元曆', '貞元曆', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["象魏纔頒曆，龍鑣已御天。","猶看後元曆，新署永貞年。","半歲光陰在，三朝禮數遷。","無因書簡冊，空得詠詩篇。"]', '["象魏纔頒曆，龙鑣已御天。","猶看後元曆，新署永貞年。","半歲光陰在，三朝禮數遷。","無因书簡冊，空得詠诗篇。"]', '诗', 'shi', '', NULL, '貞元曆 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f5114cf-d59a-4a34-9e1f-f3828deb038b', '塞馬', '塞马', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["塞馬倦江渚，今朝神彩生。","曉風寒獵獵，乍得草頭行。","夷狄寢烽候，關河無戰聲。","何由當陣面，從爾四蹄輕。"]', '["塞马倦江渚，今朝神彩生。","晓风寒獵獵，乍得草头行。","夷狄寢烽候，关河無戰声。","何由當陣面，從爾四蹄轻。"]', '诗', 'shi', '', NULL, '塞馬 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c6b57f-2574-4491-965f-83127fd81a37', '鹿角鎮', '鹿角鎮', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["去年湖水滿，此地覆行舟。","萬怪吹高浪，千人死亂流。","誰能問帝子，何事寵陽侯。","漸恐鯨鯢大，波濤及九州。"]', '["去年湖水满，此地覆行舟。","万怪吹高浪，千人死亂流。","誰能问帝子，何事寵陽侯。","漸恐鯨鯢大，波濤及九州。"]', '诗', 'shi', '', NULL, '鹿角鎮 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf8f5e2-bfd7-4fd8-bcae-b47488ff6b7f', '感事三首 一', '感事三首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["爲國謀羊舌，從來不爲身。","此心長自保，終不學張陳。"]', '["爲国謀羊舌，從来不爲身。","此心长自保，終不学張陳。"]', '诗', 'shi', '', NULL, '感事三首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a019e34-9574-468a-906d-903071a4bac8', '感事三首 二', '感事三首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["自笑心何劣，區區辨所冤。","伯仁雖到死，終不向人言。"]', '["自笑心何劣，區區辨所冤。","伯仁雖到死，終不向人言。"]', '诗', 'shi', '', NULL, '感事三首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd8007f6-1d78-4c54-a1ea-ac85294c212a', '感事三首 三', '感事三首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["富貴年皆長，風塵舊轉稀。","白頭方見絕，遙爲一霑衣。"]', '["富貴年皆长，风塵旧轉稀。","白头方见絕，遙爲一霑衣。"]', '诗', 'shi', '', NULL, '感事三首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55251641-dd16-4501-baf4-886c0d3599ad', '題翰林東閤前小松', '題翰林东閤前小松', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["簷礙修鱗亞，霜侵簇翠黃。","唯餘入琴韻，終待舜弦張。"]', '["簷礙修鱗亞，霜侵簇翠黄。","唯餘入琴韻，終待舜弦張。"]', '诗', 'shi', '', NULL, '題翰林東閤前小松 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c969ec8f-af68-484d-9131-ddd7ad918280', '清都夜境', '清都夜境', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夜久連觀靜，斜月何晶熒。","寥天如碧玉，歷歷綴華星。","樓榭自陰暎，雲牖深冥冥。","纖埃悄不起，玉砌寒光清。","棲鶴露微影，枯松多怪形。","南廂儼容衛，音響如可聆。","啓聖發空洞，朝真趨廣庭。","閑開蘂珠殿，暗閱金字經。","屏氣動方息，凝神心自靈。","悠悠車馬上，浩思安得寧。"]', '["夜久連观静，斜月何晶熒。","寥天如碧玉，歷歷綴华星。","楼榭自陰暎，云牖深冥冥。","纖埃悄不起，玉砌寒光清。","棲鹤露微影，枯松多怪形。","南廂儼容衛，音响如可聆。","啓聖發空洞，朝真趨廣庭。","闲开蘂珠殿，暗閱金字經。","屏氣动方息，凝神心自靈。","悠悠车马上，浩思安得寧。"]', '诗', 'shi', '', NULL, '清都夜境 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36ead4f2-ce71-4c04-9dae-84f0cf10c5ab', '春晚寄楊十二兼呈趙八', '春晚寄楊十二兼呈趙八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蒙蒙竹樹深，簾牖多清陰。","避日坐林影，餘花委芳襟。","傾尊就殘酌，舒卷續微吟。","空際颺高蝶，風中聆素琴。","廣庭備幽趣，復對商山岑。","獨此愛時景，曠懷雲外心。","遷鸎戀嘉木，求友多好音。","自無琅玕實，安得蓮花簪。","寄之二君子，希見雙南金。"]', '["蒙蒙竹樹深，簾牖多清陰。","避日坐林影，餘花委芳襟。","傾尊就殘酌，舒卷續微吟。","空際颺高蝶，风中聆素琴。","廣庭備幽趣，复对商山岑。","独此愛时景，曠懷云外心。","遷鸎戀嘉木，求友多好音。","自無琅玕實，安得蓮花簪。","寄之二君子，希见雙南金。"]', '诗', 'shi', '', NULL, '春晚寄楊十二兼呈趙八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55e6652-beb5-4064-9463-04e26fa7f0fc', '與楊十二李三早入永壽寺看牡丹', '與楊十二李三早入永壽寺看牡丹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["曉入白蓮宮，琉璃花界淨。","開敷多喻草，凌亂被幽徑。","壓砌錦地鋪，當霞日輪暎。","蝶舞香暫飄，蠭牽蕊難正。","籠處彩雲合，露湛紅珠瑩。","結葉影自交，搖風光不定。","繁華有時節，安得保全盛。","色見盡浮榮，希君了真性。"]', '["晓入白蓮宮，琉璃花界淨。","开敷多喻草，凌亂被幽徑。","壓砌錦地鋪，當霞日輪暎。","蝶舞香暫飄，蠭牽蕊难正。","籠处彩云合，露湛紅珠瑩。","結葉影自交，搖风光不定。","繁华有时節，安得保全盛。","色见尽浮榮，希君了真性。"]', '诗', 'shi', '', NULL, '與楊十二李三早入永壽寺看牡丹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d342a15b-2a35-4f8f-8ec1-45df42fb4d55', '春餘遣興', '春餘遣兴', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春去日漸遲，庭空草偏長。","餘英間初實，雪絮縈蛛網。","好鳥多息陰，新篁已成響。","簾開斜照入，樹褭游絲上。","絕跡念物閑，良時契心賞。","單衣頗新綽，虛室復清敞。","置酒奉親賓，樹萱自怡養。","笑倚連枝花，恭扶瑞藤杖。","步屧恣優游，望山多氣象。","雲葉遙卷舒，風裾動蕭爽。","簪纓固煩雜，江海徒浩蕩。","野馬籠赤霄，無由負羈鞅。"]', '["春去日漸遲，庭空草偏长。","餘英间初實，雪絮縈蛛網。","好鸟多息陰，新篁已成响。","簾开斜照入，樹褭游絲上。","絕跡念物闲，良时契心賞。","單衣頗新綽，虛室复清敞。","置酒奉親賓，樹萱自怡養。","笑倚連枝花，恭扶瑞藤杖。","步屧恣優游，望山多氣象。","云葉遙卷舒，风裾动蕭爽。","簪纓固煩杂，江海徒浩蕩。","野马籠赤霄，無由負羈鞅。"]', '诗', 'shi', '', NULL, '春餘遣興 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbea6fa2-9164-4aa2-b3a2-4a33a8ead96a', '憶雲之', '憶云之', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["爲魚實愛泉，食辛寧避蓼。","人生既相合，不復論窕窕。","滄海良有窮，白日非長皎。","何事一人心，各在四方表。","泛若逐水萍，居爲附松蔦。","流浪隨所之，縈紆牽所繞。","百齡頗跼促，況復迷壽夭。","芟髮君已衰，冠歲予非小。","娛樂不及時，暮年壯心少。","感此幽念綿，遂爲長悄悄。","中庭草木春，歷亂遞相擾。","奇樹花冥冥，竹竿鳳褭褭。","幽芳被蘭徑，安得寄天杪。","萬里瀟湘魂，夜夜南枝鳥。"]', '["爲鱼實愛泉，食辛寧避蓼。","人生既相合，不复論窕窕。","滄海良有窮，白日非长皎。","何事一人心，各在四方表。","泛若逐水萍，居爲附松蔦。","流浪隨所之，縈紆牽所繞。","百齡頗跼促，況复迷壽夭。","芟髮君已衰，冠歲予非小。","娛乐不及时，暮年壯心少。","感此幽念綿，遂爲长悄悄。","中庭草木春，歷亂遞相擾。","奇樹花冥冥，竹竿鳳褭褭。","幽芳被蘭徑，安得寄天杪。","万里瀟湘魂，夜夜南枝鸟。"]', '诗', 'shi', '', NULL, '憶雲之 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17ae0e25-c004-42a1-b9d2-cb854cd10c0e', '別李三', '別李三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["階蓂附瑤砌，藂蘭偶芳藿。","高位良有依，幽姿亦相託。","鮑叔知我貧，烹葵不爲薄。","半面契始終，千金比然諾。","人生繫時命，安得無苦樂。","但感遊子顏，又值餘英落。","蒼蒼秦樹雲，去去緱山鶴。","日暮分手歸，楊花滿城郭。"]', '["階蓂附瑤砌，藂蘭偶芳藿。","高位良有依，幽姿亦相託。","鲍叔知我貧，烹葵不爲薄。","半面契始終，千金比然諾。","人生繫时命，安得無苦乐。","但感游子顏，又值餘英落。","蒼蒼秦樹云，去去緱山鹤。","日暮分手归，楊花满城郭。"]', '诗', 'shi', '', NULL, '別李三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed8cefd7-9acb-43dd-880b-0b2c9659da99', '秋夕遠懷', '秋夕远懷', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["旦夕天氣爽，風飄葉漸輕。","星繁河漢白，露逼衾枕清。","丹鳥月中滅，莎雞牀下鳴。","悠悠此懷抱，況復多遠情。"]', '["旦夕天氣爽，风飄葉漸轻。","星繁河漢白，露逼衾枕清。","丹鸟月中滅，莎雞牀下鳴。","悠悠此懷抱，況复多远情。"]', '诗', 'shi', '', NULL, '秋夕遠懷 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28fd18f1-a0b6-4aef-9ac3-4de9a7839572', '東西道', '东西道', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["天皇開四極，便有東西道。","萬古閱行人，行人幾人老。","顧我倦行者，息陰何不早？","少壯塵事多，那言壯年好。"]', '["天皇开四極，便有东西道。","万古閱行人，行人幾人老。","顧我倦行者，息陰何不早？","少壯塵事多，那言壯年好。"]', '诗', 'shi', '', NULL, '東西道 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('864823bd-36a5-4ffb-afb0-08debd6583f3', '分流水', '分流水', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["古時愁別淚，滴作分流水。","日夜東西流，分流幾千里。","通塞兩不見，波瀾各自起。","與君相背飛，去去心如此。"]', '["古时愁別泪，滴作分流水。","日夜东西流，分流幾千里。","通塞兩不见，波瀾各自起。","與君相背飞，去去心如此。"]', '诗', 'shi', '', NULL, '分流水 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e2ef4b2-a580-4a91-a465-2a89be25d5af', '西還', '西還', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["悠悠洛陽夢，鬱鬱灞陵樹。","落日正西歸，逢君又東去。"]', '["悠悠洛陽梦，鬱鬱灞陵樹。","落日正西归，逢君又东去。"]', '诗', 'shi', '', NULL, '西還 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90d24d06-910e-476e-8819-47f127e03360', '含風夕', '含风夕', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["炎昏勌煩久，逮此含風夕。","夏服稍輕清，秋堂已岑寂。","載欣涼宇曠，復念佳辰擲。","絡緯驚歲功，顧我何成績。","青熒微月鉤，幽暉洞陰魄。","水鏡涵玉輪，若見淵泉璧。","參差簾牖重，次第籠虛白。","樹影滿空牀，螢光綴深壁。","悵望牽牛星，復爲經年隔。","露網褭風珠，輕河泛遙碧。","詎無深秋夜，感此乍流易。","亦有遲暮年，壯年良自惜。","循環切中腸，感念追往昔。","接瞬無停陰，何言問陳積。","馨香推蕙蘭，堅貞諭松柏。","生物固有涯，安能比金石。","況茲百齡內，擾擾紛衆役。","日月東西馳，飛車無留跡。","來者良未窮，去矣定奚適。","委順在物爲，營營復何益。"]', '["炎昏勌煩久，逮此含风夕。","夏服稍轻清，秋堂已岑寂。","載欣涼宇曠，复念佳辰擲。","絡緯驚歲功，顧我何成績。","青熒微月鉤，幽暉洞陰魄。","水镜涵玉輪，若见淵泉璧。","參差簾牖重，次第籠虛白。","樹影满空牀，螢光綴深壁。","悵望牽牛星，复爲經年隔。","露網褭风珠，轻河泛遙碧。","詎無深秋夜，感此乍流易。","亦有遲暮年，壯年良自惜。","循环切中腸，感念追往昔。","接瞬無停陰，何言问陳積。","馨香推蕙蘭，堅貞諭松柏。","生物固有涯，安能比金石。","況茲百齡內，擾擾紛衆役。","日月东西驰，飞车無留跡。","来者良未窮，去矣定奚適。","委順在物爲，營營复何益。"]', '诗', 'shi', '', NULL, '含風夕 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2261d409-1d3d-4286-979e-2dcae212eea5', '秋堂夕', '秋堂夕', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["炎涼正迴互，金火鬱相乘。","雲雷時交構，川澤方蒸騰。","清風一朝勝，白露忽已凝。","草木凡氣盡，始見天地澄。","況此秋堂夕，幽懷曠無朋。","蕭條簾外雨，倏閃案前燈。","書卷滿牀席，蠨蛸懸復升。","啼兒屢啞咽，勌僮時寢興。","泛覺昏夜目，詠謠暢煩膺。","況吟獲麟章，欲罷久不能。","堯舜事已遠，丘道安可勝。","蜉蝣不信鶴，蜩鷃肯窺鵬。","當年且不偶，沒世何必稱。","胡爲揭聞見，褒貶貽愛憎。","焉用汩其泥，豈在清如冰。","非白又非黑，誰能點青蠅。","處世苟無悶，佯狂道非弘。","無言被人覺，予亦笑孫登。"]', '["炎涼正迴互，金火鬱相乘。","云雷时交構，川澤方蒸腾。","清风一朝勝，白露忽已凝。","草木凡氣尽，始见天地澄。","況此秋堂夕，幽懷曠無朋。","蕭條簾外雨，倏閃案前灯。","书卷满牀席，蠨蛸懸复升。","啼兒屢啞咽，勌僮时寢兴。","泛覺昏夜目，詠謠暢煩膺。","況吟獲麟章，欲罷久不能。","堯舜事已远，丘道安可勝。","蜉蝣不信鹤，蜩鷃肯窺鵬。","當年且不偶，沒世何必稱。","胡爲揭闻见，褒貶貽愛憎。","焉用汩其泥，豈在清如冰。","非白又非黑，誰能点青蠅。","处世苟無悶，佯狂道非弘。","無言被人覺，予亦笑孫登。"]', '诗', 'shi', '', NULL, '秋堂夕 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dce476e-3c4b-4e29-b7df-e6cf83a3f07b', '酬樂天', '酬乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["放鶴在深水，置魚在高枝。","升沈或異勢，同謂非所宜。","君爲邑中吏，皎皎鸞鳳姿。","顧我何爲者，翻侍白玉墀。","昔作芸香侶，三載不暫離。","逮茲忽相失，旦夕夢魂思。","崔嵬驪山頂，宮樹遙參差。","祗得兩相望，不得長相隨。","多君歲寒意，裁作秋興詩。","上言風塵苦，下言時節移。","官家事拘束，安得攜手期。","願爲雲與雨，會合天之垂。"]', '["放鹤在深水，置鱼在高枝。","升沈或異勢，同謂非所宜。","君爲邑中吏，皎皎鸾鳳姿。","顧我何爲者，翻侍白玉墀。","昔作芸香侶，三載不暫離。","逮茲忽相失，旦夕梦魂思。","崔嵬驪山頂，宮樹遙參差。","祗得兩相望，不得长相隨。","多君歲寒意，裁作秋兴诗。","上言风塵苦，下言时節移。","官家事拘束，安得携手期。","願爲云與雨，會合天之垂。"]', '诗', 'shi', '', NULL, '酬樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16b7b30e-0f7c-4915-bd40-2aef2e3884cc', '楊子華畫三首 一', '楊子华畫三首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["楊畫遠於展，何言今在茲。","依然古妝服，但感時節移。","念君一朝意，遺我千載思。","子亦幾時客，安能長苦悲。"]', '["楊畫远於展，何言今在茲。","依然古妝服，但感时節移。","念君一朝意，遺我千載思。","子亦幾时客，安能长苦悲。"]', '诗', 'shi', '', NULL, '楊子華畫三首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fe720b1-bd93-400f-b107-178710f0ea75', '楊子華畫三首 二', '楊子华畫三首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["皓腕卷紅袖，錦韝臂蒼鶚。","故人斷弦心，稚齒從禽樂。","當年惜貴遊，遺形寄丹雘。","骨象或依稀，鉛華已寥落。","似對古人民，無復昔城郭。","子亦觀病身，色空俱寂寞。"]', '["皓腕卷紅袖，錦韝臂蒼鶚。","故人斷弦心，稚齒從禽乐。","當年惜貴游，遺形寄丹雘。","骨象或依稀，鉛华已寥落。","似对古人民，無复昔城郭。","子亦观病身，色空俱寂寞。"]', '诗', 'shi', '', NULL, '楊子華畫三首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6916f5c-a432-4e91-81ae-9f9f69a49e24', '楊子華畫三首 三', '楊子华畫三首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["顛倒世人心，紛紛乏公是。","真賞畫不成，畫賞真相似。","丹青各所尚，工拙何足恃。","求此妄中精，嗟哉子華子。"]', '["顛倒世人心，紛紛乏公是。","真賞畫不成，畫賞真相似。","丹青各所尚，工拙何足恃。","求此妄中精，嗟哉子华子。"]', '诗', 'shi', '', NULL, '楊子華畫三首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f04e27-0036-455d-a517-eff31de0f327', '西州院', '西州院', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["自入西州院，唯見東川城。","今夜城頭月，非暗又非明。","文案牀席滿，卷舒贓罪名。","慘悽且煩勌，棄之階下行。","悵望天廻轉，動搖萬里情。","參辰次第出，牛女顛倒傾。","況此風中柳，枝條千萬莖。","到來籬下筍，亦已長短生。","感愴正多緒，鵶鵶相喚驚。","牆上杜鵑鳥，又作思歸鳴。","以彼撩亂思，吟爲幽怨聲。","吟罷終不寢，鼕鼕復鐺鐺。"]', '["自入西州院，唯见东川城。","今夜城头月，非暗又非明。","文案牀席满，卷舒贓罪名。","慘悽且煩勌，棄之階下行。","悵望天廻轉，动搖万里情。","參辰次第出，牛女顛倒傾。","況此风中柳，枝條千万莖。","到来籬下筍，亦已长短生。","感愴正多緒，鵶鵶相喚驚。","牆上杜鵑鸟，又作思归鳴。","以彼撩亂思，吟爲幽怨声。","吟罷終不寢，鼕鼕复鐺鐺。"]', '诗', 'shi', '', NULL, '西州院 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4ccc5e8-7c44-4d38-8605-774e54b5f1eb', '臺中鞫獄憶開元觀舊事呈損之兼贈周兄四十韻', '台中鞫獄憶开元观旧事呈損之兼贈周兄四十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶在開元館，食柏練玉顏。","疎慵日高臥，自謂輕人寰。","李生隔牆住，隔牆如隔山。","怪我久不識，先來問驕頑。","十過乃一往，遂成相往還。","以我文章卷，文章甚斒斕。","因言辛庾輩，亦願放羸孱。","既廻數子顧，展轉相連攀。","驅令選科目，若在闠與闤。","學隨塵土墜，漫數公卿關。","唯恐壞情性，安能懼謗訕。","還招辛庾李，靜處杯巡環。","進取果由命，不由趨險艱。","穿楊二三子，弓矢次第彎。","推我亦上道，再聯朝士班。","二月除御史，三月使巴蠻。","蠻民詀諵訴，齧指明痛癏。","憐蠻不解語，爲發昏帥姦。","歸來五六月，旱色天地殷。","分司別兄弟，各各淚潸潸。","哀哉劇部職，唯數贓罪鍰。","死款依稀取，鬬辭方便刪。","道心常自愧，柔髮難久黫。","折支望車乘，支痛誰置患。","奇哉乳臭兒，緋紫䙀被間。","漸大官漸貴，漸富心漸慳。","鬧裝轡頭𧤾，靜拭腰帶斑。","鷂子繡線𩏪，狗兒金油鐶。","香湯洗騘馬，翠篾籠白鷴。","月請公王封，冰受天子頒。","開筵試歌舞，別宅寵妖嫻。","坐臥摩綿褥，捧擁綟絲鬟。","旦夕不相離，比翼若飛鸞。","而我亦何苦，三十身已鰥。","愁吟心骨顫，寒臥支體𤸷。","居處雖幽靜，尤悔少愉㦨。","不如周道士，鶴嶺臨鐘灣。","繞院松瑟瑟，通畦水潺潺。","陽坡自尋蕨，邨沼看漚菅。","窮通兩未遂，營營真老閑。"]', '["憶在开元館，食柏練玉顏。","疎慵日高臥，自謂轻人寰。","李生隔牆住，隔牆如隔山。","怪我久不識，先来问驕頑。","十過乃一往，遂成相往還。","以我文章卷，文章甚斒斕。","因言辛庾輩，亦願放羸孱。","既廻數子顧，展轉相連攀。","驱令選科目，若在闠與闤。","学隨塵土墜，漫數公卿关。","唯恐壞情性，安能懼謗訕。","還招辛庾李，静处杯巡环。","進取果由命，不由趨險艱。","穿楊二三子，弓矢次第彎。","推我亦上道，再聯朝士班。","二月除御史，三月使巴蠻。","蠻民詀諵訴，齧指明痛癏。","怜蠻不解語，爲發昏帥姦。","归来五六月，旱色天地殷。","分司別兄弟，各各泪潸潸。","哀哉劇部職，唯數贓罪鍰。","死款依稀取，鬬辞方便刪。","道心常自愧，柔髮难久黫。","折支望车乘，支痛誰置患。","奇哉乳臭兒，緋紫䙀被间。","漸大官漸貴，漸富心漸慳。","鬧裝轡头𧤾，静拭腰带斑。","鷂子繡線𩏪，狗兒金油鐶。","香湯洗騘马，翠篾籠白鷴。","月請公王封，冰受天子頒。","开筵試歌舞，別宅寵妖嫻。","坐臥摩綿褥，捧擁綟絲鬟。","旦夕不相離，比翼若飞鸾。","而我亦何苦，三十身已鰥。","愁吟心骨顫，寒臥支體𤸷。","居处雖幽静，尤悔少愉㦨。","不如周道士，鹤嶺臨鐘灣。","繞院松瑟瑟，通畦水潺潺。","陽坡自尋蕨，邨沼看漚菅。","窮通兩未遂，營營真老闲。"]', '诗', 'shi', '', NULL, '臺中鞫獄憶開元觀舊事呈損之兼贈周兄四十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75cfad90-de67-4955-98ca-5ec0eb0fa62f', '韋氏館與周隱客杜歸和泛舟', '韋氏館與周隐客杜归和泛舟', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["天色低澹澹，池光漫油油。","輕舟閑繳繞，不遠池上樓。","時物欣外獎，真元隨內修。","神恬津藏滿，氣委支節柔。","衆處豈自異，曠懷誰我儔。","風車籠野馬，八荒安足遊。","開顏陸渾杜，握手靈都周。","持君寶珠贈，頂戴頭上頭。"]', '["天色低澹澹，池光漫油油。","轻舟闲繳繞，不远池上楼。","时物欣外獎，真元隨內修。","神恬津藏满，氣委支節柔。","衆处豈自異，曠懷誰我儔。","风车籠野马，八荒安足游。","开顏陸渾杜，握手靈都周。","持君寶珠贈，頂戴头上头。"]', '诗', 'shi', '', NULL, '韋氏館與周隱客杜歸和泛舟 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e6ab262-f5b3-4c3e-ba7f-d43780e8fa44', '劉氏館集隱客歸和子元及之子蒙晦之', '劉氏館集隐客归和子元及之子蒙晦之', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["溼墊緣竹徑，寥落護岸冰。","偶然沽市酒，不越四五升。","詩客愛時景，道人話升騰。","笑言各有趣，悠哉古孫登。"]', '["溼墊緣竹徑，寥落護岸冰。","偶然沽市酒，不越四五升。","诗客愛时景，道人話升腾。","笑言各有趣，悠哉古孫登。"]', '诗', 'shi', '', NULL, '劉氏館集隱客歸和子元及之子蒙晦之 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1082f931-41c9-4f50-973b-82fdb64ab869', '寄隱客', '寄隐客', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我年三十二，鬢有八九絲。","非無官次第，其如身早衰。","今人夸貴富，肉食與妖姬。","而我俱不樂，貴富亦何爲。","況逢多士朝，賢俊若布棊。","班行次第立，朱紫相參差。","謨猷密勿進，羽檄縱橫馳。","監察官甚小，發言無所裨。","小官仍不了，譴奪亦已隨。","時或不之棄，得不自棄之。","陶君喜不遇，顧我復何疑。","潛書周隱士，白雲今有期。"]', '["我年三十二，鬢有八九絲。","非無官次第，其如身早衰。","今人夸貴富，肉食與妖姬。","而我俱不乐，貴富亦何爲。","況逢多士朝，賢俊若布棊。","班行次第立，朱紫相參差。","謨猷密勿進，羽檄縱橫驰。","監察官甚小，發言無所裨。","小官仍不了，譴奪亦已隨。","时或不之棄，得不自棄之。","陶君喜不遇，顧我复何疑。","潛书周隐士，白云今有期。"]', '诗', 'shi', '', NULL, '寄隱客 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67106cbb-0b9c-4d2c-ae3b-2edea7d74627', '元和五年予官不了罰俸西歸三月六日至陝府與吳十一兄端公崔二十二院長思愴曩遊因投五十韻', '元和五年予官不了罰俸西归三月六日至陝府與吳十一兄端公崔二十二院长思愴曩游因投五十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["小年閑愛春，認得春風意。","未有花草時，先醲曉窗睡。","霞朝澹雲色，霽景牽詩思。","漸到柳枝頭，川光始明媚。","長安車馬客，傾心奉權貴。","晝夜塵土中，那言早春至。","此時我獨遊，我遊有倫次。","閑行曲江岸，便宿慈恩寺。","扣林引寒龜，疏叢出幽翠。","凌晨過杏園，曉露凝芳氣。","初陽好明淨，嫩樹憐低庳。","排房似綴珠，欲啼紅臉淚。","新鶯語嬌小，淺水光流利。","冷飲空腹杯，因成日高醉。","酒醒聞飯鐘，隨僧受遺施。","餐罷還復遊，過從上文記。","行逢二月半，始足遊春騎。","是時春已老，我遊亦云既。","藤開九華觀，草結三條隧。","新筍踴犀株，落梅飜蝶翅。","名倡繡轂車，公子青絲轡。","朝士還旬休，豪家得春賜。","提攜好音樂，翦鏟空田地。","同占杏花園，喧闐各叢萃。","顧予煩寢興，復往散顦顇。","倦僕色肌羸，蹇驢行跛痺。","春衫未成就，冬服漸塵膩。","傾蓋吟短章，書空憶難字。","遙聞公主笑，近被王孫戲。","邀我上華筵，橫頭坐賓位。","那知我年少，深解酒中事。","能唱犯聲歌，偏精變籌義。","含詞待殘拍，促舞遞繁吹。","叫噪擲投盤，生獰攝觥使。","逡巡光景晏，散亂東西異。","古觀閉閒門，依然復幽閟。","無端矯情性，漫學求科試。","薄藝何足云，虛名偶頻遂。","拾遺天子前，密奏升平議。","召見不須臾，憸庸已猜忌。","朝陪香案班，暮作風塵尉。","去歲又登朝，登爲柏臺吏。","臺官相束縛，不許放情志。","寓直勞送迎，上堂煩避諱。","分司在東洛，所職尤不易。","罰俸得西歸，心知受朝庇。","常山攻小寇，淮右擇良帥。","國難身不行，勞生欲何爲。","吾兄諳性靈，崔子同臭味。","投此挂冠詞，一生還自恣。"]', '["小年闲愛春，認得春风意。","未有花草时，先醲晓窗睡。","霞朝澹云色，霽景牽诗思。","漸到柳枝头，川光始明媚。","长安车马客，傾心奉權貴。","晝夜塵土中，那言早春至。","此时我独游，我游有倫次。","闲行曲江岸，便宿慈恩寺。","扣林引寒龟，疏叢出幽翠。","凌晨過杏园，晓露凝芳氣。","初陽好明淨，嫩樹怜低庳。","排房似綴珠，欲啼紅臉泪。","新鶯語嬌小，淺水光流利。","冷饮空腹杯，因成日高醉。","酒醒闻飯鐘，隨僧受遺施。","餐罷還复游，過從上文記。","行逢二月半，始足游春騎。","是时春已老，我游亦云既。","藤开九华观，草結三條隧。","新筍踴犀株，落梅飜蝶翅。","名倡繡轂车，公子青絲轡。","朝士還旬休，豪家得春賜。","提携好音乐，翦鏟空田地。","同占杏花园，喧闐各叢萃。","顧予煩寢兴，复往散顦顇。","倦僕色肌羸，蹇驢行跛痺。","春衫未成就，冬服漸塵膩。","傾蓋吟短章，书空憶难字。","遙闻公主笑，近被王孫戲。","邀我上华筵，橫头坐賓位。","那知我年少，深解酒中事。","能唱犯声歌，偏精变籌義。","含词待殘拍，促舞遞繁吹。","叫噪擲投盤，生獰攝觥使。","逡巡光景晏，散亂东西異。","古观閉閒门，依然复幽閟。","無端矯情性，漫学求科試。","薄藝何足云，虛名偶頻遂。","拾遺天子前，密奏升平議。","召见不須臾，憸庸已猜忌。","朝陪香案班，暮作风塵尉。","去歲又登朝，登爲柏台吏。","台官相束縛，不許放情志。","寓直勞送迎，上堂煩避諱。","分司在东洛，所職尤不易。","罰俸得西归，心知受朝庇。","常山攻小寇，淮右擇良帥。","国难身不行，勞生欲何爲。","吾兄諳性靈，崔子同臭味。","投此挂冠词，一生還自恣。"]', '诗', 'shi', '', NULL, '元和五年予官不了罰俸西歸三月六日至陝府與吳十一兄端公崔二十二院長思愴曩遊因投五十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c740dd3-e671-4258-9806-0a056ec7cf92', '寄吳士矩端公五十韻', '寄吳士矩端公五十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔在鳳翔日，十歲即相識。","未有好文章，逢人賞顏色。","可憐何郎面，二十纔冠飾。","短髮予近梳，羅衫紫蟬翼。","伯舅各驕縱，仁兄未摧抑。","事業若杯盤，詩書甚徽纆。","西州戎馬地，賢豪事雄特。","百萬時可贏，十千良易借。","寒食桐陰下，春風柳林側。","藉草送遠遊，列筵酬博塞。","萎蕤雲幕翠，燦爛紅茵赩。","膾縷輕似絲，香醅膩如職。","將軍頻下城，佳人盡傾國。","媚語嬌不聞，纖腰輭無力。","歌辭妙宛轉，舞態能剜刻。","箏弦玉指調，粉汗紅綃拭。","予時最年少，專務酒中職。","未能解生獰，偏矜任狂直。","曲庇桃根盞，橫講捎雲式。","亂布鬬分朋，惟新間讒慝。","恥作最先吐，羞言未朝食。","醉眼漸紛紛，酒聲頻䬵䬵。","扣節參差亂，飛觥往來織。","強起相維持，飜成兩匍匐。","邊霜颯然降，戰馬鳴不息。","但喜秋光麗，誰憂塞雲黑。","常隨獵騎走，多在豪家匿。","夜飲天既明，朝歌日還昃。","荒狂歲云久，名利心潛逼。","時輩多得途，親朋屢相敕。","閑因適農野，忽復愛稼穡。","平生中聖人，飜然腐腸賊。","亦從酒仙去，便被書魔惑。","脫跡壯士場，甘心豎儒域。","矜持翠筠管，敲斷黃金勒。","屢益蘭膏燈，猶研兔枝墨。","崎嶇來掉蕩，矯枉事沈默。","隱笑甚艱難，斂容還屴崱。","與君始分散，勉我勞修飾。","岐路各營營，別離長惻惻。","行看二十載，萬事紛何極。","相值或須臾，安能洞胸臆。","昨來陝郊會，悲歡兩難克。","問我新相知，但報長相憶。","豈無新知者，不及小相得。","亦有生歲游，同年不同德。","爲別詎幾時，伊予墜溝洫。","大江鼓風浪，遠道參荆棘。","往事返無期，前途浩難測。","一旦得自由，相求北山北。"]', '["昔在鳳翔日，十歲即相識。","未有好文章，逢人賞顏色。","可怜何郎面，二十纔冠飾。","短髮予近梳，羅衫紫蟬翼。","伯舅各驕縱，仁兄未摧抑。","事業若杯盤，诗书甚徽纆。","西州戎马地，賢豪事雄特。","百万时可贏，十千良易借。","寒食桐陰下，春风柳林側。","藉草送远游，列筵酬博塞。","萎蕤云幕翠，燦爛紅茵赩。","膾縷轻似絲，香醅膩如職。","將軍頻下城，佳人尽傾国。","媚語嬌不闻，纖腰輭無力。","歌辞妙宛轉，舞態能剜刻。","箏弦玉指調，粉汗紅綃拭。","予时最年少，專務酒中職。","未能解生獰，偏矜任狂直。","曲庇桃根盞，橫講捎云式。","亂布鬬分朋，惟新间讒慝。","恥作最先吐，羞言未朝食。","醉眼漸紛紛，酒声頻䬵䬵。","扣節參差亂，飞觥往来织。","強起相維持，飜成兩匍匐。","邊霜颯然降，戰马鳴不息。","但喜秋光丽，誰憂塞云黑。","常隨獵騎走，多在豪家匿。","夜饮天既明，朝歌日還昃。","荒狂歲云久，名利心潛逼。","时輩多得途，親朋屢相敕。","闲因適農野，忽复愛稼穡。","平生中聖人，飜然腐腸賊。","亦從酒仙去，便被书魔惑。","脫跡壯士場，甘心豎儒域。","矜持翠筠管，敲斷黄金勒。","屢益蘭膏灯，猶研兔枝墨。","崎嶇来掉蕩，矯枉事沈默。","隐笑甚艱难，斂容還屴崱。","與君始分散，勉我勞修飾。","岐路各營營，別離长惻惻。","行看二十載，万事紛何極。","相值或須臾，安能洞胸臆。","昨来陝郊會，悲歡兩难克。","问我新相知，但報长相憶。","豈無新知者，不及小相得。","亦有生歲游，同年不同德。","爲別詎幾时，伊予墜溝洫。","大江鼓风浪，远道參荆棘。","往事返無期，前途浩难測。","一旦得自由，相求北山北。"]', '诗', 'shi', '', NULL, '寄吳士矩端公五十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad4f41bb-c368-4717-8c6e-ccf9018d14a2', '三月二十四日宿曾峰館夜對桐花寄樂天', '三月二十四日宿曾峰館夜对桐花寄乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["微月照桐花，月微花漠漠。","怨澹不勝情，低回拂簾幕。","葉新陰影細，露重枝條弱。","夜久春恨多，風清暗香薄。","是夕遠思君，思君瘦如削。","但感事睽違，非言官好惡。","奏書金鑾殿，步屣青龍閣。","我在山館中，滿地桐花落。"]', '["微月照桐花，月微花漠漠。","怨澹不勝情，低回拂簾幕。","葉新陰影細，露重枝條弱。","夜久春恨多，风清暗香薄。","是夕远思君，思君瘦如削。","但感事睽違，非言官好惡。","奏书金鑾殿，步屣青龙閣。","我在山館中，满地桐花落。"]', '诗', 'shi', '', NULL, '三月二十四日宿曾峰館夜對桐花寄樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d63100-8c8a-4236-8b5c-d0529a072330', '酬樂天書懷見寄', '酬乐天书懷见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["新昌北門外，與君從此分。","街衢走車馬，塵土不見君。","君爲分手歸，我行行不息。","我上秦嶺南，君直樞星北。","秦嶺高崔嵬，商山好顏色。","月照山館花，裁詩寄相憶。","天明作詩罷，草草隨所如。","憑人寄將去，三月無報書。","荆州白日晚，城上鼓鼕鼕。","行逢賀州牧，致書三四封。","封題樂天字，未坼已霑裳。","坼書八九讀，淚落千萬行。","中有酬我詩，句句截我腸。","仍云得詩夜，夢我魂淒涼。","終言作書處，上直金鑾東。","詩書費一夕，萬恨緘其中。","中宵宮中出，復見宮月斜。","書罷月亦落，曉燈隨暗花。","想君書罷時，南望勞所思。","況我江上立，吟君懷我詩。","懷我浩無極，江水秋正深。","清見萬丈底，照我平生心。","感君求友什，因報壯士吟。","持謝衆人口，銷盡猶是金。"]', '["新昌北门外，與君從此分。","街衢走车马，塵土不见君。","君爲分手归，我行行不息。","我上秦嶺南，君直樞星北。","秦嶺高崔嵬，商山好顏色。","月照山館花，裁诗寄相憶。","天明作诗罷，草草隨所如。","憑人寄將去，三月無報书。","荆州白日晚，城上鼓鼕鼕。","行逢賀州牧，致书三四封。","封題乐天字，未坼已霑裳。","坼书八九读，泪落千万行。","中有酬我诗，句句截我腸。","仍云得诗夜，梦我魂淒涼。","終言作书处，上直金鑾东。","诗书費一夕，万恨緘其中。","中宵宮中出，复见宮月斜。","书罷月亦落，晓灯隨暗花。","想君书罷时，南望勞所思。","況我江上立，吟君懷我诗。","懷我浩無極，江水秋正深。","清见万丈底，照我平生心。","感君求友什，因報壯士吟。","持謝衆人口，銷尽猶是金。"]', '诗', 'shi', '', NULL, '酬樂天書懷見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5849033-e6e2-4536-b5be-a3eebcced359', '酬樂天登樂遊園見憶', '酬乐天登乐游园见憶', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔君樂遊園，悵望天欲曛。","今我大江上，快意波飜雲。","秋空壓澶漫，澒洞無垢氛。","四顧皆豁達，我眉今日伸。","長安隘朝市，百道走埃塵。","軒車隨對列，骨肉非本親。","誇遊丞相第，偷入常侍門。","愛君直如髮，勿念江湖人。"]', '["昔君乐游园，悵望天欲曛。","今我大江上，快意波飜云。","秋空壓澶漫，澒洞無垢氛。","四顧皆豁達，我眉今日伸。","长安隘朝市，百道走埃塵。","軒车隨对列，骨肉非本親。","誇游丞相第，偷入常侍门。","愛君直如髮，勿念江湖人。"]', '诗', 'shi', '', NULL, '酬樂天登樂遊園見憶 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b51076e-bad9-40ff-9777-efdd4cbf1577', '酬樂天早夏見懷', '酬乐天早夏见懷', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["庭柚有垂實，燕巢無宿雛。","我亦辭社燕，茫茫焉所如。","君詩夏方早，我歎秋已徂。","食物風土異，衾裯時節殊。","荒草滿田地，近移江上居。","八日復切九，月明侵半除。"]', '["庭柚有垂實，燕巢無宿雛。","我亦辞社燕，茫茫焉所如。","君诗夏方早，我歎秋已徂。","食物风土異，衾裯时節殊。","荒草满田地，近移江上居。","八日复切九，月明侵半除。"]', '诗', 'shi', '', NULL, '酬樂天早夏見懷 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ceb3b00-bc23-488b-b536-40bcd943dff6', '酬樂天勸醉', '酬乐天勸醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["神麯清濁酒，牡丹深淺花。","少年欲相飲，此樂何可涯。","沈機造神境，不必悟楞伽。","酡顏返童貌，安用成丹砂。","劉伶稱酒德，所稱良未多。","願君聽此曲，我爲盡稱嗟。","一杯顏色好，十盞膽氣加。","半酣得自恣，酩酊歸太和。","共醉真可樂，飛觥撩亂歌。","獨醉亦有趣，兀然無與他。","美人醉燈下，左右流橫波。","王孫醉牀上，顛倒眠綺羅。","君今勸我醉，勸醉意如何。"]', '["神麯清濁酒，牡丹深淺花。","少年欲相饮，此乐何可涯。","沈機造神境，不必悟楞伽。","酡顏返童貌，安用成丹砂。","劉伶稱酒德，所稱良未多。","願君听此曲，我爲尽稱嗟。","一杯顏色好，十盞膽氣加。","半酣得自恣，酩酊归太和。","共醉真可乐，飞觥撩亂歌。","独醉亦有趣，兀然無與他。","美人醉灯下，左右流橫波。","王孫醉牀上，顛倒眠綺羅。","君今勸我醉，勸醉意如何。"]', '诗', 'shi', '', NULL, '酬樂天勸醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc380aec-cd91-4881-b0b8-e411ce754f9c', '和樂天初授戶曹喜而言志', '和乐天初授戶曹喜而言志', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["王爵無細大，得請即爲恩。","君求戶曹掾，貴以祿奉親。","聞君得所請，感我欲霑巾。","今人重軒冕，所重華與紛。","矜誇仕臺閣，奔走無朝昏。","君衣不盈篋，君食不滿囷。","君言養既薄，何以榮我門。","披誠再三請，天子憐儉貧。","詞曹直文苑，捧詔榮且忻。","歸來高堂上，兄弟羅酒尊。","各稱千萬壽，共飲三四巡。","我實知君者，千里能具陳。","感君求祿意，求祿殊衆人。","上以奉顏色，餘以及親賓。","棄名不棄實，謀養不謀身。","可憐白華士，永願凌青雲。"]', '["王爵無細大，得請即爲恩。","君求戶曹掾，貴以祿奉親。","闻君得所請，感我欲霑巾。","今人重軒冕，所重华與紛。","矜誇仕台閣，奔走無朝昏。","君衣不盈篋，君食不满囷。","君言養既薄，何以榮我门。","披誠再三請，天子怜儉貧。","词曹直文苑，捧詔榮且忻。","归来高堂上，兄弟羅酒尊。","各稱千万壽，共饮三四巡。","我實知君者，千里能具陳。","感君求祿意，求祿殊衆人。","上以奉顏色，餘以及親賓。","棄名不棄實，謀養不謀身。","可怜白华士，永願凌青云。"]', '诗', 'shi', '', NULL, '和樂天初授戶曹喜而言志 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33c308b7-ba59-4de1-a9fe-4d23e1fedf9d', '和樂天贈吳丹', '和乐天贈吳丹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["不識吳生面，久知吳生道。","跡雖染世名，心本奉天老。","雌一守命門，廻九填血腦。","委氣榮衛和，咽津顏色好。","傳聞共甲子，衰隤盡枯[槁]。","獨有冰雪容，纖華奪鮮縞。","問人何能爾，吳實曠懷抱。","弁冕徒挂身，身外非所寶。","伊予固童昧，希真亦云早。","石壇玉晨尊，晝夜長自埽。","密印視丹田，遊神夢三島。","萬過黃庭經，一食青精稻。","冥搜方朔桃，結念安期棗。","綠髮幸未改，丹誠自能保。","行當擺塵纓，吳門事探討。","君爲先此詞，終期搴瑤草。"]', '["不識吳生面，久知吳生道。","跡雖染世名，心本奉天老。","雌一守命门，廻九填血腦。","委氣榮衛和，咽津顏色好。","傳闻共甲子，衰隤尽枯[槁]。","独有冰雪容，纖华奪鲜縞。","问人何能爾，吳實曠懷抱。","弁冕徒挂身，身外非所寶。","伊予固童昧，希真亦云早。","石壇玉晨尊，晝夜长自埽。","密印視丹田，游神梦三島。","万過黄庭經，一食青精稻。","冥搜方朔桃，結念安期棗。","綠髮幸未改，丹誠自能保。","行當擺塵纓，吳门事探討。","君爲先此词，終期搴瑤草。"]', '诗', 'shi', '', NULL, '和樂天贈吳丹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb9cb9b7-03ed-497e-a738-76d3308589ee', '和樂天秋題曲江', '和乐天秋題曲江', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["十載定交契，七年鎮相隨。","長安最多處，多是曲江池。","梅杏春尚小，芰荷秋已衰。","共愛寥落境，相將偏此時。","緜緜紅蓼水，颺颺白鷺鶿。","詩句偶未得，酒杯聊久持。","今來雲雨曠，舊賞魂夢知。","況乃江楓夕，和君秋興詩。"]', '["十載定交契，七年鎮相隨。","长安最多处，多是曲江池。","梅杏春尚小，芰荷秋已衰。","共愛寥落境，相將偏此时。","緜緜紅蓼水，颺颺白鷺鶿。","诗句偶未得，酒杯聊久持。","今来云雨曠，旧賞魂梦知。","況乃江楓夕，和君秋兴诗。"]', '诗', 'shi', '', NULL, '和樂天秋題曲江 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81dc8eb8-35d5-4c79-ace2-1a4f056c98b9', '和樂天別弟後月夜作', '和乐天別弟後月夜作', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["聞君別愛弟，明天照夜寒。","秋雁拂檐影，曉琴當砌彈。","悵望天澹澹，因思路漫漫。","吟爲別弟操，聞者爲辛酸。","況我兄弟遠，一身形影單。","江波浩無極，但見時歲闌。"]', '["闻君別愛弟，明天照夜寒。","秋雁拂檐影，晓琴當砌彈。","悵望天澹澹，因思路漫漫。","吟爲別弟操，闻者爲辛酸。","況我兄弟远，一身形影單。","江波浩無極，但见时歲闌。"]', '诗', 'shi', '', NULL, '和樂天別弟後月夜作 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca21ea8-bd62-40c9-8379-af18e9b70ac6', '和樂天秋題牡丹叢', '和乐天秋題牡丹叢', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["敝宅豔山卉，別來長歎息。","吟君晚叢詠，似見摧隤色。","欲識別後容，勤過晚叢側。"]', '["敝宅豔山卉，別来长歎息。","吟君晚叢詠，似见摧隤色。","欲識別後容，勤過晚叢側。"]', '诗', 'shi', '', NULL, '和樂天秋題牡丹叢 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f432e98f-b6e0-4e2e-af94-fa92408ce57f', '春月', '春月', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春月雖至明，終有靄靄光。","不似秋冬色，逼人寒帶霜。","纖粉澹虛壁，輕煙籠半牀。","分暉間林影，餘照上虹梁。","病久塵事隔，夜閑清興長。","擁抱顛倒領，步屣東西廂。","風柳結柔援，露梅飄暗香。","雪含櫻綻蘂，珠蹙桃綴房。","杳杳有餘思，行行安可忘。","四鄰非舊識，無以話中腸。","南有居士儼，默坐調心王。","款關一問訊，爲我披衣裳。","延我入深竹，暖我於小堂。","視身琉璃瑩，諭指芭蕉黃。","復有比丘溢，早傳龍樹方。","口中祕丹訣，肘後懸青囊。","錫杖雖獨振，刀圭期共嘗。","未知仙近遠，已覺神輕翔。","夜久魂耿耿，月明露蒼蒼。","悲哉沈眠士，寧見茲夕良。"]', '["春月雖至明，終有靄靄光。","不似秋冬色，逼人寒带霜。","纖粉澹虛壁，轻煙籠半牀。","分暉间林影，餘照上虹梁。","病久塵事隔，夜闲清兴长。","擁抱顛倒領，步屣东西廂。","风柳結柔援，露梅飄暗香。","雪含櫻綻蘂，珠蹙桃綴房。","杳杳有餘思，行行安可忘。","四鄰非旧識，無以話中腸。","南有居士儼，默坐調心王。","款关一问訊，爲我披衣裳。","延我入深竹，暖我於小堂。","視身琉璃瑩，諭指芭蕉黄。","复有比丘溢，早傳龙樹方。","口中祕丹訣，肘後懸青囊。","錫杖雖独振，刀圭期共嘗。","未知仙近远，已覺神轻翔。","夜久魂耿耿，月明露蒼蒼。","悲哉沈眠士，寧见茲夕良。"]', '诗', 'shi', '', NULL, '春月 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbf36c89-11f0-44a1-a662-d56cf82538b0', '月臨花', '月臨花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["臨風颺颺花，透影朧朧月。","巫峽隔波雲，姑峰漏霞雪。","鏡勻嬌面粉，燈泛高籠纈。","夜久清露多，啼珠墜還結。"]', '["臨风颺颺花，透影朧朧月。","巫峽隔波云，姑峰漏霞雪。","镜勻嬌面粉，灯泛高籠纈。","夜久清露多，啼珠墜還結。"]', '诗', 'shi', '', NULL, '月臨花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28352993-bd3d-49af-978a-15c50c95e3a8', '紅芍藥', '紅芍藥', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["芍藥綻紅綃，巴籬織青瑣。","繁絲蹙金蘂，高燄當爐火。","翦刻彤雲片，開張赤霞裹。","煙輕琉璃葉，風亞珊瑚朵。","受露色低迷，向人嬌婀娜。","酡顏醉後泣，小女妝成坐。","豔豔錦不如，夭夭桃未可。","晴霞畏欲散，晚日愁將墮。","結植本爲誰，賞心期在我。","采之諒多思，幽贈何由果。"]', '["芍藥綻紅綃，巴籬织青瑣。","繁絲蹙金蘂，高燄當爐火。","翦刻彤云片，开張赤霞裹。","煙轻琉璃葉，风亞珊瑚朵。","受露色低迷，向人嬌婀娜。","酡顏醉後泣，小女妝成坐。","豔豔錦不如，夭夭桃未可。","晴霞畏欲散，晚日愁將墮。","結植本爲誰，賞心期在我。","采之諒多思，幽贈何由果。"]', '诗', 'shi', '', NULL, '紅芍藥 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('982d9042-2215-4e98-8246-9311c81e6dfd', '送王十一南行', '送王十一南行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夏水漾天末，晚暘依岸邨。","風調烏尾勁，眷戀餘芳尊。","解袂方瞬息，征帆已翩翻。","江豚湧高浪，楓樹搖去魂。","遠戍宗侶泊，暮煙洲渚昏。","離心詎幾許，驟若移寒溫。","此別信非久，胡爲坐憂煩。","我留石難轉，君泛雲無根。","萬里湖南月，三聲山上猿。","從茲耿幽夢，夜夜湘與沅。"]', '["夏水漾天末，晚暘依岸邨。","风調烏尾勁，眷戀餘芳尊。","解袂方瞬息，征帆已翩翻。","江豚湧高浪，楓樹搖去魂。","远戍宗侶泊，暮煙洲渚昏。","離心詎幾許，驟若移寒溫。","此別信非久，胡爲坐憂煩。","我留石难轉，君泛云無根。","万里湖南月，三声山上猿。","從茲耿幽梦，夜夜湘與沅。"]', '诗', 'shi', '', NULL, '送王十一南行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('067093bb-db5b-4c50-a358-259a913f1175', '三歎 一', '三歎 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["孤劒鋒刀澀，猶能神彩生。","有時雷雨過，暗吼闐闐聲。","主人閟靈寶，畏作升天行。","淬礪當陽鐵，刻爲干鏌名。","遠求鸊鵜瑩，同用玉匣盛。","顏色縱相類，利鈍頗相傾。","雄爲光電烻，雌但深泓澄。","龍怒有奇變，青蛇終不驚。"]', '["孤劒鋒刀澀，猶能神彩生。","有时雷雨過，暗吼闐闐声。","主人閟靈寶，畏作升天行。","淬礪當陽鐵，刻爲干鏌名。","远求鸊鵜瑩，同用玉匣盛。","顏色縱相類，利鈍頗相傾。","雄爲光電烻，雌但深泓澄。","龙怒有奇变，青蛇終不驚。"]', '诗', 'shi', '', NULL, '三歎 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4115ed4e-e092-4b2e-910d-03ad70742d3b', '三歎 二', '三歎 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["仙鳳翠皇死，葳蕤光彩低。","非無鴛鸞侶，誓不同樹棲。","飛馳歲云暮，感念雛在泥。","顧影不自暖，寄爾蟠桃雞。","馴養豈無愧，類族安得齊。","願言成羽翼，奮翅凌丹梯。"]', '["仙鳳翠皇死，葳蕤光彩低。","非無鴛鸾侶，誓不同樹棲。","飞驰歲云暮，感念雛在泥。","顧影不自暖，寄爾蟠桃雞。","馴養豈無愧，類族安得齊。","願言成羽翼，奮翅凌丹梯。"]', '诗', 'shi', '', NULL, '三歎 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('299b35c1-468e-4c88-8d3e-db70e6499155', '三歎 三', '三歎 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["天驥失龍偶，三年常夜嘶。","哀緣噴風斷，渴且含霜啼。","長恐絕遺類，不復躡雲霓。","非無駉駉者，鶴意不在雞。","春來筋骨瘦，弔影心亦迷。","自此渥洼種，應生濁水泥。"]', '["天驥失龙偶，三年常夜嘶。","哀緣噴风斷，渴且含霜啼。","长恐絕遺類，不复躡云霓。","非無駉駉者，鹤意不在雞。","春来筋骨瘦，弔影心亦迷。","自此渥洼種，應生濁水泥。"]', '诗', 'shi', '', NULL, '三歎 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d2707ec-0f62-43e3-aa3c-057876efea8e', '遣晝', '遣晝', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["密竹有清陰，曠懷無塵滓。","況乃秋日光，玲瓏曉窗裏。","旬休聊自適，今辰日高起。","櫛沐坐前軒，風輕鏡如水。","開卷恣詠謠，望雲閑徙倚。","新菊媚鮮妍，短萍憐靃靡。","埽除田地靜，摘掇園蔬美。","幽翫愜詩流，空堂稱居士。","客來傷寂寞，我念遺煩鄙。","心跡兩相忘，誰能驗行止。"]', '["密竹有清陰，曠懷無塵滓。","況乃秋日光，玲瓏晓窗裏。","旬休聊自適，今辰日高起。","櫛沐坐前軒，风轻镜如水。","开卷恣詠謠，望云闲徙倚。","新菊媚鲜妍，短萍怜靃靡。","埽除田地静，摘掇园蔬美。","幽翫愜诗流，空堂稱居士。","客来傷寂寞，我念遺煩鄙。","心跡兩相忘，誰能驗行止。"]', '诗', 'shi', '', NULL, '遣晝 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf0257b-55fe-4822-970a-bc3ad25c50d8', '冬夜懷李侍御王太祝段丞', '冬夜懷李侍御王太祝段丞', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["浩露煙壒盡，月光閒有餘。","松篁細陰影，重以簾牖疎。","泛覽星粲粲，輕河悠碧虛。","纖雲不成葉，脈脈風絲舒。","丹竈熾東序，燒香羅玉書。","飄飄魂神舉，若驂鸞鶴輿。","感念夙昔意，華尚簪與裾。","簪裾詎幾許，累創吞鉤魚。","今聞馨香道，一以悟臭帤。","悟覺誓不惑，永抱胎仙居。","晝夜欣所適，安知歲云除。","行行二三友，君懷復何如。"]', '["浩露煙壒尽，月光閒有餘。","松篁細陰影，重以簾牖疎。","泛覽星粲粲，轻河悠碧虛。","纖云不成葉，脈脈风絲舒。","丹竈熾东序，燒香羅玉书。","飄飄魂神舉，若驂鸾鹤輿。","感念夙昔意，华尚簪與裾。","簪裾詎幾許，累創吞鉤鱼。","今闻馨香道，一以悟臭帤。","悟覺誓不惑，永抱胎仙居。","晝夜欣所適，安知歲云除。","行行二三友，君懷复何如。"]', '诗', 'shi', '', NULL, '冬夜懷李侍御王太祝段丞 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b52e2b04-d70b-4f44-9a44-1f889b3e9e43', '西齋小松二首 一', '西斋小松二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["松樹短於我，清風亦已多。","況乃枝上雪，動搖微月波。","幽姿得閒地，詎感歲蹉跎。","但恐廈終構，藉君當奈何。"]', '["松樹短於我，清风亦已多。","況乃枝上雪，动搖微月波。","幽姿得閒地，詎感歲蹉跎。","但恐廈終構，藉君當奈何。"]', '诗', 'shi', '', NULL, '西齋小松二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa5f524-e2d5-4b63-82e8-91598f53ff42', '西齋小松二首 二', '西斋小松二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["簇簇枝新黃，纖纖攢素指。","柔苙漸依條，短莎還半委。","清風日夜高，凌雲意何已。","千歲盤老龍，修鱗自茲始。"]', '["簇簇枝新黄，纖纖攢素指。","柔苙漸依條，短莎還半委。","清风日夜高，凌云意何已。","千歲盤老龙，修鱗自茲始。"]', '诗', 'shi', '', NULL, '西齋小松二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23c9e117-1272-4f69-9d77-0d784c91ff39', '周先生', '周先生', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寥寥空山岑，冷冷風松林。","流月垂鱗光，懸泉揚高音。","希夷周先生，燒香調琴心。","神力盈三千，誰能還黃金。"]', '["寥寥空山岑，冷冷风松林。","流月垂鱗光，懸泉揚高音。","希夷周先生，燒香調琴心。","神力盈三千，誰能還黄金。"]', '诗', 'shi', '', NULL, '周先生 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf69f17-7c47-438c-b912-89c33a272dd8', '遣春十首 一', '遣春十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["曉月籠雲影，鸎聲餘霧中。","暗芳飄露氣，輕寒生柳風。","冉冉一趨府，未爲勞我躬。","因茲得晨起，但覺情興隆。"]', '["晓月籠云影，鸎声餘霧中。","暗芳飄露氣，轻寒生柳风。","冉冉一趨府，未爲勞我躬。","因茲得晨起，但覺情兴隆。"]', '诗', 'shi', '', NULL, '遣春十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48534bac-39c2-4d9a-93d4-2dc10e9d17b8', '遣春十首 二', '遣春十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["久雨憐霽景，偶來隄上行。","空濛天色嫩，杳淼江面平。","百草短長出，衆禽高下鳴。","春陽各有分，予亦澹無情。"]', '["久雨怜霽景，偶来隄上行。","空濛天色嫩，杳淼江面平。","百草短长出，衆禽高下鳴。","春陽各有分，予亦澹無情。"]', '诗', 'shi', '', NULL, '遣春十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0deb7b5-d369-4127-92c1-f996d20d02e9', '遣春十首 三', '遣春十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鏡皎碧潭水，微波粗成文。","煙光垂碧草，瓊脈散纖雲。","岸柳好陰影，風裾遺垢氛。","悠然送春目，八荒誰與羣。"]', '["镜皎碧潭水，微波粗成文。","煙光垂碧草，瓊脈散纖云。","岸柳好陰影，风裾遺垢氛。","悠然送春目，八荒誰與羣。"]', '诗', 'shi', '', NULL, '遣春十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27f39431-d669-4554-96ac-52badcf9a706', '遣春十首 四', '遣春十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["低迷籠樹煙，明淨當霞日。","陽燄波春空，平湖漫凝溢。","雪鷺遠近飛，渚牙淺深出。","江流復浩蕩，相爲坐紆鬱。"]', '["低迷籠樹煙，明淨當霞日。","陽燄波春空，平湖漫凝溢。","雪鷺远近飞，渚牙淺深出。","江流复浩蕩，相爲坐紆鬱。"]', '诗', 'shi', '', NULL, '遣春十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8b6c460-1009-42a0-8a35-ca6e29737887', '遣春十首 五', '遣春十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["暄寒深淺春，紅白前後花。","顏色詎相讓，生成良有涯。","梅芳勿自早，菊秀勿自賒。","各將一時意，終年無再華。"]', '["暄寒深淺春，紅白前後花。","顏色詎相讓，生成良有涯。","梅芳勿自早，菊秀勿自賒。","各將一时意，終年無再华。"]', '诗', 'shi', '', NULL, '遣春十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('542f7635-1170-48ca-9481-ee32aaf96f5f', '遣春十首 六', '遣春十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["高屋童稚少，春來歸燕多。","葺舊良易就，新院亦已羅。","俯憐雛化卵，仰愧鵬無窠。","巢棟與巢幕，秋風俱奈何。"]', '["高屋童稚少，春来归燕多。","葺旧良易就，新院亦已羅。","俯怜雛化卵，仰愧鵬無窠。","巢棟與巢幕，秋风俱奈何。"]', '诗', 'shi', '', NULL, '遣春十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bc72a8a-88bf-4e57-89ec-b21e3016b789', '遣春十首 七', '遣春十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["撩亂撲樹蜂，摧殘戀房蕊。","風吹雨又頻，安得繁於綺。","酒盃沈易過，世事紛何已。","莫倚顏似花，君看歲如水。"]', '["撩亂撲樹蜂，摧殘戀房蕊。","风吹雨又頻，安得繁於綺。","酒盃沈易過，世事紛何已。","莫倚顏似花，君看歲如水。"]', '诗', 'shi', '', NULL, '遣春十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97a5ce15-f00d-4082-b5df-053e1438a2e1', '遣春十首 八', '遣春十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["繞郭高高冢，半是荆王墓。","後嗣熾陽臺，前賢甘蓽路。","善惡徒自分，波流盡東注。","胡然不飲酒，坐落桐花樹。"]', '["繞郭高高冢，半是荆王墓。","後嗣熾陽台，前賢甘蓽路。","善惡徒自分，波流尽东注。","胡然不饮酒，坐落桐花樹。"]', '诗', 'shi', '', NULL, '遣春十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f5fa89-0a65-4d53-b596-88aa0f010c41', '遣春十首 九', '遣春十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["花陰莎草長，藉莎閑自酌。","坐看鸎鬬枝，輕花滿尊杓。","葛巾竹稍挂，書卷琴上閣。","沽酒過此生，狂歌眼前樂。"]', '["花陰莎草长，藉莎闲自酌。","坐看鸎鬬枝，轻花满尊杓。","葛巾竹稍挂，书卷琴上閣。","沽酒過此生，狂歌眼前乐。"]', '诗', 'shi', '', NULL, '遣春十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21951b1b-02ad-461f-91a7-95b8eed71859', '遣春十首 十', '遣春十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["梨葉已成陰，柳條紛起絮。","波綠紫屏風，螺紅碧籌筯。","三杯面上熱，萬事心中去。","我意風散雲，何勞問行處。"]', '["梨葉已成陰，柳條紛起絮。","波綠紫屏风，螺紅碧籌筯。","三杯面上熱，万事心中去。","我意风散云，何勞问行处。"]', '诗', 'shi', '', NULL, '遣春十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edebf922-4b99-4c67-be6d-9132f015f9e6', '表夏十首 一', '表夏十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夏風多暖暖，樹木有繁陰。","新筍紫長短，早櫻紅淺深。","煙花雲幕重，榴豔朝景侵。","華實各自好，詎云芳意沈。"]', '["夏风多暖暖，樹木有繁陰。","新筍紫长短，早櫻紅淺深。","煙花云幕重，榴豔朝景侵。","华實各自好，詎云芳意沈。"]', '诗', 'shi', '', NULL, '表夏十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9492ddc6-b920-4416-a8d9-d5c565e50818', '表夏十首 二', '表夏十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["初日滿階前，輕風動簾影。","旬時得休浣，高臥閱清景。","僮兒拂巾箱，鵶軋深林井。","心到物自閑，何勞遠箕頴。"]', '["初日满階前，轻风动簾影。","旬时得休浣，高臥閱清景。","僮兒拂巾箱，鵶軋深林井。","心到物自闲，何勞远箕頴。"]', '诗', 'shi', '', NULL, '表夏十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('534d2e7d-7e23-4185-b14d-295cbfe9b86d', '表夏十首 三', '表夏十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["江瘴炎夏早，蒸騰信難度。","今宵好風月，獨此荒庭趣。","露葉傾暗光，流星委餘素。","但恐清夜徂，詎悲朝景暮。"]', '["江瘴炎夏早，蒸腾信难度。","今宵好风月，独此荒庭趣。","露葉傾暗光，流星委餘素。","但恐清夜徂，詎悲朝景暮。"]', '诗', 'shi', '', NULL, '表夏十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a0b1723-d500-42e4-b7d8-1df7cafc7215', '表夏十首 四', '表夏十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["孟月夏猶淺，奇雲未成峰。","度霞紅漠漠，壓浪白溶溶。","玉委有餘潤，飆馳無去蹤。","何如捧雲雨，噴毒隨蛟龍。"]', '["孟月夏猶淺，奇云未成峰。","度霞紅漠漠，壓浪白溶溶。","玉委有餘潤，飆驰無去蹤。","何如捧云雨，噴毒隨蛟龙。"]', '诗', 'shi', '', NULL, '表夏十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c7fbc8-ace1-4c74-998a-7b29dd06a7a4', '表夏十首 五', '表夏十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["流芳遞炎景，繁英盡寥落。","公署香滿庭，晴霞覆闌藥。","裁紅起高燄，綴綠排新萼。","憑此遣幽懷，非言念將謔。"]', '["流芳遞炎景，繁英尽寥落。","公署香满庭，晴霞覆闌藥。","裁紅起高燄，綴綠排新萼。","憑此遣幽懷，非言念將謔。"]', '诗', 'shi', '', NULL, '表夏十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b9749d-83c5-42ba-a6a0-71b5a6d3ba7c', '表夏十首 六', '表夏十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紅絲散芳樹，旋轉光風急。","煙泛被籠香，露濃妝面溼。","佳人不在此，恨望堦前立。","忽厭夏景長，今春行已及。"]', '["紅絲散芳樹，旋轉光风急。","煙泛被籠香，露濃妝面溼。","佳人不在此，恨望堦前立。","忽厭夏景长，今春行已及。"]', '诗', 'shi', '', NULL, '表夏十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99854059-ac6f-4fc8-b634-ad48b6ad23b4', '表夏十首 七', '表夏十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["百舌漸吞聲，黃鸎正嬌小。","雲鴻方警夜，籠雞已鳴曉。","當時客自適，運去誰能矯。","莫厭夏蟲多，蜩螗定相擾。"]', '["百舌漸吞声，黄鸎正嬌小。","云鴻方警夜，籠雞已鳴晓。","當时客自適，運去誰能矯。","莫厭夏蟲多，蜩螗定相擾。"]', '诗', 'shi', '', NULL, '表夏十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('322d6de1-e145-4532-bd76-8c4f6f483c88', '表夏十首 八', '表夏十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["翩翩簾外燕，戢戢巢內雛。","啖食筋力盡，毛衣成紫襦。","朝來各飛去，雄雌梁上呼。","養子將備老，惡兒那勝無。"]', '["翩翩簾外燕，戢戢巢內雛。","啖食筋力尽，毛衣成紫襦。","朝来各飞去，雄雌梁上呼。","養子將備老，惡兒那勝無。"]', '诗', 'shi', '', NULL, '表夏十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('042c6864-1284-4ace-a521-28245a52d1c3', '表夏十首 九', '表夏十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["西山夏雪消，江勢東南瀉。","風波高若天，灩澦低於馬。","正被黃牛旋，難期白帝下。","我在平地行，翻憂濟川者。"]', '["西山夏雪消，江勢东南瀉。","风波高若天，灩澦低於马。","正被黄牛旋，难期白帝下。","我在平地行，翻憂濟川者。"]', '诗', 'shi', '', NULL, '表夏十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('700b574e-b8a8-41b8-b3c8-bb46cc94913c', '表夏十首 十', '表夏十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["靈均死波後，是節常浴蘭。","綵縷碧筠糉，香秔白玉團。","逝者良自苦，今人反爲歡。","哀哉徇名士，沒命求所難。"]', '["靈均死波後，是節常浴蘭。","綵縷碧筠糉，香秔白玉團。","逝者良自苦，今人反爲歡。","哀哉徇名士，沒命求所难。"]', '诗', 'shi', '', NULL, '表夏十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658c34e2-5bc3-4f95-8001-3328d6093c38', '解秋十首 一', '解秋十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["清晨頮寒水，動搖襟袖輕。","翳翳林上葉，不知秋暗生。","回悲鏡中髮，華白三四莖。","豈無滿頭黑，念此衰已萌。"]', '["清晨頮寒水，动搖襟袖轻。","翳翳林上葉，不知秋暗生。","回悲镜中髮，华白三四莖。","豈無满头黑，念此衰已萌。"]', '诗', 'shi', '', NULL, '解秋十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b83295ee-8b5b-40d7-9498-ad8bdff50029', '解秋十首 二', '解秋十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["微霜纔結露，翔鳩初變鷹。","無乃天地意，使之行小懲。","鴟鴞誠可惡，蔽日有高鵬。","捨大以擒細，我心終不能。"]', '["微霜纔結露，翔鳩初变鷹。","無乃天地意，使之行小懲。","鴟鴞誠可惡，蔽日有高鵬。","捨大以擒細，我心終不能。"]', '诗', 'shi', '', NULL, '解秋十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c9e941-9f5d-47ff-97b6-7bc47458754e', '解秋十首 三', '解秋十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["往歲學仙侶，各在無何鄉。","同時騖名者，次第鵷鷺行。","而我兩不遂，三十鬢添霜。","日暮江上立，蟬鳴楓樹黃。"]', '["往歲学仙侶，各在無何乡。","同时騖名者，次第鵷鷺行。","而我兩不遂，三十鬢添霜。","日暮江上立，蟬鳴楓樹黄。"]', '诗', 'shi', '', NULL, '解秋十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0f11dcd-63c1-46e3-821f-cfe9145aef48', '解秋十首 四', '解秋十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["後伏火猶在，先秋蟬已多。","雲色日夜白，驕陽能幾何。","壤隙漏江海，忽微成網羅。","勿言時不至，但恐歲蹉跎。"]', '["後伏火猶在，先秋蟬已多。","云色日夜白，驕陽能幾何。","壤隙漏江海，忽微成網羅。","勿言时不至，但恐歲蹉跎。"]', '诗', 'shi', '', NULL, '解秋十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db2a09c3-7311-42be-84ba-afe3b8063943', '解秋十首 五', '解秋十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["新月纔到地，輕河如泛雲。","螢飛高下火，樹影參差文。","露簟有微潤，清香時暗焚。","夜閑心寂默，洞庭無垢氛。"]', '["新月纔到地，轻河如泛云。","螢飞高下火，樹影參差文。","露簟有微潤，清香时暗焚。","夜闲心寂默，洞庭無垢氛。"]', '诗', 'shi', '', NULL, '解秋十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80288410-e8ee-4ccf-a11f-726eb03b1931', '解秋十首 六', '解秋十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["霽麗牀前影，飄蕭簾外竹。","簟涼朝睡重，夢覺茶香熟。","親烹園內葵，憑買家家麯。","釀酒幷毓蔬，人來有棊局。"]', '["霽丽牀前影，飄蕭簾外竹。","簟涼朝睡重，梦覺茶香熟。","親烹园內葵，憑買家家麯。","釀酒幷毓蔬，人来有棊局。"]', '诗', 'shi', '', NULL, '解秋十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6aec35b-4a12-40ab-ad18-163b207ec4c1', '解秋十首 七', '解秋十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寒竹秋雨重，凌霄晚花落。","低回翠玉梢，散亂梔黃萼。","顏色有殊異，風霜無好惡。","年年百草芳，畢意同蕭索。"]', '["寒竹秋雨重，凌霄晚花落。","低回翠玉梢，散亂梔黄萼。","顏色有殊異，风霜無好惡。","年年百草芳，畢意同蕭索。"]', '诗', 'shi', '', NULL, '解秋十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c34f843a-5e27-41d5-a34c-f09e4835a200', '解秋十首 八', '解秋十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春非我獨春，秋非我獨秋。","豈念百草死，但念霜滿頭。","頭白古所同，胡爲坐煩憂。","茫茫百年內，處身良未休。"]', '["春非我独春，秋非我独秋。","豈念百草死，但念霜满头。","头白古所同，胡爲坐煩憂。","茫茫百年內，处身良未休。"]', '诗', 'shi', '', NULL, '解秋十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06d15d6-ce1d-41f3-9ed7-bb7b4e6f6522', '解秋十首 九', '解秋十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["西風冷衾簟，展轉布華茵。","來者承玉體，去者流芳塵。","適意醜爲好，及時疎亦親。","衰周仲尼出，無乃爲妖人。"]', '["西风冷衾簟，展轉布华茵。","来者承玉體，去者流芳塵。","適意醜爲好，及时疎亦親。","衰周仲尼出，無乃爲妖人。"]', '诗', 'shi', '', NULL, '解秋十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0da9dc1-bef7-4da1-9616-47ec4f3af784', '解秋十首 十', '解秋十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["漠漠江面燒，微微楓樹煙。","今日復今夕，秋懷方浩然。","況我頭上髮，衰白不待年。","我懷有時極，此意何由詮。"]', '["漠漠江面燒，微微楓樹煙。","今日复今夕，秋懷方浩然。","況我头上髮，衰白不待年。","我懷有时極，此意何由詮。"]', '诗', 'shi', '', NULL, '解秋十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c704fa-f371-4c8e-aad8-d950f67d5b40', '遣病十首 一', '遣病十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["服藥備江瘴，四年方一癘。","豈是藥無功，伊予久留滯。","滯留人固薄，瘴久藥難制。","去日良已甘，歸途奈無際。"]', '["服藥備江瘴，四年方一癘。","豈是藥無功，伊予久留滯。","滯留人固薄，瘴久藥难制。","去日良已甘，归途奈無際。"]', '诗', 'shi', '', NULL, '遣病十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b267785-80f9-4bf6-80e1-3abf30689e39', '遣病十首 二', '遣病十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["棄置何所任，鄭公憐我病。","三十九萬錢，資予養頑瞑。","身賤殺何益，恩深報難罄。","公其萬千年，世有天之鄭。"]', '["棄置何所任，鄭公怜我病。","三十九万錢，資予養頑瞑。","身賤殺何益，恩深報难罄。","公其万千年，世有天之鄭。"]', '诗', 'shi', '', NULL, '遣病十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af8adcc6-5616-46be-9fe5-b4528206fb84', '遣病十首 三', '遣病十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶作孩稚初，健羨成人列。","倦學厭日長，嬉遊念佳節。","今來漸諱年，頓與前心別。","白日速如飛，佳晨亦騷屑。"]', '["憶作孩稚初，健羨成人列。","倦学厭日长，嬉游念佳節。","今来漸諱年，頓與前心別。","白日速如飞，佳晨亦騷屑。"]', '诗', 'shi', '', NULL, '遣病十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b05b33f9-0f28-489e-89a4-8a40742c03ba', '遣病十首 四', '遣病十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔在痛飲場，憎人病辭醉。","病來身怕酒，始悟他人意。","怕酒豈不閑，悲無少年氣。","傳語少年兒，杯盤莫廻避。"]', '["昔在痛饮場，憎人病辞醉。","病来身怕酒，始悟他人意。","怕酒豈不闲，悲無少年氣。","傳語少年兒，杯盤莫廻避。"]', '诗', 'shi', '', NULL, '遣病十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc7a697d-439d-449e-a294-41406b8c80ff', '遣病十首 五', '遣病十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶初頭始白，晝夜驚一縷。","漸及鬢與鬚，多來不能數。","壯年等閑過，過壯年已五。","華髮不再青，勞生竟何補。"]', '["憶初头始白，晝夜驚一縷。","漸及鬢與鬚，多来不能數。","壯年等闲過，過壯年已五。","华髮不再青，勞生竟何補。"]', '诗', 'shi', '', NULL, '遣病十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd72e49e-112d-43ea-a024-10b2d1c96df5', '遣病十首 六', '遣病十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["在家非不病，有病心亦安。","起居甥姪扶，藥餌兄嫂看。","今病兄遠路，道遙書信難。","寄言嬌小弟，莫作官家官。"]', '["在家非不病，有病心亦安。","起居甥姪扶，藥餌兄嫂看。","今病兄远路，道遙书信难。","寄言嬌小弟，莫作官家官。"]', '诗', 'shi', '', NULL, '遣病十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beb4132d-1343-46b2-aafe-e1f6beec0d6d', '遣病十首 七', '遣病十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["燕巢官舍內，我爾俱爲客。","歲晚我獨留，秋深爾安適。","風高翅羽垂，路遠煙波隔。","去去玉山岑，人間網羅窄。"]', '["燕巢官舍內，我爾俱爲客。","歲晚我独留，秋深爾安適。","风高翅羽垂，路远煙波隔。","去去玉山岑，人间網羅窄。"]', '诗', 'shi', '', NULL, '遣病十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74efe2b4-7f46-4c15-85db-5728cd45a02e', '遣病十首 八', '遣病十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["簷宇夜來曠，暗知秋已生。","臥悲衾簟冷，病覺支體輕。","炎昏豈不勌，時去聊自驚。","浩歎終一夕，空堂天欲明。"]', '["簷宇夜来曠，暗知秋已生。","臥悲衾簟冷，病覺支體轻。","炎昏豈不勌，时去聊自驚。","浩歎終一夕，空堂天欲明。"]', '诗', 'shi', '', NULL, '遣病十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b831e75-e886-4c54-a564-159374d90eb6', '遣病十首 九', '遣病十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["秋依靜處多，況乃凌晨趣。","深竹蟬晝風，翠茸衫曉露。","庭莎病看長，林果閑知數。","何以強健時，公門日勞騖。"]', '["秋依静处多，況乃凌晨趣。","深竹蟬晝风，翠茸衫晓露。","庭莎病看长，林果闲知數。","何以強健时，公门日勞騖。"]', '诗', 'shi', '', NULL, '遣病十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f957c76-d693-43a7-8c42-75da65c30eb8', '遣病十首 十', '遣病十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["朝結故鄉念，暮作空堂寢。","夢別淚亦流，啼痕暗橫枕。","昔愁憑酒遣，今病安能飲。","落盡秋槿花，離人病猶甚。"]', '["朝結故乡念，暮作空堂寢。","梦別泪亦流，啼痕暗橫枕。","昔愁憑酒遣，今病安能饮。","落尽秋槿花，離人病猶甚。"]', '诗', 'shi', '', NULL, '遣病十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf6a7cf-ab6c-4576-8a31-5069b66551da', '寒', '寒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["江瘴節候暖，臘初梅已殘。","夜來北風至，喜見今日寒。","扣冰淺塘水，擁雪深竹闌。","復此滿尊醁，但嗟誰與歡。"]', '["江瘴節候暖，臘初梅已殘。","夜来北风至，喜见今日寒。","扣冰淺塘水，擁雪深竹闌。","复此满尊醁，但嗟誰與歡。"]', '诗', 'shi', '', NULL, '寒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7bd9b32-1516-4511-893b-d78798e943b9', '玉泉道中作', '玉泉道中作', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["楚俗物候晚，孟冬纔有霜。","早農半華實，夕水含風涼。","遐想雲外寺，峰巒渺相望。","松門接官路，泉脈連僧房。","微露上弦月，暗焚初夜香。","谷深煙壒淨，山虛鐘磬長。","念此清境遠，復憂塵事妨。","行行即前路，勿滯分寸光。"]', '["楚俗物候晚，孟冬纔有霜。","早農半华實，夕水含风涼。","遐想云外寺，峰巒渺相望。","松门接官路，泉脈連僧房。","微露上弦月，暗焚初夜香。","谷深煙壒淨，山虛鐘磬长。","念此清境远，复憂塵事妨。","行行即前路，勿滯分寸光。"]', '诗', 'shi', '', NULL, '玉泉道中作 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409ecfdc-bec5-4cf0-b795-39aa7cd942ea', '遣病', '遣病', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["自古誰不死，不復記其名。","今年京城內，死者老少幷。","獨孤纔四十，仕宦方榮榮。","李三三十九，登朝有清聲。","趙昌八十餘，三擁大將旌。","爲生信異異，之死同冥冥。","其家哭泣愛，一一無異情。","其類嗟歎惜，各各無重輕。","萬齡龜菌等，一死天地平。","以此方我病，我病何足驚。","借如今日死，亦足了一生。","借使到百年，不知何所成。","況我早師佛，屋宅此身形。","捨彼復就此，去留何所縈。","前身爲過跡，來世即前程。","但念行不息，豈憂無路行。","蛻骨龍不死，蛻皮蟬自鳴。","胡爲神蛻體，此道人不明。","持謝愛朋友，寄之仁弟兄。","吟此可達觀，世言何足聽。"]', '["自古誰不死，不复記其名。","今年京城內，死者老少幷。","独孤纔四十，仕宦方榮榮。","李三三十九，登朝有清声。","趙昌八十餘，三擁大將旌。","爲生信異異，之死同冥冥。","其家哭泣愛，一一無異情。","其類嗟歎惜，各各無重轻。","万齡龟菌等，一死天地平。","以此方我病，我病何足驚。","借如今日死，亦足了一生。","借使到百年，不知何所成。","況我早師佛，屋宅此身形。","捨彼复就此，去留何所縈。","前身爲過跡，来世即前程。","但念行不息，豈憂無路行。","蛻骨龙不死，蛻皮蟬自鳴。","胡爲神蛻體，此道人不明。","持謝愛朋友，寄之仁弟兄。","吟此可達观，世言何足听。"]', '诗', 'shi', '', NULL, '遣病 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4e05e4-bccf-41f3-9138-a264dd24ae63', '感夢', '感梦', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["十月初二日，我行蓬州西。","三十里有館，有館名芳溪。","荒郵屋舍壞，新雨田地泥。","我病百日餘，肌體顧若刲。","氣填暮不食，早早掩竇圭。","陰寒筋骨病，夜久燈火低。","忽然寢成夢，宛見顏如珪。","似歎久離別，嗟嗟復悽悽。","問我何病痛，又歎何棲棲。","答云痰滯久，與世復相暌。","重云痰小疾，良藥固易擠。","前時奉橘丸，攻疾有神功。","何不善和療，豈獨頭有風。","殷勤平生事，款曲無不終。","悲歡兩相極，以是半日中。","言罷相與行，行行古成裏。","同行復一人，不識誰氏子。","逡巡急吏來，呼喚願且止。","馳至相君前，再拜復再起。","啓云吏有奉，奉命傳所旨。","事有大驚忙，非君不能理。","答云久就閑，不願見勞使。","多謝致勤勤，未敢相唯唯。","我因前獻言，此事愚可料。","亂熱由靜消，理繁在知要。","君如冬月陽，奔走不必召。","君如銅鏡明，萬物自可照。","願君許蒼生，勿復高體調。","相君不我言，顧我再三笑。","行行及城戶，黯黯餘日暉。","相君不我言，命我從此歸。","不省別時語，但省涕淋漓。","覺來身體汗，坐臥心骨悲。","閃閃燈背壁，膠膠雞去塒。","倦童顛倒寢，我淚縱橫垂。","淚垂啼不止，不止啼且聲。","啼聲覺僮僕，僮僕撩亂驚。","問我何所苦，問我何所思。","我亦不能語，慘慘即路岐。","前經新政縣，今夕復明辰。","寘寘滿心氣，不得說向人。","奇哉趙明府，怪我眉不伸。","云有北來僧，住此月與旬。","自言辨貴骨，謂若識天真。","談遊費閟景，何不與逡巡？","僧來爲予語，語及昔所知。","自言有奇中，裴相未相時。","讀書靈山寺，住處接園籬。","指言他日貴，晷刻似不移。","我聞僧此語，不覺淚歔欷。","因言前夕夢，無人一相謂。","無乃裴相君，念我胸中氣。","遣師及此言，使我盡前事。","僧云彼何親，言下涕不已。","我云知我深，不幸先我死。","僧云裴相君，如君恩有幾。","我云滔滔衆，好直者皆是。","唯我與白生，感遇同所以。","官學不同時，生小異鄉里。","拔我塵土中，使我名字美。","美名何足多，深分從此始。","吹噓莫我先，頑陋不我鄙。","往往裴相門，終年不曾履。","相門多衆流，多譽亦多毀。","如聞風過塵，不動井中水。","前時予掾荆，公在期復起。","自從裴公無，吾道甘已矣。","白生道亦孤，讒謗銷骨髓。","司馬九江城，無人一言理。","爲師陳苦言，揮涕滿十指。","未死終報恩，師聽此男子。"]', '["十月初二日，我行蓬州西。","三十里有館，有館名芳溪。","荒郵屋舍壞，新雨田地泥。","我病百日餘，肌體顧若刲。","氣填暮不食，早早掩竇圭。","陰寒筋骨病，夜久灯火低。","忽然寢成梦，宛见顏如珪。","似歎久離別，嗟嗟复悽悽。","问我何病痛，又歎何棲棲。","答云痰滯久，與世复相暌。","重云痰小疾，良藥固易擠。","前时奉橘丸，攻疾有神功。","何不善和療，豈独头有风。","殷勤平生事，款曲無不終。","悲歡兩相極，以是半日中。","言罷相與行，行行古成裏。","同行复一人，不識誰氏子。","逡巡急吏来，呼喚願且止。","驰至相君前，再拜复再起。","啓云吏有奉，奉命傳所旨。","事有大驚忙，非君不能理。","答云久就闲，不願见勞使。","多謝致勤勤，未敢相唯唯。","我因前獻言，此事愚可料。","亂熱由静消，理繁在知要。","君如冬月陽，奔走不必召。","君如銅镜明，万物自可照。","願君許蒼生，勿复高體調。","相君不我言，顧我再三笑。","行行及城戶，黯黯餘日暉。","相君不我言，命我從此归。","不省別时語，但省涕淋漓。","覺来身體汗，坐臥心骨悲。","閃閃灯背壁，膠膠雞去塒。","倦童顛倒寢，我泪縱橫垂。","泪垂啼不止，不止啼且声。","啼声覺僮僕，僮僕撩亂驚。","问我何所苦，问我何所思。","我亦不能語，慘慘即路岐。","前經新政縣，今夕复明辰。","寘寘满心氣，不得说向人。","奇哉趙明府，怪我眉不伸。","云有北来僧，住此月與旬。","自言辨貴骨，謂若識天真。","談游費閟景，何不與逡巡？","僧来爲予語，語及昔所知。","自言有奇中，裴相未相时。","读书靈山寺，住处接园籬。","指言他日貴，晷刻似不移。","我闻僧此語，不覺泪歔欷。","因言前夕梦，無人一相謂。","無乃裴相君，念我胸中氣。","遣師及此言，使我尽前事。","僧云彼何親，言下涕不已。","我云知我深，不幸先我死。","僧云裴相君，如君恩有幾。","我云滔滔衆，好直者皆是。","唯我與白生，感遇同所以。","官学不同时，生小異乡里。","拔我塵土中，使我名字美。","美名何足多，深分從此始。","吹噓莫我先，頑陋不我鄙。","往往裴相门，終年不曾履。","相门多衆流，多譽亦多毀。","如闻风過塵，不动井中水。","前时予掾荆，公在期复起。","自從裴公無，吾道甘已矣。","白生道亦孤，讒謗銷骨髓。","司马九江城，無人一言理。","爲師陳苦言，揮涕满十指。","未死終報恩，師听此男子。"]', '诗', 'shi', '', NULL, '感夢 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f9a6fd7-233e-4fee-ad21-ac6a39c7aff4', '和東川李相公慈竹十二韻', '和东川李相公慈竹十二韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["慈竹不外長，密比青瑤華。","矛攢有森束，玉粒無蹉跎。","纖粉妍膩質，細瓊交翠柯。","亭亭霄漢近，靄靄雨露多。","冰碧寒夜聳，簫韶風晝羅。","煙含朧朧影，月泛鱗鱗波。","鸞鳳一已顧，燕雀永不過。","幽姿媚庭實，顥氣爽天涯。","峻節高轉露，貞筠寒更佳。","託身仙壇上，靈物神所呵。","時與天籟合，日聞陽春歌。","應憐孤生者，摧折成病痾。"]', '["慈竹不外长，密比青瑤华。","矛攢有森束，玉粒無蹉跎。","纖粉妍膩質，細瓊交翠柯。","亭亭霄漢近，靄靄雨露多。","冰碧寒夜聳，簫韶风晝羅。","煙含朧朧影，月泛鱗鱗波。","鸾鳳一已顧，燕雀永不過。","幽姿媚庭實，顥氣爽天涯。","峻節高轉露，貞筠寒更佳。","託身仙壇上，靈物神所呵。","时與天籟合，日闻陽春歌。","應怜孤生者，摧折成病痾。"]', '诗', 'shi', '', NULL, '和東川李相公慈竹十二韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaf872cd-1643-493b-9f2b-bc34ecdf57eb', '酬東川李相公十六韻', '酬东川李相公十六韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔附赤霄羽，葳蕤遊紫垣。","鬬班香案上，奏語玉晨尊。","戇直撩忌諱，科儀懲傲頑。","自從真籍除，棄置勿復論。","前時共遊者，日夕黃金軒。","請帝下巫覡，八荒求我魂。","鸞鳳屢鳴顧，燕雀尚籬藩。","徒令霄漢外，往往塵念存。","存念豈虛設，併投瓊與璠。","彈珠古所訝，此用何太敦。","鄒律寒氣變，鄭琴祥景奔。","靈芝繞身出，左右光彩繁。","碾玉無俗色，蘂珠非世言。","重慙前日句，陋若蕕並蓀。","臘月巴地雨，瘴江愁浪翻。","因持駭雞寶，一照濁水昏。"]', '["昔附赤霄羽，葳蕤游紫垣。","鬬班香案上，奏語玉晨尊。","戇直撩忌諱，科儀懲傲頑。","自從真籍除，棄置勿复論。","前时共游者，日夕黄金軒。","請帝下巫覡，八荒求我魂。","鸾鳳屢鳴顧，燕雀尚籬藩。","徒令霄漢外，往往塵念存。","存念豈虛設，併投瓊與璠。","彈珠古所訝，此用何太敦。","鄒律寒氣变，鄭琴祥景奔。","靈芝繞身出，左右光彩繁。","碾玉無俗色，蘂珠非世言。","重慙前日句，陋若蕕並蓀。","臘月巴地雨，瘴江愁浪翻。","因持駭雞寶，一照濁水昏。"]', '诗', 'shi', '', NULL, '酬東川李相公十六韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ea3f5f-8721-4d41-b147-952bc0507706', '酬獨孤二十六送歸通州', '酬独孤二十六送归通州', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["再拜捧兄贈，拜兄珍重言。","我有平生志，臨別將具論。","十歲慕倜儻，愛白不愛昏。","寧愛寒切烈，不愛暘溫暾。","二十走獵騎，三十遊海門。","憎兔跳趯趯，惡鵬黑翻翻。","鼇釣氣方壯，鶻拳心頗尊。","下觀鬇鬡輩，一掃冀不存。","名冠壯士籍，功酬明主恩。","不然合身棄，何況身上痕。","金石有銷爍，胏腑無寒溫。","分畫久已定，波濤何足煩。","嘗希蘇門嘯，詎厭巴樹猿。","瘴水徒浩浩，浮雲亦軒軒。","長歌莫長歡，飲斛莫飲樽。","生爲醉鄉客，死作達士魂。"]', '["再拜捧兄贈，拜兄珍重言。","我有平生志，臨別將具論。","十歲慕倜儻，愛白不愛昏。","寧愛寒切烈，不愛暘溫暾。","二十走獵騎，三十游海门。","憎兔跳趯趯，惡鵬黑翻翻。","鼇釣氣方壯，鶻拳心頗尊。","下观鬇鬡輩，一掃冀不存。","名冠壯士籍，功酬明主恩。","不然合身棄，何況身上痕。","金石有銷爍，胏腑無寒溫。","分畫久已定，波濤何足煩。","嘗希蘇门嘯，詎厭巴樹猿。","瘴水徒浩浩，浮云亦軒軒。","长歌莫长歡，饮斛莫饮樽。","生爲醉乡客，死作達士魂。"]', '诗', 'shi', '', NULL, '酬獨孤二十六送歸通州 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('066adddf-9303-4030-a07f-ccf08e2bd81f', '酬劉猛見送', '酬劉猛见送', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["種花有顏色，異色即爲妖。","養鳥惡羽翮，剪翮不待高。","非無剪傷者，物性難自逃。","百足雖捷捷，商羊亦翹翹。","伊余狷然質，謬入多士朝。","任氣有愎戇，容身寡朋曹。","愚狂偶似直，靜僻非敢驕。","一爲毫髮忤，十載山川遙。","爍鐵不在火，割肌不在刀。","險心露山嶽，流語翻波濤。","六尺安敢主，方寸自由調。","神劒土不蝕，異布火不燋。","雖無二物姿，庶欲効一毫。","未能深蹙蹙，多謝相勞勞。","去去我移馬，遲遲君過橋。","雲勢正橫壑，江流初滿槽。","持此慰遠道，此之爲舊交。"]', '["種花有顏色，異色即爲妖。","養鸟惡羽翮，剪翮不待高。","非無剪傷者，物性难自逃。","百足雖捷捷，商羊亦翹翹。","伊余狷然質，謬入多士朝。","任氣有愎戇，容身寡朋曹。","愚狂偶似直，静僻非敢驕。","一爲毫髮忤，十載山川遙。","爍鐵不在火，割肌不在刀。","險心露山嶽，流語翻波濤。","六尺安敢主，方寸自由調。","神劒土不蝕，異布火不燋。","雖無二物姿，庶欲効一毫。","未能深蹙蹙，多謝相勞勞。","去去我移马，遲遲君過橋。","云勢正橫壑，江流初满槽。","持此慰远道，此之爲旧交。"]', '诗', 'shi', '', NULL, '酬劉猛見送 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a056ad49-c180-40f0-8657-643e2c531990', '酬樂天赴江州路上見寄三首 一', '酬乐天赴江州路上见寄三首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔在京城心，今在吳楚末。","千山道路險，萬里音塵闊。","天上參與商，地上胡與越。","終天升沈異，滿地網羅設。","心有無眹環，腸有無繩結。","有結解不開，有環尋不歇。","山嶽移可盡，江海塞可絕。","離恨若空虛，窮年思不徹。","生莫強相同，相同會相別。"]', '["昔在京城心，今在吳楚末。","千山道路險，万里音塵闊。","天上參與商，地上胡與越。","終天升沈異，满地網羅設。","心有無眹环，腸有無繩結。","有結解不开，有环尋不歇。","山嶽移可尽，江海塞可絕。","離恨若空虛，窮年思不徹。","生莫強相同，相同會相別。"]', '诗', 'shi', '', NULL, '酬樂天赴江州路上見寄三首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a02a4b68-3e7e-43d5-b1be-0bfdb4476395', '酬樂天赴江州路上見寄三首 二', '酬乐天赴江州路上见寄三首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["襄陽大隄繞，我向隄前住。","燭隨花豔來，騎送朝雲去。","萬竿高廟竹，三月徐亭樹。","我昔憶君時，君今懷我處。","有身有離別，無地無岐路。","風塵同古今，人世勞新故。"]', '["襄陽大隄繞，我向隄前住。","燭隨花豔来，騎送朝云去。","万竿高廟竹，三月徐亭樹。","我昔憶君时，君今懷我处。","有身有離別，無地無岐路。","风塵同古今，人世勞新故。"]', '诗', 'shi', '', NULL, '酬樂天赴江州路上見寄三首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b8c3d4-9f0f-4b55-8bb6-f8691c816505', '酬樂天赴江州路上見寄三首 三', '酬乐天赴江州路上见寄三首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["人亦有相愛，我爾殊衆人。","朝朝寧不食，日日願見君。","一日不得見，愁腸坐氛氳。","如何遠相失，各作萬里雲。","雲高風苦多，會合難遽因。","天上猶有礙，何況地上身。"]', '["人亦有相愛，我爾殊衆人。","朝朝寧不食，日日願见君。","一日不得见，愁腸坐氛氳。","如何远相失，各作万里云。","云高风苦多，會合难遽因。","天上猶有礙，何況地上身。"]', '诗', 'shi', '', NULL, '酬樂天赴江州路上見寄三首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a6d2252-a05a-4fbb-ae88-890ff87ce04c', '郵竹', '郵竹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["庭有蕭蕭竹，門有闐闐騎。","囂靜本殊途，因依偶同寄。","亭亭乍干雲，嫋嫋亦垂地。","人有異我心，我無異人意。"]', '["庭有蕭蕭竹，门有闐闐騎。","囂静本殊途，因依偶同寄。","亭亭乍干云，嫋嫋亦垂地。","人有異我心，我無異人意。"]', '诗', 'shi', '', NULL, '郵竹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a844e25-382f-43c0-942b-cd20bd397ee9', '落月', '落月', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["落月沈餘影，陰渠流暗光。","蚊聲靄窗戶，螢火繞屋梁。","飛幌翠雲薄，新荷清露香。","不吟復不寐，竟夕池水傍。"]', '["落月沈餘影，陰渠流暗光。","蚊声靄窗戶，螢火繞屋梁。","飞幌翠云薄，新荷清露香。","不吟复不寐，竟夕池水傍。"]', '诗', 'shi', '', NULL, '落月 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff9ba6ba-1892-40f7-b02c-2ce2e0e2c8ed', '高荷', '高荷', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["種藕百餘根，高荷纔四葉。","颭閃碧雲扇，團圓青玉疊。","亭亭自擡舉，鼎鼎難藏擪。","不學著水荃，一生長怗怗。"]', '["種藕百餘根，高荷纔四葉。","颭閃碧云扇，團圓青玉叠。","亭亭自擡舉，鼎鼎难藏擪。","不学著水荃，一生长怗怗。"]', '诗', 'shi', '', NULL, '高荷 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ca77171-5ad9-4f9a-934e-1ea54f2cc9d3', '和裴校書鷺鷥飛', '和裴校书鷺鷥飞', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鷺鷥鷺鷥何遽飛，鵶驚雀噪難久依。","清江見底草堂在，一點白光終不歸。"]', '["鷺鷥鷺鷥何遽飞，鵶驚雀噪难久依。","清江见底草堂在，一点白光終不归。"]', '诗', 'shi', '', NULL, '和裴校書鷺鷥飛 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('894341d4-2c13-4b88-a016-ebe6aeb0a66a', '夜池', '夜池', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["荷葉團圓莖削削，綠萍面上紅衣落。","滿池明月思啼螿，高屋無人風張幕。"]', '["荷葉團圓莖削削，綠萍面上紅衣落。","满池明月思啼螿，高屋無人风張幕。"]', '诗', 'shi', '', NULL, '夜池 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e110c62b-f130-4558-b4af-8282d6a2a5de', '酬楊司業十二兄早秋述情見寄', '酬楊司業十二兄早秋述情见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["白髮故人少，相逢意彌遠。","往事共銷沈，前期各衰晚。","昨來遇彌苦，已復雲離巘。","秋草古膠庠，寒沙廢宮苑。","知心豈忘鮑，詠懷難和阮。","壯志日蕭條，那能競朝幰。"]', '["白髮故人少，相逢意彌远。","往事共銷沈，前期各衰晚。","昨来遇彌苦，已复云離巘。","秋草古膠庠，寒沙廢宮苑。","知心豈忘鲍，詠懷难和阮。","壯志日蕭條，那能競朝幰。"]', '诗', 'shi', '', NULL, '酬楊司業十二兄早秋述情見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cea9c022-0ca5-4f5a-992a-7f7b42826486', '代杭人作使君一朝去二首 一', '代杭人作使君一朝去二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["使君一朝去，遺愛在人口。","惠化境內春，才名天下首。","爲問龔黃輩，兼能作詩否。"]', '["使君一朝去，遺愛在人口。","惠化境內春，才名天下首。","爲问龔黄輩，兼能作诗否。"]', '诗', 'shi', '', NULL, '代杭人作使君一朝去二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9d26c42-e29a-45f7-af74-1925d1f1f22a', '代杭人作使君一朝去二首 二', '代杭人作使君一朝去二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["使君一朝去，斷腸如剉檗。","無復見冰壺，唯應鏤金石。","自此一州人，生男盡名白。"]', '["使君一朝去，斷腸如剉檗。","無复见冰壺，唯應鏤金石。","自此一州人，生男尽名白。"]', '诗', 'shi', '', NULL, '代杭人作使君一朝去二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e779dbae-0771-4cea-9af3-67d0d761e562', '長慶曆', '长慶曆', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["年曆復年曆，卷盡悲且惜。","曆日何足悲，但悲年運易。","年年豈無歎，此歎何唧唧。","所歎別此年，永無長慶曆。"]', '["年曆复年曆，卷尽悲且惜。","曆日何足悲，但悲年運易。","年年豈無歎，此歎何唧唧。","所歎別此年，永無长慶曆。"]', '诗', 'shi', '', NULL, '長慶曆 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('675edd27-789d-417e-aaf1-27d7b405bec5', '順宗至德大聖大安孝皇帝挽歌詞三首 一', '順宗至德大聖大安孝皇帝挽歌词三首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["不改延洪祚，因成揖讓朝。","謳歌同戴啓，遏密共思堯。","雨露施恩廣，梯航會葬遙。","號弓那獨切，曾感昔年招。"]', '["不改延洪祚，因成揖讓朝。","謳歌同戴啓，遏密共思堯。","雨露施恩廣，梯航會葬遙。","號弓那独切，曾感昔年招。"]', '诗', 'shi', '', NULL, '順宗至德大聖大安孝皇帝挽歌詞三首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed566302-ccbe-44fc-b92d-df28a414c402', '順宗至德大聖大安孝皇帝挽歌詞三首 二', '順宗至德大聖大安孝皇帝挽歌词三首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["前春文祖廟，大舜嗣堯登。","及此踰年感，還因是月崩。","壽緣追孝促，業在繼明興。","儉詔同今古，山川繞灞陵。"]', '["前春文祖廟，大舜嗣堯登。","及此踰年感，還因是月崩。","壽緣追孝促，業在繼明兴。","儉詔同今古，山川繞灞陵。"]', '诗', 'shi', '', NULL, '順宗至德大聖大安孝皇帝挽歌詞三首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55813a3e-3b1d-4f2a-97b8-663a092a5cc6', '順宗至德大聖大安孝皇帝挽歌詞三首 三', '順宗至德大聖大安孝皇帝挽歌词三首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["七月悲風起，淒涼萬國人。","羽儀經巷內，輼𨍇轉城闉。","暝色依陵早，秋聲入輅新。","自嗟同草木，不識永貞春。"]', '["七月悲风起，淒涼万国人。","羽儀經巷內，輼𨍇轉城闉。","暝色依陵早，秋声入輅新。","自嗟同草木，不識永貞春。"]', '诗', 'shi', '', NULL, '順宗至德大聖大安孝皇帝挽歌詞三首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fcfdc6b-b8d6-4df3-a68e-4ce6954620d6', '憲宗章武孝皇帝挽歌詞三首 一', '憲宗章武孝皇帝挽歌词三首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["國付重離後，身隨十聖仙。","北辰移帝座，西日到虞泉。","方丈言虛設，華胥事眇然。","觸鱗曾在宥，偏哭墮髯前。"]', '["国付重離後，身隨十聖仙。","北辰移帝座，西日到虞泉。","方丈言虛設，华胥事眇然。","觸鱗曾在宥，偏哭墮髯前。"]', '诗', 'shi', '', NULL, '憲宗章武孝皇帝挽歌詞三首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4007237-d828-4152-9ec1-d74a689981ba', '憲宗章武孝皇帝挽歌詞三首 二', '憲宗章武孝皇帝挽歌词三首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["天寶遺餘事，元和盛聖功。","二凶梟帳下，三叛斬都中。","始服沙陁虜，方吞邏逤戎。","狼星如要射，猶有鼎湖弓。"]', '["天寶遺餘事，元和盛聖功。","二凶梟帳下，三叛斬都中。","始服沙陁虜，方吞邏逤戎。","狼星如要射，猶有鼎湖弓。"]', '诗', 'shi', '', NULL, '憲宗章武孝皇帝挽歌詞三首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeeff4e4-de73-4bea-9c57-c1bf522ecb93', '憲宗章武孝皇帝挽歌詞三首 三', '憲宗章武孝皇帝挽歌词三首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["月落禁垣西，星攢曉仗齊。","風傳宮漏苦，雲拂羽儀低。","路隘車千兩，橋危馬萬蹄。","共嗟封石撿，不爲報功泥。"]', '["月落禁垣西，星攢晓仗齊。","风傳宮漏苦，云拂羽儀低。","路隘车千兩，橋危马万蹄。","共嗟封石撿，不爲報功泥。"]', '诗', 'shi', '', NULL, '憲宗章武孝皇帝挽歌詞三首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf33164-0d8b-4739-9e34-005e781ee3e0', '恭王故太妃挽歌詞二首 一', '恭王故太妃挽歌词二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["燕姞貽天夢，梁王盡孝思。","雖從魏詔葬，得用漢藩儀。","曙月殘光斂，寒簫度曲遲。","平生奉恩地，哀挽欲何之。"]', '["燕姞貽天梦，梁王尽孝思。","雖從魏詔葬，得用漢藩儀。","曙月殘光斂，寒簫度曲遲。","平生奉恩地，哀挽欲何之。"]', '诗', 'shi', '', NULL, '恭王故太妃挽歌詞二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b6bb06d-6988-4aff-af45-ad7a0f59341c', '恭王故太妃挽歌詞二首 二', '恭王故太妃挽歌词二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["文衛羅新壙，仙娥掩暝山。","雪雲埋隴合，簫鼓望城還。","寒樹風難靜，霜郊夜更閑。","哀榮深孝嗣，儀表在河間。"]', '["文衛羅新壙，仙娥掩暝山。","雪云埋隴合，簫鼓望城還。","寒樹风难静，霜郊夜更闲。","哀榮深孝嗣，儀表在河间。"]', '诗', 'shi', '', NULL, '恭王故太妃挽歌詞二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b23777c-6576-4919-8704-4ed7aa64936b', '哭呂衡州六首 一', '哭呂衡州六首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["氣敵三人傑，交深一紙書。","我投冰瑩眼，君報水憐魚。","髀股惟夸瘦，膏肓豈暇除。","傷心死諸葛，憂道不憂餘。"]', '["氣敵三人傑，交深一紙书。","我投冰瑩眼，君報水怜鱼。","髀股惟夸瘦，膏肓豈暇除。","傷心死諸葛，憂道不憂餘。"]', '诗', 'shi', '', NULL, '哭呂衡州六首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a27011ee-2e78-4bcf-a41f-125975716b57', '哭呂衡州六首 二', '哭呂衡州六首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["望有經綸釣，虔收宰相刀。","江文駕風遠，雲貌接天高。","國待球琳器，家藏虎豹韜。","盡將千載寶，埋入五原蒿。"]', '["望有經綸釣，虔收宰相刀。","江文駕风远，云貌接天高。","国待球琳器，家藏虎豹韜。","尽將千載寶，埋入五原蒿。"]', '诗', 'shi', '', NULL, '哭呂衡州六首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b40ffb4-d390-4d54-a701-87cc76906bcf', '哭呂衡州六首 三', '哭呂衡州六首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["白馬雙旌隊，青山八陣圖。","請纓期繫虜，枕草誓捐軀。","勢激三千壯，年應四十無。","遙聞不瞑目，非是不憐吳。"]', '["白马雙旌隊，青山八陣圖。","請纓期繫虜，枕草誓捐軀。","勢激三千壯，年應四十無。","遙闻不瞑目，非是不怜吳。"]', '诗', 'shi', '', NULL, '哭呂衡州六首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f874a6-f01c-41f5-be65-4b7bcf652188', '哭呂衡州六首 四', '哭呂衡州六首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鵰鶚生難敵，沉檀死更香。","兒童喧巷市，羸老哭碑堂。","鴈起沙汀闇，雲連海氣黃。","祝融峰上月，幾照北人喪。"]', '["鵰鶚生难敵，沉檀死更香。","兒童喧巷市，羸老哭碑堂。","鴈起沙汀闇，云連海氣黄。","祝融峰上月，幾照北人喪。"]', '诗', 'shi', '', NULL, '哭呂衡州六首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f440666-83e7-4027-b5b2-f70f542df04c', '哭呂衡州六首 五', '哭呂衡州六首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["廻鴈峰前鴈，春廻盡却廻。","聯行四人去，同葬一人來。","鐃吹臨江返，城池隔霧開。","滿船深夜哭，風棹楚猿哀。"]', '["廻鴈峰前鴈，春廻尽却廻。","聯行四人去，同葬一人来。","鐃吹臨江返，城池隔霧开。","满船深夜哭，风棹楚猿哀。"]', '诗', 'shi', '', NULL, '哭呂衡州六首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f683e8-8fa8-498a-bd56-4e8059f0504c', '哭呂衡州六首 六', '哭呂衡州六首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["杜預春秋癖，揚雄著述精。","在時兼不語，終古定歸名。","耒水波文細，湘江竹葉輕。","平生思風月，潛寐若爲情。"]', '["杜預春秋癖，揚雄著述精。","在时兼不語，終古定归名。","耒水波文細，湘江竹葉轻。","平生思风月，潛寐若爲情。"]', '诗', 'shi', '', NULL, '哭呂衡州六首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f06deb49-67a0-4e05-bbde-b9b2b2fe3f76', '僧如展及韋載同遊碧澗寺各賦詩予落句云他生莫忘靈山座滿壁人名後會稀展共吟他生之句因話釋氏緣會所以莫不悽然久之不十日而展公長逝驚悼返覆則他生豈有兆耶其間展公仍賦黃字五十韻飛札相示予方屬和未畢自此不復撰成徒以四韻爲識', '僧如展及韋載同游碧澗寺各賦诗予落句云他生莫忘靈山座满壁人名後會稀展共吟他生之句因話釋氏緣會所以莫不悽然久之不十日而展公长逝驚悼返覆則他生豈有兆耶其间展公仍賦黄字五十韻飞札相示予方屬和未畢自此不复撰成徒以四韻爲識', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["重吟前日他生句，豈料踰旬便隔生。","會擬一來身塔下，無因共繞寺廊竹。","紫毫飛札看猶濕，黃字新詩和未成。","縱使得如羊叔子，不聞兼記舊交情。"]', '["重吟前日他生句，豈料踰旬便隔生。","會擬一来身塔下，無因共繞寺廊竹。","紫毫飞札看猶濕，黄字新诗和未成。","縱使得如羊叔子，不闻兼記旧交情。"]', '诗', 'shi', '', NULL, '僧如展及韋載同遊碧澗寺各賦詩予落句云他生莫忘靈山座滿壁人名後會稀展共吟他生之句因話釋氏緣會所以莫不悽然久之不十日而展公長逝驚悼返覆則他生豈有兆耶其間展公仍賦黃字五十韻飛札相示予方屬和未畢自此不復撰成徒以四韻爲識 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aaacf65-f482-4535-aec2-9c90b03fddc5', '公安縣遠安寺水亭見展公題壁漂然淚流因書四韻', '公安縣远安寺水亭见展公題壁漂然泪流因书四韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["碧澗去年會，與師三兩人。","今來見題壁，師已是前身。","芰葉迎僧夏，楊花度俗春。","空將數行淚，灑徧塔中塵。"]', '["碧澗去年會，與師三兩人。","今来见題壁，師已是前身。","芰葉迎僧夏，楊花度俗春。","空將數行泪，灑徧塔中塵。"]', '诗', 'shi', '', NULL, '公安縣遠安寺水亭見展公題壁漂然淚流因書四韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aecb2ee2-c4e2-400e-a841-b76053a48e11', '寒食日毛空路示姪晦及從簡', '寒食日毛空路示姪晦及從簡', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我昔孩提從我兄，我今衰白爾初成。","分明寄取原頭路，百世長須此路行。"]', '["我昔孩提從我兄，我今衰白爾初成。","分明寄取原头路，百世长須此路行。"]', '诗', 'shi', '', NULL, '寒食日毛空路示姪晦及從簡 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83ef62e6-6e12-4c94-abdd-ed38dc822865', '別孫村老人', '別孫村老人', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["年年漸覺老人稀，欲別孫翁淚滿衣。","未死不知何處去，此身終向此原歸。"]', '["年年漸覺老人稀，欲別孫翁泪满衣。","未死不知何处去，此身終向此原归。"]', '诗', 'shi', '', NULL, '別孫村老人 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fb05c83-4978-40d1-bb36-5ca1a0629256', '和樂天劉家花', '和乐天劉家花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["閑坊靜曲同消日，淚草傷花不爲春。","徧問舊交零落盡，十人纔有兩三人。"]', '["闲坊静曲同消日，泪草傷花不爲春。","徧问旧交零落尽，十人纔有兩三人。"]', '诗', 'shi', '', NULL, '和樂天劉家花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c60b89-0636-4b9b-bdaf-09c45824b38b', '褒城驛二首 一', '褒城驛二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["容州詩句在褒城，幾度經過眼暫明。","今日重看滿衫淚，可憐名字已前生。"]', '["容州诗句在褒城，幾度經過眼暫明。","今日重看满衫泪，可怜名字已前生。"]', '诗', 'shi', '', NULL, '褒城驛二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d3a16d-6c47-4795-afe0-60269a5c432e', '褒城驛二首 二', '褒城驛二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶昔萬株梨映竹，遇逢黃令醉殘春。","梨枯竹盡黃令死，今日再來衰病身。"]', '["憶昔万株梨映竹，遇逢黄令醉殘春。","梨枯竹尽黄令死，今日再来衰病身。"]', '诗', 'shi', '', NULL, '褒城驛二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bf2c95c-5bfa-4b1b-b178-f4bd1532a1f6', '和樂天夢亡友劉太白同遊二首 一', '和乐天梦亡友劉太白同游二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["君詩昨日到通州。","萬里知君一夢劉，閑坐思量小來事。","秪應元是夢中遊。"]', '["君诗昨日到通州。","万里知君一梦劉，闲坐思量小来事。","秪應元是梦中游。"]', '诗', 'shi', '', NULL, '和樂天夢亡友劉太白同遊二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4791faf7-6918-49aa-924c-1878951eb8be', '和樂天夢亡友劉太白同遊二首 二', '和乐天梦亡友劉太白同游二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["老來東郡復西州，行處生塵爲喪劉。","縱使劉君魂魄在，也應至死不同遊。"]', '["老来东郡复西州，行处生塵爲喪劉。","縱使劉君魂魄在，也應至死不同游。"]', '诗', 'shi', '', NULL, '和樂天夢亡友劉太白同遊二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc616470-cbb8-4276-b930-9567fa206e64', '酬樂天見憶兼傷仲遠', '酬乐天见憶兼傷仲远', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["死別重泉閟，生離萬里賒。","瘴侵新病骨，夢到故人家。","遙淚陳根草，閑收落地花。","庾公樓悵望，巴子國生涯。","河任天然曲，江隨峽勢斜。","與君皆直戇，須分老泥沙。"]', '["死別重泉閟，生離万里賒。","瘴侵新病骨，梦到故人家。","遙泪陳根草，闲收落地花。","庾公楼悵望，巴子国生涯。","河任天然曲，江隨峽勢斜。","與君皆直戇，須分老泥沙。"]', '诗', 'shi', '', NULL, '酬樂天見憶兼傷仲遠 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62628a33-df75-4e06-a6c6-f80faa92c977', '與樂天同葬杓直', '與乐天同葬杓直', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["元伯來相葬，山濤誓撫孤。","不知他日事，兼得似君無。"]', '["元伯来相葬，山濤誓撫孤。","不知他日事，兼得似君無。"]', '诗', 'shi', '', NULL, '與樂天同葬杓直 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('035adec3-38c3-4760-9464-6c2cb34f9f34', '夜閑', '夜闲', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["感極都無夢，魂銷轉易驚。","風簾半鉤落，秋月滿牀明。","悵望臨階坐，沈吟遶樹行。","孤琴在幽匣，時迸斷弦聲。"]', '["感極都無梦，魂銷轉易驚。","风簾半鉤落，秋月满牀明。","悵望臨階坐，沈吟遶樹行。","孤琴在幽匣，时迸斷弦声。"]', '诗', 'shi', '', NULL, '夜閑 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06432b35-8b0d-4e26-a239-4b326ecffbb0', '感小株夜合', '感小株夜合', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["纖幹未盈把，高條纔過眉。","不禁風苦動，偏受露先萎。","不分秋同盡，深嗟小便衰。","傷心落殘葉，猶識合昏期。"]', '["纖幹未盈把，高條纔過眉。","不禁风苦动，偏受露先萎。","不分秋同尽，深嗟小便衰。","傷心落殘葉，猶識合昏期。"]', '诗', 'shi', '', NULL, '感小株夜合 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b1c634b-15ac-4c6f-8d16-6ce955841f68', '醉醒', '醉醒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["積善坊中前度飲，謝家諸婢笑扶行。","今宵還似當時醉，半夜覺來聞哭聲。"]', '["積善坊中前度饮，謝家諸婢笑扶行。","今宵還似當时醉，半夜覺来闻哭声。"]', '诗', 'shi', '', NULL, '醉醒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dcd7968-f1c5-4f2e-a770-11f77a135df1', '追昔遊', '追昔游', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["謝傅堂前音樂和，狗兒吹笛膽娘歌。","花園欲盛千場飲，水閣初成百度過。","醉摘櫻桃投小玉，嬾梳叢鬢舞曹婆。","再來門館唯相弔，風落秋池紅葉多。"]', '["謝傅堂前音乐和，狗兒吹笛膽娘歌。","花园欲盛千場饮，水閣初成百度過。","醉摘櫻桃投小玉，嬾梳叢鬢舞曹婆。","再来门館唯相弔，风落秋池紅葉多。"]', '诗', 'shi', '', NULL, '追昔遊 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcc300ce-c53a-4a2a-9073-bdb619ee91f5', '空屋題', '空屋題', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["朝從空屋裏，騎馬入空臺。","盡日推閒事，還歸空屋來。","月明穿暗隙，燈燼落殘灰。","更想咸陽道，魂車昨夜回。"]', '["朝從空屋裏，騎马入空台。","尽日推閒事，還归空屋来。","月明穿暗隙，灯燼落殘灰。","更想咸陽道，魂车昨夜回。"]', '诗', 'shi', '', NULL, '空屋題 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3121ade4-3a76-4604-8160-2bd100756280', '初寒夜寄盧子蒙', '初寒夜寄盧子蒙', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["月是陰秋鏡，寒爲寂寞資。","輕寒酒醒後，斜月枕前時。","倚壁思閑事，回燈檢舊詩。","聞君亦同病，終夜遠相悲。"]', '["月是陰秋镜，寒爲寂寞資。","轻寒酒醒後，斜月枕前时。","倚壁思闲事，回灯檢旧诗。","闻君亦同病，終夜远相悲。"]', '诗', 'shi', '', NULL, '初寒夜寄盧子蒙 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c11f704-767c-4152-af8b-f3c10b1449d1', '城外回謝子蒙見諭', '城外回謝子蒙见諭', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["十里撫柩別，一身騎馬回。","寒煙半堂影，燼火滿庭灰。","稚女憑人問，病夫空自哀。","潘安寄新詠，仍是夜深來。"]', '["十里撫柩別，一身騎马回。","寒煙半堂影，燼火满庭灰。","稚女憑人问，病夫空自哀。","潘安寄新詠，仍是夜深来。"]', '诗', 'shi', '', NULL, '城外回謝子蒙見諭 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab8091c8-ab65-457e-a707-b1bbdfdd5db5', '諭子蒙', '諭子蒙', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["撫稚君休感，無兒我不傷。","片雲離岫遠，雙燕念巢忙。","大壑誰非水，華星各自光。","但令長有酒，何必謝家莊。"]', '["撫稚君休感，無兒我不傷。","片云離岫远，雙燕念巢忙。","大壑誰非水，华星各自光。","但令长有酒，何必謝家莊。"]', '诗', 'shi', '', NULL, '諭子蒙 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b57e03d-6d1f-4a4a-ba34-1f58e2551ca1', '遣悲懷三首 一', '遣悲懷三首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["謝公最小偏憐女，嫁與黔婁百事乖。","顧我無衣搜畫篋，泥他沽酒拔金釵。","野蔬充膳甘長藿，落葉添薪仰古槐。","今日俸錢過十萬，與君營奠復營齋。"]', '["謝公最小偏怜女，嫁與黔婁百事乖。","顧我無衣搜畫篋，泥他沽酒拔金釵。","野蔬充膳甘长藿，落葉添薪仰古槐。","今日俸錢過十万，與君營奠复營斋。"]', '诗', 'shi', '', NULL, '遣悲懷三首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea3f91f0-487e-4df7-826a-3692ef82e64d', '遣悲懷三首 二', '遣悲懷三首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔日戲言身後意，今朝皆到眼前來。","衣裳已施行看盡，針線猶存未忍開。","尚想舊情憐婢僕，也曾因夢送錢財。","誠知此恨人人有，貧賤夫妻百事哀。"]', '["昔日戲言身後意，今朝皆到眼前来。","衣裳已施行看尽，針線猶存未忍开。","尚想旧情怜婢僕，也曾因梦送錢財。","誠知此恨人人有，貧賤夫妻百事哀。"]', '诗', 'shi', '', NULL, '遣悲懷三首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f57261-b608-4ee9-8d88-7fde20c49a7a', '遣悲懷三首 三', '遣悲懷三首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["閑坐悲君亦自悲，百年都是幾多時。","鄧攸無子尋知命，潘岳悼亡猶費詞。","同穴窅冥何所望，他生緣會更難期。","唯將終夜長開眼，報荅平生未展眉。"]', '["闲坐悲君亦自悲，百年都是幾多时。","鄧攸無子尋知命，潘岳悼亡猶費词。","同穴窅冥何所望，他生緣會更难期。","唯將終夜长开眼，報荅平生未展眉。"]', '诗', 'shi', '', NULL, '遣悲懷三首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ab26f8-1756-4e66-bd67-de1c077e141c', '旅眠', '旅眠', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["內外都無隔，帷屏不復張。","夜眠兼客坐，同在火爐牀。"]', '["內外都無隔，帷屏不复張。","夜眠兼客坐，同在火爐牀。"]', '诗', 'shi', '', NULL, '旅眠 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832aa93e-e827-423c-870b-810d2395e847', '除夜', '除夜', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶昔歲除夜，見君花燭前。","今宵祝文上，重疊敘新年。","閑處低聲哭，空堂背月眠。","傷心小兒女，撩亂火堆邊。"]', '["憶昔歲除夜，见君花燭前。","今宵祝文上，重叠敘新年。","闲处低声哭，空堂背月眠。","傷心小兒女，撩亂火堆邊。"]', '诗', 'shi', '', NULL, '除夜 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658158db-7d51-4ec4-8cf5-0c28ae6ad4b5', '感夢', '感梦', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["行吟坐歎知何極，影絕魂銷動隔年。","今夜商山館中夢，分明同在後堂前。"]', '["行吟坐歎知何極，影絕魂銷动隔年。","今夜商山館中梦，分明同在後堂前。"]', '诗', 'shi', '', NULL, '感夢 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fd97a39-0da0-408b-ac9c-5ffd7e16e796', '合衣寢', '合衣寢', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["良夕背燈坐，方成合衣寢。","酒醉夜未闌，幾回顛倒枕。"]', '["良夕背灯坐，方成合衣寢。","酒醉夜未闌，幾回顛倒枕。"]', '诗', 'shi', '', NULL, '合衣寢 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('358a8bed-f849-414a-8de0-47844f396294', '竹簟', '竹簟', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["竹簟襯重茵，未忍都令卷。","憶昨初來日，看君自施展。"]', '["竹簟襯重茵，未忍都令卷。","憶昨初来日，看君自施展。"]', '诗', 'shi', '', NULL, '竹簟 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdcc3308-ee5d-40a6-a7ab-4c61f50c6add', '聽庾及之彈烏夜啼引', '听庾及之彈烏夜啼引', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["君彈烏夜啼，我傳樂府解古題。","良人在獄妻在閨，官家欲赦烏報妻。","烏前再拜淚如雨，烏作哀聲妻暗語。","後人寫出烏啼引，吳調哀弦聲楚楚。","四五年前作拾遺，諫書不密丞相知。","謫官詔下吏驅遣，身作囚拘妻在遠。","歸來相見淚如珠，唯說閑宵長拜烏。","君來到舍是烏力，粧點烏盤邀女巫。","今君爲我千萬彈，烏啼啄啄淚瀾瀾。","感君此曲有深意，昨日烏啼桐葉墜。","當時爲我賽烏人，死葬咸陽原上地。"]', '["君彈烏夜啼，我傳乐府解古題。","良人在獄妻在閨，官家欲赦烏報妻。","烏前再拜泪如雨，烏作哀声妻暗語。","後人寫出烏啼引，吳調哀弦声楚楚。","四五年前作拾遺，諫书不密丞相知。","謫官詔下吏驱遣，身作囚拘妻在远。","归来相见泪如珠，唯说闲宵长拜烏。","君来到舍是烏力，粧点烏盤邀女巫。","今君爲我千万彈，烏啼啄啄泪瀾瀾。","感君此曲有深意，昨日烏啼桐葉墜。","當时爲我賽烏人，死葬咸陽原上地。"]', '诗', 'shi', '', NULL, '聽庾及之彈烏夜啼引 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('578e682b-2c71-4949-bc64-daa901dc2549', '夢井', '梦井', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夢上高高原，原上有深井。","登高意枯渴，願見深泉冷。","裴回遶井顧，自照泉中影。","沈浮落井瓶，井上無懸綆。","念此瓶欲沈，荒忙爲求請。","遍入原上村，村空犬仍猛。","還來遶井哭，哭聲通復哽。","哽噎夢忽驚，覺來房舍靜。","燈焰碧朧朧，淚光疑冏冏。","鍾聲夜方半，坐臥心難整。","忽憶咸陽原，荒田萬餘頃。","土厚壙亦深，埋魂在深埂。","埂深安可越，魂通有時逞。","今宵泉下人，化作瓶相憬。","感此涕汍瀾，汍瀾涕霑領。","所傷覺夢間，便覺死生境。","豈無同穴期，生期諒綿永。","又恐前後魂，安能兩知省。","尋環意無極，坐見天將昞。","吟此夢井詩，春朝好光景。"]', '["梦上高高原，原上有深井。","登高意枯渴，願见深泉冷。","裴回遶井顧，自照泉中影。","沈浮落井瓶，井上無懸綆。","念此瓶欲沈，荒忙爲求請。","遍入原上村，村空犬仍猛。","還来遶井哭，哭声通复哽。","哽噎梦忽驚，覺来房舍静。","灯焰碧朧朧，泪光疑冏冏。","鍾声夜方半，坐臥心难整。","忽憶咸陽原，荒田万餘頃。","土厚壙亦深，埋魂在深埂。","埂深安可越，魂通有时逞。","今宵泉下人，化作瓶相憬。","感此涕汍瀾，汍瀾涕霑領。","所傷覺梦间，便覺死生境。","豈無同穴期，生期諒綿永。","又恐前後魂，安能兩知省。","尋环意無極，坐见天將昞。","吟此梦井诗，春朝好光景。"]', '诗', 'shi', '', NULL, '夢井 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2982b48c-527e-4f8a-adbc-4479085c2d93', '江陵三夢 一', '江陵三梦 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["平生每相夢，不省兩相知。","況乃幽明隔，夢魂徒爾爲。","情知夢無益，非夢見何期。","今夕亦何夕，夢君相見時。","依稀舊粧服，晻淡昔容儀。","不道間生死，但言將別離。","分張碎針線，襵疊故幈幃。","撫稚再三囑，淚珠千萬垂。","囑云唯此女，自歎總無兒。","尚念嬌且騃，未禁寒與飢。","君復不憘事，奉身猶脫遺。","況有官縛束，安能長顧私。","他人生間別，婢僕多謾欺。","君在或有託，出門當付誰。","言罷泣幽噎，我亦涕淋漓。","驚悲忽然寤，坐臥若狂癡。","月影半床黑，蟲聲幽草移。","心魂生次第，覺夢久自疑。","寂默深想像，淚下如流澌。","百年永已訣，一夢何太悲。","悲君所嬌女，棄置不我隨。","長安遠於日，山川雲間之。","縱我生羽翼，網羅生縶維。","今宵淚零落，半爲生別滋。","感君下泉魄，動我臨川思。","一水不可越，黃泉況無涯。","此懷何由極，此夢何由追。","坐見天欲曙，江風吟樹枝。"]', '["平生每相梦，不省兩相知。","況乃幽明隔，梦魂徒爾爲。","情知梦無益，非梦见何期。","今夕亦何夕，梦君相见时。","依稀旧粧服，晻淡昔容儀。","不道间生死，但言將別離。","分張碎針線，襵叠故幈幃。","撫稚再三囑，泪珠千万垂。","囑云唯此女，自歎總無兒。","尚念嬌且騃，未禁寒與飢。","君复不憘事，奉身猶脫遺。","況有官縛束，安能长顧私。","他人生间別，婢僕多謾欺。","君在或有託，出门當付誰。","言罷泣幽噎，我亦涕淋漓。","驚悲忽然寤，坐臥若狂癡。","月影半床黑，蟲声幽草移。","心魂生次第，覺梦久自疑。","寂默深想像，泪下如流澌。","百年永已訣，一梦何太悲。","悲君所嬌女，棄置不我隨。","长安远於日，山川云间之。","縱我生羽翼，網羅生縶維。","今宵泪零落，半爲生別滋。","感君下泉魄，动我臨川思。","一水不可越，黄泉況無涯。","此懷何由極，此梦何由追。","坐见天欲曙，江风吟樹枝。"]', '诗', 'shi', '', NULL, '江陵三夢 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2217c01b-cc6c-4c0a-afd1-61ba7ee33870', '江陵三夢 二', '江陵三梦 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["古原三丈穴，深葬一枝瓊。","崩剝山門壞，煙綿墳草生。","久依荒隴坐，却望遠村行。","驚覺滿床月，風波江上聲。"]', '["古原三丈穴，深葬一枝瓊。","崩剝山门壞，煙綿墳草生。","久依荒隴坐，却望远村行。","驚覺满床月，风波江上声。"]', '诗', 'shi', '', NULL, '江陵三夢 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d248f583-59ea-4085-8d07-ca902f456bcb', '江陵三夢 三', '江陵三梦 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["君骨久爲土，我心長似灰。","百年何處盡，三夜夢中來。","逝水良已矣，行雲安在哉？","坐看朝日出，衆鳥雙裴回。"]', '["君骨久爲土，我心长似灰。","百年何处尽，三夜梦中来。","逝水良已矣，行云安在哉？","坐看朝日出，衆鸟雙裴回。"]', '诗', 'shi', '', NULL, '江陵三夢 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5832c35-3c94-470f-9a79-3e11476c1248', '張舊蚊幬', '張旧蚊幬', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["踰年間生死，千里曠南北。","家居無見期，況乃異鄉國。","破盡裁縫衣，忘收遺翰墨。","獨有纈紗幬，憑人遠攜得。","施張合歡榻，展卷雙鴛翼。","已矣長空虛，依然舊顏色。","裴回將就寢，徙倚情何極。","昔透香田田，今無魂惻惻。","隙穿斜月照，燈背空床黑。","達理強開懷，夢啼還過臆。","平生貧寡歡，夭枉勞苦憶。","我亦距幾時，胡爲自摧逼。","燭蛾焰中舞，蠒蠶叢上織。","燋爛各自求，他人顧何力。","多離因苟合，惡影當務息。","往事勿復言，將來幸前識。"]', '["踰年间生死，千里曠南北。","家居無见期，況乃異乡国。","破尽裁縫衣，忘收遺翰墨。","独有纈紗幬，憑人远携得。","施張合歡榻，展卷雙鴛翼。","已矣长空虛，依然旧顏色。","裴回將就寢，徙倚情何極。","昔透香田田，今無魂惻惻。","隙穿斜月照，灯背空床黑。","達理強开懷，梦啼還過臆。","平生貧寡歡，夭枉勞苦憶。","我亦距幾时，胡爲自摧逼。","燭蛾焰中舞，蠒蠶叢上织。","燋爛各自求，他人顧何力。","多離因苟合，惡影當務息。","往事勿复言，將来幸前識。"]', '诗', 'shi', '', NULL, '張舊蚊幬 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ceccf70-4da6-4c11-90cb-fd49af6bec31', '獨夜傷懷贈呈張侍御', '独夜傷懷贈呈張侍御', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["燼火孤星滅，殘燈寸焰明。","竹風吹面冷，簷雪墜階聲。","寡鶴連天呌，寒雛徹夜驚。","秪應張侍御，潛會我心情。"]', '["燼火孤星滅，殘灯寸焰明。","竹风吹面冷，簷雪墜階声。","寡鹤連天呌，寒雛徹夜驚。","秪應張侍御，潛會我心情。"]', '诗', 'shi', '', NULL, '獨夜傷懷贈呈張侍御 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7d820dd-b106-4c8f-9eec-c04bbb8c4347', '六年春遣懷八首 一', '六年春遣懷八首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["傷禽我是籠中鶴，沈劒君爲泉下龍。","重纊猶存孤枕在，春衫無復舊裁縫。"]', '["傷禽我是籠中鹤，沈劒君爲泉下龙。","重纊猶存孤枕在，春衫無复旧裁縫。"]', '诗', 'shi', '', NULL, '六年春遣懷八首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6391003a-2248-48db-88a4-e7a6e2781eab', '六年春遣懷八首 二', '六年春遣懷八首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["檢得舊書三四紙，高低闊狹粗成行。","自言併食尋高事，唯念山深驛路長。"]', '["檢得旧书三四紙，高低闊狹粗成行。","自言併食尋高事，唯念山深驛路长。"]', '诗', 'shi', '', NULL, '六年春遣懷八首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72d2e362-2a47-4fb7-9fe2-54514118febb', '六年春遣懷八首 三', '六年春遣懷八首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["公無渡河音響絕，已隔前春復去秋。","今日閑窗拂塵土，殘弦猶迸鈿箜篌。"]', '["公無渡河音响絕，已隔前春复去秋。","今日闲窗拂塵土，殘弦猶迸鈿箜篌。"]', '诗', 'shi', '', NULL, '六年春遣懷八首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('257d4e4d-4a82-475d-a094-996ae3df5d4d', '六年春遣懷八首 四', '六年春遣懷八首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["婢僕曬君餘服用，嬌癡稚女遶床行。","玉梳鈿朵香膠解，盡日風吹玳瑁箏。"]', '["婢僕曬君餘服用，嬌癡稚女遶床行。","玉梳鈿朵香膠解，尽日风吹玳瑁箏。"]', '诗', 'shi', '', NULL, '六年春遣懷八首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9d0862-3c66-4ae5-a004-8fbb4a75d7f8', '六年春遣懷八首 五', '六年春遣懷八首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["伴客銷愁長日飲，偶然乘興便醺醺。","怪來醒後傍人泣，醉裏時時錯問君。"]', '["伴客銷愁长日饮，偶然乘兴便醺醺。","怪来醒後傍人泣，醉裏时时錯问君。"]', '诗', 'shi', '', NULL, '六年春遣懷八首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fa8a162-3426-446f-a7f7-3ca6a3ecb6c4', '六年春遣懷八首 六', '六年春遣懷八首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我隨楚澤波中梗，君作咸陽泉下泥。","百事無心值寒食，身將稚女帳前啼。"]', '["我隨楚澤波中梗，君作咸陽泉下泥。","百事無心值寒食，身將稚女帳前啼。"]', '诗', 'shi', '', NULL, '六年春遣懷八首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e77ad85-2bda-4d61-a72c-daa3fc5a1edc', '六年春遣懷八首 七', '六年春遣懷八首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["童稚癡狂撩亂走，繡毬花仗滿堂前。","病身一到繐帷下，還向臨階背日眠。"]', '["童稚癡狂撩亂走，繡毬花仗满堂前。","病身一到繐帷下，還向臨階背日眠。"]', '诗', 'shi', '', NULL, '六年春遣懷八首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ed476c3-dff5-4908-9590-a4f36b26e69e', '六年春遣懷八首 八', '六年春遣懷八首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["小於潘岳頭先白，學取莊周淚莫多。","止竟悲君須自省，川流前後各風波。"]', '["小於潘岳头先白，学取莊周泪莫多。","止竟悲君須自省，川流前後各风波。"]', '诗', 'shi', '', NULL, '六年春遣懷八首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e2e750e-0af2-46d9-b5a9-1ce7d03ace46', '荅友封見贈', '荅友封见贈', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["荀令香銷潘簟空，悼亡詩滿舊屏風。","扶床小女君先識，應爲些些似外翁。"]', '["荀令香銷潘簟空，悼亡诗满旧屏风。","扶床小女君先識，應爲些些似外翁。"]', '诗', 'shi', '', NULL, '荅友封見贈 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d449b13-aabf-46be-80a0-dd34a128f2a5', '夢成之', '梦成之', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["燭暗船風獨夢驚，夢君頻問向南行。","覺來不語到明坐，一夜洞庭湖水聲。"]', '["燭暗船风独梦驚，梦君頻问向南行。","覺来不語到明坐，一夜洞庭湖水声。"]', '诗', 'shi', '', NULL, '夢成之 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94428446-19f1-418f-8775-14e5409f6e0e', '哭小女降真', '哭小女降真', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雨點輕漚風復驚，偶來何事去何情。","浮生未到無生地，暫到人間又一生。"]', '["雨点轻漚风复驚，偶来何事去何情。","浮生未到無生地，暫到人间又一生。"]', '诗', 'shi', '', NULL, '哭小女降真 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5926ca12-e01f-4fc7-a484-554e39ba7a65', '哭女樊', '哭女樊', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["秋天淨綠月分明，何事巴猿不賸鳴。","應是一聲腸斷去，不容啼到第三聲。"]', '["秋天淨綠月分明，何事巴猿不賸鳴。","應是一声腸斷去，不容啼到第三声。"]', '诗', 'shi', '', NULL, '哭女樊 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b5624fc-d2df-4ead-ad76-3a91a6f3ebaa', '哭女樊四十韻', '哭女樊四十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["逝者何由見，中人未達情。","馬無生角望，猿有斷腸鳴。","去伴投遐徼，來隨夢險程。","四年巴養育，萬里硤回縈。","病是他鄉染，魂應遠處驚。","山魈邪亂逼，沙虱毒潛嬰。","母約看寧辨，余慵療不精。","欲尋方次第，俄值疾充盈。","燈火徒相守，香花秪浪擎。","蓮初開月梵，蕣已落朝榮。","魄散雲將盡，形全玉尚瑩。","空垂兩行血，深送一枝瓊。","祕祝休巫覡，安眠放使令。","舊衣和篋施，殘藥滿甌傾。","乳媼閑於社，醫僧婗似酲。","憫渠身覺賸，訝佛力難爭。","騎竹癡猶子，牽車小外甥。","等長迷過影，遙戲誤啼聲。","涴紙傷餘畫，扶床念試行。","獨留呵面鏡，誰弄倚牆箏。","憶昨工言語，憐初妙長成。","撩風妬鸚舌，凌露觸蘭英。","翠鳳輿真女，紅蕖捧化生。","秪憂嫌五濁，終恐向三清。","宿惡諸葷味，懸知衆物名。","環從枯樹得，經認寶函盛。","慍怒偏憎數，分張雅愛平。","最憐貪栗妹，頻救嬾書兄。","爲占嬌饒分，良多眷戀誠。","別常回面泣，歸定出門迎。","解怪還家晚，長將遠信呈。","說人偷罪過，要我抱縱橫。","騰蹋遊江舫，攀緣看樂棚。","和蠻歌字拗，學妓舞腰輕。","迢遰離荒服，提攜到近京。","未容誇伎倆，唯恨枉聰明。","往緒心千結，新絲鬢百莖。","暗窗風報曉，秋幌雨聞更。","敗槿蕭疎館，衰楊破壞城。","此中臨老淚，仍自哭孩嬰。"]', '["逝者何由见，中人未達情。","马無生角望，猿有斷腸鳴。","去伴投遐徼，来隨梦險程。","四年巴養育，万里硤回縈。","病是他乡染，魂應远处驚。","山魈邪亂逼，沙虱毒潛嬰。","母約看寧辨，余慵療不精。","欲尋方次第，俄值疾充盈。","灯火徒相守，香花秪浪擎。","蓮初开月梵，蕣已落朝榮。","魄散云將尽，形全玉尚瑩。","空垂兩行血，深送一枝瓊。","祕祝休巫覡，安眠放使令。","旧衣和篋施，殘藥满甌傾。","乳媼闲於社，醫僧婗似酲。","憫渠身覺賸，訝佛力难爭。","騎竹癡猶子，牽车小外甥。","等长迷過影，遙戲誤啼声。","涴紙傷餘畫，扶床念試行。","独留呵面镜，誰弄倚牆箏。","憶昨工言語，怜初妙长成。","撩风妬鸚舌，凌露觸蘭英。","翠鳳輿真女，紅蕖捧化生。","秪憂嫌五濁，終恐向三清。","宿惡諸葷味，懸知衆物名。","环從枯樹得，經認寶函盛。","慍怒偏憎數，分張雅愛平。","最怜貪栗妹，頻救嬾书兄。","爲占嬌饒分，良多眷戀誠。","別常回面泣，归定出门迎。","解怪還家晚，长將远信呈。","说人偷罪過，要我抱縱橫。","腾蹋游江舫，攀緣看乐棚。","和蠻歌字拗，学妓舞腰轻。","迢遰離荒服，提携到近京。","未容誇伎倆，唯恨枉聰明。","往緒心千結，新絲鬢百莖。","暗窗风報晓，秋幌雨闻更。","敗槿蕭疎館，衰楊破壞城。","此中臨老泪，仍自哭孩嬰。"]', '诗', 'shi', '', NULL, '哭女樊四十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f619c79-94aa-41a1-889a-cee7d82a5d3c', '哭子十首 一', '哭子十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["維鵜受刺因吾過，得馬生災念爾冤。","獨在中庭倚閑樹，亂蟬嘶噪欲黃昏。"]', '["維鵜受刺因吾過，得马生災念爾冤。","独在中庭倚闲樹，亂蟬嘶噪欲黄昏。"]', '诗', 'shi', '', NULL, '哭子十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31750525-f643-4697-98ad-827486571e82', '哭子十首 二', '哭子十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["纔能辨別東西位，未解分明管帶身。","自食自眠猶未得，九重泉路託何人。"]', '["纔能辨別东西位，未解分明管带身。","自食自眠猶未得，九重泉路託何人。"]', '诗', 'shi', '', NULL, '哭子十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b188da7e-b837-4794-a18b-b98c67062f6e', '哭子十首 三', '哭子十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["爾母溺情連夜哭，我身因事有時悲。","鍾聲欲絕東方動，便是尋常上學時。"]', '["爾母溺情連夜哭，我身因事有时悲。","鍾声欲絕东方动，便是尋常上学时。"]', '诗', 'shi', '', NULL, '哭子十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bfd871a-01ea-44d3-8e11-7d4c84398803', '哭子十首 四', '哭子十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蓮花上品生真界，兜率天中離世途。","彼此業緣多障礙，不知還得見兒無。"]', '["蓮花上品生真界，兜率天中離世途。","彼此業緣多障礙，不知還得见兒無。"]', '诗', 'shi', '', NULL, '哭子十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9c46414-a0d8-4da8-901d-d30dba0f63ac', '哭子十首 五', '哭子十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["節量棃栗愁生疾，教示詩書望早成。","鞭扑校多憐校少，又緣遺恨哭三聲。"]', '["節量棃栗愁生疾，教示诗书望早成。","鞭扑校多怜校少，又緣遺恨哭三声。"]', '诗', 'shi', '', NULL, '哭子十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb30a518-8a79-46f6-b9d1-3f1a2f318d32', '哭子十首 六', '哭子十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["深嗟爾更無兄弟，自歎予應絕子孫。","寂寞講堂基址在，何人車馬入高門。"]', '["深嗟爾更無兄弟，自歎予應絕子孫。","寂寞講堂基址在，何人车马入高门。"]', '诗', 'shi', '', NULL, '哭子十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b57ac5cd-1244-47f3-b0e6-4f26f7498c93', '哭子十首 七', '哭子十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["往年鬢已同潘岳，垂老年教作鄧攸。","煩惱數中除一事，自茲無復子孫憂。"]', '["往年鬢已同潘岳，垂老年教作鄧攸。","煩惱數中除一事，自茲無复子孫憂。"]', '诗', 'shi', '', NULL, '哭子十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9edfa7fc-e23e-48c1-84ed-fab50e202dd0', '哭子十首 八', '哭子十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["長年苦境知何限，豈得因兒獨喪明。","消遣又來緣爾母，夜深和淚有經聲。"]', '["长年苦境知何限，豈得因兒独喪明。","消遣又来緣爾母，夜深和泪有經声。"]', '诗', 'shi', '', NULL, '哭子十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04414b63-3fc3-4a2f-8440-9b08a320c768', '哭子十首 九', '哭子十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["烏生八子今無七，猿呌三聲月正孤。","寂寞空堂天欲曙，拂簾雙燕引新雛。"]', '["烏生八子今無七，猿呌三声月正孤。","寂寞空堂天欲曙，拂簾雙燕引新雛。"]', '诗', 'shi', '', NULL, '哭子十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0271325b-c2a6-48d5-bc32-0254b4789280', '哭子十首 十', '哭子十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["頻頻子落長江水，夜夜巢邊舊處棲。","若是愁腸終不斷，一年添得一聲啼。"]', '["頻頻子落长江水，夜夜巢邊旧处棲。","若是愁腸終不斷，一年添得一声啼。"]', '诗', 'shi', '', NULL, '哭子十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf8de4b-9cc2-45ce-95ea-8aa15434766a', '感逝', '感逝', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["頭白夫妻分無子，誰令蘭夢感衰翁。","三聲啼婦臥床上，一寸斷腸埋土中。","蜩甲暗枯秋葉墜，燕雛新去夜巢空。","情知此恨人皆有，應與暮年心不同。"]', '["头白夫妻分無子，誰令蘭梦感衰翁。","三声啼婦臥床上，一寸斷腸埋土中。","蜩甲暗枯秋葉墜，燕雛新去夜巢空。","情知此恨人皆有，應與暮年心不同。"]', '诗', 'shi', '', NULL, '感逝 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87897b1f-84f8-44e3-a590-d75f479afa53', '妻滿月日相唁', '妻满月日相唁', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["十月辛勤一月悲，今朝相見淚淋漓。","狂風落盡莫惆悵，猶勝因花壓折枝。"]', '["十月辛勤一月悲，今朝相见泪淋漓。","狂风落尽莫惆悵，猶勝因花壓折枝。"]', '诗', 'shi', '', NULL, '妻滿月日相唁 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('045b57ab-f8b0-4230-b0cd-18ae35d8c577', '代曲江老人百韻', '代曲江老人百韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何事花前泣，曾逢舊日春。","先皇初在鎬，賤子正遊秦。","撥亂干戈後，經文禮樂辰。","徽章懸象魏，貔虎畫騏驎。","光武休言戰，唐堯念睦姻。","琳瑯鋪柱礎，葛藟茂河漘。","尚齒惇耆艾，搜材拔積薪。","裴王持藻鏡，姚宋斡陶鈞。","內史稱張敞，蒼生借寇恂。","名卿唯講德，命士恥憂貧。","杞梓無遺用，蒭蕘不忘詢。","懸金收逸驥，鼓瑟薦嘉賓。","羽翼皆隨鳳，圭璋肯雜珉。","班行容濟濟，文質道彬彬。","百度依皇極，千門闢紫宸。","措刑非苟簡，稽古蹈因循。","書謬偏求伏，詩亡遠聽申。","雄推三虎賈，羣擢八龍荀。","海外恩方洽，寰中教不泯。","儒林精閫奧，流品重清淳。","天淨三光麗，時和四序均。","卑官休力役，蠲賦免艱辛。","蠻貊同車軌，鄉原盡里仁。","帝途高蕩蕩，風俗厚誾誾。","暇日耕耘足，豐年雨露頻。","戍煙生不見，村豎老猶純。","耒耜勤千畝，牲牢奉六禋。","南郊禮天地，東野闢原畇。","校獵求初吉，先農卜上寅。","萬方來合雜，五色瑞輪囷。","池籞呈朱鴈，壇場得白麟。","酹金光照耀，奠璧綵璘玢。","掉蕩雲門發，蹁躚鷺羽振。","集靈撞玉磬，和鼓奏金錞。","建簴崇牙盛，銜鐘獸目嗔。","總干形屹崪，戛敔背嶙峋。","文物千官會，夷音九部陳。","魚龍華外戲，歌舞洛中嬪。","佳節修酺禮，非時宴侍臣。","梨園明月夜，花萼豔陽晨。","李杜詩篇敵，蘇張筆力勻。","樂章輕鮑照，碑板笑顏竣。","泰嶽陪封禪，汾陰頌鬼神。","星移逐西顧，風暖助東巡。","浴德留湯谷，蒐畋過渭濱。","沸天雷殷殷，匝地轂轔轔。","沃土心逾熾，豪家禮漸湮。","老農羞荷鍤，貪賈學垂紳。","曲藝爭工巧，彫機變組紃。","青鳧連不解，紅粟朽相因。","山澤長孳貨，梯航競獻珍。","翠毛開越巂，龍眼弊甌閩。","玉饌薪然蠟，椒房燭用銀。","銅山供橫賜，金屋貯宜嚬。","班女恩移趙，思王賦感甄。","輝光隨顧步，生死屬搖脣。","世族功勳久，王姬寵愛親。","街衢連甲第，冠蓋擁朱輪。","大道垂珠箔，當壚踏錦茵。","軒車隘南陌，鐘磬滿西鄰。","出入張公子，驕奢石季倫。","雞場潛介羽，馬埒並揚塵。","韜袖誇狐腋，弓弦尚鹿𦟘。","紫絛牽白犬，繡䪜被花駰。","箭倒南山虎，鷹擒東郭㕙。","翻身迎過鴈，劈肘取廻鶉。","竟蓄朱公產，爭藏邴氏緡。","橋桃矜馬鶩，倚頓數牛犉。","齏鬬冬中韭，羹憐遠處蓴。","萬錢纔下筯，五酘未稱醇。","曲水閑銷日，倡樓醉度旬。","探丸依郭解，投轄伴陳遵。","共謂長之泰，那知遽搆屯。","姦心興桀黠，凶醜比頑嚚。","斗柄侵妖彗，天泉化逆鱗。","背恩欺乃祖，連禍及吾民。","䝟貐當前路，鯨鯢得要津。","王師纔業業，暴卒已䖜䖜。","雜虜同謀夏，宗周蹔去豳。","陵園深暮景，霜露下秋旻。","鳳闕悲巢鵩，鵷行亂野麏。","華林荒茂草，寒竹碎貞筠。","村落空垣壞，城隍舊井堙。","破船沉古渡，戰鬼聚陰燐。","振臂誰相應，攢眉獨不伸。","毀容懷赤紱，混跡戴黃巾。","木梗隨波蕩，桃源斅隱淪。","弟兄書信斷，鷗鷺往來馴。","忽遇山光澈，遙瞻海氣真。","祕圖推廢[主]，後聖合經綸。","野杏渾休植，幽蘭不復紉。","但驚心憤憤，誰戀水粼粼。","盡室離深洞，輕橈盪小䑳。","殷勤題白石，悵望出青蘋。","夢寐平生在，經過處所新。","阮郎迷里巷，遼鶴記城闉。","虛過休明代，旋爲朽病身。","勞生常矻矻，語舊苦諄諄。","晚歲多衰柳，先秋愧大椿。","眼前年少客，無復昔時人。"]', '["何事花前泣，曾逢旧日春。","先皇初在鎬，賤子正游秦。","撥亂干戈後，經文禮乐辰。","徽章懸象魏，貔虎畫騏驎。","光武休言戰，唐堯念睦姻。","琳瑯鋪柱礎，葛藟茂河漘。","尚齒惇耆艾，搜材拔積薪。","裴王持藻镜，姚宋斡陶鈞。","內史稱張敞，蒼生借寇恂。","名卿唯講德，命士恥憂貧。","杞梓無遺用，蒭蕘不忘詢。","懸金收逸驥，鼓瑟薦嘉賓。","羽翼皆隨鳳，圭璋肯杂珉。","班行容濟濟，文質道彬彬。","百度依皇極，千门闢紫宸。","措刑非苟簡，稽古蹈因循。","书謬偏求伏，诗亡远听申。","雄推三虎賈，羣擢八龙荀。","海外恩方洽，寰中教不泯。","儒林精閫奧，流品重清淳。","天淨三光丽，时和四序均。","卑官休力役，蠲賦免艱辛。","蠻貊同车軌，乡原尽里仁。","帝途高蕩蕩，风俗厚誾誾。","暇日耕耘足，豐年雨露頻。","戍煙生不见，村豎老猶純。","耒耜勤千畝，牲牢奉六禋。","南郊禮天地，东野闢原畇。","校獵求初吉，先農卜上寅。","万方来合杂，五色瑞輪囷。","池籞呈朱鴈，壇場得白麟。","酹金光照耀，奠璧綵璘玢。","掉蕩云门發，蹁躚鷺羽振。","集靈撞玉磬，和鼓奏金錞。","建簴崇牙盛，銜鐘獸目嗔。","總干形屹崪，戛敔背嶙峋。","文物千官會，夷音九部陳。","鱼龙华外戲，歌舞洛中嬪。","佳節修酺禮，非时宴侍臣。","梨园明月夜，花萼豔陽晨。","李杜诗篇敵，蘇張笔力勻。","乐章轻鲍照，碑板笑顏竣。","泰嶽陪封禪，汾陰頌鬼神。","星移逐西顧，风暖助东巡。","浴德留湯谷，蒐畋過渭濱。","沸天雷殷殷，匝地轂轔轔。","沃土心逾熾，豪家禮漸湮。","老農羞荷鍤，貪賈学垂紳。","曲藝爭工巧，彫機变組紃。","青鳧連不解，紅粟朽相因。","山澤长孳貨，梯航競獻珍。","翠毛开越巂，龙眼弊甌閩。","玉饌薪然蠟，椒房燭用銀。","銅山供橫賜，金屋貯宜嚬。","班女恩移趙，思王賦感甄。","輝光隨顧步，生死屬搖脣。","世族功勳久，王姬寵愛親。","街衢連甲第，冠蓋擁朱輪。","大道垂珠箔，當壚踏錦茵。","軒车隘南陌，鐘磬满西鄰。","出入張公子，驕奢石季倫。","雞場潛介羽，马埒並揚塵。","韜袖誇狐腋，弓弦尚鹿𦟘。","紫絛牽白犬，繡䪜被花駰。","箭倒南山虎，鷹擒东郭㕙。","翻身迎過鴈，劈肘取廻鶉。","竟蓄朱公產，爭藏邴氏緡。","橋桃矜马鶩，倚頓數牛犉。","齏鬬冬中韭，羹怜远处蓴。","万錢纔下筯，五酘未稱醇。","曲水闲銷日，倡楼醉度旬。","探丸依郭解，投轄伴陳遵。","共謂长之泰，那知遽搆屯。","姦心兴桀黠，凶醜比頑嚚。","斗柄侵妖彗，天泉化逆鱗。","背恩欺乃祖，連禍及吾民。","䝟貐當前路，鯨鯢得要津。","王師纔業業，暴卒已䖜䖜。","杂虜同謀夏，宗周蹔去豳。","陵园深暮景，霜露下秋旻。","鳳闕悲巢鵩，鵷行亂野麏。","华林荒茂草，寒竹碎貞筠。","村落空垣壞，城隍旧井堙。","破船沉古渡，戰鬼聚陰燐。","振臂誰相應，攢眉独不伸。","毀容懷赤紱，混跡戴黄巾。","木梗隨波蕩，桃源斅隐淪。","弟兄书信斷，鷗鷺往来馴。","忽遇山光澈，遙瞻海氣真。","祕圖推廢[主]，後聖合經綸。","野杏渾休植，幽蘭不复紉。","但驚心憤憤，誰戀水粼粼。","尽室離深洞，轻橈盪小䑳。","殷勤題白石，悵望出青蘋。","梦寐平生在，經過处所新。","阮郎迷里巷，遼鹤記城闉。","虛過休明代，旋爲朽病身。","勞生常矻矻，語旧苦諄諄。","晚歲多衰柳，先秋愧大椿。","眼前年少客，無复昔时人。"]', '诗', 'shi', '', NULL, '代曲江老人百韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b06b95c9-6fe7-4d85-bf88-b0a6751037cb', '開元觀閑居酬吳士矩侍御三十韻', '开元观闲居酬吳士矩侍御三十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["靜習狂心盡，幽居道氣添。","神編啓黃簡，祕籙捧朱籤。","爛熳煙霞駐，優游歲序淹。","登壇擁旄節，趨殿禮胡髯。","醮起彤庭燭，香開白玉匳。","結盟金劒重，斬魅寶刀銛。","禹步星綱動，焚符竈鬼詹。","冥搜呼直使，章奏役飛廉。","仙籍聊憑檢，浮名復爲占。","赤誠祈皓鶴，綠髮代青縑。","虛室常懷素，玄關屢引枮。","貂蟬徒自寵，鷗鷺不相嫌。","始悟身爲患，唯欣祿未恬。","龜龍戀淮海，雞犬傍閭閻。","松笠新偏翠，山峰遠更尖。","簫聲吟茂竹，虹影逗虛簷。","初日先通牖，輕颸每透簾。","露盤朝滴滴，鉤月夜纖纖。","已得餐霞味，應嗤食蓼甜。","工琴閑度晝，耽酒醉銷炎。","几案隨宜設，詩書逐便拈。","灌園多抱甕，刈藿乍腰鐮。","野鳥終難縶，鷦鷯本易厭。","風高雲遠逝，波駭鯉深潛。","邸第過從隔，蓬壺夢寐瞻。","所希顏頗練，誰恨突無黔。","思拙慙圭璧，詞煩雜米鹽。","諭錐言太小，求藥意何謙。","語默君休問，行藏我詎兼。","狂歌終此曲，情盡口長箝。"]', '["静習狂心尽，幽居道氣添。","神編啓黄簡，祕籙捧朱籤。","爛熳煙霞駐，優游歲序淹。","登壇擁旄節，趨殿禮胡髯。","醮起彤庭燭，香开白玉匳。","結盟金劒重，斬魅寶刀銛。","禹步星綱动，焚符竈鬼詹。","冥搜呼直使，章奏役飞廉。","仙籍聊憑檢，浮名复爲占。","赤誠祈皓鹤，綠髮代青縑。","虛室常懷素，玄关屢引枮。","貂蟬徒自寵，鷗鷺不相嫌。","始悟身爲患，唯欣祿未恬。","龟龙戀淮海，雞犬傍閭閻。","松笠新偏翠，山峰远更尖。","簫声吟茂竹，虹影逗虛簷。","初日先通牖，轻颸每透簾。","露盤朝滴滴，鉤月夜纖纖。","已得餐霞味，應嗤食蓼甜。","工琴闲度晝，耽酒醉銷炎。","几案隨宜設，诗书逐便拈。","灌园多抱甕，刈藿乍腰鐮。","野鸟終难縶，鷦鷯本易厭。","风高云远逝，波駭鯉深潛。","邸第過從隔，蓬壺梦寐瞻。","所希顏頗練，誰恨突無黔。","思拙慙圭璧，词煩杂米鹽。","諭錐言太小，求藥意何謙。","語默君休问，行藏我詎兼。","狂歌終此曲，情尽口长箝。"]', '诗', 'shi', '', NULL, '開元觀閑居酬吳士矩侍御三十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75abd818-1160-4e48-b49f-bbaf0627fd8f', '病減逢春期白二十二辛大不至十韻', '病減逢春期白二十二辛大不至十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["病與窮陰退，春從血氣生。","寒膚漸舒展，陽脈乍虛盈。","就日臨堦坐，扶牀履地行。","問人知面瘦，祝鳥願身輕。","風暖牽詩興，時新變賣聲。","飢饞看藥忌，閑悶點書名。","舊雪依深竹，微和動早萌。","推遷悲往事，疎數辨交情。","琴待嵇中散，杯思阮步兵。","世間除却病，何者不營營。"]', '["病與窮陰退，春從血氣生。","寒膚漸舒展，陽脈乍虛盈。","就日臨堦坐，扶牀履地行。","问人知面瘦，祝鸟願身轻。","风暖牽诗兴，时新变賣声。","飢饞看藥忌，闲悶点书名。","旧雪依深竹，微和动早萌。","推遷悲往事，疎數辨交情。","琴待嵇中散，杯思阮步兵。","世间除却病，何者不營營。"]', '诗', 'shi', '', NULL, '病減逢春期白二十二辛大不至十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfdc251a-0522-4ea7-acde-620e456a4a9e', '黃明府詩', '黄明府诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["少年曾痛飲，黃令苦飛觥。","席上當時走，馬前今日迎。","依稀迷姓氏，積漸識平生。","故友身皆遠，他鄉眼暫明。","便邀連榻坐，兼共榜船行。","酒思臨風亂，霜稜埽地平。","不堪深淺酌，貪愴古今情。","邐迤七盤路，坡陁數丈城。","花疑褒女笑，棧想武侯征。","一種埋幽石，老閑千載名。"]', '["少年曾痛饮，黄令苦飞觥。","席上當时走，马前今日迎。","依稀迷姓氏，積漸識平生。","故友身皆远，他乡眼暫明。","便邀連榻坐，兼共榜船行。","酒思臨风亂，霜稜埽地平。","不堪深淺酌，貪愴古今情。","邐迤七盤路，坡陁數丈城。","花疑褒女笑，棧想武侯征。","一種埋幽石，老闲千載名。"]', '诗', 'shi', '', NULL, '黃明府詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c586ff-dfa2-4c4e-88fe-4f017c9b52bb', '酬翰林白學士代書一百韻', '酬翰林白学士代书一百韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔歲俱充賦，同年遇有司。","八人稱迥拔，兩郡濫相知。","逸驥初翻步，鞲鷹暫脫羈。","遠途憂地窄，高視覺天卑。","並入紅蘭署，偏親白玉規。","近朱憐冉冉，伐木願偲偲。","魚魯非難識，鉛黃自嬾持。","心輕馬融帳，謀奪子房帷。","秀發幽巖電，清澄隘岸陂。","九霄排直上，萬里整前期。","勇贈棲鸞句，慙當古井詩。","多聞全受益，擇善頗相師。","脫俗殊常調，潛工大有爲。","還醇憑酎酒，運智託圍棊。","情會招車胤，閑行覓戴逵。","僧餐月燈閣，醵宴劫灰池。","勝概爭先到，篇章競出奇。","輸贏論破的，點竄肯容絲。","山岫當街翠，牆花拂面枝。","鶯聲愛嬌小，燕翼翫逶迤。","轡爲逢車緩，鞭緣趂伴施。","密攜長上樂，偷宿靜坊姬。","僻性慵朝起，新晴助晚嬉。","相歡常滿目，別處鮮開眉。","翰墨題名盡，光陰聽話移。","綠袍因醉典，烏帽逆風遺。","暗插輕籌箸，仍提小屈巵。","本絃纔一舉，下口已三遲。","逃席衝門出，歸倡借馬騎。","狂歌繁節亂，醉舞半衫垂。","散漫紛長薄，邀遮守隘岐。","幾遭朝士笑，兼任巷童隨。","苟務形骸達，渾將性命[推]。","何曾愛官序，不省計家資。","忽悟成虛擲，翻然歎未宜。","使回躭樂事，堅赴策賢時。","寢食都忘倦，園廬遂絕闚。","勞神甘慼慼，攻短過孜孜。","葉怯穿楊箭，囊藏透頴錐。","超遙望雲雨，擺落占泉坻。","略削荒涼苑，搜求激直詞。","那能作牛後，更擬助洪基。","唱第聽雞集，趨朝忘馬疲。","內人輿御案，朝景麗神旗。","首被呼名姓，多慙冠等衰。","千官容眷盼，五色照離披。","鵷侶從茲洽，鷗情轉自縻。","分張殊品命，中外却驅馳。","出入稱金籍，東西侍碧墀。","鬬班雲洶湧，開扇雉參差。","切愧尋常質，親瞻咫尺姿。","日輪光照耀，龍服瑞葳蕤。","誓欲通愚謇，生憎效喔咿。","佞存真妾婦，諫死是男兒。","便殿承偏召，權臣懼撓私。","廟堂雖稷契，城社有狐貍。","似錦言應巧，如弦數易欺。","敢嗟身暫黜，所恨政無毗。","謬辱良由此，昇騰亦在斯。","再令陪憲禁，依舊履阽危。","使蜀常緜遠，分臺更嶮巇。","匿姦勞發掘，破黨惡持疑。","斧刃迎皆碎，盤牙老未萎。","乍能還帝笏，詎忍折吾支。","虎尾元來險，圭文却類疵。","浮榮齊壤芥，閑氣詠江蘺。","闕下殷勤拜，樽前嘯傲辭。","飄沈委蓬梗，忠信敵蠻夷。","戲誚青雲驛，譏題皓髮祠。","貪過谷隱寺，留讀峴山碑。","草沒章臺阯，隄橫楚澤湄。","野蓮侵稻隴，亞柳壓城陴。","遇物傷凋換，登樓思漫瀰。","金攢嫩橙子，瑿泛遠鸕鶿。","仰竹藤纏屋，苫茆荻補籬。","麪梨通蔕朽，火米帶芒炊。","葦筍鍼筒束，鯾魚箭羽鬐。","芋羹真底可，鱸鱠漫勞思。","北渚銷魂望，南風著骨吹。","度梅衣色漬，食稗馬蹄羸。","院榷和泥鹼，官酤小麴醨。","訛音煩繳繞，輕俗醜威儀。","樹罕貞心柏，畦豐衛足葵。","坳窪饒尰矮，游惰壓庸緇。","病賽烏稱鬼，巫占瓦代龜。","連陰蛙張王，瘴瘧雪治醫。","我正窮於是，君寧念及茲。","一篇從日下，雙鯉送天涯。","坐捧迷前席，行吟忘結綦。","匡床鋪錯繡，几案踴靈芝。","形影同初合，參商喻此離。","扇因秋棄置，鏡異月盈虧。","壯志誠難奪，良辰豈復追。","甯牛終夜永，潘鬢去年衰。","溟渤深那測，穹蒼意在誰。","馭方輕騕褭，車肯重辛夷。","臥轍希濡沫，低顏受頷頤。","世情焉足怪，自省固堪悲。","溷鼠虛求潔，籠禽方訝飢。","猶勝憶黃犬，幸得早圖之。"]', '["昔歲俱充賦，同年遇有司。","八人稱迥拔，兩郡濫相知。","逸驥初翻步，鞲鷹暫脫羈。","远途憂地窄，高視覺天卑。","並入紅蘭署，偏親白玉規。","近朱怜冉冉，伐木願偲偲。","鱼魯非难識，鉛黄自嬾持。","心轻马融帳，謀奪子房帷。","秀發幽巖電，清澄隘岸陂。","九霄排直上，万里整前期。","勇贈棲鸾句，慙當古井诗。","多闻全受益，擇善頗相師。","脫俗殊常調，潛工大有爲。","還醇憑酎酒，運智託圍棊。","情會招车胤，闲行覓戴逵。","僧餐月灯閣，醵宴劫灰池。","勝概爭先到，篇章競出奇。","輸贏論破的，点竄肯容絲。","山岫當街翠，牆花拂面枝。","鶯声愛嬌小，燕翼翫逶迤。","轡爲逢车緩，鞭緣趂伴施。","密携长上乐，偷宿静坊姬。","僻性慵朝起，新晴助晚嬉。","相歡常满目，別处鲜开眉。","翰墨題名尽，光陰听話移。","綠袍因醉典，烏帽逆风遺。","暗插轻籌箸，仍提小屈巵。","本絃纔一舉，下口已三遲。","逃席衝门出，归倡借马騎。","狂歌繁節亂，醉舞半衫垂。","散漫紛长薄，邀遮守隘岐。","幾遭朝士笑，兼任巷童隨。","苟務形骸達，渾將性命[推]。","何曾愛官序，不省計家資。","忽悟成虛擲，翻然歎未宜。","使回躭乐事，堅赴策賢时。","寢食都忘倦，园廬遂絕闚。","勞神甘慼慼，攻短過孜孜。","葉怯穿楊箭，囊藏透頴錐。","超遙望云雨，擺落占泉坻。","略削荒涼苑，搜求激直词。","那能作牛後，更擬助洪基。","唱第听雞集，趨朝忘马疲。","內人輿御案，朝景丽神旗。","首被呼名姓，多慙冠等衰。","千官容眷盼，五色照離披。","鵷侶從茲洽，鷗情轉自縻。","分張殊品命，中外却驱驰。","出入稱金籍，东西侍碧墀。","鬬班云洶湧，开扇雉參差。","切愧尋常質，親瞻咫尺姿。","日輪光照耀，龙服瑞葳蕤。","誓欲通愚謇，生憎效喔咿。","佞存真妾婦，諫死是男兒。","便殿承偏召，權臣懼撓私。","廟堂雖稷契，城社有狐貍。","似錦言應巧，如弦數易欺。","敢嗟身暫黜，所恨政無毗。","謬辱良由此，昇腾亦在斯。","再令陪憲禁，依旧履阽危。","使蜀常緜远，分台更嶮巇。","匿姦勞發掘，破黨惡持疑。","斧刃迎皆碎，盤牙老未萎。","乍能還帝笏，詎忍折吾支。","虎尾元来險，圭文却類疵。","浮榮齊壤芥，闲氣詠江蘺。","闕下殷勤拜，樽前嘯傲辞。","飄沈委蓬梗，忠信敵蠻夷。","戲誚青云驛，譏題皓髮祠。","貪過谷隐寺，留读峴山碑。","草沒章台阯，隄橫楚澤湄。","野蓮侵稻隴，亞柳壓城陴。","遇物傷凋換，登楼思漫瀰。","金攢嫩橙子，瑿泛远鸕鶿。","仰竹藤纏屋，苫茆荻補籬。","麪梨通蔕朽，火米带芒炊。","葦筍鍼筒束，鯾鱼箭羽鬐。","芋羹真底可，鱸鱠漫勞思。","北渚銷魂望，南风著骨吹。","度梅衣色漬，食稗马蹄羸。","院榷和泥鹼，官酤小麴醨。","訛音煩繳繞，轻俗醜威儀。","樹罕貞心柏，畦豐衛足葵。","坳窪饒尰矮，游惰壓庸緇。","病賽烏稱鬼，巫占瓦代龟。","連陰蛙張王，瘴瘧雪治醫。","我正窮於是，君寧念及茲。","一篇從日下，雙鯉送天涯。","坐捧迷前席，行吟忘結綦。","匡床鋪錯繡，几案踴靈芝。","形影同初合，參商喻此離。","扇因秋棄置，镜異月盈虧。","壯志誠难奪，良辰豈复追。","甯牛終夜永，潘鬢去年衰。","溟渤深那測，穹蒼意在誰。","馭方轻騕褭，车肯重辛夷。","臥轍希濡沫，低顏受頷頤。","世情焉足怪，自省固堪悲。","溷鼠虛求潔，籠禽方訝飢。","猶勝憶黄犬，幸得早圖之。"]', '诗', 'shi', '', NULL, '酬翰林白學士代書一百韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a797ae-9623-412f-8b66-4d18a7e5be7f', '紀懷贈李六戶曹崔二十功曹五十韻', '紀懷贈李六戶曹崔二十功曹五十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔冠諸生首，初因三道徵。","公卿碧墀會，名姓白麻稱。","日月光遙射，煙霄志漸弘。","榮班聯錦繡，諫紙賜牋藤。","便欲呈肝膽，何言犯股肱。","椎埋衝斗劒，消碎瑩壺冰。","赤縣纔分務，青驄已迥乘。","因騎度海鶻，擬殺蔽天鵬。","縛虎聲空壯，連鼇力未勝。","風翻波竟蹙，山壓勢逾崩。","僇辱徒相困，蒼黃性不能。","酣歌離峴頂，負氣入江陵。","華表當蟾魄，高樓挂玉繩。","角聲悲掉蕩，城影暗稜層。","軍幕威容盛，官曹禮數兢。","心雖出雲鶴，身尚觸籠鷹。","竦足良甘分，排衙苦未曾。","通名參將校，抵掌見親朋。","喣沫求涓滴，滄波怯斗升。","荒居鄰鬼魅，羸馬步殑㱥。","白草堂簷短，黃梅雨氣蒸。","霑黏經汗席，颭閃盡油燈。","夜怯餐膚蚋，朝煩拂面蠅。","過從愁厭賤，專靜畏猜仍。","旅寓誰堪託，官聯自可憑。","甲科崔並騖，柱史李齊昇。","共展排空翼，俱遭激遠矰。","他鄉元易感，同病轉相矜。","投分多然諾，忘言少愛憎。","誓將探胏腑，恥更辨淄澠。","會宿形骸遠，論交意氣增。","一心吞渤澥，戮力拔嵩恆。","語到磨圭角，疑消破弩癥。","吹噓期指掌，患難許檐簦。","鎩翮鸞棲棘，藏鋒箭在弸。","雪中方覩桂，木上莫施罾。","且泛夤沿水，兼過被病僧。","有時鞭欵段，盡日醉儚僜。","躡屐看秧稻，敲船和採菱。","叉魚江火合，喚客谷神應。","嘯傲雖開口，幽憂復滿膺。","望雲鰭撥剌，透匣色騰凌。","每想潢池寇，猶稽赤族懲。","夔龍勞算畫，貔虎帶威稜。","逐鳥忠潛奮，懸旌意遠凝。","弢弓思徹札，絆驥悶牽緪。","運甓調辛苦，聞雞屢寢興。","閑隨人兀兀，夢聽鼓鼟鼟。","班筆行看擲，黃陂莫漫澄。","騏驎高閣上，須及壯時登。"]', '["昔冠諸生首，初因三道徵。","公卿碧墀會，名姓白麻稱。","日月光遙射，煙霄志漸弘。","榮班聯錦繡，諫紙賜牋藤。","便欲呈肝膽，何言犯股肱。","椎埋衝斗劒，消碎瑩壺冰。","赤縣纔分務，青驄已迥乘。","因騎度海鶻，擬殺蔽天鵬。","縛虎声空壯，連鼇力未勝。","风翻波竟蹙，山壓勢逾崩。","僇辱徒相困，蒼黄性不能。","酣歌離峴頂，負氣入江陵。","华表當蟾魄，高楼挂玉繩。","角声悲掉蕩，城影暗稜層。","軍幕威容盛，官曹禮數兢。","心雖出云鹤，身尚觸籠鷹。","竦足良甘分，排衙苦未曾。","通名參將校，抵掌见親朋。","喣沫求涓滴，滄波怯斗升。","荒居鄰鬼魅，羸马步殑㱥。","白草堂簷短，黄梅雨氣蒸。","霑黏經汗席，颭閃尽油灯。","夜怯餐膚蚋，朝煩拂面蠅。","過從愁厭賤，專静畏猜仍。","旅寓誰堪託，官聯自可憑。","甲科崔並騖，柱史李齊昇。","共展排空翼，俱遭激远矰。","他乡元易感，同病轉相矜。","投分多然諾，忘言少愛憎。","誓將探胏腑，恥更辨淄澠。","會宿形骸远，論交意氣增。","一心吞渤澥，戮力拔嵩恆。","語到磨圭角，疑消破弩癥。","吹噓期指掌，患难許檐簦。","鎩翮鸾棲棘，藏鋒箭在弸。","雪中方覩桂，木上莫施罾。","且泛夤沿水，兼過被病僧。","有时鞭欵段，尽日醉儚僜。","躡屐看秧稻，敲船和採菱。","叉鱼江火合，喚客谷神應。","嘯傲雖开口，幽憂复满膺。","望云鰭撥剌，透匣色腾凌。","每想潢池寇，猶稽赤族懲。","夔龙勞算畫，貔虎带威稜。","逐鸟忠潛奮，懸旌意远凝。","弢弓思徹札，絆驥悶牽緪。","運甓調辛苦，闻雞屢寢兴。","闲隨人兀兀，梦听鼓鼟鼟。","班笔行看擲，黄陂莫漫澄。","騏驎高閣上，須及壯时登。"]', '诗', 'shi', '', NULL, '紀懷贈李六戶曹崔二十功曹五十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81c1e7b-dec6-413c-a12f-0e1cac054b72', '答姨兄胡靈之見寄五十韻', '答姨兄胡靈之见寄五十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶昔鳳翔城，齠年是事榮。","理家煩伯舅，相宅盡吾兄。","詩律蒙親授，朋遊忝自迎。","題頭筠管縵，教射角弓騂。","矮馬駞鬉䪜，犛牛獸面纓。","對談依赳赳，送客步盈盈。","米椀諸賢讓，蠡杯大戶傾。","一船席外語，三榼拍心精。","傳盞加分數，橫波擲目成。","華奴歌淅淅，媚子舞卿卿。","鬬設狂爲好，誰憂飲敗名。","屠過隱朱亥，樓夢古秦嬴。","環坐唯便草，投盤暫廢觥。","春郊纔爛熳，夕鼓已砰轟。","荏苒移灰琯，喧闐勌塞兵。","糟漿聞漸足，書劒訝無成。","抵璧慙虛棄，彈珠覺用輕。","遂籠雲際鶴，來狎谷中鶯。","學問攻方苦，篇章興太清。","囊疎螢易透，錐鈍股多坑。","筆陣戈矛合，文房棟桷撐。","豆萁才敏儁，羽獵正崢嶸。","岐下尋時別，京師觸處行。","醉眠街北廟，閑繞宅南營。","柳愛凌寒軟，梅憐上番驚。","觀松青黛笠，欄藥紫霞英。","盡日聽僧講，通宵詠月明。","正耽幽趣樂，旋被宦途縈。","吏晉資材枉，留秦歲序更。","我髯黳數寸，君髮白千莖。","芸閣懷鉛暇，姑峰帶雪晴。","何由身倚玉，空覩翰飛瓊。","世道難於劒，讒言巧似笙。","但憎心可轉，不解跽如擎。","始效神羊觸，俄隨旅鴈征。","孤芳安可駐，五鼎幾時烹。","潦倒沉泥滓，欹危踐矯衡。","登樓王粲望，落帽孟嘉情。","巫峽連天水，章臺塞路荆。","雨摧漁火燄，風引竹枝聲。","分作屯之蹇，那知困亦亨。","官曹三語掾，國器萬尋楨。","逸傑雄姿迥，皇王雅論評。","蕙依潛可習，雲合定誰令。","原燎逢冰井，鴻流值木罌。","智囊推有在，勇爵敢徒爭。","迅拔看鵬舉，高音侍鶴鳴。","所期人拭目，焉肯自佯盲。","鉛鈍丁寧淬，蕪荒展轉耕。","窮通須豹變，攖搏笑狼獰。","愧捧芝蘭贈，還披胏腑呈。","此生如未死，未擬變平生。"]', '["憶昔鳳翔城，齠年是事榮。","理家煩伯舅，相宅尽吾兄。","诗律蒙親授，朋游忝自迎。","題头筠管縵，教射角弓騂。","矮马駞鬉䪜，犛牛獸面纓。","对談依赳赳，送客步盈盈。","米椀諸賢讓，蠡杯大戶傾。","一船席外語，三榼拍心精。","傳盞加分數，橫波擲目成。","华奴歌淅淅，媚子舞卿卿。","鬬設狂爲好，誰憂饮敗名。","屠過隐朱亥，楼梦古秦嬴。","环坐唯便草，投盤暫廢觥。","春郊纔爛熳，夕鼓已砰轟。","荏苒移灰琯，喧闐勌塞兵。","糟漿闻漸足，书劒訝無成。","抵璧慙虛棄，彈珠覺用轻。","遂籠云際鹤，来狎谷中鶯。","学问攻方苦，篇章兴太清。","囊疎螢易透，錐鈍股多坑。","笔陣戈矛合，文房棟桷撐。","豆萁才敏儁，羽獵正崢嶸。","岐下尋时別，京師觸处行。","醉眠街北廟，闲繞宅南營。","柳愛凌寒軟，梅怜上番驚。","观松青黛笠，欄藥紫霞英。","尽日听僧講，通宵詠月明。","正耽幽趣乐，旋被宦途縈。","吏晉資材枉，留秦歲序更。","我髯黳數寸，君髮白千莖。","芸閣懷鉛暇，姑峰带雪晴。","何由身倚玉，空覩翰飞瓊。","世道难於劒，讒言巧似笙。","但憎心可轉，不解跽如擎。","始效神羊觸，俄隨旅鴈征。","孤芳安可駐，五鼎幾时烹。","潦倒沉泥滓，欹危踐矯衡。","登楼王粲望，落帽孟嘉情。","巫峽連天水，章台塞路荆。","雨摧漁火燄，风引竹枝声。","分作屯之蹇，那知困亦亨。","官曹三語掾，国器万尋楨。","逸傑雄姿迥，皇王雅論評。","蕙依潛可習，云合定誰令。","原燎逢冰井，鴻流值木罌。","智囊推有在，勇爵敢徒爭。","迅拔看鵬舉，高音侍鹤鳴。","所期人拭目，焉肯自佯盲。","鉛鈍丁寧淬，蕪荒展轉耕。","窮通須豹变，攖搏笑狼獰。","愧捧芝蘭贈，還披胏腑呈。","此生如未死，未擬变平生。"]', '诗', 'shi', '', NULL, '答姨兄胡靈之見寄五十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf031530-a0f2-489c-908b-74ca603d96e8', '酬許五康佐', '酬許五康佐', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["奮迅君何晚，羈離我詎儔。","鶴籠閑警露，鷹縛悶牽韝。","蓬閣深沈省，荆門遠慢州。","課書同吏職，旅宦各鄉愁。","白日傷心過，滄江滿眼流。","嘶風悲代馬，喘月伴吳牛。","枯涸方窮轍，生涯不繫舟。","猿啼三峽雨，蟬報兩京秋。","珠玉慙新贈，芝蘭忝舊游。","他年問狂客，須向老農求。"]', '["奮迅君何晚，羈離我詎儔。","鹤籠闲警露，鷹縛悶牽韝。","蓬閣深沈省，荆门远慢州。","課书同吏職，旅宦各乡愁。","白日傷心過，滄江满眼流。","嘶风悲代马，喘月伴吳牛。","枯涸方窮轍，生涯不繫舟。","猿啼三峽雨，蟬報兩京秋。","珠玉慙新贈，芝蘭忝旧游。","他年问狂客，須向老農求。"]', '诗', 'shi', '', NULL, '酬許五康佐 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d8ddb6a-0a57-4b7b-93ad-96a081b6295f', '送崔侍御之嶺南二十韻', '送崔侍御之嶺南二十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["漢法戎施幕，秦官郡置監。","蕭何歸舊印，鮑永授新銜。","幣聘雖盈篋，泥章未破緘。","蛛懸絲繚繞，鵲報語詀諵。","再礪神羊角，重開憲簡函。","鞶纓驄赳赳，緌珮繡縿縿。","逸翮憐鴻翥，離心覺刃劖。","聯游虧片玉，洞照失明鑒。","遙想車登嶺，那無淚滿衫。","茅蒸連蟒氣，衣漬度梅黬。","象鬬緣谿竹，猿鳴帶雨杉。","颶風狂浩浩，韶石峻嶄嶄。","宿浦宜深泊，祈瀧在至諴。","瘴江乘早度，毒草莫親芟。","試蠱看銀黑，排腥貴食鹹。","菌須蟲已蠹，菓重鳥先鵮。","冰瑩懷貪水，霜清顧痛巖。","珠璣當盡擲，薏苡詎能讒。","荆俗欺王粲，吾生問季咸。","遠書多不達，勤爲枉攕攕。"]', '["漢法戎施幕，秦官郡置監。","蕭何归旧印，鲍永授新銜。","幣聘雖盈篋，泥章未破緘。","蛛懸絲繚繞，鵲報語詀諵。","再礪神羊角，重开憲簡函。","鞶纓驄赳赳，緌珮繡縿縿。","逸翮怜鴻翥，離心覺刃劖。","聯游虧片玉，洞照失明鑒。","遙想车登嶺，那無泪满衫。","茅蒸連蟒氣，衣漬度梅黬。","象鬬緣谿竹，猿鳴带雨杉。","颶风狂浩浩，韶石峻嶄嶄。","宿浦宜深泊，祈瀧在至諴。","瘴江乘早度，毒草莫親芟。","試蠱看銀黑，排腥貴食鹹。","菌須蟲已蠹，菓重鸟先鵮。","冰瑩懷貪水，霜清顧痛巖。","珠璣當尽擲，薏苡詎能讒。","荆俗欺王粲，吾生问季咸。","远书多不達，勤爲枉攕攕。"]', '诗', 'shi', '', NULL, '送崔侍御之嶺南二十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9253a6d3-3d63-4a08-917f-497aadb0333d', '酬段丞與諸棊流會宿弊居見贈二十四韻', '酬段丞與諸棊流會宿弊居见贈二十四韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鳴局寧虛日，閑窗任廢時。","琴書甘盡棄，園井詎能窺。","運石疑填海，爭籌憶坐帷。","赤心方苦鬬，紅燭已先施。","蛇勢縈山合，鴻聯度嶺遲。","堂堂排直陣，袞袞逼羸師。","懸劫偏深猛，回征特險巇。","旁攻百道進，死戰萬般爲。","異日玄黃隊，今宵黑白棊。","斫營看迥點，對壘重相持。","善敗雖稱怯，驕盈最易欺。","狼牙當必碎，虎口禍難移。","乘勝同三捷，扶顛望一詞。","希因送目便，敢恃指縱奇。","退引防邊策，雄吟斬將詩。","眠牀都浪置，通夕共忘疲。","曉雉風傳角，寒藂雪壓枝。","繁星收玉版，殘月耀冰池。","僧請聞鐘粥，賓催下藥巵。","獸炎餘炭在，蠟淚短光衰。","俛仰嗟陳跡，殷勤卜後期。","公私牽去住，車馬各支離。","分作終身癖，兼從是事隳。","此中無限興，唯怕俗人知。"]', '["鳴局寧虛日，闲窗任廢时。","琴书甘尽棄，园井詎能窺。","運石疑填海，爭籌憶坐帷。","赤心方苦鬬，紅燭已先施。","蛇勢縈山合，鴻聯度嶺遲。","堂堂排直陣，袞袞逼羸師。","懸劫偏深猛，回征特險巇。","旁攻百道進，死戰万般爲。","異日玄黄隊，今宵黑白棊。","斫營看迥点，对壘重相持。","善敗雖稱怯，驕盈最易欺。","狼牙當必碎，虎口禍难移。","乘勝同三捷，扶顛望一词。","希因送目便，敢恃指縱奇。","退引防邊策，雄吟斬將诗。","眠牀都浪置，通夕共忘疲。","晓雉风傳角，寒藂雪壓枝。","繁星收玉版，殘月耀冰池。","僧請闻鐘粥，賓催下藥巵。","獸炎餘炭在，蠟泪短光衰。","俛仰嗟陳跡，殷勤卜後期。","公私牽去住，车马各支離。","分作終身癖，兼從是事隳。","此中無限兴，唯怕俗人知。"]', '诗', 'shi', '', NULL, '酬段丞與諸棊流會宿弊居見贈二十四韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5d59d9d-e52a-4c05-b850-47fb66b39263', '酬竇校書二十韻', '酬竇校书二十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鷗鷺元相得，杯觴每共傳。","芳遊春爛熳，晴望月團圓。","調笑風流劇，論文屬對全。","賞花珠並綴，看雪璧常連。","竹寺荒唯好，松齋小更憐。","潛投孟公轄，狂乞莫愁錢。","塵土拋書卷，槍籌弄酒權。","令誇齊箭道，力鬬抹弓弦。","但喜添樽滿，誰憂乏桂然。","漸輕身外役，渾證飲中禪。","及我辭雲陛，逢君仕圃田。","音徽千里斷，魂夢兩情偏。","足聽猿啼雨，深藏馬腹鞭。","官醪半清濁，夷饌雜腥膻。","顧影無依倚，甘心守靜專。","那知暮江上，俱會落英前。","欵曲生平在，悲涼歲序遷。","鶴方同北渚，鴻又過南天。","麗句慙虛擲，沈機嬾強牽。","粗酬珍重意，工拙定相懸。"]', '["鷗鷺元相得，杯觴每共傳。","芳游春爛熳，晴望月團圓。","調笑风流劇，論文屬对全。","賞花珠並綴，看雪璧常連。","竹寺荒唯好，松斋小更怜。","潛投孟公轄，狂乞莫愁錢。","塵土拋书卷，槍籌弄酒權。","令誇齊箭道，力鬬抹弓弦。","但喜添樽满，誰憂乏桂然。","漸轻身外役，渾證饮中禪。","及我辞云陛，逢君仕圃田。","音徽千里斷，魂梦兩情偏。","足听猿啼雨，深藏马腹鞭。","官醪半清濁，夷饌杂腥膻。","顧影無依倚，甘心守静專。","那知暮江上，俱會落英前。","欵曲生平在，悲涼歲序遷。","鹤方同北渚，鴻又過南天。","丽句慙虛擲，沈機嬾強牽。","粗酬珍重意，工拙定相懸。"]', '诗', 'shi', '', NULL, '酬竇校書二十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee2a018b-e708-404c-81e5-ae6d1a0cee91', '泛江翫月十二韻', '泛江翫月十二韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["楚塞分形勢，羊公壓大邦。","因依多士子，參畫盡敦厖。","岳璧閑相對，荀龍自有雙。","共將船載酒，同泛月臨江。","遠樹懸金鏡，深潭倒玉幢。","委波添淨練，洞照滅凝釭。","闐咽沙頭市，𤫩瓏竹岸窗。","巴童唱巫峽，海客話神瀧。","已困連飛盞，猶催未倒缸。","飲荒情爛熳，風棹樂崢摐。","勝事他年憶，愁心此夜降。","知君皆逸韻，須爲應莛撞。"]', '["楚塞分形勢，羊公壓大邦。","因依多士子，參畫尽敦厖。","岳璧闲相对，荀龙自有雙。","共將船載酒，同泛月臨江。","远樹懸金镜，深潭倒玉幢。","委波添淨練，洞照滅凝釭。","闐咽沙头市，𤫩瓏竹岸窗。","巴童唱巫峽，海客話神瀧。","已困連飞盞，猶催未倒缸。","饮荒情爛熳，风棹乐崢摐。","勝事他年憶，愁心此夜降。","知君皆逸韻，須爲應莛撞。"]', '诗', 'shi', '', NULL, '泛江翫月十二韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('799d09c7-b7db-4e45-a9ea-1500216d6d46', '痁臥聞幕中諸公徵樂會飲因有戲呈三十韻', '痁臥闻幕中諸公徵乐會饮因有戲呈三十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["濩落因寒甚，沈陰與病偕。","藥囊堆小案，書卷塞空齋。","脹腹看成鼓，羸形漸比柴。","道情憂易適，溫瘴氣難排。","治尰扶輕杖，開門立靜街。","耳鳴疑暮角，眼暗助昏霾。","野竹連荒草，平陂接斷崖。","坐隅甘對鵩，當路恐遭豺。","蛇蠱迷弓影，鵰翎落箭靫。","晚籬喧鬬雀，殘菊半枯荄。","悵望悲回鴈，依遲傍古槐。","一生長苦節，三省詎行怪。","奔北翻成勇，司南却是咼。","穹蒼真漠漠，風雨漫喈喈。","彼美猶谿女，其誰占館娃。","誠知通有日，太極浩無涯。","布卦求无妄，祈天願孔皆。","藏衰謀計拙，地僻往還乖。","況羨蓮花侶，方欣綺席諧。","鈿車迎妓樂，銀翰屈朋儕。","白紵顰歌黛，同蹄墜舞釵。","纖身霞出海，豔臉月臨淮。","籌箸隨宜放，投盤止罰啀。","紅娘留醉打，觥使及醒差。","顧我潛孤憤，何人想獨懷。","夜燈然檞葉，凍雪墮塼堦。","壞壁虛缸倚，深爐小火埋。","鼠驕銜筆硯，被冷束筋骸。","畢竟圖斟酌，先須遣癘痎。","槍旗如在手，那復敢崴㠢。"]', '["濩落因寒甚，沈陰與病偕。","藥囊堆小案，书卷塞空斋。","脹腹看成鼓，羸形漸比柴。","道情憂易適，溫瘴氣难排。","治尰扶轻杖，开门立静街。","耳鳴疑暮角，眼暗助昏霾。","野竹連荒草，平陂接斷崖。","坐隅甘对鵩，當路恐遭豺。","蛇蠱迷弓影，鵰翎落箭靫。","晚籬喧鬬雀，殘菊半枯荄。","悵望悲回鴈，依遲傍古槐。","一生长苦節，三省詎行怪。","奔北翻成勇，司南却是咼。","穹蒼真漠漠，风雨漫喈喈。","彼美猶谿女，其誰占館娃。","誠知通有日，太極浩無涯。","布卦求无妄，祈天願孔皆。","藏衰謀計拙，地僻往還乖。","況羨蓮花侶，方欣綺席諧。","鈿车迎妓乐，銀翰屈朋儕。","白紵顰歌黛，同蹄墜舞釵。","纖身霞出海，豔臉月臨淮。","籌箸隨宜放，投盤止罰啀。","紅娘留醉打，觥使及醒差。","顧我潛孤憤，何人想独懷。","夜灯然檞葉，凍雪墮塼堦。","壞壁虛缸倚，深爐小火埋。","鼠驕銜笔硯，被冷束筋骸。","畢竟圖斟酌，先須遣癘痎。","槍旗如在手，那复敢崴㠢。"]', '诗', 'shi', '', NULL, '痁臥聞幕中諸公徵樂會飲因有戲呈三十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545657de-d6a7-4051-91e3-a539862a6df2', '酬友封話舊敘懷十二韻', '酬友封話旧敘懷十二韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風波千里別，書信二年稀。","乍見悲兼喜，猶驚是與非。","身名判作夢，盃盞莫相違。","草館同牀宿，沙頭待月歸。","春深鄉路遠，老去宦情微。","魏闕何由到，荆州且共依。","人欺翻省事，官冷易藏威。","但擬馴鷗鳥，無因用弩機。","開張圖卷軸，顛倒醉衫衣。","蓴菜銀絲嫩，鱸魚雪片肥。","憐君詩似湧，贈我筆如飛。","會遣諸伶唱，篇篇入禁闈。"]', '["风波千里別，书信二年稀。","乍见悲兼喜，猶驚是與非。","身名判作梦，盃盞莫相違。","草館同牀宿，沙头待月归。","春深乡路远，老去宦情微。","魏闕何由到，荆州且共依。","人欺翻省事，官冷易藏威。","但擬馴鷗鸟，無因用弩機。","开張圖卷軸，顛倒醉衫衣。","蓴菜銀絲嫩，鱸鱼雪片肥。","怜君诗似湧，贈我笔如飞。","會遣諸伶唱，篇篇入禁闈。"]', '诗', 'shi', '', NULL, '酬友封話舊敘懷十二韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba8ed091-2d31-4f42-8416-d2deed04c071', '送王協律游杭越十韻', '送王協律游杭越十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["去去莫悽悽，餘杭接會稽。","松門天竺寺，花洞若耶溪。","浣渚逢新豔，蘭亭識舊題。","山經秦帝望，壘辨越王棲。","江樹春常早，城樓月易低。","鏡呈湖面出，雲疊海潮齊。","章甫官人戴，蓴絲姹女提。","長干迎客鬧，小市隔煙迷。","紙亂紅藍壓，甌凝碧玉泥。","荆南無抵物，來日爲儂攜。"]', '["去去莫悽悽，餘杭接會稽。","松门天竺寺，花洞若耶溪。","浣渚逢新豔，蘭亭識旧題。","山經秦帝望，壘辨越王棲。","江樹春常早，城楼月易低。","镜呈湖面出，云叠海潮齊。","章甫官人戴，蓴絲姹女提。","长干迎客鬧，小市隔煙迷。","紙亂紅藍壓，甌凝碧玉泥。","荆南無抵物，来日爲儂携。"]', '诗', 'shi', '', NULL, '送王協律游杭越十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3567f8d0-9a5e-4412-8b21-49d6c1f1f305', '送東川馬逢侍御使回十韻', '送东川马逢侍御使回十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風水荆門闊，文章蜀地豪。","眼青賓禮重，眉白衆情高。","思勇曾吞筆，投虛慣用刀。","詞鋒倚天劒，學海駕雲濤。","南郡傳紗帳，東方讓錦袍。","旋吟新樂府，便續古離騷。","雪岸猶封草，春江欲滿槽。","餞筵君置醴，隨俗我餔糟。","莫歎巴三峽，休驚鬢二毛。","流年等頭過，人世各勞勞。"]', '["风水荆门闊，文章蜀地豪。","眼青賓禮重，眉白衆情高。","思勇曾吞笔，投虛慣用刀。","词鋒倚天劒，学海駕云濤。","南郡傳紗帳，东方讓錦袍。","旋吟新乐府，便續古離騷。","雪岸猶封草，春江欲满槽。","餞筵君置醴，隨俗我餔糟。","莫歎巴三峽，休驚鬢二毛。","流年等头過，人世各勞勞。"]', '诗', 'shi', '', NULL, '送東川馬逢侍御使回十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c76f3ccd-1927-4788-a6bb-c5f58d000c39', '酬盧祕書', '酬盧祕书', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["偶有衝天氣，都無處世才。","未容榮路穩，先蹋禍機開。","分久沉荆掾，慙經廁柏臺。","理推愁易惑，鄉思病難裁。","夜伴吳牛喘，春驚朔鴈回。","北人腸斷送，西日眼穿頹。","唯望魂歸去，那知詔下來。","涸魚千丈水，殭燕一聲雷。","幽匣提清鏡，衰顏拂故埃。","夢雲期紫閣，厭雨別黃梅。","親戚迎時到，班行見處陪。","文工猶畏忌，朝士絕嫌猜。","新識蓬山傑，深交翰苑材。","連投珠作貫，獨和玉成堆。","劇敵徒相軋，羸師亦自媒。","磨礱刮骨刃，翻擲委心灰。","恐被神明哭，憂爲造化災。","私調破葉箭，定飲搴旗杯。","金寶潛砂礫，芝蘭似草萊。","憑君毫髮鑒，莫遣翳莓苔。"]', '["偶有衝天氣，都無处世才。","未容榮路穩，先蹋禍機开。","分久沉荆掾，慙經廁柏台。","理推愁易惑，乡思病难裁。","夜伴吳牛喘，春驚朔鴈回。","北人腸斷送，西日眼穿頹。","唯望魂归去，那知詔下来。","涸鱼千丈水，殭燕一声雷。","幽匣提清镜，衰顏拂故埃。","梦云期紫閣，厭雨別黄梅。","親戚迎时到，班行见处陪。","文工猶畏忌，朝士絕嫌猜。","新識蓬山傑，深交翰苑材。","連投珠作貫，独和玉成堆。","劇敵徒相軋，羸師亦自媒。","磨礱刮骨刃，翻擲委心灰。","恐被神明哭，憂爲造化災。","私調破葉箭，定饮搴旗杯。","金寶潛砂礫，芝蘭似草萊。","憑君毫髮鑒，莫遣翳莓苔。"]', '诗', 'shi', '', NULL, '酬盧祕書 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c895dac-d461-45d2-8613-940494bc98e4', '見人詠韓舍人新律詩因有戲贈', '见人詠韓舍人新律诗因有戲贈', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["喜聞韓古調，兼愛近詩篇。","玉磬聲聲徹，金鈴箇箇圓。","高疎明月下，細膩早春前。","花態繁於綺，閨情軟似綿。","輕新便妓唱，凝妙入僧禪。","欲得人人伏，能教面面全。","延之苦拘檢，摩詰好因緣。","七字排居敬，千詞敵樂天。","殷勤閑太祝，好去老通川。","莫漫裁章句，須饒紫禁仙。"]', '["喜闻韓古調，兼愛近诗篇。","玉磬声声徹，金鈴箇箇圓。","高疎明月下，細膩早春前。","花態繁於綺，閨情軟似綿。","轻新便妓唱，凝妙入僧禪。","欲得人人伏，能教面面全。","延之苦拘檢，摩詰好因緣。","七字排居敬，千词敵乐天。","殷勤闲太祝，好去老通川。","莫漫裁章句，須饒紫禁仙。"]', '诗', 'shi', '', NULL, '見人詠韓舍人新律詩因有戲贈 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e04a8844-2663-48cb-b8de-5989fbf5845b', '奉和權相公行次臨闕驛逢僕射相公歸朝俄頃分途因以奉贈詩十四韻', '奉和權相公行次臨闕驛逢僕射相公归朝俄頃分途因以奉贈诗十四韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["帝下赤霄符，搜求造化爐。","中台歸內座，太一直南都。","黃霸乘軺入，王尊叱馭趨。","萬人東道送，六纛北風驅。","棧閣纔傾蓋，關門已合繻。","貫魚行邐迤，交馬語踟躕。","去速熊羆兆，來馳虎豹夫。","昔憐三易地，今訝兩分途。","別路環山雪，離章運寸珠。","鋒鋩斷犀兕，波浪沒蓬壺。","區宇聲雖動，淮河孽末誅。","將軍遙策畫，師氏密訏謨。","漢上壇仍築，褒西陣再圖。","公方先二虜，何暇進愚儒。"]', '["帝下赤霄符，搜求造化爐。","中台归內座，太一直南都。","黄霸乘軺入，王尊叱馭趨。","万人东道送，六纛北风驱。","棧閣纔傾蓋，关门已合繻。","貫鱼行邐迤，交马語踟躕。","去速熊羆兆，来驰虎豹夫。","昔怜三易地，今訝兩分途。","別路环山雪，離章運寸珠。","鋒鋩斷犀兕，波浪沒蓬壺。","區宇声雖动，淮河孽末誅。","將軍遙策畫，師氏密訏謨。","漢上壇仍築，褒西陣再圖。","公方先二虜，何暇進愚儒。"]', '诗', 'shi', '', NULL, '奉和權相公行次臨闕驛逢僕射相公歸朝俄頃分途因以奉贈詩十四韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc110d69-e883-45b4-b69b-080c6d7bd941', '酬樂天東南行詩一百韻', '酬乐天东南行诗一百韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我病方吟越，君行已過湖。","去應緣直道，哭不爲窮途。","亞竹寒驚牖，空堂夜向隅。","暗魂思背燭，危夢怯乘桴。","坐痛筋骸憯，旁嗟物候殊。","雨蒸蟲沸渭，浪湧怪睢盱。","索綆飄蚊蚋，蓬麻甃舳艫。","短簷苫稻草，微俸封漁租。","泥浦喧撈蛤，荒郊險鬬貙。","鯨吞近溟漲，猿鬧接黔巫。","芒屩泅牛婦，丫頭蕩槳夫。","酢醅荷裹賣，醨酒水淋沽。","舞態翻鸜鵒，歌詞咽鷓鴣。","夷音啼似笑，蠻語謎相呼。","江郭船添店，山城木豎郛。","吠聲沙市犬，爭食墓林烏。","獷俗誠堪憚，妖神甚可虞。","欲令仁漸及，已被瘧潛圖。","膳減思調鼎，行稀恐蠹樞。","雜蓴多剖鱔，和黍半蒸菰。","綠糉新菱實，金丸小木奴。","芋羹真蹔淡，䶉炙漫塗蘇。","炰鼈那勝羜，烹鯄只似鱸。","楚風輕似蜀，巴地濕如吳。","氣濁星難見，州斜日易晡。","通宵但雲霧，未酉即桑榆。","瘴窟蛇休蟄，炎溪暑不徂。","倀魂陰叫嘯，鵩貌晝踟躕。","鄉里家藏蠱，官曹世乏儒。","斂緡偷印信，傳箭作符繻。","椎髻拋巾幗，鑹刀代轆轤。","當心鞙銅鼓，背弝射桑弧。","豈復民甿料，須將鳥獸驅。","是非渾並漆，詞訟敢研朱。","陋室鴞窺伺，衰形蟒覬覦。","鬢毛霜點合，襟淚血痕濡。","倍憶京華伴，偏忘我爾軀。","謫居今共遠，榮路昔同趨。","科試銓衡局，衙參典校廚。","月中分桂樹，天上識昌蒲。","應召逢鴻澤，陪游值賜酺。","心唯撞衛磬，耳不亂齊竽。","海岱詞鋒截，皇王筆陣敺。","疾奔凌騕褭，高唱軋吳歈。","點檢張儀舌，提攜傅說圖。","擺囊看利頴，開頷出明珠。","並取千人特，皆非十上徒。","白麻雲色膩，墨詔電光麤。","衆口貪歸美，何顏敢妬姝。","秦臺納紅旭，酆匣洗黃壚。","諫獵寧規避，彈豪詎囁嚅。","胏肝憎巧曲，蹊徑絕縈迂。","誓遣朝綱振，忠饒翰苑輸。","驥調方汗血，蠅點忽成盧。","遂謫栖遑掾，還飛送別盂。","痛嗟親愛隔，顛望友朋扶。","狸病翻隨鼠，驄羸返作駒。","物情良狥俗，時論太誣吾。","瓶罄罍偏恥，松摧柏自枯。","虎雖遭陷穽，龍不怕泥塗。","重喜登賢苑，方欣佐伍符。","判身入矛戟，輕敵比錙銖。","驛騎來千里，天書下九衢。","因教罷飛檄，便許到皇都。","舟敗罌浮漢，驂疲杖過邘。","郵亭一蕭索，烽候各崎嶇。","饋餉人推輅，誰何吏執殳。","拔家逃力役，連鏁責逋誅。","防戍兄兼弟，收田婦與姑。","縑緗工女竭，青紫使臣紆。","望國參雲樹，歸家滿地蕪。","破窗塵𡋯𡋯，幽院鳥嗚嗚。","祖竹藂新筍，孫枝壓舊梧。","晚花狂蛺蝶，殘蒂宿茱萸。","始悟摧林秀，因銜避繳蘆。","文房長遣閉，經肆未曾鋪。","鵷鷺方求侶，鴟鳶已嚇雛。","徵還何鄭重，斥去亦須臾。","迢遞投遐徼，蒼黃出奧區。","通川誠有咎，湓口定無辜。","利器從頭匣，剛腸到底刳。","薰蕕任盛貯，稊稗莫超踰。","公幹經時臥，鍾儀幾歲拘。","光陰流似水，蒸瘴熱於鑪。","薄命知然也，深交有矣夫。","救焚期骨肉，投分刻肌膚。","二妙馳軒陛，三英詠袴襦。","李多嘲蝘蜓，竇數集蜘蛛。","數子皆奇貨，唯予獨朽株。","邯鄲笑匍匐，燕蒯受揶揄。","嬾學三閭憤，甘齊百里愚。","耽眠稀醒素，憑醉少嗟吁。","學問徒爲爾，書題盡已于。","別猶多夢寐，情尚感凋枯。","近喜司戎健，尋傷掌誥徂。","士元名位屈，伯道子孫無。","舊好飛瓊翰，新詩灌玉壺。","幾催閑處泣，終作苦中娛。","廉藺聲相讓，燕秦勢豈俱。","此篇應絕倒，休漫捋髭鬚。"]', '["我病方吟越，君行已過湖。","去應緣直道，哭不爲窮途。","亞竹寒驚牖，空堂夜向隅。","暗魂思背燭，危梦怯乘桴。","坐痛筋骸憯，旁嗟物候殊。","雨蒸蟲沸渭，浪湧怪睢盱。","索綆飄蚊蚋，蓬麻甃舳艫。","短簷苫稻草，微俸封漁租。","泥浦喧撈蛤，荒郊險鬬貙。","鯨吞近溟漲，猿鬧接黔巫。","芒屩泅牛婦，丫头蕩槳夫。","酢醅荷裹賣，醨酒水淋沽。","舞態翻鸜鵒，歌词咽鷓鴣。","夷音啼似笑，蠻語謎相呼。","江郭船添店，山城木豎郛。","吠声沙市犬，爭食墓林烏。","獷俗誠堪憚，妖神甚可虞。","欲令仁漸及，已被瘧潛圖。","膳減思調鼎，行稀恐蠹樞。","杂蓴多剖鱔，和黍半蒸菰。","綠糉新菱實，金丸小木奴。","芋羹真蹔淡，䶉炙漫塗蘇。","炰鼈那勝羜，烹鯄只似鱸。","楚风轻似蜀，巴地濕如吳。","氣濁星难见，州斜日易晡。","通宵但云霧，未酉即桑榆。","瘴窟蛇休蟄，炎溪暑不徂。","倀魂陰叫嘯，鵩貌晝踟躕。","乡里家藏蠱，官曹世乏儒。","斂緡偷印信，傳箭作符繻。","椎髻拋巾幗，鑹刀代轆轤。","當心鞙銅鼓，背弝射桑弧。","豈复民甿料，須將鸟獸驱。","是非渾並漆，词訟敢研朱。","陋室鴞窺伺，衰形蟒覬覦。","鬢毛霜点合，襟泪血痕濡。","倍憶京华伴，偏忘我爾軀。","謫居今共远，榮路昔同趨。","科試銓衡局，衙參典校廚。","月中分桂樹，天上識昌蒲。","應召逢鴻澤，陪游值賜酺。","心唯撞衛磬，耳不亂齊竽。","海岱词鋒截，皇王笔陣敺。","疾奔凌騕褭，高唱軋吳歈。","点檢張儀舌，提携傅说圖。","擺囊看利頴，开頷出明珠。","並取千人特，皆非十上徒。","白麻云色膩，墨詔電光麤。","衆口貪归美，何顏敢妬姝。","秦台納紅旭，酆匣洗黄壚。","諫獵寧規避，彈豪詎囁嚅。","胏肝憎巧曲，蹊徑絕縈迂。","誓遣朝綱振，忠饒翰苑輸。","驥調方汗血，蠅点忽成盧。","遂謫栖遑掾，還飞送別盂。","痛嗟親愛隔，顛望友朋扶。","狸病翻隨鼠，驄羸返作駒。","物情良狥俗，时論太誣吾。","瓶罄罍偏恥，松摧柏自枯。","虎雖遭陷穽，龙不怕泥塗。","重喜登賢苑，方欣佐伍符。","判身入矛戟，轻敵比錙銖。","驛騎来千里，天书下九衢。","因教罷飞檄，便許到皇都。","舟敗罌浮漢，驂疲杖過邘。","郵亭一蕭索，烽候各崎嶇。","饋餉人推輅，誰何吏執殳。","拔家逃力役，連鏁責逋誅。","防戍兄兼弟，收田婦與姑。","縑緗工女竭，青紫使臣紆。","望国參云樹，归家满地蕪。","破窗塵𡋯𡋯，幽院鸟嗚嗚。","祖竹藂新筍，孫枝壓旧梧。","晚花狂蛺蝶，殘蒂宿茱萸。","始悟摧林秀，因銜避繳蘆。","文房长遣閉，經肆未曾鋪。","鵷鷺方求侶，鴟鳶已嚇雛。","徵還何鄭重，斥去亦須臾。","迢遞投遐徼，蒼黄出奧區。","通川誠有咎，湓口定無辜。","利器從头匣，剛腸到底刳。","薰蕕任盛貯，稊稗莫超踰。","公幹經时臥，鍾儀幾歲拘。","光陰流似水，蒸瘴熱於鑪。","薄命知然也，深交有矣夫。","救焚期骨肉，投分刻肌膚。","二妙驰軒陛，三英詠袴襦。","李多嘲蝘蜓，竇數集蜘蛛。","數子皆奇貨，唯予独朽株。","邯鄲笑匍匐，燕蒯受揶揄。","嬾学三閭憤，甘齊百里愚。","耽眠稀醒素，憑醉少嗟吁。","学问徒爲爾，书題尽已于。","別猶多梦寐，情尚感凋枯。","近喜司戎健，尋傷掌誥徂。","士元名位屈，伯道子孫無。","旧好飞瓊翰，新诗灌玉壺。","幾催闲处泣，終作苦中娛。","廉藺声相讓，燕秦勢豈俱。","此篇應絕倒，休漫捋髭鬚。"]', '诗', 'shi', '', NULL, '酬樂天東南行詩一百韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c5775e2-be12-40ae-8382-ce87f9c2037c', '和樂天送客遊嶺南二十韻', '和乐天送客游嶺南二十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我自離鄉久，君那度嶺頻。","一杯魂慘澹，萬里路艱辛。","江館連沙市，瀧船泊水濱。","騎田廻北顧，銅柱指南鄰。","大壑浮三島，周天過五均。","波心湧樓閣，規外布星辰。","狒狒穿筒格，猩猩置屐馴。","貢兼蛟女絹，俗重語兒巾。","舶主腰藏寶，黃家砦起塵。","歌鍾排象背，炊爨上魚身。","電白雷山接，旗紅賊艦新。","島夷徐市種，廟覡趙佗神。","鳶跕方知瘴，蛇蘇不待春。","曙潮雲斬斬，夜海火燐燐。","冠冕中華客，梯航異域臣。","果然皮勝錦，吉了舌如人。","風黖秋茅葉，煙埋曉月輪。","定應玄髮變，焉用翠毛珍。","句漏沙須買，貪泉貨莫親。","能傳稚川術，何患隱之貧。"]', '["我自離乡久，君那度嶺頻。","一杯魂慘澹，万里路艱辛。","江館連沙市，瀧船泊水濱。","騎田廻北顧，銅柱指南鄰。","大壑浮三島，周天過五均。","波心湧楼閣，規外布星辰。","狒狒穿筒格，猩猩置屐馴。","貢兼蛟女絹，俗重語兒巾。","舶主腰藏寶，黄家砦起塵。","歌鍾排象背，炊爨上鱼身。","電白雷山接，旗紅賊艦新。","島夷徐市種，廟覡趙佗神。","鳶跕方知瘴，蛇蘇不待春。","曙潮云斬斬，夜海火燐燐。","冠冕中华客，梯航異域臣。","果然皮勝錦，吉了舌如人。","风黖秋茅葉，煙埋晓月輪。","定應玄髮变，焉用翠毛珍。","句漏沙須買，貪泉貨莫親。","能傳稚川術，何患隐之貧。"]', '诗', 'shi', '', NULL, '和樂天送客遊嶺南二十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6326d175-7980-4cbc-9237-62120d12a482', '獻滎陽公詩五十韻', '獻滎陽公诗五十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鄭驛騎翩翩，丘門子弟賢。","文翁開學日，正禮騁途年。","駿骨黃金買，英髦絳帳延。","趨風皆蹀足，侍坐各差肩。","解榻招徐穉，登樓引仲宣。","鳳攢題字扇，魚落講經筵。","盛氣河包濟，貞姿嶽柱天。","臯夔當五百，鄒魯重三千。","科斗翻騰取，關雎教授先。","篆垂朝露滴，詩綴夜珠聯。","逸禮多心匠，焚書舊口傳。","陳遵修尺牘，阮瑀讓飛牋。","中的顏初啓，抽毫踵未旋。","森羅萬木合，屬對百花全。","詞海跳波湧，文星拂坐懸。","戴馮遙避席，祖逖後施鞭。","西蜀凌雲賦，東陽詠月篇。","勁芟鼇足斷，精貫蝨心穿。","浩汗神彌王，鷂颺興欲仙。","冰壺通皓雪，綺樹眇晴煙。","驅駕雷霆走，鋪陳錦繡鮮。","情機登穾奧，流韻溢山川。","墨客膺潛服，談賓膝誤前。","張鱗定摧敗，折角反矜憐。","句句推瓊玉，聲聲播管弦。","纖新撩造化，澒洞斡陶甄。","衛磬琤鍧極，齊竽僭濫偏。","空虛慙炙輠，點竄許懷鉛。","憊色秋來草，哀吟雨後蟬。","自傷魂慘沮，何暇思幽玄。","喜到樽罍側，愁親几案邊。","菁華知竭矣，胏腑尚求旃。","抵滯渾成醉，徘徊轉慕膻。","老歎才漸少，閑苦病相煎。","瓦礫難追琢，芻蕘分棄捐。","漫勞成懇懇，那得美娟娟。","拙劣仍非速，迂愚且異專。","移時停筆硯，揮景乏戈鋋。","儀舌忻猶在，舒帷誓不褰。","會將連獻楚，深恥謬游燕。","蒲有臨書葉，韋充讀易編。","沙須披見寶，經擬帶耕田。","入霧長期閏，持朱本望研。","輪轅呈曲直，鑿枘取方圓。","呼吸寧徒爾，霑濡豈浪然。","過簫資響亮，隨水漲淪漣。","惜日看圭短，偷光恨壁堅。","勤勤彫朽木，細細導蒙泉。","傳癖今應甚，頭風昨已痊。","丹青公舊物，一爲變蚩妍。"]', '["鄭驛騎翩翩，丘门子弟賢。","文翁开学日，正禮騁途年。","駿骨黄金買，英髦絳帳延。","趨风皆蹀足，侍坐各差肩。","解榻招徐穉，登楼引仲宣。","鳳攢題字扇，鱼落講經筵。","盛氣河包濟，貞姿嶽柱天。","臯夔當五百，鄒魯重三千。","科斗翻腾取，关雎教授先。","篆垂朝露滴，诗綴夜珠聯。","逸禮多心匠，焚书旧口傳。","陳遵修尺牘，阮瑀讓飞牋。","中的顏初啓，抽毫踵未旋。","森羅万木合，屬对百花全。","词海跳波湧，文星拂坐懸。","戴馮遙避席，祖逖後施鞭。","西蜀凌云賦，东陽詠月篇。","勁芟鼇足斷，精貫蝨心穿。","浩汗神彌王，鷂颺兴欲仙。","冰壺通皓雪，綺樹眇晴煙。","驱駕雷霆走，鋪陳錦繡鲜。","情機登穾奧，流韻溢山川。","墨客膺潛服，談賓膝誤前。","張鱗定摧敗，折角反矜怜。","句句推瓊玉，声声播管弦。","纖新撩造化，澒洞斡陶甄。","衛磬琤鍧極，齊竽僭濫偏。","空虛慙炙輠，点竄許懷鉛。","憊色秋来草，哀吟雨後蟬。","自傷魂慘沮，何暇思幽玄。","喜到樽罍側，愁親几案邊。","菁华知竭矣，胏腑尚求旃。","抵滯渾成醉，徘徊轉慕膻。","老歎才漸少，闲苦病相煎。","瓦礫难追琢，芻蕘分棄捐。","漫勞成懇懇，那得美娟娟。","拙劣仍非速，迂愚且異專。","移时停笔硯，揮景乏戈鋋。","儀舌忻猶在，舒帷誓不褰。","會將連獻楚，深恥謬游燕。","蒲有臨书葉，韋充读易編。","沙須披见寶，經擬带耕田。","入霧长期閏，持朱本望研。","輪轅呈曲直，鑿枘取方圓。","呼吸寧徒爾，霑濡豈浪然。","過簫資响亮，隨水漲淪漣。","惜日看圭短，偷光恨壁堅。","勤勤彫朽木，細細導蒙泉。","傳癖今應甚，头风昨已痊。","丹青公旧物，一爲变蚩妍。"]', '诗', 'shi', '', NULL, '獻滎陽公詩五十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5d6b2c8-8c40-41bd-bc26-89b792f8b659', '酬樂天江樓夜吟稹詩因成三十韻', '酬乐天江楼夜吟稹诗因成三十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["忽見君新句，君吟我舊篇。","見當巴徼外，吟在楚江前。","思鄙寧通律，聲清遂扣玄。","三都時覺重，一顧世稱妍。","排韻曾遙荅，分題幾共聯。","昔憑銀翰寫，今賴玉音宣。","布鼓隨椎響，坯泥仰匠圓。","鈴因風斷續，珠與調牽緜。","阮籍驚長嘯，商陵怨別弦。","猿羞啼月峽，鶴讓警秋天。","志士潛興感，高僧暫廢禪。","興飄滄海動，氣合碧雲連。","點綴工微者，吹噓勢特然。","休文徒倚檻，彥伯浪回船。","伎樂當筵唱，兒童滿巷傳。","改張思婦錦，騰躍賈人牋。","魏拙虛教出，曹風敢望痊。","定遭才子笑，恐賺學生癲。","裁什情何厚，飛書信不專。","隼猜鴻蓄縮，虎橫犬迍邅。","水墨看雖久，瓊瑤喜尚全。","纔從魚裏得，便向市頭懸。","夜置堂東序，朝鋪座右邊。","手尋韋欲絕，淚滴紙渾穿。","甘蔗銷殘醉，醍醐醒早眠。","深藏那遽滅，同詠苦無緣。","雅羨詩能聖，終嗟藥未仙。","五千誠遠道，四十已中年。","暗魄多相夢，衰容每自憐。","卒章還慟哭，蚊蚋溢山川。"]', '["忽见君新句，君吟我旧篇。","见當巴徼外，吟在楚江前。","思鄙寧通律，声清遂扣玄。","三都时覺重，一顧世稱妍。","排韻曾遙荅，分題幾共聯。","昔憑銀翰寫，今賴玉音宣。","布鼓隨椎响，坯泥仰匠圓。","鈴因风斷續，珠與調牽緜。","阮籍驚长嘯，商陵怨別弦。","猿羞啼月峽，鹤讓警秋天。","志士潛兴感，高僧暫廢禪。","兴飄滄海动，氣合碧云連。","点綴工微者，吹噓勢特然。","休文徒倚檻，彥伯浪回船。","伎乐當筵唱，兒童满巷傳。","改張思婦錦，腾躍賈人牋。","魏拙虛教出，曹风敢望痊。","定遭才子笑，恐賺学生癲。","裁什情何厚，飞书信不專。","隼猜鴻蓄縮，虎橫犬迍邅。","水墨看雖久，瓊瑤喜尚全。","纔從鱼裏得，便向市头懸。","夜置堂东序，朝鋪座右邊。","手尋韋欲絕，泪滴紙渾穿。","甘蔗銷殘醉，醍醐醒早眠。","深藏那遽滅，同詠苦無緣。","雅羨诗能聖，終嗟藥未仙。","五千誠远道，四十已中年。","暗魄多相梦，衰容每自怜。","卒章還慟哭，蚊蚋溢山川。"]', '诗', 'shi', '', NULL, '酬樂天江樓夜吟稹詩因成三十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dddafe62-5195-43d1-ae5d-8b1ac66eb1ca', '酬樂天待漏入閤見贈', '酬乐天待漏入閤见贈', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["未勘銀臺契，先排浴殿關。","沃心因特召，[承]旨絕常班。","颭閃才人袖，嘔鵶軟舉鐶。","宮花低作帳，雲從積成山。","密視樞機草，偷瞻咫尺顏。","恩垂天語近，對久漏聲閑。","丹陛曾同立，金鑾恨獨攀。","筆無鴻業潤，袍愧紫文殷。","河水通天上，瀛州接世間。"]', '["未勘銀台契，先排浴殿关。","沃心因特召，[承]旨絕常班。","颭閃才人袖，嘔鵶軟舉鐶。","宮花低作帳，云從積成山。","密視樞機草，偷瞻咫尺顏。","恩垂天語近，对久漏声闲。","丹陛曾同立，金鑾恨独攀。","笔無鴻業潤，袍愧紫文殷。","河水通天上，瀛州接世间。"]', '诗', 'shi', '', NULL, '酬樂天待漏入閤見贈 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7890db1-28cc-4cc4-b81a-90b6f9d68568', '酬樂天早春閑遊西湖頗多野趣恨不得與微之同賞因思在越官重事殷鏡湖之遊或恐未暇因成十八韻見寄樂天前篇到時適會予亦宴鏡湖南亭因述目前所睹以成酬荅末章亦示暇誠則勢使之然亦欲粗爲恬養之贈耳', '酬乐天早春闲游西湖頗多野趣恨不得與微之同賞因思在越官重事殷镜湖之游或恐未暇因成十八韻见寄乐天前篇到时適會予亦宴镜湖南亭因述目前所睹以成酬荅末章亦示暇誠則勢使之然亦欲粗爲恬養之贈耳', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雁思欲回賓，風聲乍變新。","各攜紅粉伎，俱伴紫垣人。","水面波疑縠，山腰虹似巾。","柳條黃大帶，茭葑綠文茵。","雪盡纔通屐，汀寒未有蘋。","向陽偏曬羽，依岸小游鱗。","浦嶼崎嶇到，林園次第巡。","墨池憐嗜學，丹井羨登真。","雅歎游方盛，聊非意所親。","白頭辭北闕，滄海是東鄰。","問俗煩江界，蒐畋想渭津。","故交音訊少，歸夢往來頻。","獨喜同門舊，皆爲列郡臣。","三刀連地軸，一葦礙車輪。","尚阻青天霧，空瞻白玉塵。","龍因雕字識，犬爲送書馴。","勝事無窮境，流年有限身。","嬾將閑氣力，爭鬬野塘春。"]', '["雁思欲回賓，风声乍变新。","各携紅粉伎，俱伴紫垣人。","水面波疑縠，山腰虹似巾。","柳條黄大带，茭葑綠文茵。","雪尽纔通屐，汀寒未有蘋。","向陽偏曬羽，依岸小游鱗。","浦嶼崎嶇到，林园次第巡。","墨池怜嗜学，丹井羨登真。","雅歎游方盛，聊非意所親。","白头辞北闕，滄海是东鄰。","问俗煩江界，蒐畋想渭津。","故交音訊少，归梦往来頻。","独喜同门旧，皆爲列郡臣。","三刀連地軸，一葦礙车輪。","尚阻青天霧，空瞻白玉塵。","龙因雕字識，犬爲送书馴。","勝事無窮境，流年有限身。","嬾將闲氣力，爭鬬野塘春。"]', '诗', 'shi', '', NULL, '酬樂天早春閑遊西湖頗多野趣恨不得與微之同賞因思在越官重事殷鏡湖之遊或恐未暇因成十八韻見寄樂天前篇到時適會予亦宴鏡湖南亭因述目前所睹以成酬荅末章亦示暇誠則勢使之然亦欲粗爲恬養之贈耳 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c14a7b2-fa69-4730-b1c2-849eda7012d9', '江邊四十韻', '江邊四十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["官借江邊宅，天生地勢坳。","敧危饒壞構，迢遞接長郊。","怪鵩頻棲息，跳蛙頗混殽。","總無籬繳繞，尤怕虎咆哮。","停潦魚招獺，空倉鼠敵貓。","土虛煩穴蟻，柱朽畏藏蛟。","蛇虺吞簷雀，豺狼逐野麃。","犬驚狂浩浩，雞亂響嘐嘐。","濩落貧甘守，荒涼穢盡包。","斷簾飛熠燿，當戶網蠨蛸。","曲突翻成沼，行廊却代庖。","橋橫老顛枿，馬病裛芻茭。","一一牀頭點，連連砌下泡。","辱泥疑在絳，避雨想經崤。","相顧憂爲鼈，誰能復繫匏。","誓心來利往，卜食過安爻。","何計逃昏墊，移文報舊交。","棟梁存伐木，苫蓋愧分茅。","金琯排黃荻，琅玕褭翠梢。","花塼水面鬬，鴛瓦玉聲敲。","方礎荆山採，修掾郢匠鉋。","隱錐雷震蟄，破竹箭鳴骹。","正寢初停午，頻眠欲轉胞。","囷圓收薄祿，廚敝備嘉肴。","各各人寧宇，雙雙燕賀巢。","高門受車轍，華廐稱蒲捎。","尺寸皆隨用，毫釐敢浪拋。","篾餘籠白鶴，枝賸架青鵁。","製榻容筐篚，施關拒斗筲。","欄干防汲井，密室待持膠。","庭草傭工薙，園蔬稚子掊。","本圖閑種植，那要擇肥磽。","綠柚勤勤數，紅榴箇箇抄。","池清漉螃蟹，瓜蠹拾𧏘蟊。","曬篆看沙鳥，磨刀綻海鮫。","羅灰修藥竈，築垛閱弓弰。","散誕都由習，童蒙剩嬾教。","最便陶靜飲，還作解愁嘲。","近浦聞歸楫，遙城罷曉鐃。","王孫如有問，須爲併揮鞘。"]', '["官借江邊宅，天生地勢坳。","敧危饒壞構，迢遞接长郊。","怪鵩頻棲息，跳蛙頗混殽。","總無籬繳繞，尤怕虎咆哮。","停潦鱼招獺，空倉鼠敵貓。","土虛煩穴蟻，柱朽畏藏蛟。","蛇虺吞簷雀，豺狼逐野麃。","犬驚狂浩浩，雞亂响嘐嘐。","濩落貧甘守，荒涼穢尽包。","斷簾飞熠燿，當戶網蠨蛸。","曲突翻成沼，行廊却代庖。","橋橫老顛枿，马病裛芻茭。","一一牀头点，連連砌下泡。","辱泥疑在絳，避雨想經崤。","相顧憂爲鼈，誰能复繫匏。","誓心来利往，卜食過安爻。","何計逃昏墊，移文報旧交。","棟梁存伐木，苫蓋愧分茅。","金琯排黄荻，琅玕褭翠梢。","花塼水面鬬，鴛瓦玉声敲。","方礎荆山採，修掾郢匠鉋。","隐錐雷震蟄，破竹箭鳴骹。","正寢初停午，頻眠欲轉胞。","囷圓收薄祿，廚敝備嘉肴。","各各人寧宇，雙雙燕賀巢。","高门受车轍，华廐稱蒲捎。","尺寸皆隨用，毫釐敢浪拋。","篾餘籠白鹤，枝賸架青鵁。","製榻容筐篚，施关拒斗筲。","欄干防汲井，密室待持膠。","庭草傭工薙，园蔬稚子掊。","本圖闲種植，那要擇肥磽。","綠柚勤勤數，紅榴箇箇抄。","池清漉螃蟹，瓜蠹拾𧏘蟊。","曬篆看沙鸟，磨刀綻海鮫。","羅灰修藥竈，築垛閱弓弰。","散誕都由習，童蒙剩嬾教。","最便陶静饮，還作解愁嘲。","近浦闻归楫，遙城罷晓鐃。","王孫如有问，須爲併揮鞘。"]', '诗', 'shi', '', NULL, '江邊四十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c99e55a4-ea4a-49ea-b3ca-980c39777cdf', '春六十韻', '春六十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["節應寒灰下，春生返照中。","未能消積雪，已漸少回風。","迎氣邦經重，齋誠帝念隆。","龍驤紫宸北，天壓翠壇東。","仙仗搖佳彩，榮光荅聖衷。","便從威仰座，隨入大羅宮。","先到璇淵底，偷穿玳瑁櫳。","館娃朝鏡晚，太液曉冰融。","撩摘芳情徧，搜求好處終。","九霄渾可可，萬姓尚忡忡。","晝漏頻加箭，宵暉欲半弓。","驅令三殿出，乞與百蠻同。","直自方壺島，斜臨絕漠戎。","南巡曖珠樹，西轉麗崆峒。","度嶺梅甘坻，潛泉脈暗洪。","悠悠鋪塞草，冉冉著江楓。","蠶役投筐妾，耘催荷蓧翁。","既蒸難發地，仍送嬾歸鴻。","約略環區宇，殷勤綺鎬酆。","華山青黛撲，渭水碧沙蒙。","宿露清餘靄，晴煙塞迥空。","燕巢纔點綴，鶯舌最惺愡。","膩粉梨園白，臙脂桃徑紅。","鬱金垂嫩柳，罯畫委高籠。","地甲門闌大，天開禁掖崇。","層臺張舞鳳，閣道架飛虹。","麴糵調神化，鵷鸞竭至忠。","歌鍾齊錫宴，車服獎庸功。","俊造欣時用，閭閻賀歲豐。","倡樓妝㸌㸌，農野綠芃芃。","貴主驕矜盛，豪家恃賴雄。","偏霑打毬彩，頻得鑄錢銅。","專殺擒楊若，殊恩赦鄧通。","女孫新在內，嬰稚近封公。","游衍關心樂，詩書對面聾。","盤筵饒異味，音樂斥庸工。","酒愛油衣淺，杯誇瑪瑙烘。","挑鬟玉釵髻，刺繡寶裝攏。","啓齒呈編貝，彈絲動削蔥。","醉圓雙媚靨，波溢兩明瞳。","但賞歡無極，那知恨亦充。","洞房閑窈窕，庭院獨蔥蘢。","謝砌縈殘絮，班窗網曙蟲。","望夫身化石，爲伯首如蓬。","顧我沉憂士，騎他老病驄。","靜街乘曠蕩，初日接曈曨。","飲敗胏常渴，魂驚耳更聰。","虛逢好陽豔，其那苦昏懜。","僶俛還移步，持疑又省躬。","慵將疲顇質，漫走倦羸僮。","季月行當暮，良辰坐歎窮。","晉悲焚介子，魯願浴沂童。","燧改鮮妍火，陰繁晻澹桐。","瑞雲低𢈁𢈁，香雨潤濛濛。","藥溉分窠數，籬栽備幼沖。","種莎憐見葉，護筍冀成筒。","有夢多爲蝶，因蒐定坐熊。","漂沈隨壞芥，榮茂委蒼穹。","震動風千變，晴和鶴一沖。","丁寧搴芳侶，須識未開叢。"]', '["節應寒灰下，春生返照中。","未能消積雪，已漸少回风。","迎氣邦經重，斋誠帝念隆。","龙驤紫宸北，天壓翠壇东。","仙仗搖佳彩，榮光荅聖衷。","便從威仰座，隨入大羅宮。","先到璇淵底，偷穿玳瑁櫳。","館娃朝镜晚，太液晓冰融。","撩摘芳情徧，搜求好处終。","九霄渾可可，万姓尚忡忡。","晝漏頻加箭，宵暉欲半弓。","驱令三殿出，乞與百蠻同。","直自方壺島，斜臨絕漠戎。","南巡曖珠樹，西轉丽崆峒。","度嶺梅甘坻，潛泉脈暗洪。","悠悠鋪塞草，冉冉著江楓。","蠶役投筐妾，耘催荷蓧翁。","既蒸难發地，仍送嬾归鴻。","約略环區宇，殷勤綺鎬酆。","华山青黛撲，渭水碧沙蒙。","宿露清餘靄，晴煙塞迥空。","燕巢纔点綴，鶯舌最惺愡。","膩粉梨园白，臙脂桃徑紅。","鬱金垂嫩柳，罯畫委高籠。","地甲门闌大，天开禁掖崇。","層台張舞鳳，閣道架飞虹。","麴糵調神化，鵷鸾竭至忠。","歌鍾齊錫宴，车服獎庸功。","俊造欣时用，閭閻賀歲豐。","倡楼妝㸌㸌，農野綠芃芃。","貴主驕矜盛，豪家恃賴雄。","偏霑打毬彩，頻得鑄錢銅。","專殺擒楊若，殊恩赦鄧通。","女孫新在內，嬰稚近封公。","游衍关心乐，诗书对面聾。","盤筵饒異味，音乐斥庸工。","酒愛油衣淺，杯誇瑪瑙烘。","挑鬟玉釵髻，刺繡寶裝攏。","啓齒呈編貝，彈絲动削蔥。","醉圓雙媚靨，波溢兩明瞳。","但賞歡無極，那知恨亦充。","洞房闲窈窕，庭院独蔥蘢。","謝砌縈殘絮，班窗網曙蟲。","望夫身化石，爲伯首如蓬。","顧我沉憂士，騎他老病驄。","静街乘曠蕩，初日接曈曨。","饮敗胏常渴，魂驚耳更聰。","虛逢好陽豔，其那苦昏懜。","僶俛還移步，持疑又省躬。","慵將疲顇質，漫走倦羸僮。","季月行當暮，良辰坐歎窮。","晉悲焚介子，魯願浴沂童。","燧改鲜妍火，陰繁晻澹桐。","瑞云低𢈁𢈁，香雨潤濛濛。","藥溉分窠數，籬栽備幼沖。","種莎怜见葉，護筍冀成筒。","有梦多爲蝶，因蒐定坐熊。","漂沈隨壞芥，榮茂委蒼穹。","震动风千变，晴和鹤一沖。","丁寧搴芳侶，須識未开叢。"]', '诗', 'shi', '', NULL, '春六十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('019b3965-59ae-46a8-8b7a-96f1cb9ab59c', '月三十韻', '月三十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蓂葉標新朔，霜豪引細輝。","白眉驚半隱，虹勢訝全微。","涼魄潭空洞，虛弓雁畏威。","上弦何汲汲，佳色轉依依。","綺幕殘燈斂，妝樓破鏡飛。","玲瓏穿竹樹，岑寂思幈幃。","坐愛規將合，行看望已幾。","絳河冰鑑朗，黃道玉輪巍。","迥照偏瓊砌，餘光借粉闈。","泛池相皎潔，壓桂共芳菲。","的的當歌扇，娟娟透舞衣。","殷勤入懷什，懇款墮雲圻。","素液傳烘盞，鳴琴薦碧徽。","椒房深肅肅，蘭路靄霏霏。","翡翠通簾影，琉璃瑩殿扉。","西園筵玳瑁，東壁射蛜蝛。","老將占天陣，幽人釣石磯。","荷鋤元亮息，回櫂子猷歸。","迢遞同千里，孤高淨九圍。","從星作風雨，配日麗旌旗。","麟鬬寧徒設，蠅聲豈浪譏。","司存委卿士，新拜出郊畿。","今古雖云極，虧盈不易違。","珠胎方夜滿，清露忍朝晞。","漸減姮娥面，徐收楚練機。","卞疑雕璧碎，潘感竟牀稀。","捐篋辭班女，潛波蔽虙妃。","氛埃誰定滅，蟾兔杳難希。","須遣圓明盡，良嗟造化非。","如能付刀尺，別爲創璿璣。"]', '["蓂葉標新朔，霜豪引細輝。","白眉驚半隐，虹勢訝全微。","涼魄潭空洞，虛弓雁畏威。","上弦何汲汲，佳色轉依依。","綺幕殘灯斂，妝楼破镜飞。","玲瓏穿竹樹，岑寂思幈幃。","坐愛規將合，行看望已幾。","絳河冰鑑朗，黄道玉輪巍。","迥照偏瓊砌，餘光借粉闈。","泛池相皎潔，壓桂共芳菲。","的的當歌扇，娟娟透舞衣。","殷勤入懷什，懇款墮云圻。","素液傳烘盞，鳴琴薦碧徽。","椒房深肅肅，蘭路靄霏霏。","翡翠通簾影，琉璃瑩殿扉。","西园筵玳瑁，东壁射蛜蝛。","老將占天陣，幽人釣石磯。","荷鋤元亮息，回櫂子猷归。","迢遞同千里，孤高淨九圍。","從星作风雨，配日丽旌旗。","麟鬬寧徒設，蠅声豈浪譏。","司存委卿士，新拜出郊畿。","今古雖云極，虧盈不易違。","珠胎方夜满，清露忍朝晞。","漸減姮娥面，徐收楚練機。","卞疑雕璧碎，潘感竟牀稀。","捐篋辞班女，潛波蔽虙妃。","氛埃誰定滅，蟾兔杳难希。","須遣圓明尽，良嗟造化非。","如能付刀尺，別爲創璿璣。"]', '诗', 'shi', '', NULL, '月三十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8847586-067b-4b68-a2fc-740b860e11c1', '飲致用神麴酒三十韻', '饮致用神麴酒三十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["七月調神麴，三春釀綠醽。","雕鐫荆玉盞，烘透內丘缾。","試滴盤心露，疑添案上螢。","滿尊凝止水，祝地落繁星。","翻陋瓊漿濁，唯聞石髓馨。","冰壺通角簟，金鏡徹雲屏。","雪暎煙光薄，霜涵霽色泠。","蚌珠懸皎皛，桂魄倒瀴溟。","晝灑蟬將飲，宵揮鶴誤聆。","琉璃驚太白，鍾乳訝微青。","詎敢辭濡首，幷憐可鑒形。","行當遣俗累，便得造禪扃。","何憚說千日，甘從過百齡。","但令長泛蟻，無復恨漂萍。","膽壯還增氣，機忘反自冥。","甕眠思畢卓，糟籍憶劉伶。","髣髴中聖日，希夷夾大庭。","眼前須底物，座右任他銘。","刮骨都無痛，如泥未擬停。","殘觴猶漠漠，華燭已熒熒。","真性臨時見，狂歌半睡聽。","喧闐爭意氣，調笑學娉婷。","酩酊焉知極，羇離忽暫寧。","雞聲催欲曙，蟾影照初醒。","咽絕鵑啼竹，蕭撩雁去汀。","遙城傳漏箭，鄉寺響風鈴。","楚澤一爲梗，堯階屢變蓂。","醉荒非獨此，愁夢幾曾經。","每恥窮途哭，今那客淚零。","感君澄醴酒，不遣渭和涇。"]', '["七月調神麴，三春釀綠醽。","雕鐫荆玉盞，烘透內丘缾。","試滴盤心露，疑添案上螢。","满尊凝止水，祝地落繁星。","翻陋瓊漿濁，唯闻石髓馨。","冰壺通角簟，金镜徹云屏。","雪暎煙光薄，霜涵霽色泠。","蚌珠懸皎皛，桂魄倒瀴溟。","晝灑蟬將饮，宵揮鹤誤聆。","琉璃驚太白，鍾乳訝微青。","詎敢辞濡首，幷怜可鑒形。","行當遣俗累，便得造禪扃。","何憚说千日，甘從過百齡。","但令长泛蟻，無复恨漂萍。","膽壯還增氣，機忘反自冥。","甕眠思畢卓，糟籍憶劉伶。","髣髴中聖日，希夷夾大庭。","眼前須底物，座右任他銘。","刮骨都無痛，如泥未擬停。","殘觴猶漠漠，华燭已熒熒。","真性臨时见，狂歌半睡听。","喧闐爭意氣，調笑学娉婷。","酩酊焉知極，羇離忽暫寧。","雞声催欲曙，蟾影照初醒。","咽絕鵑啼竹，蕭撩雁去汀。","遙城傳漏箭，乡寺响风鈴。","楚澤一爲梗，堯階屢变蓂。","醉荒非独此，愁梦幾曾經。","每恥窮途哭，今那客泪零。","感君澄醴酒，不遣渭和涇。"]', '诗', 'shi', '', NULL, '飲致用神麴酒三十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1734c10-cff7-42c7-8763-0b04378a3864', '感石榴二十韻', '感石榴二十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何年安石國，萬里貢榴花。","迢遞河源道，因依漢使槎。","酸辛犯蔥嶺，顦顇涉龍沙。","初到摽珍木，多來比亂麻。","深拋故園裏，少種貴人家。","唯我荆州見，憐君胡地賒。","從教當路長，兼恣入檐斜。","綠葉裁煙翠，紅英動日華。","新簾帬透影，疎牖燭籠紗。","委作金爐燄，飄成玉砌瑕。","乍驚珠綴密，終誤繡幃奢。","琥珀烘梳碎，燕支嬾頰塗。","風翻一樹火，電轉五雲車。","絳帳迎宵日，芙蕖綻早牙。","淺深俱隱映，前後各分葩。","宿露低蓮臉，朝光借綺霞。","暗虹徒繳繞，濯錦莫周遮。","俗態能嫌舊，芳姿尚可嘉。","非專愛顏色，同恨阻幽遐。","滿眼思鄉淚，相嗟亦自嗟。"]', '["何年安石国，万里貢榴花。","迢遞河源道，因依漢使槎。","酸辛犯蔥嶺，顦顇涉龙沙。","初到摽珍木，多来比亂麻。","深拋故园裏，少種貴人家。","唯我荆州见，怜君胡地賒。","從教當路长，兼恣入檐斜。","綠葉裁煙翠，紅英动日华。","新簾帬透影，疎牖燭籠紗。","委作金爐燄，飄成玉砌瑕。","乍驚珠綴密，終誤繡幃奢。","琥珀烘梳碎，燕支嬾頰塗。","风翻一樹火，電轉五云车。","絳帳迎宵日，芙蕖綻早牙。","淺深俱隐映，前後各分葩。","宿露低蓮臉，朝光借綺霞。","暗虹徒繳繞，濯錦莫周遮。","俗態能嫌旧，芳姿尚可嘉。","非專愛顏色，同恨阻幽遐。","满眼思乡泪，相嗟亦自嗟。"]', '诗', 'shi', '', NULL, '感石榴二十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fb84b33-da4d-4bb9-bb7d-9bfeab08608b', '度門寺', '度门寺', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["北祖三禪地，西山萬樹松。","門臨溪一帶，橋映竹千重。","翦鑿基階正，包藏景氣濃。","諸巖分院宇，雙嶺抱垣墉。","舍利開層墖，香爐占小峰。","道場居士置，經藏大師封。","太子知栽植，神王守要衝。","由旬排講座，丈六寫真容。","佛語迦陵說，僧行猛虎從。","修羅擡日拒，樓至拔霜鋒。","畫井垂枯朽，穿池救噞喁。","蕉非難敗壞，槿喻暫丰茸。","寶界留遺事，金棺滅去蹤。","鉢傳烘瑪瑙，石長翠芙蓉。","影帳紗全落，繩牀土半壅。","荒林迷醉象，危壁亞盤龍。","行色憐初月，歸程待曉鐘。","心源雖了了，塵世苦憧憧。","宿蔭高聲懺，齋糧幷力舂。","他生再來此，還願總相逢。"]', '["北祖三禪地，西山万樹松。","门臨溪一带，橋映竹千重。","翦鑿基階正，包藏景氣濃。","諸巖分院宇，雙嶺抱垣墉。","舍利开層墖，香爐占小峰。","道場居士置，經藏大師封。","太子知栽植，神王守要衝。","由旬排講座，丈六寫真容。","佛語迦陵说，僧行猛虎從。","修羅擡日拒，楼至拔霜鋒。","畫井垂枯朽，穿池救噞喁。","蕉非难敗壞，槿喻暫丰茸。","寶界留遺事，金棺滅去蹤。","鉢傳烘瑪瑙，石长翠芙蓉。","影帳紗全落，繩牀土半壅。","荒林迷醉象，危壁亞盤龙。","行色怜初月，归程待晓鐘。","心源雖了了，塵世苦憧憧。","宿蔭高声懺，斋糧幷力舂。","他生再来此，還願總相逢。"]', '诗', 'shi', '', NULL, '度門寺 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e26451-3be1-460a-9f1d-e17607290640', '大雲寺二十韻', '大云寺二十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["地勝宜臺殿，山晴離垢氛。","現身千佛國，護世四王軍。","碧耀高樓瓦，赬飛半壁文。","鶴林縈古道，雁墖沒歸雲。","幡影中天颺，鐘聲下界聞。","攀蘿極峰頂，游目到江濆。","馴鴿閑依綴，調猿靜守羣。","虎行風捷獵，龍睡氣氛氳。","穫稻禪衣卷，燒畬劫火焚。","新英蜂采掇，荒草象耕耘。","鉢付靈童洗，香教善女熏。","果枝低罯罯，花雨澤雰雰。","示化維摩疾，降魔力士勳。","聽經神變見，說偈鳥紛紜。","上境光猶在，深谿暗不分。","竹籠煙欲暝，松帶日餘曛。","真諦成知別，迷心尚有云。","多生沈五蘊，宿習樂三墳。","諭鹿車雖設，如蠶緒正棼。","且將平等義，還奉聖明君。"]', '["地勝宜台殿，山晴離垢氛。","現身千佛国，護世四王軍。","碧耀高楼瓦，赬飞半壁文。","鹤林縈古道，雁墖沒归云。","幡影中天颺，鐘声下界闻。","攀蘿極峰頂，游目到江濆。","馴鴿闲依綴，調猿静守羣。","虎行风捷獵，龙睡氣氛氳。","穫稻禪衣卷，燒畬劫火焚。","新英蜂采掇，荒草象耕耘。","鉢付靈童洗，香教善女熏。","果枝低罯罯，花雨澤雰雰。","示化維摩疾，降魔力士勳。","听經神变见，说偈鸟紛紜。","上境光猶在，深谿暗不分。","竹籠煙欲暝，松带日餘曛。","真諦成知別，迷心尚有云。","多生沈五蘊，宿習乐三墳。","諭鹿车雖設，如蠶緒正棼。","且將平等義，還奉聖明君。"]', '诗', 'shi', '', NULL, '大雲寺二十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c83743-6442-49fb-b288-203753683560', '和友封題開善寺十韻', '和友封題开善寺十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["梁王開佛廟，雲構歲時遙。","珠綴飛閑鴿，紅泥落碎椒。","燈籠青燄短，香印白灰銷。","古匣收遺施，行廊畫本朝。","藏經霑雨爛，魔女捧花嬌。","亞樹牽藤閣，橫查壓石橋。","竹荒新筍細，池淺小魚跳。","匠正琉璃瓦，僧鋤芍藥苗。","旋蒸茶嫩葉，偏把柳長條。","便欲忘歸路，方知隱易招。"]', '["梁王开佛廟，云構歲时遙。","珠綴飞闲鴿，紅泥落碎椒。","灯籠青燄短，香印白灰銷。","古匣收遺施，行廊畫本朝。","藏經霑雨爛，魔女捧花嬌。","亞樹牽藤閣，橫查壓石橋。","竹荒新筍細，池淺小鱼跳。","匠正琉璃瓦，僧鋤芍藥苗。","旋蒸茶嫩葉，偏把柳长條。","便欲忘归路，方知隐易招。"]', '诗', 'shi', '', NULL, '和友封題開善寺十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9126df60-fdbd-4366-a7de-737c8008ab7d', '牡丹二首 一', '牡丹二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["簇蘂風頻壞，裁紅雨更新。","眼看吹落地，便別一年春。"]', '["簇蘂风頻壞，裁紅雨更新。","眼看吹落地，便別一年春。"]', '诗', 'shi', '', NULL, '牡丹二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c57e3942-d51e-4d6c-af57-0993269f0ed8', '牡丹二首 二', '牡丹二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["繁綠陰全合，衰紅展漸難。","風光一擡舉，猶得暫時看。"]', '["繁綠陰全合，衰紅展漸难。","风光一擡舉，猶得暫时看。"]', '诗', 'shi', '', NULL, '牡丹二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec33550f-5cd0-433f-ab85-a86a288eeeab', '象人', '象人', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["被色空成象，觀空色異真。","自悲人是假，那復假爲人。"]', '["被色空成象，观空色異真。","自悲人是假，那复假爲人。"]', '诗', 'shi', '', NULL, '象人 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6b9f2e8-6fd8-4b1c-9492-b6c5cd780ada', '與楊十二巨源盧十九經濟同遊大安亭各賦二物各爲五韻探得松石', '與楊十二巨源盧十九經濟同游大安亭各賦二物各爲五韻探得松石', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["片石與孤松，曾經物外逢。","月臨棲鶴影，雲抱老人峰。","蜀客君當問，秦官我舊封。","積膏當琥珀，新劫長芙蓉。","待補蒼蒼去，樛柯早變龍。"]', '["片石與孤松，曾經物外逢。","月臨棲鹤影，云抱老人峰。","蜀客君當问，秦官我旧封。","積膏當琥珀，新劫长芙蓉。","待補蒼蒼去，樛柯早变龙。"]', '诗', 'shi', '', NULL, '與楊十二巨源盧十九經濟同遊大安亭各賦二物各爲五韻探得松石 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98cf143d-0917-47aa-8a24-ce3db79ce765', '賦得春雪映早梅', '賦得春雪映早梅', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["飛舞先春雪，因依上番梅。","一枝方漸秀，六出已同開。","積素光逾密，真花節暗催。","摶風飄不散，見晛忽偏摧。","郢曲琴空奏，羌音笛自哀。","今朝兩成詠，翻挾昔人才。"]', '["飞舞先春雪，因依上番梅。","一枝方漸秀，六出已同开。","積素光逾密，真花節暗催。","摶风飄不散，见晛忽偏摧。","郢曲琴空奏，羌音笛自哀。","今朝兩成詠，翻挾昔人才。"]', '诗', 'shi', '', NULL, '賦得春雪映早梅 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('012cfe29-e025-4b76-97ad-b096c3c25975', '賦得玉巵無當', '賦得玉巵無當', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["共惜連城寶，翻成無當巵。","詎慙君子貴，深訝巧工隳。","泛蟻功全小，如虹色不移。","可憐殊礫石，何計辨糟醨。","江海誠難滿，盤筵莫忘施。","縱乖斟酌意，猶得對光儀。"]', '["共惜連城寶，翻成無當巵。","詎慙君子貴，深訝巧工隳。","泛蟻功全小，如虹色不移。","可怜殊礫石，何計辨糟醨。","江海誠难满，盤筵莫忘施。","縱乖斟酌意，猶得对光儀。"]', '诗', 'shi', '', NULL, '賦得玉巵無當 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac18257-d38e-4150-a334-fd228d6a3bd3', '賦得數蓂', '賦得數蓂', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["將課司天曆，先觀近砌蓂。","一旬開應月，五日數從星。","桂滿叢初合，蟾虧影漸零。","辨時長有素，數閏或餘青。","墜葉推前事，新芽察未形。","堯年始今歲，方欲瑞千齡。"]', '["將課司天曆，先观近砌蓂。","一旬开應月，五日數從星。","桂满叢初合，蟾虧影漸零。","辨时长有素，數閏或餘青。","墜葉推前事，新芽察未形。","堯年始今歲，方欲瑞千齡。"]', '诗', 'shi', '', NULL, '賦得數蓂 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd96aa7d-7490-44c0-8c76-f9499f44b62a', '賦得九月盡', '賦得九月尽', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["霜降三旬後，蓂餘一葉秋。","玄陰迎落日，涼魄盡殘釣。","半夜灰移琯，明朝帝御裘。","潘安過今夕，休詠賦中愁。"]', '["霜降三旬後，蓂餘一葉秋。","玄陰迎落日，涼魄尽殘釣。","半夜灰移琯，明朝帝御裘。","潘安過今夕，休詠賦中愁。"]', '诗', 'shi', '', NULL, '賦得九月盡 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ef0c6f-d36b-4825-9659-120c77e2bec5', '賦得雨後花', '賦得雨後花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紅芳憐靜色，深與雨相宜。","餘滴下纖蘂，殘珠墮細枝。","浣花江上思，啼粉鏡中窺。","念此低回久，風光幸一吹。"]', '["紅芳怜静色，深與雨相宜。","餘滴下纖蘂，殘珠墮細枝。","浣花江上思，啼粉镜中窺。","念此低回久，风光幸一吹。"]', '诗', 'shi', '', NULL, '賦得雨後花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c609eb2-61d7-4af4-9233-bfe611c6edfa', '早歸', '早归', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春靜曉風微，凌晨帶酒歸。","遠山籠宿霧，高樹影朝暉。","飲馬魚驚水，穿花露滴衣。","嬌鶯似相惱，含囀傍人飛。"]', '["春静晓风微，凌晨带酒归。","远山籠宿霧，高樹影朝暉。","饮马鱼驚水，穿花露滴衣。","嬌鶯似相惱，含囀傍人飞。"]', '诗', 'shi', '', NULL, '早歸 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('798fd01e-5640-491a-b856-20f3f58be019', '晚秋', '晚秋', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["竹露滴寒聲，離人曉思驚。","酒醒秋簟冷，風急夏衣輕。","寢倦解幽夢，慮閑添遠情。","誰憐獨欹枕，斜月透窗明。"]', '["竹露滴寒声，離人晓思驚。","酒醒秋簟冷，风急夏衣轻。","寢倦解幽梦，慮闲添远情。","誰怜独欹枕，斜月透窗明。"]', '诗', 'shi', '', NULL, '晚秋 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dad4f0cb-e7a1-4cde-877e-a181b7c8b7d7', '送林復夢赴韋令辟', '送林复梦赴韋令辟', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蜀路危於劒，憐君自坦途。","幾回曾啖炙，千里遠銜珠。","野性便荒飲，時風忌酒徒。","相門多禮讓，前後莫相踰。"]', '["蜀路危於劒，怜君自坦途。","幾回曾啖炙，千里远銜珠。","野性便荒饮，时风忌酒徒。","相门多禮讓，前後莫相踰。"]', '诗', 'shi', '', NULL, '送林復夢赴韋令辟 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9599c93-9d2d-4ca0-9ff3-1ee8df809789', '憶楊十二', '憶楊十二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["楊子愛言詩，春天好詠時。","戀花從馬滯，聯句放杯遲。","日映含煙竹，風牽臥柳絲。","南山更多興，須作白雲期。"]', '["楊子愛言诗，春天好詠时。","戀花從马滯，聯句放杯遲。","日映含煙竹，风牽臥柳絲。","南山更多兴，須作白云期。"]', '诗', 'shi', '', NULL, '憶楊十二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a095532-df23-4c16-b7d7-02dd9fc3e563', '夜合', '夜合', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["綺樹滿朝陽，融融有露光。","雨多疑濯錦，風散似分妝。","葉密煙蒙火，枝低繡拂牆。","更憐當暑見，留詠日偏長。"]', '["綺樹满朝陽，融融有露光。","雨多疑濯錦，风散似分妝。","葉密煙蒙火，枝低繡拂牆。","更怜當暑见，留詠日偏长。"]', '诗', 'shi', '', NULL, '夜合 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f19beb4c-5135-4a1c-8534-3945c8430474', '新竹', '新竹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["新篁纔解籜，寒色已青蔥。","冉冉偏凝粉，蕭蕭漸引風。","扶疎多透日，寥落未成叢。","惟有團團節，堅貞大小同。"]', '["新篁纔解籜，寒色已青蔥。","冉冉偏凝粉，蕭蕭漸引风。","扶疎多透日，寥落未成叢。","惟有團團節，堅貞大小同。"]', '诗', 'shi', '', NULL, '新竹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7eac3f3-b918-4887-885d-d49e71f8764a', '秋相望', '秋相望', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["檐月驚殘夢，浮涼滿夏衾。","蠨蛸低戶網，螢火度牆陰。","爐暗燈光短，牀空帳影深。","此時相望久，高樹憶橫岑。"]', '["檐月驚殘梦，浮涼满夏衾。","蠨蛸低戶網，螢火度牆陰。","爐暗灯光短，牀空帳影深。","此时相望久，高樹憶橫岑。"]', '诗', 'shi', '', NULL, '秋相望 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac5ab62-cc19-4f32-9667-4ed0077ee6c3', '春病', '春病', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["病來閑臥久，因見靜時心。","殘月曉窗迥，落花幽院深。","望山移坐榻，行藥步牆陰。","車馬門前度，遙聞哀苦吟。"]', '["病来闲臥久，因见静时心。","殘月晓窗迥，落花幽院深。","望山移坐榻，行藥步牆陰。","车马门前度，遙闻哀苦吟。"]', '诗', 'shi', '', NULL, '春病 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30c10188-d6da-4384-a219-25b8bf00bff8', '山竹枝', '山竹枝', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["深院虎溪竹，遠公身自栽。","多慙折君節，扶我出山來。","貴宅安危步，難將混俗材。","還投輞川水，從作老龍回。"]', '["深院虎溪竹，远公身自栽。","多慙折君節，扶我出山来。","貴宅安危步，难將混俗材。","還投輞川水，從作老龙回。"]', '诗', 'shi', '', NULL, '山竹枝 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d086a93-0b1d-4a07-a994-6e76198a17d6', '悟禪三首寄胡果 一', '悟禪三首寄胡果 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["近聞胡隱士，潛認得心王。","不恨百年促，翻悲萬劫長。","有修終有限，無事亦無殃。","慎莫通方便，應機不頓忘。"]', '["近闻胡隐士，潛認得心王。","不恨百年促，翻悲万劫长。","有修終有限，無事亦無殃。","慎莫通方便，應機不頓忘。"]', '诗', 'shi', '', NULL, '悟禪三首寄胡果 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b7ae190-430b-47fa-99a4-3c5dfaf383df', '悟禪三首寄胡果 二', '悟禪三首寄胡果 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["百年都幾日，何事苦囂然。","晚歲倦爲學，閑心易到禪。","病宜多宴坐，貧似少攀緣。","自笑無名字，因名自在天。"]', '["百年都幾日，何事苦囂然。","晚歲倦爲学，闲心易到禪。","病宜多宴坐，貧似少攀緣。","自笑無名字，因名自在天。"]', '诗', 'shi', '', NULL, '悟禪三首寄胡果 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d6865db-c817-450d-9c4f-42b95c941275', '悟禪三首寄胡果 三', '悟禪三首寄胡果 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["近見新章句，因知見在心。","春游晉祠水，晴上霍山岑。","問法僧當偈，還丹客贈金。","莫驚頭欲白，禪觀老彌深。"]', '["近见新章句，因知见在心。","春游晉祠水，晴上霍山岑。","问法僧當偈，還丹客贈金。","莫驚头欲白，禪观老彌深。"]', '诗', 'shi', '', NULL, '悟禪三首寄胡果 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b21fcf-2c71-4ade-b6dd-744e6618accf', '東臺去', '东台去', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["陶君喜不遇，予每爲君言。","今日東臺去，澄心在陸渾。","旋抽隨日俸，幷買近山園。","千萬崔兼白，殷勤承主恩。"]', '["陶君喜不遇，予每爲君言。","今日东台去，澄心在陸渾。","旋抽隨日俸，幷買近山园。","千万崔兼白，殷勤承主恩。"]', '诗', 'shi', '', NULL, '東臺去 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1764691-f3e8-453a-b9c8-ec3dfa2e27c8', '戴光弓', '戴光弓', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["潞府筋角勁，戴光因合成。","因君懷膽氣，贈我定交情。","不擬閑穿葉，那能枉始生。","唯調一隻箭，飛入破聊城。"]', '["潞府筋角勁，戴光因合成。","因君懷膽氣，贈我定交情。","不擬闲穿葉，那能枉始生。","唯調一隻箭，飞入破聊城。"]', '诗', 'shi', '', NULL, '戴光弓 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89403a0f-4a7e-496f-980b-ab261d5a1d0e', '劉頗詩', '劉頗诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["一言感激士，三世義忠臣。","破甕嫌妨路，燒莊恥屬人。","迥分遼海氣，閑蹋洛陽塵。","儻使權由我，還君白馬津。"]', '["一言感激士，三世義忠臣。","破甕嫌妨路，燒莊恥屬人。","迥分遼海氣，闲蹋洛陽塵。","儻使權由我，還君白马津。"]', '诗', 'shi', '', NULL, '劉頗詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd9d3425-7ad3-42c0-aca0-c8328a19d8c7', '夜飲', '夜饮', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["燈火隔簾明，竹梢風雨聲。","詩篇隨意贈，杯酒越巡行。","漫唱江朝曲，閑徵藥草名。","莫辭終夜飲，朝起又營營。"]', '["灯火隔簾明，竹梢风雨声。","诗篇隨意贈，杯酒越巡行。","漫唱江朝曲，闲徵藥草名。","莫辞終夜饮，朝起又營營。"]', '诗', 'shi', '', NULL, '夜飲 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80c921a7-8d8a-4e92-9952-49bf6e5654d3', '襃城驛', '襃城驛', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["嚴秦修此驛，兼漲驛前池。","已種千竿竹，又栽千樹棃。","四年三月半，新筍晚花時。","悵望東川去，等閑題作詩。"]', '["嚴秦修此驛，兼漲驛前池。","已種千竿竹，又栽千樹棃。","四年三月半，新筍晚花时。","悵望东川去，等闲題作诗。"]', '诗', 'shi', '', NULL, '襃城驛 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c91be134-8bc6-4a1b-8577-021ce2f8abc4', '閑二首 一', '闲二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["晻澹洲煙白，籬篩日脚紅。","江喧過雲雨，船泊打頭風。","艇子收魚市，鴉兒噪荻叢。","不堪堤上立，滿眼是蚊蟲。"]', '["晻澹洲煙白，籬篩日脚紅。","江喧過云雨，船泊打头风。","艇子收鱼市，鴉兒噪荻叢。","不堪堤上立，满眼是蚊蟲。"]', '诗', 'shi', '', NULL, '閑二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('259c50f9-2131-4404-a442-35bd3b70e6c3', '閑二首 二', '闲二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["青衫經夏黕，白髮望鄉稠。","雨冷新秋簟，星稀欲曙樓。","連鴻盡南去，雙鯉本東流。","北信無人寄，蟬聲滿樹頭。"]', '["青衫經夏黕，白髮望乡稠。","雨冷新秋簟，星稀欲曙楼。","連鴻尽南去，雙鯉本东流。","北信無人寄，蟬声满樹头。"]', '诗', 'shi', '', NULL, '閑二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('873d6894-bc6d-447d-8042-7a8847e0f44a', '欲曙', '欲曙', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["江隄閱暗流，漏鼓急殘籌。","片月低城堞，稀星轉角樓。","鶴媒華表上，{篦𥫗+鳥}鵊柳枝頭。","不爲來趨府，何因欲曙遊。"]', '["江隄閱暗流，漏鼓急殘籌。","片月低城堞，稀星轉角楼。","鹤媒华表上，{篦𥫗+鸟}鵊柳枝头。","不爲来趨府，何因欲曙游。"]', '诗', 'shi', '', NULL, '欲曙 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd7ec50-36c9-4c76-bba5-d1abc18c15cd', '寄胡靈之', '寄胡靈之', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["早歲顛狂伴，城中共幾年。","有時潛步出，連夜小亭眠。","月影侵牀上，花叢在眼前。","今宵正風雨，空宅楚江邊。"]', '["早歲顛狂伴，城中共幾年。","有时潛步出，連夜小亭眠。","月影侵牀上，花叢在眼前。","今宵正风雨，空宅楚江邊。"]', '诗', 'shi', '', NULL, '寄胡靈之 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64167d4a-dae8-4bd9-8725-6f2a2fd0334b', '夜雨', '夜雨', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["水怪潛幽草，江雲擁廢居。","雷驚空屋柱，電照滿牀書。","竹瓦風頻裂，茅檐雨漸疎。","平生滄海意，此去怯爲魚。"]', '["水怪潛幽草，江云擁廢居。","雷驚空屋柱，電照满牀书。","竹瓦风頻裂，茅檐雨漸疎。","平生滄海意，此去怯爲鱼。"]', '诗', 'shi', '', NULL, '夜雨 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a1f6e57-20f4-4ff9-922d-8aac1a118229', '酬李六醉後見寄口號', '酬李六醉後见寄口號', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["頓愈頭風疾，因吟口號詩。","文章紛似繡，珠玉布如棊。","健羨觥飛酒，蒼黃日映籬。","命童寒色倦，撫穉晚啼飢。","潦倒慙相識，平生頗自奇。","明公將有問，林下是靈龜。"]', '["頓愈头风疾，因吟口號诗。","文章紛似繡，珠玉布如棊。","健羨觥飞酒，蒼黄日映籬。","命童寒色倦，撫穉晚啼飢。","潦倒慙相識，平生頗自奇。","明公將有问，林下是靈龟。"]', '诗', 'shi', '', NULL, '酬李六醉後見寄口號 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0acb89-0bc3-4682-87a2-701cc0494fbc', '歸田', '归田', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["陶君三十七，挂綬出都門。","我亦今年去，商山淅岸邨。","冬修方丈室，春種桔橰園。","千萬人間事，從茲不復言。"]', '["陶君三十七，挂綬出都门。","我亦今年去，商山淅岸邨。","冬修方丈室，春種桔橰园。","千万人间事，從茲不复言。"]', '诗', 'shi', '', NULL, '歸田 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7642989a-74c8-4e46-8ab1-3c0b3b97aa95', '緣路', '緣路', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["總是玲瓏竹，兼藏淺漫溪。","沙平深見底，石亂不成泥。","煙火遙邨落，桑麻隔稻畦。","此中如有問，甘被到頭迷。"]', '["總是玲瓏竹，兼藏淺漫溪。","沙平深见底，石亂不成泥。","煙火遙邨落，桑麻隔稻畦。","此中如有问，甘被到头迷。"]', '诗', 'shi', '', NULL, '緣路 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b96ab4-54a6-4083-bd94-3147ec1b07e6', '誚盧戡與予數約遊三寺戡獨沈醉而不行', '誚盧戡與予數約游三寺戡独沈醉而不行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["乘興無羈束，閑行信馬蹄。","路幽穿竹遠，野迥望雲低。","素帚茅花亂，圓珠稻實齊。","如何盧進士，空戀醉如泥。"]', '["乘兴無羈束，闲行信马蹄。","路幽穿竹远，野迥望云低。","素帚茅花亂，圓珠稻實齊。","如何盧進士，空戀醉如泥。"]', '诗', 'shi', '', NULL, '誚盧戡與予數約遊三寺戡獨沈醉而不行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f918b6f5-8cd9-468c-b3a9-0e192436a66f', '遣春三首 一', '遣春三首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["楊公三不惑，我惑兩般全。","逢酒判身病，拈花盡意憐。","水生低岸沒，梅蹙小珠連。","千萬紅顏輩，須驚又一年。"]', '["楊公三不惑，我惑兩般全。","逢酒判身病，拈花尽意怜。","水生低岸沒，梅蹙小珠連。","千万紅顏輩，須驚又一年。"]', '诗', 'shi', '', NULL, '遣春三首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1630277-c5c5-42d3-b5c9-190f346c00ce', '遣春三首 二', '遣春三首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["柳眼開渾盡，梅心動已闌。","風光好時少，杯酒病中難。","學問慵都廢，聲名老更判。","唯餘看花伴，未免憶長安。"]', '["柳眼开渾尽，梅心动已闌。","风光好时少，杯酒病中难。","学问慵都廢，声名老更判。","唯餘看花伴，未免憶长安。"]', '诗', 'shi', '', NULL, '遣春三首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ac218bc-c596-4eba-822c-e42344cf124f', '遣春三首 三', '遣春三首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["失却遊花伴，因風浪引將。","柳堤遙認馬，梅徑誤尋香。","晚景行看謝，春心漸欲狂。","園林都不到，何處枉風光。"]', '["失却游花伴，因风浪引將。","柳堤遙認马，梅徑誤尋香。","晚景行看謝，春心漸欲狂。","园林都不到，何处枉风光。"]', '诗', 'shi', '', NULL, '遣春三首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da350090-e297-4f80-8fd3-3d440b97f166', '歲日', '歲日', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["一日今年始，一年前事空。","淒涼百年事，應與一年同。"]', '["一日今年始，一年前事空。","淒涼百年事，應與一年同。"]', '诗', 'shi', '', NULL, '歲日 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7dcb73d-37ac-4df5-858b-ea11bfcab662', '湘南登臨湘樓', '湘南登臨湘楼', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["高處望瀟湘，花時萬井香。","雨餘憐日嫩，歲閏覺春長。","霞剎分危牓，煙波透遠光。","情知樓上好，不是仲宣鄉。"]', '["高处望瀟湘，花时万井香。","雨餘怜日嫩，歲閏覺春长。","霞剎分危牓，煙波透远光。","情知楼上好，不是仲宣乡。"]', '诗', 'shi', '', NULL, '湘南登臨湘樓 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f01afb00-59b5-484a-b2f3-e76bb1717686', '晚宴湘亭', '晚宴湘亭', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["晚日宴清湘，晴空走豔陽。","花低愁露醉，絮起覺春狂。","舞旋紅裙急，歌垂碧袖長。","甘心出童羖，須一盡時荒。"]', '["晚日宴清湘，晴空走豔陽。","花低愁露醉，絮起覺春狂。","舞旋紅裙急，歌垂碧袖长。","甘心出童羖，須一尽时荒。"]', '诗', 'shi', '', NULL, '晚宴湘亭 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a3cb0d0-89e9-4dc4-bca0-da2bc61718f7', '酒醒', '酒醒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["飲醉日將盡，醒時夜已闌。","暗燈風燄曉，春席水窗寒。","未解縈身帶，猶傾墜枕冠。","呼兒問狼藉，疑是夢中歡。"]', '["饮醉日將尽，醒时夜已闌。","暗灯风燄晓，春席水窗寒。","未解縈身带，猶傾墜枕冠。","呼兒问狼藉，疑是梦中歡。"]', '诗', 'shi', '', NULL, '酒醒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc2316f-aced-4ab3-a30a-41e8c1b5d6e0', '獨遊', '独游', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["遠地難逢侶，閑人且獨行。","上山隨老鶴，接酒待殘鸎。","花當西施面，泉勝衛玠清。","鵜鶘滿春野，無限好同聲。"]', '["远地难逢侶，闲人且独行。","上山隨老鹤，接酒待殘鸎。","花當西施面，泉勝衛玠清。","鵜鶘满春野，無限好同声。"]', '诗', 'shi', '', NULL, '獨遊 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67c3da71-0821-41bf-a3db-ca498688fb4b', '洞庭湖', '洞庭湖', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["人生除泛海，便到洞庭波。","駕浪沉西日，吞空接曙河。","虞巡竟安在，軒樂詎曾過。","唯有君山下，狂風萬古多。"]', '["人生除泛海，便到洞庭波。","駕浪沉西日，吞空接曙河。","虞巡竟安在，軒乐詎曾過。","唯有君山下，狂风万古多。"]', '诗', 'shi', '', NULL, '洞庭湖 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51974ef1-b8d8-4166-baca-7d4b9e8c147b', '雪天', '雪天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["故鄉千里夢，往事萬重悲。","小雪沈陰夜，閑窗老病時。","獨聞歸去鴈，偏詠別來詩。","慚愧紅妝女，頻驚兩鬢絲。"]', '["故乡千里梦，往事万重悲。","小雪沈陰夜，闲窗老病时。","独闻归去鴈，偏詠別来诗。","慚愧紅妝女，頻驚兩鬢絲。"]', '诗', 'shi', '', NULL, '雪天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9cb9e32-4eac-41f3-a19a-52a4f044a04c', '贈熊士登', '贈熊士登', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["平生本多思，況復老逢春。","今日梅花下，他鄉值故人。"]', '["平生本多思，況复老逢春。","今日梅花下，他乡值故人。"]', '诗', 'shi', '', NULL, '贈熊士登 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30cc1776-1373-48e5-b49d-c67fde633d71', '別嶺南熊判官', '別嶺南熊判官', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["十年常遠道，不忍別離聲。","況復三巴外，仍逢萬里行。","桐花新雨氣，梨葉晚春晴。","到海知何日，風波從此生。"]', '["十年常远道，不忍別離声。","況复三巴外，仍逢万里行。","桐花新雨氣，梨葉晚春晴。","到海知何日，风波從此生。"]', '诗', 'shi', '', NULL, '別嶺南熊判官 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca73e2e5-6e5a-438e-a481-372a8831d7ce', '水上寄樂天', '水上寄乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["眼前明月水，先入漢江流。","漢水流江海，西江過庾樓。","庾樓今夜月，君豈在樓頭。","萬一樓頭望，還應望我愁。"]', '["眼前明月水，先入漢江流。","漢水流江海，西江過庾楼。","庾楼今夜月，君豈在楼头。","万一楼头望，還應望我愁。"]', '诗', 'shi', '', NULL, '水上寄樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93def192-bc98-416c-9057-3664a224bede', '夏陽亭臨望寄河陽侍御堯', '夏陽亭臨望寄河陽侍御堯', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["望遠音書絕，臨川意緒長。","殷勤眼前水，千里到河陽。"]', '["望远音书絕，臨川意緒长。","殷勤眼前水，千里到河陽。"]', '诗', 'shi', '', NULL, '夏陽亭臨望寄河陽侍御堯 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1351b044-b89a-4fc3-85e3-d9e17297f0ed', '日高睡', '日高睡', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["隔是身如夢，頻來不爲名。","憐君近南住，時得到山行。"]', '["隔是身如梦，頻来不爲名。","怜君近南住，时得到山行。"]', '诗', 'shi', '', NULL, '日高睡 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2360a884-4907-4da4-93e1-3ebc4dc3c053', '輞川', '輞川', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["世累爲身累，閑忙不自由。","殷勤輞川水，何事出山流。"]', '["世累爲身累，闲忙不自由。","殷勤輞川水，何事出山流。"]', '诗', 'shi', '', NULL, '輞川 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba94648-c512-4152-b3a1-3a5f4e53b4d5', '天壇歸', '天壇归', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["爲結區中累，因辭洞裏花。","還來舊城郭，煙火萬人家。"]', '["爲結區中累，因辞洞裏花。","還来旧城郭，煙火万人家。"]', '诗', 'shi', '', NULL, '天壇歸 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('716d0de3-1d63-44c7-adc2-6632a34c7857', '雨後', '雨後', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["倦寢數殘更，孤燈暗又明。","竹梢餘雨重，時復拂簾驚。"]', '["倦寢數殘更，孤灯暗又明。","竹梢餘雨重，时复拂簾驚。"]', '诗', 'shi', '', NULL, '雨後 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d715a486-a4c6-4694-b408-9dae3ecd8707', '晴日', '晴日', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["多病苦虛羸，晴明強展眉。","讀書心緒少，閑臥日長時。"]', '["多病苦虛羸，晴明強展眉。","读书心緒少，闲臥日长时。"]', '诗', 'shi', '', NULL, '晴日 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ad9a59-b634-4fd1-a0f5-eeefc89443d9', '直臺', '直台', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["麋入神羊隊，烏驚海鷺眠。","仍教百餘日，迎送直廳前。"]', '["麋入神羊隊，烏驚海鷺眠。","仍教百餘日，迎送直廳前。"]', '诗', 'shi', '', NULL, '直臺 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02943f6d-2c91-4d9c-9690-247eab9ae3ec', '行宮', '行宮', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寥落古行宮，宮花寂寞紅。","白頭宮女在，閑坐說玄宗。"]', '["寥落古行宮，宮花寂寞紅。","白头宮女在，闲坐说玄宗。"]', '诗', 'shi', '', NULL, '行宮 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f99986f-0c0c-4efa-b660-5160aa94dea4', '醉行', '醉行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["秋風方索漠，霜貌足暌攜。","今日騎驄馬，街中醉蹋泥。"]', '["秋风方索漠，霜貌足暌携。","今日騎驄马，街中醉蹋泥。"]', '诗', 'shi', '', NULL, '醉行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f0b2bc8-134b-460f-8a7d-b7540d063e9b', '指巡胡', '指巡胡', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["遣悶多憑酒，公心只仰胡。","挺身唯直指，無意獨欺愚。"]', '["遣悶多憑酒，公心只仰胡。","挺身唯直指，無意独欺愚。"]', '诗', 'shi', '', NULL, '指巡胡 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca9c210-fdbf-4b02-9bef-bf9bc3acbaae', '飲新酒', '饮新酒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["聞君新酒熟，況值菊花秋。","莫怪平生志，圖銷盡日愁。"]', '["闻君新酒熟，況值菊花秋。","莫怪平生志，圖銷尽日愁。"]', '诗', 'shi', '', NULL, '飲新酒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59577abf-ce99-4aa1-a172-0af65d1c00c7', '香毬', '香毬', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["順俗唯團轉，居中莫動搖。","愛君心不惻，猶訝火長燒。"]', '["順俗唯團轉，居中莫动搖。","愛君心不惻，猶訝火长燒。"]', '诗', 'shi', '', NULL, '香毬 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d842a27-5a1a-48d8-87bf-b6bf55304f93', '景申秋八首 一', '景申秋八首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["年年秋意緒，多向雨中生。","漸欲煙火近，稍憐衣服輕。","詠詩閑處立，憶事夜深行。","濩落尋常慣，淒涼別爲情。"]', '["年年秋意緒，多向雨中生。","漸欲煙火近，稍怜衣服轻。","詠诗闲处立，憶事夜深行。","濩落尋常慣，淒涼別爲情。"]', '诗', 'shi', '', NULL, '景申秋八首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d54a89ca-a73e-442b-98e9-0ad6df390d48', '景申秋八首 二', '景申秋八首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蚊幌雨來卷，燭蛾燈上稀。","啼兒冷秋簟，思婦問寒衣。","簾斷螢火入，窗明蝙蝠飛。","良辰日夜去，漸與壯心違。"]', '["蚊幌雨来卷，燭蛾灯上稀。","啼兒冷秋簟，思婦问寒衣。","簾斷螢火入，窗明蝙蝠飞。","良辰日夜去，漸與壯心違。"]', '诗', 'shi', '', NULL, '景申秋八首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408db686-9dc4-42b9-b417-6e6f3109e980', '景申秋八首 三', '景申秋八首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["嗢嗢簷霤凝，丁丁窗雨繁。","枕傾筒簟滑，幔颭案燈翻。","喚魘兒難覺，吟詩婢苦煩。","強眠終不著，閑臥暗消魂。"]', '["嗢嗢簷霤凝，丁丁窗雨繁。","枕傾筒簟滑，幔颭案灯翻。","喚魘兒难覺，吟诗婢苦煩。","強眠終不著，闲臥暗消魂。"]', '诗', 'shi', '', NULL, '景申秋八首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc8e033-081e-4cea-bd80-fabc0ab807de', '景申秋八首 四', '景申秋八首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["瓶瀉高簷雨，窗來激箭風。","病憎燈火暗，寒覺薄幃空。","婢報樵蘇竭，妻愁院落通。","老夫慵計數，教想蔡城東。"]', '["瓶瀉高簷雨，窗来激箭风。","病憎灯火暗，寒覺薄幃空。","婢報樵蘇竭，妻愁院落通。","老夫慵計數，教想蔡城东。"]', '诗', 'shi', '', NULL, '景申秋八首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('380e9a6b-777e-4842-877b-50d2b0b91641', '景申秋八首 五', '景申秋八首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風頭難著枕，病眼厭看書。","無酒銷長夜，回燈照小餘。","三元推廢王，九曜入乘除。","廊廟應多算，參差斡太虛。"]', '["风头难著枕，病眼厭看书。","無酒銷长夜，回灯照小餘。","三元推廢王，九曜入乘除。","廊廟應多算，參差斡太虛。"]', '诗', 'shi', '', NULL, '景申秋八首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('008ea4f5-5596-4c20-a485-3195084c2686', '景申秋八首 六', '景申秋八首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["經雨籬落壞，入秋田地荒。","竹垂哀折節，蓮敗惜空房。","小片慈菇白，低叢柚子黃。","眼前撩亂輩，無不是同鄉。"]', '["經雨籬落壞，入秋田地荒。","竹垂哀折節，蓮敗惜空房。","小片慈菇白，低叢柚子黄。","眼前撩亂輩，無不是同乡。"]', '诗', 'shi', '', NULL, '景申秋八首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edf23bd7-766e-4427-8b6a-39419e902624', '景申秋八首 七', '景申秋八首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雨柳枝枝弱，風光片片斜。","蜻蜓憐曉露，蛺蝶戀秋花。","飢啅空籬雀，寒棲滿樹鴉。","荒涼池館內，不似有人家。"]', '["雨柳枝枝弱，风光片片斜。","蜻蜓怜晓露，蛺蝶戀秋花。","飢啅空籬雀，寒棲满樹鴉。","荒涼池館內，不似有人家。"]', '诗', 'shi', '', NULL, '景申秋八首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1dc725-a463-466a-bb8b-a70ff7eee1f9', '景申秋八首 八', '景申秋八首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["病苦十年後，連陰十日餘。","人方教作鼠，天豈遣爲魚。","鮫綻酆城劒，蟲凋鬼火書。","出聞泥濘盡，何地不摧車。"]', '["病苦十年後，連陰十日餘。","人方教作鼠，天豈遣爲鱼。","鮫綻酆城劒，蟲凋鬼火书。","出闻泥濘尽，何地不摧车。"]', '诗', 'shi', '', NULL, '景申秋八首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c45a54fc-1535-4029-b28e-d8b230e01109', '遣行十首 一', '遣行十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["慘切風雨夕，沉吟離別情。","燕辭前日社，蟬是每年聲。","暗淚深相感，危心亦自驚。","不如元不識，俱作路人行。"]', '["慘切风雨夕，沉吟離別情。","燕辞前日社，蟬是每年声。","暗泪深相感，危心亦自驚。","不如元不識，俱作路人行。"]', '诗', 'shi', '', NULL, '遣行十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('172ba709-45f7-4228-933b-cad93131e78c', '遣行十首 二', '遣行十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["十五年前事，恓惶無限情。","病僮更借出，羸馬共馳聲。","射葉楊纔破，聞弓鴈已驚。","小年辛苦學，求得苦辛行。"]', '["十五年前事，恓惶無限情。","病僮更借出，羸马共驰声。","射葉楊纔破，闻弓鴈已驚。","小年辛苦学，求得苦辛行。"]', '诗', 'shi', '', NULL, '遣行十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abea8f2d-9e51-46ad-b122-fdaf1c004361', '遣行十首 三', '遣行十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["徙倚簷宇下，思量去住情。","暗螢穿竹見，斜雨隔窗聲。","就枕回轉數，聞雞撩亂驚。","一家同草草，排比送君行。"]', '["徙倚簷宇下，思量去住情。","暗螢穿竹见，斜雨隔窗声。","就枕回轉數，闻雞撩亂驚。","一家同草草，排比送君行。"]', '诗', 'shi', '', NULL, '遣行十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b9cf01-87da-4ac1-abb8-e4ddcc62e941', '遣行十首 四', '遣行十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["已愴朋交別，復懷兒女情。","相兄亦相舊，同病又同聲。","白髮年年剩，秋蓬處處驚。","不堪身漸老，頻送異鄉行。"]', '["已愴朋交別，复懷兒女情。","相兄亦相旧，同病又同声。","白髮年年剩，秋蓬处处驚。","不堪身漸老，頻送異乡行。"]', '诗', 'shi', '', NULL, '遣行十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f55d2e-80e3-44c4-9269-f37ce0720105', '遣行十首 五', '遣行十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["塞上風雨思，城中兄弟情。","北隨鵷立位，南送鴈來聲。","遇適尤兼恨，聞書喜復驚。","唯應遙料得，知我伴君行。"]', '["塞上风雨思，城中兄弟情。","北隨鵷立位，南送鴈来声。","遇適尤兼恨，闻书喜复驚。","唯應遙料得，知我伴君行。"]', '诗', 'shi', '', NULL, '遣行十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2813ccde-f3e5-4eb9-b1e7-6fa273b30143', '遣行十首 六', '遣行十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["暮欲歌吹樂，暗衝泥水情。","稻花秋雨氣，江石夜灘聲。","犬吠穿籬出，鷗眠起水驚。","愁君明月夜，獨自入山行。"]', '["暮欲歌吹乐，暗衝泥水情。","稻花秋雨氣，江石夜灘声。","犬吠穿籬出，鷗眠起水驚。","愁君明月夜，独自入山行。"]', '诗', 'shi', '', NULL, '遣行十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d89a661a-974b-4215-b831-beb3479417f1', '遣行十首 七', '遣行十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["七過襃城驛，回回各爲情。","八年身世夢，一種水風聲。","尋覓詩章在，思量歲月驚。","更悲西塞別，終夜繞池行。"]', '["七過襃城驛，回回各爲情。","八年身世梦，一種水风声。","尋覓诗章在，思量歲月驚。","更悲西塞別，終夜繞池行。"]', '诗', 'shi', '', NULL, '遣行十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1890307f-3123-4b81-aed9-b32600e5f84f', '遣行十首 八', '遣行十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["襃縣驛前境，曲江池上情。","南堤衰柳意，西寺晚鐘聲。","雲水興方遠，風波心已驚。","可憐皆老大，不得自由行。"]', '["襃縣驛前境，曲江池上情。","南堤衰柳意，西寺晚鐘声。","云水兴方远，风波心已驚。","可怜皆老大，不得自由行。"]', '诗', 'shi', '', NULL, '遣行十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d65a96-fa9b-4df4-bd9b-752927d7957e', '遣行十首 九', '遣行十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["見說巴風俗，都無漢性情。","猿聲蘆管調，羌笛竹雞聲。","迎候人應少，平安火莫驚。","每逢危棧處，須作貫魚行。"]', '["见说巴风俗，都無漢性情。","猿声蘆管調，羌笛竹雞声。","迎候人應少，平安火莫驚。","每逢危棧处，須作貫鱼行。"]', '诗', 'shi', '', NULL, '遣行十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ac61d90-5ce4-4999-90c9-a969abb9c978', '遣行十首 十', '遣行十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["聞道陰平郡，翛然古戍情。","橋兼麋鹿蹋，山應鼓鼙聲。","羌婦梳頭緊，蕃牛護尾驚。","憐君閑悶極，只傍白江行。"]', '["闻道陰平郡，翛然古戍情。","橋兼麋鹿蹋，山應鼓鼙声。","羌婦梳头緊，蕃牛護尾驚。","怜君闲悶極，只傍白江行。"]', '诗', 'shi', '', NULL, '遣行十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5170856-6ead-4edf-b076-f7378a593959', '生春二十首 一', '生春二十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生雲色中。","籠蔥閑著水，晻淡欲隨風。","度曉分霞態，餘光庇雪融。","晚來低漠漠，渾欲泥幽叢。"]', '["何处生春早，春生云色中。","籠蔥闲著水，晻淡欲隨风。","度晓分霞態，餘光庇雪融。","晚来低漠漠，渾欲泥幽叢。"]', '诗', 'shi', '', NULL, '生春二十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a4ef431-d432-4382-8bcc-ba64a8352846', '生春二十首 二', '生春二十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生漫雪中。","渾無到地片，唯逐入樓風。","屋上些些薄，池心旋旋融。","自悲銷散盡，誰假入蘭叢。"]', '["何处生春早，春生漫雪中。","渾無到地片，唯逐入楼风。","屋上些些薄，池心旋旋融。","自悲銷散尽，誰假入蘭叢。"]', '诗', 'shi', '', NULL, '生春二十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee3cdbe7-145e-48ac-995a-77ca43f2d81e', '生春二十首 三', '生春二十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生霽色中。","遠林橫返照，高樹亞東風。","水凍霜威庇，泥新地氣融。","漸知殘雪薄，杪近最憐叢。"]', '["何处生春早，春生霽色中。","远林橫返照，高樹亞东风。","水凍霜威庇，泥新地氣融。","漸知殘雪薄，杪近最怜叢。"]', '诗', 'shi', '', NULL, '生春二十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c31dfe5e-f537-41fc-8e29-865ecf856220', '生春二十首 四', '生春二十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生曙火中。","星圍分暗陌，煙氣滿晴風。","宮樹棲鵶亂，城樓帶雪融。","競排閶闔側，珂傘自相叢。"]', '["何处生春早，春生曙火中。","星圍分暗陌，煙氣满晴风。","宮樹棲鵶亂，城楼带雪融。","競排閶闔側，珂傘自相叢。"]', '诗', 'shi', '', NULL, '生春二十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b5aad9-2e43-4717-9aab-04da6afd869c', '生春二十首 五', '生春二十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生曉禁中。","殿階龍斾日，漏閣寶箏風。","藥樹香煙重，天顏瑞氣融。","柳梅渾未覺，青紫已叢叢。"]', '["何处生春早，春生晓禁中。","殿階龙斾日，漏閣寶箏风。","藥樹香煙重，天顏瑞氣融。","柳梅渾未覺，青紫已叢叢。"]', '诗', 'shi', '', NULL, '生春二十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8fc8df0-c6ac-4f7b-8476-8eb464b2c1a0', '生春二十首 六', '生春二十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生江路中。","雨移臨浦市，晴候過湖風。","蘆筍錐猶短，凌澌玉漸融。","數宗船載足，商婦兩眉叢。"]', '["何处生春早，春生江路中。","雨移臨浦市，晴候過湖风。","蘆筍錐猶短，凌澌玉漸融。","數宗船載足，商婦兩眉叢。"]', '诗', 'shi', '', NULL, '生春二十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d62d3a70-1742-45fd-a08d-0be5ba5733f9', '生春二十首 七', '生春二十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生野墅中。","病翁閑向日，征婦嬾成風。","斫筤天雖暖，穿區凍未融。","鞭牛縣門外，爭土蓋蠶叢。"]', '["何处生春早，春生野墅中。","病翁闲向日，征婦嬾成风。","斫筤天雖暖，穿區凍未融。","鞭牛縣门外，爭土蓋蠶叢。"]', '诗', 'shi', '', NULL, '生春二十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76206acd-40e7-41bc-a957-12a30e59dd7e', '生春二十首 八', '生春二十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生冰岸中。","尚憐扶臘雪，漸覺受東風。","織女雲橋斷，波神玉貌融。","便成嗚咽去，流恨與蓮叢。"]', '["何处生春早，春生冰岸中。","尚怜扶臘雪，漸覺受东风。","织女云橋斷，波神玉貌融。","便成嗚咽去，流恨與蓮叢。"]', '诗', 'shi', '', NULL, '生春二十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c746891e-189b-49e8-8459-459317031476', '生春二十首 九', '生春二十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生柳眼中。","芽新纔綻日，茸短未含風。","綠誤眉心重，黃驚蠟淚融。","碧條殊未合，愁緒已先叢。"]', '["何处生春早，春生柳眼中。","芽新纔綻日，茸短未含风。","綠誤眉心重，黄驚蠟泪融。","碧條殊未合，愁緒已先叢。"]', '诗', 'shi', '', NULL, '生春二十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb1e142c-039f-4630-aa60-ea6c311ecbe0', '生春二十首 十', '生春二十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生梅援中。","蘂排難犯雪，香乞擬來風。","隴迥羌聲怨，江遙客思融。","年年最相惱，緣未有諸叢。"]', '["何处生春早，春生梅援中。","蘂排难犯雪，香乞擬来风。","隴迥羌声怨，江遙客思融。","年年最相惱，緣未有諸叢。"]', '诗', 'shi', '', NULL, '生春二十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14140e43-736f-4e66-94e3-77a7297124b7', '生春二十首 十一', '生春二十首 十一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生鳥思中。","鵲巢移舊歲，䳒羽旋高風。","鴻鴈驚沙暖，鴛鴦愛水融。","最憐雙翡翠，飛入小梅叢。"]', '["何处生春早，春生鸟思中。","鵲巢移旧歲，䳒羽旋高风。","鴻鴈驚沙暖，鴛鴦愛水融。","最怜雙翡翠，飞入小梅叢。"]', '诗', 'shi', '', NULL, '生春二十首 十一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9077071d-8e11-463f-b540-cd3e65bd328c', '生春二十首 十二', '生春二十首 十二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生池榭中。","鏤瓊冰陷日，文縠水廻風。","柳愛和身動，梅愁合樹融。","草芽猶未出，挑得小萱叢。"]', '["何处生春早，春生池榭中。","鏤瓊冰陷日，文縠水廻风。","柳愛和身动，梅愁合樹融。","草芽猶未出，挑得小萱叢。"]', '诗', 'shi', '', NULL, '生春二十首 十二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62991599-6a5c-46c4-b197-4f07e39893ad', '生春二十首 十三', '生春二十首 十三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生稚戲中。","亂騎殘爆竹，爭唾小旋風。","駡雨愁妨走，呵冰喜旋融。","女兒針線盡，偷學五辛叢。"]', '["何处生春早，春生稚戲中。","亂騎殘爆竹，爭唾小旋风。","駡雨愁妨走，呵冰喜旋融。","女兒針線尽，偷学五辛叢。"]', '诗', 'shi', '', NULL, '生春二十首 十三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4579fbab-df7b-4e90-ba1d-35bb35b4db41', '生春二十首 十四', '生春二十首 十四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生人意中。","曉妝雖近火，晴戲漸憐風。","暗入心情嬾，先添酒思融。","預知花好惡，偏在最深叢。"]', '["何处生春早，春生人意中。","晓妝雖近火，晴戲漸怜风。","暗入心情嬾，先添酒思融。","預知花好惡，偏在最深叢。"]', '诗', 'shi', '', NULL, '生春二十首 十四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55542850-61a0-4958-9f15-a65ca013f0b6', '生春二十首 十五', '生春二十首 十五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生半睡中。","見燈如見霧，聞雨似聞風。","開眼猶殘夢，擡身便恐融。","却成雙翅蝶，還繞庳花叢。"]', '["何处生春早，春生半睡中。","见灯如见霧，闻雨似闻风。","开眼猶殘梦，擡身便恐融。","却成雙翅蝶，還繞庳花叢。"]', '诗', 'shi', '', NULL, '生春二十首 十五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c69fb38-d8a5-4dc1-a713-c17d084adcd0', '生春二十首 十六', '生春二十首 十六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生曉鏡中。","手寒勻面粉，鬟動倚簾風。","宿霧梅心滴，朝光幕上融。","思牽梳洗嬾，空拔綠絲叢。"]', '["何处生春早，春生晓镜中。","手寒勻面粉，鬟动倚簾风。","宿霧梅心滴，朝光幕上融。","思牽梳洗嬾，空拔綠絲叢。"]', '诗', 'shi', '', NULL, '生春二十首 十六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f22aec4-e20a-47f2-b637-6c81be69f2b6', '生春二十首 十七', '生春二十首 十七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生綺戶中。","玉櫳穿細日，羅幔張輕風。","柳軟腰支嫩，梅香密氣融。","獨眠傍妬物，偷鏟合歡叢。"]', '["何处生春早，春生綺戶中。","玉櫳穿細日，羅幔張轻风。","柳軟腰支嫩，梅香密氣融。","独眠傍妬物，偷鏟合歡叢。"]', '诗', 'shi', '', NULL, '生春二十首 十七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6203fcb-4ab3-4af2-9b2a-4fa906d6cc94', '生春二十首 十八', '生春二十首 十八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生老病中。","土膏蒸足腫，天暖癢頭風。","似覺肌膚展，潛知血氣融。","又添新一歲，衰白轉成叢。"]', '["何处生春早，春生老病中。","土膏蒸足腫，天暖癢头风。","似覺肌膚展，潛知血氣融。","又添新一歲，衰白轉成叢。"]', '诗', 'shi', '', NULL, '生春二十首 十八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0a8c0eb-fbe9-478d-9e65-a6e9370a4b54', '生春二十首 十九', '生春二十首 十九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生客思中。","旅魂驚北鴈，鄉信是東風。","縱有心灰動，無由鬢雪融。","未知開眼日，空繞未開叢。"]', '["何处生春早，春生客思中。","旅魂驚北鴈，乡信是东风。","縱有心灰动，無由鬢雪融。","未知开眼日，空繞未开叢。"]', '诗', 'shi', '', NULL, '生春二十首 十九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3605d246-f841-4fc9-9af4-81e50af7ff21', '生春二十首 二十', '生春二十首 二十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何處生春早，春生濛雨中。","裛塵微有氣，拂面細如風。","柳誤啼珠密，梅驚粉汗融。","滿空愁淡淡，應豫憶芳叢。"]', '["何处生春早，春生濛雨中。","裛塵微有氣，拂面細如风。","柳誤啼珠密，梅驚粉汗融。","满空愁淡淡，應豫憶芳叢。"]', '诗', 'shi', '', NULL, '生春二十首 二十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ceee809-a65a-4eac-91d7-8b2859b4fa4e', '嘉陵水', '嘉陵水', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["爾是無心水，東流有恨無。","我心無說處，也共爾何殊。"]', '["爾是無心水，东流有恨無。","我心無说处，也共爾何殊。"]', '诗', 'shi', '', NULL, '嘉陵水 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2070aa40-e05d-4f56-8cd5-81dc52349125', '漫天嶺贈僧', '漫天嶺贈僧', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["五上兩漫天，因師懺業緣。","漫天無盡日，浮世有窮年。"]', '["五上兩漫天，因師懺業緣。","漫天無尽日，浮世有窮年。"]', '诗', 'shi', '', NULL, '漫天嶺贈僧 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a5a05fc-b27d-4506-afb8-6a1e6aebeff0', '百牢關', '百牢关', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["天上無窮路，生期七十間。","那堪九年內，五度百牢關。"]', '["天上無窮路，生期七十间。","那堪九年內，五度百牢关。"]', '诗', 'shi', '', NULL, '百牢關 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d86248a-1761-4971-bdf8-ee2ed0ed10a6', '二月十九日酬王十八全素', '二月十九日酬王十八全素', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["君念世上川，嗟予老瘴天。","那堪十日內，又長白頭年。"]', '["君念世上川，嗟予老瘴天。","那堪十日內，又长白头年。"]', '诗', 'shi', '', NULL, '二月十九日酬王十八全素 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90d7fd77-5000-4cfd-8d58-0d1f0c8c6006', '滎陽鄭公以稹寓居嚴茅有池塘之勝寄詩四首因有意獻', '滎陽鄭公以稹寓居嚴茅有池塘之勝寄诗四首因有意獻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["激射分流闊，灣環此地多。","暫停隨梗浪，猶閱敗霜荷。","恨阻還江勢，思深到海波。","自傷才畎澮，其奈贈珠何。"]', '["激射分流闊，灣环此地多。","暫停隨梗浪，猶閱敗霜荷。","恨阻還江勢，思深到海波。","自傷才畎澮，其奈贈珠何。"]', '诗', 'shi', '', NULL, '滎陽鄭公以稹寓居嚴茅有池塘之勝寄詩四首因有意獻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ac6dc5-8146-4d05-a26e-2b751770184f', '酬樂天寄蘄州簟', '酬乐天寄蘄州簟', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蘄簟未經春，君先拭翠筠。","知爲熱時物，預與瘴中人。","碾玉連心潤，編牙小片珍。","霜凝青汗簡，冰透碧游鱗。","水魄輕涵黛，琉璃薄帶塵。","夢成傷冷滑，驚臥老龍身。"]', '["蘄簟未經春，君先拭翠筠。","知爲熱时物，預與瘴中人。","碾玉連心潤，編牙小片珍。","霜凝青汗簡，冰透碧游鱗。","水魄轻涵黛，琉璃薄带塵。","梦成傷冷滑，驚臥老龙身。"]', '诗', 'shi', '', NULL, '酬樂天寄蘄州簟 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df9de0ac-2b78-433f-ac3c-e86dfbb9b2ee', '酬李浙西先因從事見寄之作', '酬李浙西先因從事见寄之作', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["近日金鑾直，親於漢珥貂。","內人傳帝命，丞相讓吾僚。","浙郡懸旌遠，長安諭日遙。","因君蘂珠贈，還一夢煙霄。"]', '["近日金鑾直，親於漢珥貂。","內人傳帝命，丞相讓吾僚。","浙郡懸旌远，长安諭日遙。","因君蘂珠贈，還一梦煙霄。"]', '诗', 'shi', '', NULL, '酬李浙西先因從事見寄之作 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9eab0f2-9bea-4065-b574-ec7bcae31f25', '酬周從事望海亭見寄', '酬周從事望海亭见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["年老無流輩，行稀足薜蘿。","熱時憐水近，高處見山多。","衣袖長堪舞，喉嚨轉解歌。","不辭狂復醉，人世有風波。"]', '["年老無流輩，行稀足薜蘿。","熱时怜水近，高处见山多。","衣袖长堪舞，喉嚨轉解歌。","不辞狂复醉，人世有风波。"]', '诗', 'shi', '', NULL, '酬周從事望海亭見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a0cdeca-65bb-4e52-9a40-f1a1a037b5d9', '代杭民答樂天', '代杭民答乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["翠幕籠斜日，朱衣儼別筵。","管弦淒欲罷，城郭望依然。","路溢新城市，農開舊廢田。","春坊幸無事，何惜借三年。"]', '["翠幕籠斜日，朱衣儼別筵。","管弦淒欲罷，城郭望依然。","路溢新城市，農开旧廢田。","春坊幸無事，何惜借三年。"]', '诗', 'shi', '', NULL, '代杭民答樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed96672b-c89f-47c1-983b-c7bf78e34ce1', '杏園', '杏园', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["浩浩長安車馬塵，狂風吹送每年春。","門前本是虛空界，何事栽花誤世人。"]', '["浩浩长安车马塵，狂风吹送每年春。","门前本是虛空界，何事栽花誤世人。"]', '诗', 'shi', '', NULL, '杏園 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8085e498-9420-4bf8-93ac-c407eca63f03', '菊花', '菊花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["秋叢繞舍似陶家，遍繞籬邊日漸斜。","不是花中偏愛菊，此花開盡更無花。"]', '["秋叢繞舍似陶家，遍繞籬邊日漸斜。","不是花中偏愛菊，此花开尽更無花。"]', '诗', 'shi', '', NULL, '菊花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb447c4-43a5-4f22-8a48-b1e0a823a08c', '酬哥舒大少府寄同年科第', '酬哥舒大少府寄同年科第', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["前年科第偏年少，未解知羞最愛狂。","九陌爭馳好鞍馬，八人同著綵衣裳。","自言行樂朝朝是，豈料浮生漸漸忙。","賴得官閑且疎散，到君花下憶諸郎。"]', '["前年科第偏年少，未解知羞最愛狂。","九陌爭驰好鞍马，八人同著綵衣裳。","自言行乐朝朝是，豈料浮生漸漸忙。","賴得官闲且疎散，到君花下憶諸郎。"]', '诗', 'shi', '', NULL, '酬哥舒大少府寄同年科第 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b864ee4-2a60-4408-88bb-cae317fc78c1', '幽棲', '幽棲', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["野人自愛幽棲所，近對長松遠是山。","盡日望雲心不繫，有時看月夜方閑。","壺中天地乾坤外，夢裏身名旦暮間。","遼海若思千歲鶴，且留城市會飛還。"]', '["野人自愛幽棲所，近对长松远是山。","尽日望云心不繫，有时看月夜方闲。","壺中天地乾坤外，梦裏身名旦暮间。","遼海若思千歲鹤，且留城市會飞還。"]', '诗', 'shi', '', NULL, '幽棲 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b328e435-0a88-46e0-b4cc-28c87753b6f1', '清都春霽寄胡三吳十一', '清都春霽寄胡三吳十一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蘂珠宮殿經微雨，草樹無塵耀眼光。","白日當空天氣暖，好風飄樹柳陰涼。","蜂憐宿露攢芳久，燕得新泥拂戶忙。","時節催年春不住，武陵花謝憶諸郎。"]', '["蘂珠宮殿經微雨，草樹無塵耀眼光。","白日當空天氣暖，好风飄樹柳陰涼。","蜂怜宿露攢芳久，燕得新泥拂戶忙。","时節催年春不住，武陵花謝憶諸郎。"]', '诗', 'shi', '', NULL, '清都春霽寄胡三吳十一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4e9e77c-3ae0-4c64-80ce-73d705d4a835', '華嶽寺', '华嶽寺', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["山前古寺臨長道，來往淹留爲愛山。","雙燕營巢始西別，百花成子又東還。","暝驅羸馬頻看堠，曉聽鳴雞欲度關。","羞見竇師無外役，竹窗依舊老身閑。"]', '["山前古寺臨长道，来往淹留爲愛山。","雙燕營巢始西別，百花成子又东還。","暝驱羸马頻看堠，晓听鳴雞欲度关。","羞见竇師無外役，竹窗依旧老身闲。"]', '诗', 'shi', '', NULL, '華嶽寺 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f0f6a5-d9aa-4474-9a47-1632823cf119', '天壇上境', '天壇上境', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["野人性僻窮深僻，芸署官閑不似官。","萬里洞中朝玉帝，九光霞外宿天壇。","洪漣浩渺東溟曙，白日低回上境寒。","因爲南昌檢仙籍，馬君家世奉還丹。"]', '["野人性僻窮深僻，芸署官闲不似官。","万里洞中朝玉帝，九光霞外宿天壇。","洪漣浩渺东溟曙，白日低回上境寒。","因爲南昌檢仙籍，马君家世奉還丹。"]', '诗', 'shi', '', NULL, '天壇上境 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ef4954c-9fcf-4f13-ae95-18c6f94853f4', '尋西明寺僧不在', '尋西明寺僧不在', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春來日日到西林，飛錫經行不可尋。","蓮池舊是無波水，莫逐狂風起浪心。"]', '["春来日日到西林，飞錫經行不可尋。","蓮池旧是無波水，莫逐狂风起浪心。"]', '诗', 'shi', '', NULL, '尋西明寺僧不在 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d07f27-f539-44f0-a402-00e3a59a0691', '與吳侍御春遊', '與吳侍御春游', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蒼龍闕下陪驄馬，紫閣峰頭見白雲。","滿眼流光隨日度，今朝花落更紛紛。"]', '["蒼龙闕下陪驄马，紫閣峰头见白云。","满眼流光隨日度，今朝花落更紛紛。"]', '诗', 'shi', '', NULL, '與吳侍御春遊 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a0f8ea1-9ba7-4c4d-a85c-9f1df1e8065d', '晚春', '晚春', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["晝靜簾疎燕語頻，雙雙鬬雀動階塵。","柴扉日暮隨風掩，落盡閑花不見人。"]', '["晝静簾疎燕語頻，雙雙鬬雀动階塵。","柴扉日暮隨风掩，落尽闲花不见人。"]', '诗', 'shi', '', NULL, '晚春 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94824a5c-c555-449f-96e3-8dbdab954b28', '先醉', '先醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["今日樽前敗飲名，三桮未盡不能傾。","怪來花下長先醉，半是春風蕩酒情。"]', '["今日樽前敗饮名，三桮未尽不能傾。","怪来花下长先醉，半是春风蕩酒情。"]', '诗', 'shi', '', NULL, '先醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1486d94d-a8a6-4c71-88ec-221c17920dab', '獨醉', '独醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["一樹芳菲也當春，漫隨車馬擁行塵。","桃花解笑鶯能語，自醉自眠那藉人。"]', '["一樹芳菲也當春，漫隨车马擁行塵。","桃花解笑鶯能語，自醉自眠那藉人。"]', '诗', 'shi', '', NULL, '獨醉 元稹 shi');
